\begin{algorithm}[!t]
\caption{\simplexwater{} and \heavywater{} Watermark Generation}
\begin{algorithmic}[1]
    \State \textbf{Inputs}: Token distribution $P_X$, score function $f$, side information $s$, tilting parameter $\delta$.  
    \State \textbf{Outputs:} Watermarked distribution $P_{X|S=s}$
    \State Calculate OT cost matrix $\rC_{x',s'}=-f(x',s')$, for all $(x',s')\in[1:m]\times[1:k]$
    \State $P_{X,S} = \mathsf{Sinkhorn}\left( \rC, P_X, P_S \right)$, where $P_S=\mathsf{Unif}([1:k])$
    \State $P_{X|S=s}(x|s)= k\cdot P_{X,S}(x,s)$ 
    \If{$\delta>0$}
    \State $P_{X|S=s}\gets \mathsf{tilt}(P_{X|S=s},s,\delta)$
    \State Normalize $P_{X|S=s}$
    \EndIf
    \State \textbf{Return} $P_{X|S=s}$
\end{algorithmic}
\label{alg:watermark}
\end{algorithm}
