\subsection{Bistars}

\begin{theorem}
	\label{thm-reconstructingBistarsK2}
	Let $k=2$. Bistars are reconstructable with three multiset-queries.
\end{theorem}

\begin{proof}
	Let $\Sigma=(A,B)$ and $\mathcal{B}=(G,\lambda)$ be such that $G$ is a bistar with center vertices $u$ and $v$, vertex $u$ (resp. $v$) having $\ell_u$ (resp. $\ell_v$) adjacent leaves. First, use \Cref{lem-leavesAndInternal} to obtain the composition of leaves and of $u$ and $v$.
	Now, there are two cases to consider.

	\medskip\noindent\textbf{Case 1: $u$ and $v$ have the same label.} Assume without loss of generality that they both have label $A$. Let $a_u$ and $b_u$ (resp. $a_v$, $b_v$) be the (yet unknown) number of leaves attached to $u$ (resp. $v$) labeled with $A$ and $B$, respectively. Denote by $\alpha$ and $\beta$ the total number of vertices labeled with $A$ and $B$, respectively (which are known from $S_{n}(\mathcal{B})$). Note that we have $\alpha=a_u+a_v+2$ and $\beta=b_u+b_v$, as well as $a_u+b_u=\ell_u$ and $a_v+b_v=\ell_v$.

	The query $\mathcal{M}_{3}(\mathcal{B})$ outputs the composition of connected subgraphs of order~3, from which we can obtain $x$ and $y$ the number of subgraphs with compositions $A^3$ and $A^2B$, respectively. Note that if $x=0$ then we are done (all leaves have label $B$), and likewise if $y=0$ (all leaves have label $A$). Hence, assume that $x,y > 0$, we have:
	\begin{equation}
		\label{eqn-bistar}
		x = a_u + a_v + \binom{a_u}{2} + \binom{a_v}{2} = \frac{\alpha-2+a_u^2+a_v^2}{2} \Longrightarrow a_u^2+a_v^2 = 2x - \alpha +2
	\end{equation}
	as well as:
	\begin{align*}
		y & = b_u + b_v + a_ub_u + a_vb_v & \\
		& = \beta + a_u(\ell_u-a_u) + a_v(\ell_v - a_v) & \text{by $a_u+b_u=\ell_u$ and $a_v+b_v=\ell_v$} \\
		& = \beta + \ell_u a_u + \ell_v a_v - (a_u^2+a_v^2) & \\
		& = \beta + \ell_u a_u + \ell_v (\alpha - a_u - 2) - (a_u^2+a_v^2) & \text{by $\alpha=a_u+a_v+2$} \\
		& = \beta + \ell_u a_u + \ell_v (\alpha - a_u - 2) - (2x-\alpha+2) & \text{by (\ref{eqn-bistar})} \\
		& = \beta + a_u(\ell_u - \ell_v) + \alpha (\ell_v + 1) -2 (\ell_v+x+1) & 
	\end{align*}
	and hence:
	$$ a_u = \frac{y - \beta - \alpha (\ell_v+1) + 2(\ell_v+x+1)}{\ell_u-\ell_v} $$
	from which we can now find $a_v$, $b_u$ and $b_v$.



	\medskip\noindent\textbf{Case 2: $u$ and $v$ have different labels.} Let $a$ (resp. $y$) and $x$ (resp. $b$) be the (yet unknown) number of leaves attached to the internal vertex with label $A$ (resp. $B$) and themselves labeled with $A$ and $B$, respectively. Denote by $\alpha$ and $\beta$ the total number of vertices labeled with $A$ and $B$, respectively (which are known from $S_{n}(\mathcal{B})$). Note that we have $\alpha=a+y+1$ and $\beta=b+x+1$.

	The query $\mathcal{M}_{2}(\mathcal{B})$ outputs the composition of pairs of connected vertices, from which we can obtain $\alpha'$ and $\beta'$ the number of such pairs with composition $A^2$ and $B^2$, respectively. Note that we necessarily have $a = \alpha'$ and $b = \beta'$. This allows us to also obtain $x=\beta-\beta'-1$ and $y=\alpha-\alpha'-1$. We can now use those values to deduce whether $\ell_u=x+a$ and $\ell_v=b+y$, or $\ell_v=x+a$ and $\ell_u=y+b$; note that the two possibilities can  be true simultaneously if and only if $\ell_u = \ell_v$ (in which case, we are trivially done). Hence, we can find the labels of $u$ and $v$ as well as the labels of the attached leaves.

	\medskip
	This concludes the case analysis; note that we use two queries, followed by one more query in both cases, so three queries in total.
\end{proof}

\begin{theorem}
	\label{thm-reconstructingBistarsAnyK}
	For $k \geq 3$, bistars are reconstructable. Furthermore, if the two non-leaves have different labels, then, this can be done in three multiset-queries.
\end{theorem}

\begin{proof}
	Let $\mathcal{B}=(B,\lambda)$ be such that $B$ is a bistar with center vertices $u$ and $v$, vertex $u$ (resp. $v$) having $\ell_u$ (resp. $\ell_v$) adjacent leaves. First, use \Cref{lem-leavesAndInternal} to obtain the composition of leaves and of $u$ and $v$. There are two cases to consider.

	\medskip\noindent\textbf{Case 1: $u$ and $v$ have different labels.} We will apply a similar technique as in the proof of the same case in \Cref{thm-reconstructingBistarsK2}. Assume without loss of generality that $u$ and $v$ have labels $X$ and $Y$, denote the (yet unknown) number of leaves attached to the vertex with label $X$ (resp. $Y$) by $\ell_x$ (resp. $\ell_y$); we want to decide whether $\ell_u=\ell_x$ or $\ell_u=\ell_y$. Note that we also know $x$ (resp. $y$) the number of vertices labeled with $X$ (resp. $Y$).

	The query $\mathcal{M}_2(\mathcal{B})$ outputs the composition of pairs of connected vertices. There are three types of combinations: $XY$, $XZ$ for $Z \neq Y$ and $YZ$ for $Z \neq X$. The combinations $XZ$ for $Z \neq Y$ give us all leaves adjacent to the vertex with label $X$, denote by $z_x$ their number. The combinations $YZ$ for $Z \neq X$ give us all leaves adjacent to the vertex with label $Y$, denote by $z_y$ their number. From those, we also know $x_2$ and $y_2$, the numbers of combinations $XX$ and $YY$, respectively. Finally, let $\alpha$ (resp. $\beta$) be the (yet unknown) number of vertices labeled with $Y$ (resp. $X$) attached to the internal vertex with label $X$ (resp. $Y$). We have $x=\beta+x_2+1$ and $y=\alpha+y_2+1$, from which we can deduce $\alpha$ and $\beta$. Furthermore, $\ell_x=z_x+\alpha$ and $\ell_y=z_y+\beta$, so we can decide whether $\ell_u=\ell_x$ or $\ell_u=\ell_y$ (if both are true simultaneously, then, $\ell_u=\ell_v$ and we are trivially done).

	\medskip\noindent\textbf{Case 2: $u$ and $v$ have the same label.}

	Let us denote by $A$ the label of vertices $u$ and $v$. Since $u$ and $v$ have the same label, we may consider the largest composition which contains only one $A$ (this is found by exploring queries $\mathcal{M}_i(\mathcal{B})$ for decreasing values of $i$, starting from $i=\ell_u+\ell_v+2$). The single $A$ in this composition is either $u$ or $v$ (unless every vertex is labeled with $A$, in which case the reconstruction is trivially done). Hence, this composition gives every non-$A$ label on one side of the bistar. Denote the total number of these non-$A$ symbols by $\beta_1$. As we can obtain the total number of each symbol with 1-vertex subgraphs, we can also obtain the number of non-$A$ symbols on the other side of the bistar, denote this by $\beta_2$. Hence, we only need to solve whether we have $\beta_1$ non-$A$ symbols adjacent to $u$ or adjacent to $v$. Note that when $\beta_1=\beta_2$ or $\ell_u=\ell_v$, we are already done. 

	Assume without loss of generality that $\ell_v> \ell_u$ and let $\ell_v=\ell_u+\ell$. We denote by $A_u$ ($A_v$) and $B_u$ ($B_v$) the number of symbols $A$ and non-$A$ symbols adjacent to $u$ ($v$), respectively.
	Consider next the number of compositions $A^3$ (obtained using $\mathcal{M}_3(\mathcal{B})$) and denote it by $a_3$. Since each $A^3$ contains either two vertices adjacent to one of $u$ or $v$, or both $u$ and $v$ and a single vertex adjacent to one of $u$ or $v$, we have $$a_3=\binom{A_u}{2}+\binom{A_v}{2}+A_u+A_v=\frac{A_u^2+A_v^2+A_u+A_v}{2}.$$ Furthermore, as we know the total number of vertices labeled with $A$, denote it by $\alpha$, we also know that $A_u+A_v=\alpha-2$. Hence, $2a_3-\alpha+2=A_u^2+A_v^2$. Furthermore, we have $$A_u^2+A_v^2=(\ell_u-B_u)^2+(\ell_v-B_v)^2=\ell_u^2-2\ell_uB_u+B_u^2+\ell_v^2-2\ell_vB_v+B_v^2.$$ Note that we have $\beta_1^2+\beta_2^2=B_u^2+B_v^2$. Hence, we have $\frac{-2a_3+\alpha-2+\beta_1^2+\beta_2^2+\ell_u^2+\ell_v^2}{2}=\ell_uB_u+\ell_vB_v=(B_u+B_v)\ell_u+\ell B_v$. Therefore, $$B_v=\frac{-2a_3+\alpha-2+\beta_1^2+\beta_2^2+\ell_u^2+\ell_v^2-2(\beta_1+\beta_2)\ell_u}{2\ell}.$$
	As we can compute everything on the right hand side, we can compute $B_v$. Furthermore, $\{B_v,B_u\}=\{\beta_1,\beta_2\}$. As we mentioned above, this is enough to reconstruct the labeling of $\mathcal{B}$.
\end{proof}



\subsection{Stars $S_{1,1, m}$}

In this section, we study paths with one leaf false-twinned (that is, we create a false twin of one leaf). As shown with the proof of \Cref{thm-reconstructingS11k}, this very simple operation changes the status of the graph: recall that some paths are confusable~\cite{acharya2015string}; we show that false-twinning one of the leaves makes the graph sum-reconstructable with a linear number of queries, and the proof is quite technical. However, we will see later (\Cref{thm-triangleWithTail} in \Cref{secSmallConfusable}) that true-twinning a leaf (that is, creating a twin of it) creates a graph class exhibiting another behaviour (alternating between sum-reconstructable and confusable with the parity of $m$).

Recall that we have shown in \Cref{SecLabels} that subdivided stars of type $S_{1,1,m}$ allow more labelings than paths using $m+3$ labels. Furthermore, since it is relatively simple to construct $S_{1,1,m}$, these graphs seem suitable candidates for applications related to advanced information storages.

\begin{theorem}
	\label{thm-reconstructingS11k}
	For any nonnegative integer $m$, the subdivided star $\mathcal{S}=(S_{1,1, m},\lambda)$ is sum-reconstructable.
\end{theorem}

\begin{proof}
	Note that $P_3$ is sum-reconstructable by \Cref{cor-reconstructingStars}, so let $m$ be a positive integer.
	Let $\mathcal{S}=(S,\lambda)$ where $S=S_{1,1, m}$, denote the two leaves attached to the center of $S$ by $u_1$ and $u_2$, and the vertices from the center to the end of the branch of length $m$ by $v_1,v_2,\ldots,v_{m+1}$ (so the center is $v_1$ and $v_{m+1}$ is a leaf).

	For readability, we will use the notation of a given query $S_t(\mathcal{S})$ as a sum of labels, such that $X$ corresponds to the label of vertex $x$. For example, \Cref{lem-s2G} implies that for every positive $m$:
	\begin{equation}
		\label{eqn-S2S}
		S_2(\mathcal{S})=U_1+U_2+V_{m+1}+3V_1+2(V_2+\ldots+V_m).
	\end{equation}

	Note that, from \Cref{lem-centerOfAStar}, we can compute the label of $v_1$, and from \Cref{lem-leavesAndInternal} the composition of the three leaves ($U_1+U_2+V_{m+1}$) and of all internal vertices ($\sum_{i=2}^{m}V_i$). Furthermore, \Cref{cor-reconstructingStars} implies that the case $m \leq 1$ already holds. First, let $m = 2$. Since we already know the label of $v_1$, the other internal label is $v_2$. Furthermore, we have $S_3(\mathcal{S}) = 2U_1+2U_2+4V_1+3V_2+V_3$, allowing us to reconstruct $u_1$ and $u_2$, and thus $v_3$, completing the reconstruction of $\mathcal{S}$. Hence, for the rest of the proof, let us assume that $m \geq 3$.

	There are three types of subgraphs of order $i$ in $\mathcal{S}$ (for $3 \leq i \leq m+1$): one subgraph containing both $u_1$ and $u_2$ as well as $v_1,\ldots,v_{i-2}$, two subgraphs each containing one of either $u_1$ or $u_2$ as well as $v_1,\ldots,v_{i-1}$, and $m+2-i$ paths containing vertices $v_j,\ldots,v_{j+i-1}$ for $j \in \{1,\ldots,m+2-i\}$.

	In the following, we consider two cases, depending on the parity of $m$.

	\medskip\noindent\textbf{Case 1: $m$ is odd, so $m=2p-1$ for $p \geq 3$.} We will consider $2p-2$ queries, which will give the following results.
	First, for $i \in \{3,\ldots,p\}$,
	\begin{equation}\label{eqSi}
		S_i(\mathcal{S}) = 2(U_1+U_2) + \sum_{j=1}^{i-2} \left((j+3)V_j\right) + (i+1)V_{i-1} + \sum_{j=i}^{2p-i+1} \left( iV_j \right) + \sum_{j=1}^{i-1} \left( jV_{2p-j+1} \right). 
	\end{equation}
	Then, for $i \in \{1,\ldots,p\}$,
	\begin{equation}\label{eqSpi}
		S_{p+i}(\mathcal{S}) = 2(U_1+U_2) + \sum_{j=1}^{p-i} \left( (j+3)V_j \right) + \sum_{j=p-i+1}^{p+i-2} \left( (p-i+4)V_j \right) + (p-i+3)V_{p+i-1} + \sum_{j=1}^{p-i+1} \left( jV_{2p-j+1} \right).     
	\end{equation}


	\begin{claim}
		\label{clm-oddBranch-1}
		For $i \in \{1,\ldots,p-1\}$, \[S_{p+i}(\mathcal{S}) - S_{p+i+1}(\mathcal{S}) = \sum_{j=p-i+1}^{p+i-2} (V_j) - V_{p+i}.\]
	\end{claim}

	\begin{proof}[Proof of Claim \ref{clm-oddBranch-1}]
		By applying Equation (\ref{eqSpi}) twice, we obtain:
		\begin{eqnarray*}
			S_{p+i}(\mathcal{S}) - S_{p+i+1}(\mathcal{S}) & = & \left(2(U_1+U_2) + \sum_{j=1}^{p-i} \left( (j+3)V_j \right) + \sum_{j=p-i+1}^{p+i-2} \left( (p-i+4)V_j \right)\right. \\
			& & \left.+ (p-i+3)V_{p+i-1} + \sum_{j=1}^{p-i+1} \left( jV_{2p-j+1} \right)\right) \\
			& & - \left(2(U_1+U_2) + \sum_{j=1}^{p-i-1} \left( (j+3)V_j \right) + \sum_{j=p-i}^{p+i-1} \left( (p-i+3)V_j \right)\right. \\
			& & \left.+ (p-i+2)V_{p+i} + \sum_{j=1}^{p-i} \left( jV_{2p-j+1} \right)\right) \\
			& = & (p-i+3 - (p-i+3)) V_{p-i} + \sum_{j=p-i+1}^{p+i-2} \left( V_j \right) \\
			& & + (p-i+3 - (p-i+3))V_{p+i-1} + (p-i+1-(p-i+2))V_{p+i} \\
			& = & \sum_{j=p-i+1}^{p+i-2} (V_j) - V_{p+i}.\qedhere
		\end{eqnarray*}
	\end{proof}

	\begin{claim}
		\label{clm-oddBranch-2}
		For $i \in \{3,\ldots,p\}$, \[S_{i+1}(\mathcal{S}) - S_{i}(\mathcal{S}) = V_{i-1} + 2 V_i + \sum_{j=i+1}^{2p-i} (V_j).\]
	\end{claim}

	\begin{proof}[Proof of Claim \ref{clm-oddBranch-2}]
		By applying Equation (\ref{eqSi}) twice for $i\in\{3,\ldots, p-1\}$, we obtain:
		\begin{eqnarray*}
			S_{i+1}(\mathcal{S}) - S_{i}(\mathcal{S}) & = & \left(2(U_1+U_2) + \sum_{j=1}^{i-1} \left( (j+3)V_j \right) + (i+2)V_i\right. \\
			& &\left. + \sum_{j=i+1}^{2p-i} \left( (i+1)V_j \right) + \sum_{j=1}^{i} \left( jV_{2p-j+1} \right)\right) \\
			& & - \left(2(U_1+U_2) + \sum_{j=1}^{i-2} \left( (j+3)V_j \right) + (i+1)V_{i-1} \right.\\
			& &\left. + \sum_{j=i}^{2p-i+1} \left( iV_j \right) + \sum_{j=1}^{i-1} \left( jV_{2p-j+1} \right)\right) \\
			& = & (i+2 - (i+1)) V_{i-1} + (i+2 - i)V_i + \sum_{j=i+1}^{2p-i} \left( V_j \right) + (i-i)V_{2p-i+1} \\
			& = & V_{i-1} + 2 V_i + \sum_{j=i+1}^{2p-i} (V_j).
		\end{eqnarray*}

		We note that $S_{p+1}(\mathcal{S})-S_p(\mathcal{S})$ can be obtained with similar calculations by applying (\ref{eqSpi}) for $S_{p+1}(\mathcal{S})$.
	\end{proof}

	We next compute the labels of vertices in the following way: alternating between $S_{p+i+1}(\mathcal{S})-S_{p+i}(\mathcal{S})$ for $i \in \{1,\ldots,p-1\}$ and $S_{i'+1}(\mathcal{S})-S_{i'}(\mathcal{S})$ for $i' \in \{p,\ldots,3\}$, we will be able to find the labels of $v_{p+i}$ and both $v_{i'-1}$ and $v_{i'}$, respectively. We prove that we can do those computations by induction on $i \in \{1,\ldots,p-2\}$ and $i' \in \{p,\ldots,3\}$ (with $i$ increasing and $i'$ decreasing at each step; so $i+i'=p+1$). First, if $(i,i')=(1,p)$ and $p>2$, we compute, by \Cref{clm-oddBranch-1}:
	\[ S_{p+2}(\mathcal{S}) - S_{p+1}(\mathcal{S}) = V_{p+1}-\sum_{j=p-1+1}^{p+1-2} (V_j) = V_{p+1} \]
	which gives the label of $v_{p+1}$, and, by \Cref{clm-oddBranch-2}:
	\[ S_{p+1}(\mathcal{S}) - S_{p}(\mathcal{S}) = V_{p-1} + 2 V_p + \sum_{j=p+1}^{2p-p} (V_j) = V_{p-1} + 2V_p \]
	which gives the labels of $v_{p-1}$ and $v_p$ (if $V_p=V_{p-1}$, the same label appears thrice; otherwise, $v_p$ has the label that appears twice and $v_{p-1}$ the label that appears once).
	Note that, if $p=2$ (so we are reconstructing $\mathcal{S}=(S_{1,1,3},\lambda)$), there is an adjustment: we apply \Cref{clm-oddBranch-1} with $i=1$ and compute $S_4(\mathcal{S})-S_3(\mathcal{S})=V_3$. We can then deduce the label of $v_2$ which is the last of the three internal vertices (recall that we have already obtained the label of the center vertex $v_1$). Next, we use Equations~(\ref{eqn-S2S}) and (\ref{eqSi}) to compute $S_3(\mathcal{S})-S_2(\mathcal{S})=U_1+U_2+V_1+2V_2$, obtaining the labels of $u_1$ and $u_2$, after which we can find the label of $v_4$. This ends the reconstruction for $p=2$. For the rest of Case~1, we assume that $p \geq 3$.

	Assume now that the statement holds for a pair $(i-1,i'+1)$, so we know the labels of $v_{p-i+1},\ldots,v_{p+i-1}$. We compute, by \Cref{clm-oddBranch-1}:
	\begin{eqnarray*}
		S_{p+i+1}(\mathcal{S}) - S_{p+i}(\mathcal{S}) & = & V_{p+i} - \sum_{j=p-i+1}^{p+i-2} (V_j) \\
		& = & V_{p+i} - \sum_{j=i'}^{p+i-2} (V_j) \\
		& = & V_{p+i} - Q
	\end{eqnarray*}
	where $Q$ is a known quantity by induction hypothesis, hence we obtain the label of $v_{p+i}$. Therefore, we obtain labels $V_{p},\ldots, V_{p+i}$.
	Using now \Cref{clm-oddBranch-2}, we compute:
	\begin{eqnarray*}
		S_{i'+1}(\mathcal{S}) - S_{i'}(\mathcal{S}) & = & V_{i'-1} + 2 V_{i'} + \sum_{j=i'+1}^{2p-i'} (V_j) \\
		& = & V_{i'-1} + 2 V_{i'} + \sum_{j=i'+1}^{p+i-1} (V_j) \\
		& = & V_{i'-1} + Q' \\
	\end{eqnarray*}
	where $Q'$ is a known quantity by induction hypothesis, hence we obtain the label of $v_{i'-1}$. Hence, when $i$ traverses from $1$ to $p-2$ and $i'$ from $p$ to $3$, we are able to compute the labels of $v_2,\ldots,v_{2p-2}$ (and the label of $v_1$ was already known). Now, using one last time \Cref{clm-oddBranch-1}, we compute
	\[ S_{2p}(\mathcal{S}) - S_{2p-1}(\mathcal{S}) = V_{2p-1} - \sum_{j=2}^{2p-3} (V_j) = V_{2p-1} + Q'' \]
	where $Q''$ is a known quantity, allowing us to find the label of $v_{2p-1}$.
	We now only have to find the label of $v_{2p}$. We observe that $S_{2p+1}(\mathcal{S}) =  2(U_1+U_2) + \sum_{j=1}^{2p-1} \left( 3V_j \right) + 2V_{2p}$, which leads to:
	\begin{eqnarray*}
		S_{2p+1}(\mathcal{S}) - S_{2p}(\mathcal{S}) & = & 2(U_1+U_2) + \sum_{j=1}^{2p-1} \left( 3V_j \right) + 2V_{2p} - 2(U_1+U_2) - \sum_{j=1}^{2p-2} \left( 4V_j \right) - 3V_{2p-1} - V_{2p} \\
		& = & V_{2p} - \sum_{j=1}^{2p-2} V_j \\
		& = & V_{2p} + Q'''
	\end{eqnarray*}
	where $Q'''$ is a known quantity. The labels of $u_1$ and $u_2$ are now the two labels of leaves remaining. Recall that we already found the composition $U_1+U_2+V_{m+1}$. Hence, we can also deduce the labels of $u_1$ and $u_2$.
	This concludes the case where $m$ is odd.

	\medskip\noindent\textbf{Case 2: $m$ is even, so $m=2p$ for $p \geq 2$.}
	Let us first consider the case with $p=2$ (so we are reconstructing $\mathcal{S}=(S_{1,1,4},\lambda)$), which will serve as a concrete example of the case disjunction that we are going to need for this case. This is necessary since one main equation needed for the proof (\Cref{clm-evenBranch-1}) does not hold for this small graph. We have $S_5(\mathcal{S})-S_4(\mathcal{S})=V_4-V_2$. We divide our considerations according to whether we have $V_2 \neq V_4$ or $V_2 = V_4$. If $V_2\neq V_4$, then we can know $V_2$ and $V_4$. Hence, we may deduce $V_3=I-V_1-V_2-V_4$ and $U_1,U_2$ from $S_3(\mathcal{S})-S_2(\mathcal{S})=U_1+U_2+V_1+2V_2+V_3$. Finally, we may finish with $V_5=L-U_1-U_2$.
	If $V_2=V_4$, then we compute $S_4(\mathcal{S})-S_3(\mathcal{S})=V_2+V_3$, so if $V_2=V_3$ we are done (this gives their value, and we then conclude as above). Assume then that $V_2 \neq V_3$, we use Equation~(\ref{eqn-S2S}) to compute $S_6(\mathcal{S})-S_2(\mathcal{S})=U_1+U_2+V_2+V_3+V_4+V_5=L+2V_2+V_3$ where $L$ is the sum of the labels of leaves (which is known). This gives us the values of $V_2$ and $V_3$, and we then conclude as above.
	For the rest of Case~2, we assume that $p \geq 3$.

	We will consider $2p-1$ queries, which will give the following results. First, for $i \in \{3,\ldots,p+1\}$,
	\begin{equation}\label{eqSiEven}
		S_i(\mathcal{S}) = 2(U_1+U_2) + \sum_{j=1}^{i-2} \left( (j+3)V_j \right) + (i+1)V_{i-1} + \sum_{j=i}^{2p-i+2} \left( iV_j \right) + \sum_{j=1}^{i-1} \left( jV_{2p-j+2} \right). 
	\end{equation}
	Then, for $i \in \{1,\ldots,p\}$,
	\begin{equation}\label{eqSpiEven}
		S_{p+1+i}(\mathcal{S}) = 2(U_1+U_2) + \sum_{j=1}^{p-i+1} \left( (j+3)V_j \right) + \sum_{j=p-i+2}^{p+i-1} \left( (p+4-i)V_j \right) + (p+3-i)V_{p+i} + \sum_{j=1}^{p-i+1} \left( jV_{2p-j+2} \right). \end{equation}

	\begin{claim}
		\label{clm-evenBranch-1}
		For $i \in \{3,\ldots,p\}$:
		\[ S_{i+1}(\mathcal{S}) - S_i(\mathcal{S}) = V_{i-1} + 2V_i + \sum_{j=i+1}^{2p-i+1} \left( V_j \right). \]
	\end{claim}

	\begin{proof}[Proof of Claim \ref{clm-evenBranch-1}]        By applying Equation (\ref{eqSiEven}) twice, we obtain for $i \in \{3,\ldots,p\}$
		\begin{eqnarray*}
			S_{i+1}(\mathcal{S}) - S_i(\mathcal{S}) & = & \left(2(U_1+U_2) + \sum_{j=1}^{i-1} \left( (j+3)V_j \right) + (i+2)V_{i} + \sum_{j=i+1}^{2p-i+1} \left( (i+1)V_j \right) + \sum_{j=1}^{i} \left( jV_{2p-j+2} \right)\right) \\
			& & - \left(2(U_1+U_2) + \sum_{j=1}^{i-2} \left( (j+3)V_j \right) + (i+1)V_{i-1} + \sum_{j=i}^{2p-i+2} \left( iV_j \right) + \sum_{j=1}^{i-1} \left( jV_{2p-j+2} \right)\right) \\
			& = & \left( (i-1+3)-(i+1) \right) V_{i-1} + \left( i+2-i \right) V_i + \sum_{j=i+1}^{2p-i+1} \left( V_j \right) + (i-i)V_{2p-i+2} \\
			& = & V_{i-1} + 2V_i + \sum_{j=i+1}^{2p-i+1} \left( V_j \right).\qedhere
		\end{eqnarray*}%\todo{T: I think there is an error comes here from the last step. The top $+1$ changes into $-1$}
	\end{proof}

	\begin{claim}
		\label{clm-evenBranch-2}
		For $i \in \{ 1,\ldots,p-1\}$:
		\[ S_{p+1+i}(\mathcal{S}) - S_{p+2+i}(\mathcal{S}) = V_{p-i+1} - V_{p+i+1} + \sum_{j=p-i+2}^{p+i-1} \left( V_j \right). \]
	\end{claim}

	\begin{proof}[Proof of Claim \ref{clm-evenBranch-2}]  By applying Equation (\ref{eqSpiEven}) twice, we obtain for $i \in \{ 1,\ldots,p-1\}$
		\begin{eqnarray*}
			S_{p+1+i}(\mathcal{S}) - S_{p+2+i}(\mathcal{S}) & = & \left(2(U_1+U_2) + \sum_{j=1}^{p-i+1} \left( (j+3)V_j \right) + \sum_{j=p-i+2}^{p+i-1} \left( (p+4-i)V_j \right)\right. \\
			& & \left.+ (p+3-i)V_{p+i} + \sum_{j=1}^{p-i+1} \left( jV_{2p-j+2} \right)\right) \\
			& & - \left(2(U_1+U_2) + \sum_{j=1}^{p-i} \left( (j+3)V_j \right) + \sum_{j=p-i+1}^{p+i} \left( (p+3-i)V_j \right)\right. \\
			& &\left. + (p+2-i)V_{p+i+1} + \sum_{j=1}^{p-i} \left( jV_{2p-j+2} \right)\right) \\
			& = & \left( (p-i+1+3) - (p+3-i) \right) V_{p-i+1} + \sum_{j=p-i+2}^{p+i-1} \left( V_j \right) \\
			& & + \left( (p+3-i) - (p+3-i) \right) V_{p+i} + \left( (p-i+1) - (p+2-i) \right) V_{p+i+1} \\
			& = & V_{p-i+1} - V_{p+i+1} + \sum_{j=p-i+2}^{p+i-1} \left( V_j \right).\qedhere
		\end{eqnarray*}
	\end{proof}

	We now start computing the labels of vertices. First, note that by Claim \ref{clm-evenBranch-1} with $i=p$ we have:
	\begin{equation}\label{eqSp1Sp}
		S_{p+1}(\mathcal{S}) - S_p(\mathcal{S}) = V_{p-1} + 2V_p + V_{p+1}.
	\end{equation}

	We can derive two subcases from Equation~(\ref{eqSp1Sp}).

	\medskip\noindent\textbf{Subcase 2.1: $V_{p-1} \neq V_{p+1}$, or $V_{p-1}=V_p=V_{p+1}$.} In this case, $S_{p+1}(\mathcal{S}) - S_p(\mathcal{S})$ clearly allows us to deduce $V_p$ (it is the value that is repeated at least twice). From Equations (\ref{eqSiEven}) and (\ref{eqSpiEven}) for $i=p+1$ and $i=1$, respectively, we obtain $S_{p+2}(\mathcal{S})-S_{p+1}(\mathcal{S}) = V_p + V_{p+1}$. Since we already know $V_p$, we obtain the label of $v_{p+1}$, and thus the label of $v_{p-1}$ from Equation (\ref{eqSp1Sp}). Now, like in Case~1, we use induction and alternate between $S_{p+1+i}(\mathcal{S}) - S_{p+2+i}(\mathcal{S})$ and $S_{i'+1}(\mathcal{S})-S_{i'}(\mathcal{S})$, for increasing $i \in \{1,\ldots,p-3\}$ and decreasing $i' \in \{p-1,\ldots,3\}$, respectively.
	Doing so allows us to know the labels of $v_{i'-1},\ldots,v_{p+i+1}$ 
	for the pair $(i,i')$ where $i+i'=p$. Hence, our induction hypothesis is that after computing the pair $(i,i')$, we know the labels of $v_{i'-1},\ldots,v_{p+i+1}$. Once this is done, we finish with $i\in\{p-2,p-1\}$. By \Cref{clm-evenBranch-2} and induction hypothesis, we have
	\begin{equation}\label{eqC2.1eqi}
		S_{p+1+i}(\mathcal{S}) - S_{p+2+i}(\mathcal{S})=V_{p-i+1}-V_{p+i+1}+\sum_{j=p-i+2}^{p+i-1}(V_j),
	\end{equation}
	which allows us to compute the label of $v_{p+i+1}$. By \Cref{clm-evenBranch-1}, we also have
	$$S_{i'+1}(\mathcal{S})-S_{i'}(\mathcal{S})=V_{i'-1}+2V_{i'}+\sum_{j=i'+1}^{2p-i'+1}(V_j).$$
	Hence, the induction hypothesis together with the label of $v_{p+i+1}$ allows us to compute the label of $v_{i'-1}$. Note that as we have mentioned above, there are more potential values for $i$ than for $i'$ in order to compute all the internal labels. Hence, we first alternate between $i$ and $i'$ until the case $(p-2,3)$. At this point, we know the labels of $v_1,\dots, v_{2p-2}$. After this, we use Equation~(\ref{eqC2.1eqi}) for $i=p-2$ and $i=p-1$ which gives the labels of $v_{2p-1}$ and $v_{2p}$.
	We can again conclude by computing the label of $v_{2p+1}$ (from $S_{2p+1}(\mathcal{S})-S_{2p+2}(\mathcal{S})=\sum_{i=1}^{2p-1} (V_i) - V_{2p+1}$), allowing us to deduce the labels of $u_1$ and $u_2$, and thus completing the reconstruction.

	\medskip\noindent\textbf{Subcase 2.2: $V_{p-1} = V_{p+1}$ and $V_{p-1} \neq V_p$.} In this case, \Cref{eqSp1Sp} gives $S_{p+1}(\mathcal{S}) - S_p(\mathcal{S})= V_{p-1} + 2V_p + V_{p+1}$ and does not allow us to decide on the values of $V_{p-1}$ and $V_p$. Now, like in Case~1 and Subcase~2.1, we will use induction and alternate operations. However, this time, we will prove by induction either that, for values of $i$ that will be given later, $V_{2i}=V_{2i+2}$ and $V_{2i-1}=V_{2i+1}$ (depending on the parity of the induction step) and that $V_{2i-1}\neq V_{2i}$, or that we are able to determine the values of $V_{p-i},\ldots,V_{p+i}$ (after which we start a second induction, exactly like in Case~1 and Subcase~2.1, which will allow us to compute the remaining labels $V_{j}$).

	To start the induction, note that $V_{p-1}=V_{p+1}\neq V_p$, and let us denote for readability and without loss of generality that $V_{p-1}=V_{p+1}=A$ and $V_p=B$ (though we do not know these values yet). Assume that, for a given $0\leq i\leq \frac{p-3}{2}$, we have $V_{p-2j}=V_{p+2j}=B$ and $V_{p-2j-1}=V_{p+2j+1}=A$ for each $j \in \{0,\ldots,i\}$. This is our induction hypothesis, which holds for the base case $i=0$.

	Every main step of the induction is comprised of an \emph{even} and an \emph{odd} step, each seeing two computations using \Cref{clm-evenBranch-1,clm-evenBranch-2}. At any point during those two steps, we may actually collapse all values (that is, be able to know the values of $V_{p-1}$ and $V_p$, and thus all the other values that are equal to those) and end this induction. During the even step, we try to compute the values of $V_{p+2i}$ and then of $V_{p-2i}$. If we are able to determine their actual value, then the induction ends. Otherwise, we get $V_{p-2i}=V_{p+2i}=V_p$. Then, during the odd step, we try to compute the values of $V_{p+2i+1}$ and then of $V_{p-2i-1}$. Again, either we are able to determine them and the induction ends, or we get $V_{p-2i-1}=V_{p+2i+1}=V_{p-1}$. In the latter case, we continue the induction.

	\smallskip
	We first detail the \emph{even} case of the induction step, where we try to compute the values of $V_{p+2i}$ and then of $V_{p-2i}$. By induction hypothesis, we have $V_{p-2i+2}=V_{p-2i+4}=\cdots=V_{p+2i-2}=B$ and $V_{p-2i+1}=V_{p-2i+3}=\cdots=V_{p+2i-1}=A$.
	We compute, by \Cref{clm-evenBranch-2} and induction hypothesis (we have $1 \leq i \leq  \frac{p-3}{2}$):
	\begin{eqnarray*}
		S_{p+2i}(\mathcal{S}) - S_{p+1+2i}(\mathcal{S}) & = & V_{p-2i+2} - V_{p+2i} + \sum_{j=p-2i+3}^{p+2i-2} \left( V_j \right) \\
		& = & V_{p-2i+2} - V_{p+2i} + \sum_{\substack{j=p-2i+4 \\ j-p \text{ even}}}^{p+2i-2} \left( V_j \right) + \sum_{\substack{j=p-2i+3 \\ j-p \text{ odd}}}^{p+2i-3} \left( V_j \right) \\
		& = & B - V_{p+2i} + (2i-2)B + (2i-2)A.
	\end{eqnarray*}
	Now, if $V_{p+2i}=B$, then, we are still in the induction loop, since we cannot decide the value of $B$ with the equation. Indeed, we can in this case only know that $V_{p+2i}=V_{p}$. Otherwise, the equation allows us to ``collapse'' the unknown values of $V_{p-2i+1},\ldots,V_{p+2i-1}$, as well as the value of $V_{p+2i}$, in which case we end the induction. Recall that by induction hypothesis, we have $V_{p-2i+2}=V_{p-2i+4}=\cdots=V_{p+2i-2}=B$ and $V_{p-2i+1}=V_{p-2i+3}=\cdots=V_{p+2i-1}=A$.
	Similarly, using \Cref{clm-evenBranch-1}, the induction hypothesis, and the fact that $V_{p+2i}=B$ (we have $1\leq i \leq  \frac{p-3}{2}$):
	\begin{eqnarray*}
		S_{p+2-2i}(\mathcal{S}) - S_{p+1-2i}(\mathcal{S}) & = & V_{p-2i} + 2V_{p-2i+1} + \sum_{j=p-2i+2}^{p+2i} \left( V_j \right) \\
		& = & V_{p-2i} + 2A + (2i-1)A + (2i)B.
	\end{eqnarray*}
	Again, if $V_{p-2i} = B$, then, we cannot decide the values with the equation and thus, we remain in the induction loop; otherwise, we can deduce the value of $B$ as well as the unknown values of $V_{2p-2i+1},\ldots,V_{p+2i-1}$. In the latter case, we end this induction.

	\smallskip
	Let us next detail the \emph{odd} case of the induction step, where we try to compute the values of $V_{p+2i+1}$, and then of $V_{p-2i-1}$. Note that it is very similar to the even case.
	By induction hypothesis and after the even step, we have $V_{p-2i}=V_{p-2i+2}=\cdots=V_{p+2i}=B$ and $V_{p-2i+1}=V_{p-2i+3}=\cdots=V_{p+2i-1}=A$.
	We compute, by \Cref{clm-evenBranch-2} and induction hypothesis (we have $1 \leq i \leq  \frac{p-3}{2}$):
	\begin{eqnarray*}
		S_{p+1+2i}(\mathcal{S}) - S_{p+2+2i}(\mathcal{S}) & = & V_{p-2i+1} - V_{p+2i+1} + \sum_{j=p-2i+2}^{p+2i-1} \left( V_j \right) \\
		& = & V_{p-2i+1} - V_{p+2i+1} + \sum_{\substack{j=p-2i+2 \\ j-p \text{ even}}}^{p+2i-2} \left( V_j \right) + \sum_{\substack{j=p-2i+3 \\ j-p \text{ odd}}}^{p+2i-1} \left( V_j \right) \\
		& = & A - V_{p+2i+1} + (2i-1)B + (2i-1)A.
	\end{eqnarray*}
	Again, if $V_{p+2i+1}=A$, then, we are still in the induction loop, since we cannot decide the value of $A$ with the equation. Indeed, we can in this case only know that $V_{p+2i+1}=V_{p-1}=V_{p+1}$. Otherwise, the equation allows us to ``collapse'' the unknown values of $V_{p-2i+1},\ldots,V_{p+2i-1}$, as well as the value of $V_{p+2i+1}$, in which case we end the induction. Recall that by induction hypothesis and after the even step, we have $V_{p-2i}=V_{p-2i+4}=\cdots=V_{p+2i}=B$ and $V_{p-2i+1}=V_{p-2i+3}=\cdots=V_{p+2i-1}=A$. Similarly, using \Cref{clm-evenBranch-1}, the induction hypothesis, and the facts that $V_{p+2i+1}=A$ and $V_{p-2i}=B$ (we have $1\leq i \leq \frac{p-3}{2}$):%This case is unclear
	\begin{eqnarray*}
		S_{p-2i+1}(\mathcal{S})-S_{p-2i}(\mathcal{S}) & = & V_{p-2i-1} + 2V_{p-2i} + \sum_{j=p-2i+1}^{p+2i+1} \left( V_j \right) \\
		& = & V_{p-2i-1} + 2B + (2i+1)A + (2i)B.
	\end{eqnarray*}
	Again, if $V_{p-2i-1} = A$, then, we cannot decide their values with the equation and thus are still in the induction loop; if at least one of those conditions does not hold, then we can deduce their values as well as the unknown values of $V_{2p-2i+1},\ldots,V_{p+2i-1}$, in which case the induction ends.

	\smallskip
	Hence, either we are able to determine the unknown values (ending the induction at any point during the even or odd step), after which we complete the reconstruction using the same method as in Case~1 and Subcase~2.1 (we do not give the details here, since this leads to the exactly same computations, so we refer the reader to Case~1), or the induction continues until we reach the last possible value for $i$.

	If the induction does not stop early and we continue in this way until $i=\lfloor \frac{p-3}{2}\rfloor$, then, by (the already proved) induction hypothesis, for an odd $p$ we have $V_2=V_4=\cdots=V_{2p-2}=A$ and $V_3=V_5=\cdots=V_{2p-3}=B$. We then compute $S_{2p-1}(\mathcal{S})-S_{2p}(\mathcal{S})$ to obtain $V_{2p-1}$ and $S_{2p}(\mathcal{S})-S_{2p+1}(\mathcal{S})$ to obtain $V_{2p}$. As above, we check if these computations cause the collapse and allow us to finish the proof as in Case~1. If not, we have $V_2=V_4=\cdots=V_{2p}=A$ and $V_3=V_5=\cdots=V_{2p-1}=B$. Recall that we know the labels of the leaves, and let $L$ be the sum of those three labels. Hence, $S_1(\mathcal{S})-L-V_1=pA+(p-1)B$ and therefore, we can deduce the values of both $A$ and $B$.

	Consider then an even $p$. We have, by (the already proved) induction hypothesis, $V_3=V_5=\cdots=V_{2p-3}=A$ and $V_4=V_6=\cdots=V_{2p-4}=B$. We then compute first $S_{4}(\mathcal{S})-S_{3}(\mathcal{S})$ to obtain $V_{2}$. After this, we obtain values of $V_{2p-2}, V_{2p-1}$ and $ V_{2p}$ by computing $S_{2p-2}(\mathcal{S})-S_{2p-1}(\mathcal{S})$, $S_{2p-1}(\mathcal{S})-S_{2p}(\mathcal{S})$ and $S_{2p}(\mathcal{S})-S_{2p+1}(\mathcal{S})$, respectively. As above, we check if these computations cause the collapse and allow us to finish the proof as in Case~1. If not, we have $V_2=V_4=\cdots=V_{2p}=B$ and $V_3=V_5=\cdots=V_{2p-1}=A$. Hence, $S_1(\mathcal{S})-L-V_1=pB+(p-1)A$ and therefore, we can again deduce the values of both $A$ and $B$.

	\smallskip
	Hence, we know all the labels of $v_1,\ldots,v_{2p}$. Note that knowing the value of $V_1$ was primordial for this last part, which will be important later in \Cref{thm-triangleWithTail}. Finally, by computing $S_{2p+1}(\mathcal{S}) - S_{2p+2}(\mathcal{S}) = \sum_{i=1}^{2p-1} \left( V_i \right) - V_{2p+1}$, we can compute the label of $v_{2p+1}$, and thus the labels of $u_1$ and $u_2$ which are the two other leaves, completing the reconstruction.
\end{proof}

\subsection{Summary}
\label{subsec-SummaryOfReconstructing}

We considered several families of trees, which we were able to reconstruct. There are a few interesting remarks to draw from this. First, note that not all paths are reconstructable~\cite{acharya2015string}, but creating a false twin of one of the leaves of a path, that is appending a leaf to its second vertex, makes the graph always reconstructable (\Cref{thm-reconstructingS11k} for $S_{1,1,m}$). A natural question would be to further this by appending a leaf to other vertices of a path, studying the reconstructability of the subdivided star $S_{1,m,t}$. As we will see later (\Cref{fig-s123}), this family is not reconstructable in general, but it might be possible under some conditions (such as $m \leq \frac{t}{4}$).

However, the most interesting point is the diversity of algorithms for reconstruction that we found. As explained in \Cref{SecLabels}, one can reconstruct a reconstructable graph by enumerating all subgraph composition multisets of all possible labelings and comparing it to the subgraph composition multiset of the graph, but doing so can be extremely costly. We are able to be way more fine-grained, using only two sum-queries to reconstruct a star (\Cref{cor-reconstructingStars}), and four queries (one multiset and three sums) for stars subdivided at most once when the alphabet contains two symbols (\Cref{thm-reconstructingStarsSubdividedAtMostOnce}). For bistars, the alphabet size plays a role: with two symbols, three queries (two sums and one multiset) are enough (\Cref{thm-reconstructingBistarsK2}), which is also the case for a larger alphabet if the two non-leaves have different labels (Case 1 of \Cref{thm-reconstructingBistarsAnyK}). However, if those vertices have different labels, then, we may have to apply a brute-force method to find a specific composition (Case~2 of \Cref{thm-reconstructingBistarsAnyK}). Finally, for the star $S_{1,1,m}$, we use $m+1$ sum-queries, and may have different methods depending on the parity of $m$ (\Cref{thm-reconstructingS11k}).

These very different methods of reconstruction are particularly interesting, and we conjecture that the methods used above are all optimal, meaning that no reconstruction algorithm for those classes can use fewer queries. This also begs the question of the existence of graphs for which, without using a brute-force reconstruction, the highest possible number of stronger queries (that is, a linear number of multiset-queries) would still be needed. Similarly, the classes we studied either can be reconstructed using a constant and small number of queries, or seem to require a linear number of queries; are there classes that require a logarithmic, or a sublinear but non-constant number of queries?

Another question that arises from the study of bistars and stars subdivided at most once is the part played by alphabet size. Which other classes require different algorithms for reconstruction, and in particular a difference between a constant and a linear number of queries when the alphabet size $k\geq2$ passes certain thresholds?

\section{Smallest confusable graphs}\label{secSmallConfusable}

In this section, we enumerate the smallest confusable graphs and trees, and construct a general family of graphs with a dichotomy between confusable and sum-reconstructable members depending on parity of their order. We also give the smallest non-sum-reconstructable graphs.

\begin{theorem}
	\label{thm-smallestConfusableGraphs}
	The smallest confusable graphs have order~5. The smallest confusable tree has order~7.
\end{theorem}

\begin{proof}
	This is an expansion on results from~\cite{acharya2015string,bartha2021reconstructibility,bartha2016reconstruction}. As in the proof of \Cref{thm-reconstructingS11k}, for sum-queries, $X$ denotes the label of vertex $x$.

	\medskip\noindent\textbf{Smallest confusable graphs.} No graphs of order at most~3 can be confusable, since those graphs the are paths or complete graphs.

	There are six connected graphs of order~4, three of them (path $P_4$, star $S_3$ and clique $K_4$) are clearly reconstructable. The cycle $C_4$ can easily be reconstructed: let $A$ be a label of a vertex, we can immediately finish if either of $A^i \in \mathcal{M}_i(\mathcal{G})$ holds for $i \in \{2,3,4\}$; otherwise, if $\mathcal{M}_4(\mathcal{G})=\{A^2XY\}$ with $X,Y \neq A$ we have two non-adjacent vertices with label $A$ and we are done, and if $\mathcal{M}_4(\mathcal{G})=\{AXYZ\}$ with $X,Y,Z \neq A$ we use $\mathcal{M}_2(\mathcal{G})$ to find the labels of the two vertices adjacent to the vertex with label $A$ and conclude with the last label. Note however that $C_4$ is not sum-reconstructable since every vertex appears with the same multiplicity in every $S_i(\mathcal{G})$.

	The diamond graph with vertices $V=\{u,v,w,x\}$ and edges $E=\{uv,vw,wx,xu,uw\}$, that is, complete graph $K_4$ without the edge $vx$, can easily be reconstructed. Indeed, since the query $S_2(\mathcal{G})-2S_1(\mathcal{G})$ gives the labels of $u$ and $w$, after which we can know the labels of $v$ and $x$. Vertices $u$ and $w$, and $v$ and $x$, respectively, are at symmetrical positions and hence, this is enough.

	Finally, the paw (a triangle with a vertex adjacent to one vertex of the triangle) can be reconstructed since the degree~3 vertex is the only one in all three subgraphs of order~3 (the other ones appear in two) so its label can be be computed with $S_3(\mathcal{G})-2S_1(\mathcal{G})$. After this, the label of the degree~1 vertex can be computed with $2S_1(\mathcal{G})-S_2(\mathcal{G})$ together with the knowledge of the label of the degree 3 vertex. Finally, we can find the labels of the two degree~2 vertices which are at symmetrical positions. Hence, no graph of order~4 is confusable.

	The line graph of the graph in Example~2 in~\cite{bartha2016reconstruction} (depicted on Figure~1 in their paper) is confusable, as proved in \Cref{thm-triangleWithTail} and seen in Figure~\ref{fig5verteqcomp}.
	Furthermore, the gem (a path plus one universal vertex) is confusable; consider the two labelings depicted on \Cref{fig-gemeqcomp}, we have, for both of them, $\mathcal{M}_1(\mathcal{G})=\{\{ 3A,2B \}\}$ $\mathcal{M}_2(\mathcal{G})= \{\{ 2A^2,B^2,4AB \}\}$, $\mathcal{M}_3(\mathcal{G})=\{\{ A^3,4A^2B,3AB^2 \}\}$ and $\mathcal{M}_4(\mathcal{G})=\{\{ 2A^3B,3A^2B^2 \}\}$.

	Let us next consider the remaining 19 connected graphs of order~5. Some can be managed easily: $K_5$, $P_5$, $S_4$ and $S_{1,1,2}$ are all reconstructable by~\cite{acharya2015string}, \Cref{cor-reconstructingStars} and \Cref{thm-reconstructingS11k}. In the following, we consider the remaining graphs of order~5, see~\cite{smallGraphs} for a list of 5-vertex graphs.

	\begin{enumerate}  \setcounter{enumi}{4}

		\item $K_5$ minus an edge. For this graph, the query $S_{2}(\mathcal{G})$ counts three times the two degree~3 vertices and four times the three degree~4 vertices, which can be separated. Since they are symmetrical, this is enough for reconstruction.

		\item $K_4$ plus one degree~2 vertex. Let $u_1$ and $u_2$ be the degree~3 vertices, $v_1$ and $v_2$ be the degree~4 vertices, and $w$ be the degree~2 vertex. We have $4S_3(\mathcal{G})-6S_2(\mathcal{G})=2(U_1+U_2)+8W$, from which we can clearly deduce the label of $w$, and thus the labels of $u_1$ and $u_2$, after which we can easily know the labels of $v_1$ and $v_2$.

		\item An edge to which three false twins are connected. The endpoints of the edge can be found using $S_2(\mathcal{G}) - 2S_1(\mathcal{G})$, after which we can deduce the labels of the three twins.

		\item $K_4$ plus a leaf. For this graph, the query $S_{2}(\mathcal{G})$ counts three times the three degree~3 vertices, four times the degree~4 vertex, and the leaf once. Hence, $S_2(\mathcal{G})-3S_5(\mathcal{G})$ allows us to find the label of the leaf (which is "negative") and of the degree~4 vertex. The last three vertices are twins, so this is enough.

		\item The cycle $C_4$ plus a vertex of degree~3. Let $u$ be the degree~2 vertex, $v_1$ and $v_2$ be its neighbours (those are false twins), and $w_1$ and $w_2$ be the other two vertices (those are true twins). We have $S_3(\mathcal{G})=5U+6(V_1+V_2)+5(W_1+W_2)$, so we can deduce the labels of $v_1$ and $v_2$. Furthermore, $S_2(\mathcal{G})$ counts three times each vertex, except $u$ which is counted twice, hence we can know its label too. This leaves the last two labels for $w_1$ and $w_2$, completing the reconstruction.

		\item The wheel $W_4$ (a cycle plus one universal vertex) can be reconstructed from $S_2(\mathcal{G})$: the four vertices of the cycle are symmetrical and counted three times each while the universal vertex is counted four times.

		\item The cycle $C_5$ can be reconstructed. Assume that the symbol $A$ is used in the labeling. Clearly, if $A^5$, $A^4$ or $A^3$ appear in $\mathcal{M}_5(\mathcal{G})$, $\mathcal{M}_4(\mathcal{G})$ or $\mathcal{M}_3(\mathcal{G})$, respectively, then we are done. If none holds, but $A^2$ appears in $\mathcal{M}_2(\mathcal{G})$, then two adjacent vertices are labeled with $A$ and their two neighbours are labeled with other symbols. If the number of $A$'s (found with $\mathcal{M}_5(\mathcal{G})$) is~3, then, the fifth vertex is labeled with $A$ and we are done. Otherwise, the query $\mathcal{M}_2(\mathcal{G})$ contains exactly two compositions $AX$ and $AY$, which give us the labels of the two neighbours, and the last vertex has the last label. Now, if there are no two consecutive $A$'s, then, there are two possibilities. Assume first that two vertices are labeled with $A$, they are at distance~2 from each other, we can find the label $X$ of their common neighbour with the composition $A^2X$ in query $\mathcal{M}_3(\mathcal{G})$, and the last two vertices are symmetric, so we are done. Assume next that each  vertex has a unique label. Let one of the vertices have label $A$. We can know the labels of its neighbours with compositions $AX$ and $AY$ in query $\mathcal{M}_2(\mathcal{G})$, after which the same query will contain compositions $XW_1$, $YW_2$ and $W_1W_2$, from which we can clearly deduce the last two labels. %(the only possible confusion would be if $\{X,Y\}=\{W_1,W_2\}$, which is resolved by isomorphism of the labelings it generates).

		\item The butterfly (two triangles attached together through a vertex $c$) can be reconstructed: the label of $c$ can be found with $S_2(\mathcal{G})-2S_1(\mathcal{G})$ since it is the only vertex appearing four times in $\mathcal{S}_2(\mathcal{G})$ (all the other ones appear twice), and then the multiset-query $\mathcal{M}_2(\mathcal{G})$ can be used to eliminate all the compositions with $c$ in it, leaving only two compositions corresponding to the pairs on each triangle.

		\item The kite (a cycle $vw_1xw_2$ with an edge $w_1w_2$, and a leaf $u$ attached to $v$) can be reconstructed. We have $S_3(\mathcal{G})-(S_2(\mathcal{G})+S_5(\mathcal{G})=V$, after which $2S_2(\mathcal{G})-S_3(\mathcal{G})=V+2(W_1+W_2)+X$ so we can find the labels of $w_1$ and $w_2$ (those are repeated twice, and are symmetric) and of $x$ (it appears an odd number of times). Finding the label of $u$ is then trivial.

		\item The dart (a cycle $vw_1xw_2$ with an edge $vx$ and a leaf $u$ attached to $v$) can be reconstructed. We have $S_2(\mathcal{G})+2S_5(\mathcal{G})-S_3(\mathcal{G}=X$, after which $S_3(\mathcal{G})-2S_2(\mathcal{G})=U-2V-2X$ so we can find the labels of $u$ and $v$. Finding the labels of $w_1$ and $w_2$ is trivial (both are false twins and we do not need to separate them).

		\item The house (a cycle $v_1w_1w_2v_2$ with a vertex $u$ adjacent to both $v_1$ and $v_2$). We have $S_2(\mathcal{G})-2S_5(\mathcal{G})=V_1+V_2$ and $2S_2(\mathcal{G})-S_3(\mathcal{G})=U+V_1+V_2$ so we know those three labels. All that is left is to decide which of the two remaining labels are $W_1$ and $W_2$, which we can deduce using $\mathcal{M}_2(\mathcal{G})$ (the only possible confusion would be if $W_1=V_2$ and $W_2=V_1$, which is not a problem since the two possible labelings would be isomorphic).

		\item The banner (a cycle $vw_1xw_2$ with a leaf $u$ attached to $v$) can be reconstructed. We have $S_4(\mathcal{G})-3S_5(\mathcal{G})=V$, after which $S_2(\mathcal{G})-2S_5(\mathcal{G})=V-U$ so we know the label of $u$ (whether $U=V$ or not). Furthermore, we have $2S_2(\mathcal{G})-S_3(\mathcal{G})=V+X$ from which we know the label of $x$, and we can find the labels of false twins $w_1$ and $w_2$.

		\item The cricket (a triangle $vw_1w_2$ with two leaves $u_1$ and $u_2$ attached to $v$) can be reconstructed. We have $S_2(\mathcal{G})+2S_5(\mathcal{G})-S_3(\mathcal{G})=W_1+W_2$ (both $w_1$ and $w_2$ are twins, so we know their labels), after which $3S_2(\mathcal{G})-S_3(\mathcal{G})=6V+3(W_1+W_2)$ so we can find the label of $v$. Finally, finding the labels of $u_1$ and $u_2$ is trivial (both are false twins).

		\item The bull (a triangle $v_1v_2w$ with two leaves $u_1$ and $u_2$ attached to $v_1$ and $v_2$, respectively) can be reconstructed. We have $2S_2(\mathcal{G})-S_3(\mathcal{G})=2(V_1+V_2)+W$, so we know the label of $w$ and the composition of labels of $v_1$ and $v_2$, then the query $\mathcal{M}_2(\mathcal{G})$ will allow us to find the labels of $u_1$ and $u_2$ (the only possible confusion is if $U_1=V_2$ and $U_2=V_1$, which is not a problem since the two possible labelings would be isomorphic).

		\item The complete bipartite graph $K_{2,3}$ can trivially be reconstructed from $S_2(\mathcal{G})$ (since all vertices in each part are equivalent to each other; the two parts can be separated and thus we are done).
	\end{enumerate}

	Hence, the only confusable graphs of order~5 are the gem and the graph depicted on \Cref{fig-triangleWithTail}, which we will call $T_2$.

	\medskip\noindent\textbf{Smallest confusable trees.} Trees of order at most~5 are not confusable per above.
	Trees of order~6 are $P_6$, $S_5$, $S_{1,1,3}$, the bistar $B_{2,2}$ (none of which are confusable, see \cite{acharya2015string}, \Cref{cor-reconstructingStars} and \Cref{thm-reconstructingBistarsAnyK,thm-reconstructingS11k}, respectively), and $S_{1,2,2}$ and $S_{1,1,1,2}$. For $S_{1,2,2}$, the proof of \Cref{thm-reconstructingStarsSubdividedAtMostOnce} works with any alphabet: the only possible confusion at the end of the proof (and identified in \Cref{rem-StarSubdividedAtMostOnce}) is if the two branches of length~2 are palindromes of each other, in which case the confusion does not matter due to isomorphisms. As for $S_{1,1,1,2}$, the proof of \Cref{thm-reconstructingStarsSubdividedAtMostOnce} clearly works too: once the label of the center vertex has been found, this gives the label of the only degree~2 vertex, after which we can remove pairs of leaves, hence having the composition of the branch of length~2, from which we can know the label of its leaf, giving the labels of the other three symmetrical leaves.

	Trees of order~7 require more work. Some of them we can easily manage: $P_7$ (\cite{acharya2015string}), the star $S_6$ (\Cref{cor-reconstructingStars}), $S_{1,1,4}$ (\Cref{thm-reconstructingS11k}) and the bistar $B_{2,3}$ (\Cref{thm-reconstructingBistarsAnyK}). The subdivided star $S_{1,2,3}$ is confusable, as can be seen on \Cref{fig-s123} (this is a result from~\cite{bartha2016reconstruction}, where they do not explicitly give the example, but Petér Burcsi and Zsuzsanna Lipták communicated the graph to us); this can be checked by enumerating the multiset compositions of both labelings. Since there are 11 trees with 7 vertices (see~\cite{smallTrees}), there are six remaining trees of order~7 to analyze.
	Note that in the following considerations, we obtain the composition of inner vertices $I$ with \Cref{lem-leavesAndInternal} and in the cases of subdivided stars (that is, in Cases~1, 2, 3 and 4) \Cref{lem-centerOfAStar} gives the label of the center vertex:
	\begin{enumerate}
		\item $S_{2,2,2}$. For this graph, the proof of \Cref{thm-reconstructingStarsSubdividedAtMostOnce} works, except in the case outlined in \Cref{rem-StarSubdividedAtMostOnce}: the branches of length~2 form a ``cycle'' (such as having compositions $AB$, $BC$ and $CA$) and we can obtain the label $X$ of the center vertex. However, in this case, the query $\mathcal{M}_4(\mathcal{S})$ will allow us to distinguish between the two possible labelings (if composition $A^2BX$ is appearing, then the branch with composition $AB$ has leaf $A$ and degree~2 vertex $B$, allowing us to find the rest; otherwise, it is the reverse).

		\item $S_{1,1,2,2}$. For this graph, the proof of \Cref{thm-reconstructingStarsSubdividedAtMostOnce} works: the only possible confusion at the end of the proof is if the two branches of length~2 are palindromes of each other, in which case the confusion does not matter since it leads to isomorphic labelings.

		\item $S_{1,1,1,3}$. Denote the center by $c$, and the vertices of the branch of length~3 by $v_1$, $v_2$ and $v_3$ where $v_1$ is adjacent to $c$ and $v_3$ is a leaf. We have $S_5(\mathcal{S})-(S_3(\mathcal{S})+S_2(\mathcal{S}))=-4C+2V_2+V_3$. Since we know $C$, this allows us to deduce $V_2$ and $V_3$, from which we can learn $V_1$ (the last internal vertex) and the three leaves adjacent to $c$.

		\item $S_{1,1,1,1,2}$. For this graph, there are two inner vertices. As one of them is the center vertex, we can obtain labels of both of them. Hence, we only need to identify the label of the leaf at distance two from the center.  We can do that by   removing the pairs of leaves from compositions obtained with $\bigsqcup_{X \in \mathcal{M}_5(\mathcal{S})} (S_7(\mathcal{S})-X)$, leaving only the pair with this leaf and the degree~2 vertex, whose label is known.


		\item The labeled tree $\mathcal{B}$ obtained by subdividing the middle edge of the bistar $B_{2,2}$. We can find the compositions $L$ of leaves and $I$ of internal vertices by \Cref{lem-leavesAndInternal}, from which we can compute the label of the middle vertex with $L+3I-S_2(\mathcal{B})$. Assume that the middle vertex has label $A$; we will check the largest $i$ such that the query $\mathcal{M}_i(\mathcal{B})$ contains the composition $A^i$, which will allow us to reconstruct the labeling. If $i=7$, then, each label is $A$ and we are done. If $i=6$, then, every vertex but one leaf is labeled with $A$, so we are done.

		If $i=5$, then, two leaves are not labeled with $A$, so we can check whether there is an $AXY$ (for $X,Y \neq A$) in $\mathcal{M}_3(\mathcal{B})$; if true, then the two non-$A$ leaves are adjacent to the same degree~3 vertex, otherwise they are adjacent to different degree~3 vertices, and in both cases we are done.

		If $i=4$, then, either a degree~3 vertex is labeled with $X \neq A$, or exactly three leaves are labeled with $X,Y,Z \neq A$. In the first case the two leaves adjacent to the degree~3 vertex labeled with $A$ are also labeled with $A$, and we know all other labels, so we are done. In the second case only one of $AXY$, $AXZ$ and $AYZ$ will be in $\mathcal{M}_3(\mathcal{B})$, allowing us to know which leaf is at distance~2 of the leaf labeled with $A$. In both cases we can reconstruct the labeling.

		If $i=3$, then, either exactly one degree~3 vertex has label $X \neq A$ and a leaf adjacent to the degree~3 vertex with label $A$ has itself label $A$ and the other leaf has label $W \neq A$, or we have $I=3A$.
		In the first case we know $X$, and we can use query $\mathcal{M}_3(\mathcal{B})$ to find all compositions $A^2Y$ with $Y \neq A$: there can be from one to five $A^2X$ depending on if zero, one or two leaves adjacent to the $X$-labeled degree~3 vertex are labeled with $A$ and whether or not $W=X$; if there are one or two $A^2X$, then $W \neq X$ and we can find $W$ from the only composition $AY$ other than $AX$ in $\mathcal{M}_2(\mathcal{B})$ after which we get the last two leaves; if there are three $A^2X$, then we have either $W=X$ and none of the last two leaves with label $A$ or $W \neq X$ and the last two leaves have label $A$, we can distinguish between them by counting the number of $AX$ compositions in $\mathcal{M}_2(\mathcal{B})$, which is two in the former case and three in the latter case, in both cases we can then easily conclude; if there are four $A^2X$, then we have $W=X$ and one of the last leaves has label $A$, we conclude immediately with the last leaf; if there are five $A^2X$, then $W=X$ and the last two leaves have label $A$. In the second case with $I=3A$, all leaves have labels different from $A$, say $W$, $X$, $Y$ and $Z$. In this case the query $\mathcal{M}_3(\mathcal{B})$ will allow us to check possible combinations among $AWX$, $AWY$, $AWZ$, $AXY$, $AXZ$ and $AYZ$; note that only two of those can exist unless there is some isomorphism, in both cases we can reconstruct the graph.

		If $i=2$, then, one of the degree~3 vertices has label $A$ and its two adjacent leaves have labels $X,Y \neq A$ and the other degree~3 vertex has label $Z$ (which we know). If a leaf is labeled with $A$, then it is adjacent to the $Z$-labeled degree~3 vertex. We can use query $\mathcal{M}_2(\mathcal{B})$ to get all $AX$ and $AY$ combinations, allowing us to complete the reconstruction.

		Finally, if $i=1$, then the two degree~3 vertices are labeled with $U,V \neq A$. Let $W$, $X$, $Y$ and $Z$ be the labels of the leaves. If $U=V$, then, we use query $\mathcal{M}_3(\mathcal{B})$. First, we count the number of $A^2U$ compositions which there are at most six; if there are six $A^2U$, then all leaves have label $A$; there cannot be exactly five $A^2U$; if there are four $A^2U$, then three leaves have label $A$ and we are done; if there are three $A^2U$, then two leaves attached to the same degree~3 vertex have label $A$; if there are two $A^2U$, then two leaves attached to different degree~3 vertices have label $A$; if there is one $A^2U$, then only one leaf has label $A$ and we may query $M_3(\mathcal{B})$ to find $WZU$ where $W,Z\neq A$ to find how labels are distributed between the leaves. In all of cases, completing the reconstruction afterwards is easy.
		If no $A^2U$ composition can be found, we remove all compositions containing $A$ and are left with the following possible compositions: $UWX$, $UWY$, $UWZ$, $UXY$, $UXZ$ and $UYZ$; only two of these exist unless there is some isomorphism, in both cases we can reconstruct the graph. If $U \neq V$, then, leaves labeled with $A$ can easily be found with compositions $AU$ and $AV$ in $\mathcal{M}_2(\mathcal{B})$ (there is at least one of each using the middle vertex, any supplementary one gives us a leaf labeled with $A$), after which we use query $\mathcal{M}_3(\mathcal{B})$ to check for $AUW$, $AVW, \ldots, AUZ$, $AVZ$, and again we can find which leaves are attached to each degree~3 vertex.

		\item The tree obtained by subdividing an edge incident with a leaf in the bistar $B_{2,2}$. Denote the vertices as following: $x$ is the degree~2 vertex, $y$ its adjacent leaf and $w$ its adjacent degree~3 vertex, $z$ is the leaf adjacent to $w$, $v$ is the other degree~3 vertex, and $u_1$ and $u_2$ are the two leaves adjacent to $v$. Recall that we know $L$, the composition of leaves ($u_1$, $u_2$, $y$ and $z$), and $I$, the composition of internal vertices ($v$, $w$ and $x$), thanks to \Cref{lem-leavesAndInternal}. We have $S_4(\mathcal{B})-S_3(\mathcal{B})-L-2I=Z$. Furthermore, we have $S_5(\mathcal{B})-S_3(\mathcal{B})-2L-I=V+2X$, so we can deduce those two labels, which also gives the last internal label $W$. Finally, $S_3(\mathcal{B})-2L=5V+6W+3X-Y$ allows us to know the value of $Y$, from which we finally deduce the labels of the last two leaves $u_1$ and $u_2$, completing the reconstruction.
	\end{enumerate}

	Hence, $S_{1,2,3}$ is the only confusable tree of order at most~7.
\end{proof}

