\subsection*{Proofs of Main Results}

The following lemma presents matrix differentiation formulas from \cite{bernstein2009matrix}, which will be central to the proofs of the main results. Note that since \cite{bernstein2009matrix} follows the convention $\left[\frac{\mathrm{d}}{\mathrm{d}X}\right]_{ij}=\frac{\mathrm{d}}{\mathrm{d}[X]_{ji}}$, these formulas have been transposed.
\begin{lemma}
The following formulas hold true by \cite{bernstein2009matrix}
\begin{itemize}
    \item For any $A\in\mathbb{R}^{n\times m}, B\in \mathbb{R}^{l\times n}$:
\begin{align}
&X\in\mathbb{R}^{m\times n}:~\frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AX=\frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}XA=A^\mathrm{T},\label{eq:AX}\\
&X\in\mathbb{R}^{m\times l}:~\frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AXB=A^\mathrm{T}B^\mathrm{T}, \label{eq:AXB}\\
&X\in\mathbb{R}^{l\times m}:~\frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AX^\mathrm{T}B=BA.\label{eq:AXtB}
\end{align}
\item For any $A\in\mathbb{R}^{n\times m}, B\in \mathbb{R}^{m\times n},  X\in\mathbb{R}^{m\times m}$:
\begin{equation}
   \frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AX^2B=
   A^\mathrm{T}B^\mathrm{T}X^\mathrm{T}+X^\mathrm{T}A^\mathrm{T}B^\mathrm{T}.\label{eq:AX2B} \\
\end{equation}
\item For any  $A,B\in\mathbb{R}^{n\times m}, X\in\mathbb{R}^{m\times n}$:  
\begin{equation}
    \frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AXBX=A^\mathrm{T}X^\mathrm{T}B^\mathrm{T}+B^\mathrm{T}X^\mathrm{T}A^\mathrm{T}.\label{eq:AXBX}
\end{equation}
\item For any $A\in\mathbb{R}^{n\times n}, B\in \mathbb{R}^{m\times m}, X\in\mathbb{R}^{n\times m}$:
\begin{equation}
    \frac{\mathrm{d}}{\mathrm{d}X}\mathrm{tr}AXBX^\mathrm{T}=AXB+A^\mathrm{T}XB^\mathrm{T}.\label{eq:AXBXt}
\end{equation}
\end{itemize}
\end{lemma}

The proofs of the main results follow next.

\textit{Proof of Lemma \ref{le:stab}}:
    Let $\{\hat{\Lambda}^n,\hat{P}_u^n\}_{n\in\mathbb{N}}$ be a minimizing sequence of \eqref{eq:opt1}, i.e., a sequence that satisfies the constraints of \eqref{eq:opt1}, and for which $J(\hat{\Lambda}^n,\hat{P}_u^n)$ converges to the infimum of \eqref{eq:opt1} as $n\rightarrow\infty$. Note that $\hat{\Lambda}^n$ and $K_u(\hat{\Lambda}^n)$ must be bounded uniformly; for if they are not, then $\lim_{n\rightarrow\infty}J(\hat{\Lambda}^n,\hat{P}_u^n)=\infty$ owing to the fact that $J(\hat{\Lambda}^n,\hat{P}_u^n)\ge\norm{K_u(\hat{\Lambda}^n)-\bar{K}}_{\mathrm{F}}^2+\lambda_{\textrm{min}}(\Gamma)\norm{\hat{\Lambda}^n}^2_{\mathrm{F}}$, whereas $J(0,P)<\infty$, which contradicts optimality. Therefore, one can extract from  $\{\hat{\Lambda}^n,\hat{P}_u^n\}_{n\in\mathbb{N}}$ a subsequence  $\{\bar{\Lambda}^n,\bar{P}_u^n\}_{n\in\mathbb{N}}$ such that $\lim_{n\rightarrow\infty}\bar{\Lambda}^n=\bar{\Lambda}\in\mathbb{R}^{m_u\times n}$ and $\lim_{n\rightarrow\infty}K_u(\bar{\Lambda}^n)=\bar{K}_u\in\mathbb{R}^{m_a\times n}$ [Theorem 3.6 in \cite{rudin1964principles}].  Using these limits and \eqref{eq:LE_S}, we have
    \begin{align*}       (A&+B_u\bar{\Lambda}+B_a\bar{K}_u)^\mathrm{T}S+S(A+B_u\bar{\Lambda}+B_a\bar{K}_u)\\=&(A+B_aK^\star)^\mathrm{T}S+S(A+B_aK^\star)+SB_u\bar{\Lambda} +(SB_u\bar{\Lambda} )^\mathrm{T}\\&+SB_a(\bar{K}_u-K^\star)+(SB_a(\bar{K}_u-K^\star))^\mathrm{T}\\=&-2I+SB_u\bar{\Lambda} +(SB_u\bar{\Lambda} )^\mathrm{T}\\&+SB_a(\bar{K}_u-K^\star)+(SB_a(\bar{K}_u-K^\star))^\mathrm{T}.
    \end{align*}
    Based on the Lyapunov theorem and the equality above, $A+B_u\bar{\Lambda}+B_a\bar{K}_u$ will be strictly stable if
    \begin{multline*}
    \|SB_u\bar{\Lambda} +(SB_u\bar{\Lambda} )^\mathrm{T}+SB_a(\bar{K}_u-K^\star)\\+(SB_a(\bar{K}_u-K^\star))^\mathrm{T}\|_{\mathrm{F}}<2.
    \end{multline*}
    This holds true if
    \begin{equation}\label{eq:ineq_1f}
    \norm{SB_u}_{\mathrm{F}}\norm{\bar{\Lambda}}_{\mathrm{F}}+\norm{SB_a}_{\mathrm{F}}\norm{\bar{K}_u-K^\star}_{\mathrm{F}}<1.
    \end{equation}
   So we need to obtain a condition that will allow \eqref{eq:ineq_1f} to hold. 
    To that end, note that $\Lambda=0$ and $P_u=P$ from \eqref{eq:are} are feasible solutions to \eqref{eq:opt1}. As a result, by optimality of the limit of the minimizing sequence, we have:
    \begin{align*}
        &\lim_{n\rightarrow\infty}J(\bar{\Lambda}^n,\bar{P}_u^n)\le J(0,P) \Longrightarrow\\&\lim_{n\rightarrow\infty}\norm{K_u(\bar{\Lambda}^n){-}K^\star}_{\mathrm{F}}^2{+} \lim_{n\rightarrow\infty}\mathrm{tr}(\bar{\Lambda}^{n\mathrm{T}}\Gamma\bar{\Lambda}^n)\le \norm{K^\star{-}\bar{K}}_{\mathrm{F}}^2 
    \\&{\Longrightarrow} \norm{\bar{K}_u{-}K^\star}_{\mathrm{F}}^2+ \mathrm{tr}(\bar{\Lambda}^{\mathrm{T}}\Gamma\bar{\Lambda})\le \norm{K^\star{-}\bar{K}}_{\mathrm{F}}^2. 
    \end{align*}
    This implies that
    \begin{equation}\label{eq:ineq_2f}
    \begin{split}        &\norm{\bar{K}_u-K^\star}_{\mathrm{F}}\le \norm{K^\star-\bar{K}}_{\mathrm{F}},\\       &\norm{\bar{\Lambda}}_{\mathrm{F}}\le \frac{1}{\sqrt{\lambda_{\textrm{min}}(\Gamma)}}\norm{K^\star-\bar{K}}_{\mathrm{F}}.
        \end{split}
    \end{equation}
     Hence, using \eqref{eq:ineq_2f}, \eqref{eq:ineq_1f} will hold by imposing the condition
   \begin{multline}\label{eq:cond_stab_proof}
    \hspace{-2mm}\frac{1}{\sqrt{\lambda_{\textrm{min}}(\Gamma)}}\norm{SB_u}_{\mathrm{F}}\norm{K^\star{-}\bar{K}}_{\mathrm{F}}+\norm{SB_a}_{\mathrm{F}}\norm{K^\star{-}\bar{K}}_{\mathrm{F}}<1 \\\Longrightarrow \norm{K^\star-\bar{K}}_{\mathrm{F}}< \frac{\sqrt{\lambda_{\textrm{min}}(\Gamma)}}{\sqrt{\lambda_{\textrm{min}}(\Gamma)}\norm{SB_a}_{\mathrm{F}}+\norm{SB_u}_{\mathrm{F}}}.
    \end{multline}
    Therefore, under \eqref{eq:cond_stab_proof}, $A+B_u\bar{\Lambda}+B_a\bar{K}_u$ is strictly stable. Accordingly, the following LE admits a unique symmetric solution $\bar{P}_u\in\mathbb{R}^{n\times n}$:
    \begin{multline}\label{eq:PulimLE}
    (A+B_u\bar{\Lambda}+B_a\bar{K}_u)^\mathrm{T}\bar{P}_u+\bar{P}_u(A+B_u\bar{\Lambda}+B_a\bar{K}_u)\\+Q-\bar{K}_u^\mathrm{T}R\bar{K}_u=0.
    \end{multline}
    Subtracting \eqref{eq:PulimLE} from \eqref{eq:RicL} for $\Lambda=\bar{\Lambda}^n$ and $P_u=\bar{P}_u^n$, and defining $\tilde{P}_u^n=\bar{P}_u^n-\bar{P}_u$,  $\tilde{\Lambda}_u^n=\bar{\Lambda}^n-\bar{\Lambda}$, $\tilde{K}_u^n=K_u(\bar{\Lambda}^n)-\bar{K}_u$ gives: 
    \begin{align}\nonumber
        (A+&B_u\bar{\Lambda}^n{+}B_aK_u(\bar{\Lambda}^n))^\mathrm{T}\tilde{P}_u^n+\tilde{P}_u^n(A{+}B_u\bar{\Lambda}^n{+}B_aK_u(\bar{\Lambda}^n))\\\nonumber&+\tilde{\Lambda}^{n\mathrm{T}}B_u^\mathrm{T}\bar{P}_u+\bar{P}_uB_u\tilde{\Lambda}^n+\tilde{K}_u^{n\mathrm{T}}B_a^\mathrm{T}\bar{P}_u+\bar{P}_uB_a\tilde{K}_u^n
        \\&-{K}_u^{\mathrm{T}}(\bar{\Lambda}^n)R{K}_u(\bar{\Lambda}^n) +\bar{K}_u^\mathrm{T}R\bar{K}_u=0.\label{eq:tildep}
    \end{align}
    Note that $A_n:=A+B_u\bar{\Lambda}^n+B_aK_u(\bar{\Lambda}^n)$ must remain strictly stable uniformly and it converges to the strictly stable matrix $A_{\infty}:=A+B_u\bar{\Lambda}+B_a\bar{K}_u$ as $n\rightarrow\infty$. In addition, for each $n$ \eqref{eq:tildep} is an LE for $\tilde{P}_u^n$,  in which the last six terms satisfy:
    \begin{multline*}
S_n:=\tilde{\Lambda}^{n\mathrm{T}}B_u^\mathrm{T}\bar{P}_u+\bar{P}_uB_u\tilde{\Lambda}^n+\tilde{K}_u^{n\mathrm{T}}B_a^\mathrm{T}\bar{P}_u+\bar{P}_uB_a\tilde{K}_u^n
        \\-{K}_u^{\mathrm{T}}(\bar{\Lambda}^n)R{K}_u(\bar{\Lambda}^n) +\bar{K}_u^\mathrm{T}R\bar{K}_u\rightarrow0
    \end{multline*}
     as $n\rightarrow\infty$ because $\lim_{n\rightarrow\infty}\bar{\Lambda}^n=\bar{\Lambda}$ and $\lim_{n\rightarrow\infty}K_u(\bar{\Lambda}^n)=\bar{K}_u$. Therefore, by solving \eqref{eq:tildep}:
     \begin{equation*}
    \tilde{P}_u^n=\int_0^{\infty}\mathrm{e}^{A_n^\textrm{T}\tau}S_n\mathrm{e}^{A_n\tau}\textrm{d}\tau\rightarrow\int_0^{\infty}\mathrm{e}^{A_\infty^\textrm{T}\tau}\cdot0\cdot\mathrm{e}^{A_\infty\tau}\textrm{d}\tau=0
     \end{equation*}
     and thus $\bar{P}_u^n\rightarrow\bar{P}_u$ as $n\rightarrow\infty$. In addition, note that since $\bar{P}_u^n$ are positive definite for all $n$, $\bar{P}_u$ must be positive semi-definite, and in fact positive definite owing to Theorem 6.23(ii) in \cite{bacsar1998dynamic}. At the same time, it is straightforward to see that $\bar{K}_u=R^{-1}B_a^\mathrm{T}\bar{P}_u$ since $\bar{K}_u=\lim_{n\rightarrow\infty}K_u(\bar{\Lambda}^n)=\lim_{n\rightarrow\infty}R^{-1}B_a^\mathrm{T}\bar{P}_u^n=R^{-1}B_a^\mathrm{T}\bar{P}_u$, thus $\bar{P}_u$ is the stabilizing solution to \eqref{eq:RicL} for $\Lambda=\bar{\Lambda}$ and hence its minimal one because of Theorem 6.23(vi) in \cite{bacsar1998dynamic}, i.e., $\bar{P}_u\in\mathbb{S}_+$. Thus $(\bar{\Lambda},\bar{P}_u)$ is a feasible solution of \eqref{eq:opt1} that is also minimizing, hence \eqref{eq:opt1} admits a minimizer. The second part follows from the fact that $A+B_u\bar{\Lambda}+B_a\bar{K}_u$ was proved to be strictly stable. \frQED

\textit{Proof of Theorem \ref{th:1}}:
Define the Lagrangian of the optimization \eqref{eq:opt1} as:
\begin{align}\nonumber
\mathcal{L}(\Lambda,P_u,\Pi)=&\norm{R^{-1}B_a^\mathrm{T}P_u-\bar{K}}_{\mathrm{F}}^2+\mathrm{tr}(\Lambda^\mathrm{T}\Gamma\Lambda)\\\nonumber&+\mathrm{tr}\Big(\Pi ((A+B_u\Lambda)^\mathrm{T}P_u+P_u(A+B_u\Lambda)\\&+Q+P_uB_aR^{-1}B_a^\mathrm{T}P_u) \Big),\nonumber
\end{align}
where $\Pi\in\mathbb{R}^{n\times n}$  denotes the Lagrange multiplier. Note that because the left-hand side of the ARE \eqref{eq:RicL} is symmetric, $\Pi$ is symmetric as well.
Applying the first of the three necessary conditions for optimality, namely $\frac{\partial \mathcal{L}}{\partial {\Pi}}=0$, we get
\begin{multline*}
\frac{\partial}{\partial {\Pi}}\mathrm{tr}\Big(\Pi ((A+B_u\Lambda)^\mathrm{T}P_u+P_u(A+B_u\Lambda)\\ \qquad\qquad+Q+P_uB_aR^{-1}B_a^\mathrm{T}P_u) \Big)=0 \stackrel{\eqref{eq:AX}}{\Longrightarrow} \\ (A+B_u\Lambda)^\mathrm{T}P_u{+}P_u(A+B_u\Lambda){+}Q{+}P_uB_aR^{-1}B_a^\mathrm{T}P_u=0,
\end{multline*}
which yields \eqref{eq:eq1}.
Next, by applying the second of the three necessary conditions for optimality, namely $\frac{\partial \mathcal{L}}{\partial {\Lambda}}=0$, and the fact that $\mathrm{tr}(\Lambda^\mathrm{T}\Gamma\Lambda)=\mathrm{tr}(\Gamma\Lambda\Lambda^\mathrm{T})$ we get:
\begin{multline*}
\frac{\partial }{\partial {\Lambda}}
\left(\mathrm{tr}\Big(\Lambda^\mathrm{T}\Gamma\Lambda{+}\Pi ((A+B_u\Lambda)^\mathrm{T}P_u{+}P_u(A+B_u\Lambda)) \right)=0 \\\stackrel{\eqref{eq:AXBXt},\eqref{eq:AXtB},\eqref{eq:AX}}{\Longrightarrow}
2\Gamma\Lambda+2B_u^\mathrm{T}P_u\Pi  =0 \Longrightarrow \Lambda=-\Gamma^{-1}B_u^\mathrm{T}P_u\Pi,
\end{multline*}
where we used the fact that $\Pi$ and $P_u$ are symmetric, hence we obtain \eqref{eq:eq3}.
Finally, applying the third of the three necessary conditions for optimality, namely $\frac{\partial \mathcal{L}}{\partial {P_u}}=0$, and using the fact that $\norm{R^{-1}B_a^\mathrm{T}P_u-\bar{K}}_{\mathrm{F}}^2=\mathrm{tr}((R^{-1}B_a^\mathrm{T}P_u-\bar{K})(R^{-1}B_a^\mathrm{T}P_u-\bar{K})^\mathrm{T})$, we require:
\begin{multline*}
\frac{\partial }{\partial {P_u}}\Big(\mathrm{tr}\Big(R^{-1}B_a^\mathrm{T}P_u^2B_aR^{-1}- R^{-1}B_a^\mathrm{T}P_u\bar{K}^\mathrm{T}\\-\bar{K}P_uB_aR^{-1}\Big)
+\mathrm{tr}\Big(\Pi ((A+B_u\Lambda)^\mathrm{T}P_u\\+P_u(A+B_u\Lambda)+P_uB_aR^{-1}B_a^\mathrm{T}P_u) \Big)=0.
\end{multline*}
Using properties \eqref{eq:AX2B}, \eqref{eq:AXB}, \eqref{eq:AX}, \eqref{eq:AXBX}, we obtain
\begin{multline}\nonumber
(A+B_u\Lambda)\Pi+\Pi(A+B_u\Lambda)^\mathrm{T}+\Pi P_uB_aR^{-1}B_a^\mathrm{T}\\+B_aR^{-1}B_a^\mathrm{T}P_u\Pi-\bar{K}^\mathrm{T}R^{-1}B_a^\mathrm{T}-B_aR^{-1}\bar{K}\\+P_uB_aR^{-2}B_a^\mathrm{T}+B_aR^{-2}B_a^\mathrm{T}P_u=0,
\end{multline}
which, after grouping together the terms containing $\Pi$, is equivalent to \eqref{eq:eq2}. \frQED

\textit{Proof of Lemma \ref{le:grad}}:
Note that we can write the cost as $\tilde{J}(\Lambda)=\tilde{J}_1(\Lambda)+\tilde{J}_2(\Lambda)$, where $\tilde{J}_1(\Lambda)=\mathrm{tr}(\Lambda^\mathrm{T}\Gamma\Lambda)$ and $\tilde{J}_2(\Lambda)=\norm{K_u(\Lambda)-\bar{K}}_{\mathrm{F}}^2$. In that respect, on the one hand, we have:
\begin{equation}\label{eq:dJ1}
\frac{\mathrm{d}\tilde{J}_1(\Lambda)}{\mathrm{d}\Lambda}=\frac{\mathrm{d}}{\mathrm{d}\Lambda}\mathrm{tr}(\Lambda^\mathrm{T}\Gamma\Lambda)=\frac{\mathrm{d}}{\mathrm{d}\Lambda}\mathrm{tr}(\Gamma\Lambda\Lambda^\mathrm{T})\stackrel{\eqref{eq:AXBXt}}{=}2\Gamma\Lambda.
\end{equation}
On the other hand, using the definition of the Frobenius norm we can write $\tilde{J}_2(\Lambda)=\mathrm{tr}((R^{-1}B_a^\mathrm{T}P_u(\Lambda)-\bar{K})(R^{-1}B_a^\mathrm{T}P_u(\Lambda)-\bar{K})^\mathrm{T})$. In that respect, denoting $\Lambda_{ij}=[\Lambda]_{ij}$ and using the commutative property of the derivative operator and the trace, we get:
\begin{align}\nonumber
\frac{\mathrm{d}\tilde{J}_2(\Lambda)}{\mathrm{d}\Lambda_{ij}}&=\frac{\mathrm{d}}{\mathrm{d}\Lambda_{ij}}\Big(\mathrm{tr}\Big(R^{-1}B_a^\mathrm{T}P_u^2B_aR^{-1}- R^{-1}B_a^\mathrm{T}P_u\bar{K}^\mathrm{T}\\\nonumber&\quad-\bar{K}P_uB_aR^{-1}+\bar{K}^\mathrm{T}\bar{K}\Big)\\\nonumber&=\mathrm{tr}\Big(R^{-1}B_a^\mathrm{T}P_u\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}B_aR^{-1}- R^{-1}B_a^\mathrm{T}\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}\bar{K}^\mathrm{T}\\\nonumber&\quad+R^{-1}B_a^\mathrm{T}\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}P_uB_aR^{-1}{-}\bar{K}\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}B_aR^{-1}\Big)\\&\nonumber=\mathrm{tr}\Big(\Big(-\bar{K}^\mathrm{T}R^{-1}B_a^\mathrm{T}-B_aR^{-1}\bar{K}\\&\quad+ P_uB_aR^{-2}B_a^\mathrm{T}{+}B_aR^{-2}B_a^\mathrm{T}P_u          \Big)\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}\Big),\label{eq:dJ2t}
\end{align}
where we also applied the cyclic property of the trace. Next, note that since \eqref{eq:PL} is an equality constraint, we can take the total derivative with respect to $\Lambda_{ij}$ on both sides and obtain:
\begin{align*}
0=&~\frac{\mathrm{d}}{\mathrm{d}\Lambda_{ij}}\Big((A+B_u\Lambda)^\mathrm{T}P_u(\Lambda)+P_u(\Lambda)(A+B_u\Lambda)\\&+Q+P_u(\Lambda)B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda)\Big)\\=&~e_je_i^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda)+(A+B_u\Lambda)^\mathrm{T}\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}+P_u(\Lambda)B_ue_ie_j^\mathrm{T}\\&+\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}(A+B_u\Lambda)+\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda)\\&+P_u(\Lambda)B_aR^{-1}B_a^\mathrm{T}\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}},
\end{align*}
where we used the fact that $\frac{\mathrm{d}\Lambda}{\mathrm{d}\Lambda_{ij}}=e_ie_j^\mathrm{T}$.
Grouping together the differential terms yields the LE:
\begin{equation}\label{eq:LE_dPij}
\tilde{A}^\mathrm{T}(\Lambda)\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}+\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}\tilde{A}(\Lambda)+\tilde{Q}(\Lambda)=0
\end{equation}
where
\begin{align}\label{eq:tildeA}
\tilde{A}(\Lambda)&=A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda),\\\label{eq:tildeQ}
\tilde{Q}(\Lambda)&=e_je_i^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda)+P_u(\Lambda)B_ue_ie_j^\mathrm{T}.
\end{align}
Note that since $P_u(\Lambda)\in\mathbb{S}_+$, $\tilde{A}(\Lambda)$ is Hurwitz. Therefore, the LE \eqref{eq:LE_dPij} admits the following unique symmetric solution:
\begin{equation}\label{eq:dPij}
\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{ij}}=\int_0^\infty \mathrm{e}^{\tilde{A}^\mathrm{T}(\Lambda)\tau}\tilde{Q}(\Lambda)\mathrm{e}^{\tilde{A}(\Lambda)\tau}\mathrm{d}\tau.
\end{equation}
Combining \eqref{eq:dPij} with \eqref{eq:dJ2t}, and using the trace cyclic property, yields
\begin{align}\nonumber
\frac{\mathrm{d}\tilde{J}_2(\Lambda)}{\mathrm{d}\Lambda_{ij}}&=\mathrm{tr}\Big(\Big(-\bar{K}^\mathrm{T}R^{-1}B_a^\mathrm{T}-B_aR^{-1}\bar{K}+ P_uB_aR^{-2}B_a^\mathrm{T}\\\nonumber&\quad+B_aR^{-2}B_a^\mathrm{T}P_u          \Big)\int_0^\infty \mathrm{e}^{\tilde{A}^\mathrm{T}(\Lambda)\tau}\tilde{Q}(\Lambda)\mathrm{e}^{\tilde{A}(\Lambda)\tau}\mathrm{d}\tau\Big)\\\nonumber&=\mathrm{tr}\Big(\tilde{Q}(\Lambda)\int_0^\infty \mathrm{e}^{\tilde{A}(\Lambda)\tau}\Big(-\bar{K}^\mathrm{T}R^{-1}B_a^\mathrm{T}-B_aR^{-1}\bar{K}\\&\quad{+} P_uB_aR^{-2}B_a^\mathrm{T}{+}B_aR^{-2}B_a^\mathrm{T}P_u          \Big)\mathrm{e}^{\tilde{A}^\mathrm{T}(\Lambda)\tau}\mathrm{d}\tau\Big).\hspace{-2mm}\label{eq:dJ2_b}
\end{align}
Note that the integral inside the trace expression above is exactly the solution of the LE \eqref{eq:grad_Pi}. Hence, in light also of the formula \eqref{eq:tildeQ} for $\tilde{Q}$, \eqref{eq:dJ2_b} turns into:
\begin{align*}
\frac{\mathrm{d}\tilde{J}_2(\Lambda)}{\mathrm{d}\Lambda_{ij}}&=\mathrm{tr}\Big((e_je_i^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda)+P_u(\Lambda)B_ue_ie_j^\mathrm{T})\Pi(\Lambda)\Big)\\&=2e_i^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda)\Pi(\Lambda)e_j=2[B_u^\mathrm{T}P_u(\Lambda)\Pi(\Lambda)]_{ij}.
\end{align*}
Therefore 
\begin{equation}\label{eq:dJ2}
\frac{\mathrm{d}\tilde{J}_2(\Lambda)}{\mathrm{d}\Lambda}=2B_u^\mathrm{T}P_u(\Lambda)\Pi(\Lambda).
\end{equation}
Since we defined $\tilde{J}(\Lambda)=\tilde{J}_1(\Lambda)+\tilde{J}_2(\Lambda)$, the results follows by \eqref{eq:dJ1} and \eqref{eq:dJ2}. \frQED

\textit{Proof of Lemma \ref{le:uniformly_bounded}}: 
Based on \eqref{eq:LE_S}, we have:
\begin{align}\nonumber
&(A+B_u\Lambda+B_aK_u(\Lambda))^\mathrm{T}S+S(A+B_u\Lambda+B_aK_u(\Lambda))\\&\nonumber=(A{+}B_aK^\star)^\mathrm{T}S+S(A{+}B_aK^\star)+(K_u(\Lambda){-}K^\star)^\mathrm{T}B_a^\mathrm{T}S\\&\nonumber\quad+SB_a(K_u(\Lambda)-K^\star)+\Lambda B_u^\mathrm{T}S+SB_u\Lambda\\\nonumber&=-2I+(K_u(\Lambda)-K^\star)^\mathrm{T}B_a^\mathrm{T}S+SB_a(K_u(\Lambda)-K^\star)\\&\quad+\Lambda^\mathrm{T}B_u^\mathrm{T}S+SB_u\Lambda.\hspace{-1mm}\label{eq:bounded1}
\end{align}
However:
\begin{multline}\label{eq:bounded2}
\|(K_u(\Lambda)-K^\star)^\mathrm{T}B_a^\mathrm{T}S+SB_a(K_u(\Lambda)-K^\star)\\+\Lambda^\mathrm{T}B_u^\mathrm{T}S+SB_u\Lambda\|_{\mathrm{F}}\\\le 2\norm{SB_a}_{\mathrm{F}}\norm{K_u(\Lambda)-K^\star}_{\mathrm{F}}+2\norm{SB_u}_{\mathrm{F}}\norm{\Lambda}_{\mathrm{F}}\\\le 2\norm{SB_a}_{\mathrm{F}}\norm{K_u(\Lambda)-\bar{K}}_{\mathrm{F}}+2\norm{SB_u}_{\mathrm{F}}\norm{\Lambda}_{\mathrm{F}}\\+2\norm{SB_a}_{\mathrm{F}}\norm{\bar{K}-{K}^\star}_{\mathrm{F}}.
\end{multline}
In addition, if $\Lambda \in\mathcal{S}_0$ then
\begin{align}\nonumber
        &\tilde{J}(\Lambda)\le \tilde{J}(0) \\&\nonumber\Longrightarrow\norm{K_u(\Lambda)-\bar{K}}_{\mathrm{F}}^2+ \mathrm{tr}(\Lambda^{\mathrm{T}}\Gamma\Lambda)\le \norm{K^\star-\bar{K}}_{\mathrm{F}}^2\\&\Longrightarrow \norm{K_u(\Lambda)-\bar{K}}_{\mathrm{F}}^2+\lambda_{\textrm{min}}(\Gamma)\norm{\Lambda}_{\mathrm{F}}^2\le \norm{K^\star-\bar{K}}_{\mathrm{F}}^2.\hspace{-1mm}\label{eq:bounded3}
    \end{align}
    Combining \eqref{eq:bounded2}-\eqref{eq:bounded3} yields
\begin{multline}\nonumber
\hspace{-3mm}\|(K_u(\Lambda)-K^\star)^\mathrm{T}B_a^\mathrm{T}S+SB_a(K_u(\Lambda)-K^\star)+\Lambda^\mathrm{T}B_u^\mathrm{T}S+SB_u\Lambda\|_{\mathrm{F}}\\\le 4(\norm{SB_a}_{\mathrm{F}}+\lambda_{\textrm{min}}^{-1/2}(\Gamma)\norm{SB_u}_{\mathrm{F}})\norm{K^\star-\bar{K}}_{\mathrm{F}}.
\end{multline}
Using \eqref{eq:stab_condition2}, we conclude:
\begin{multline}\label{eq:2-e}
\|(K_u(\Lambda)-K^\star)^\mathrm{T}B_a^\mathrm{T}S+SB_a(K_u(\Lambda)-K^\star)\\+\Lambda^\mathrm{T}B_u^\mathrm{T}S+SB_u\Lambda\|_{\mathrm{F}}\le2\epsilon.
\end{multline}
Combining \eqref{eq:2-e} with \eqref{eq:bounded1}, we obtain
\begin{multline}\label{eq:ineq_unif_stab}
(A+B_u\Lambda+B_aK_u(\Lambda))^\mathrm{T}S\\+S(A+B_u\Lambda+B_aK_u(\Lambda))\preceq -2(1-\epsilon) I.
\end{multline}
Since $S$ is constant, this implies that $A+B_u\Lambda+B_aK_u(\Lambda)$ remains strictly stable uniformly in $\mathcal{S}_0$ and that the energy $\int_0^\infty x^\textrm{T}(t)x(t)\textrm{d}t$ is bounded for every $x_0$ uniformly in $\mathcal{S}_0$.  In light of this and the fact that $K_u(\Lambda)$ is bounded uniformly in $\mathcal{S}_0$, it follows that
the value matrix $P_u(\Lambda)$ is also bounded uniformly in $\mathcal{S}_0$, i.e., $\textrm{sup}_{\Lambda\in\mathcal{S}_0}\norm{P_u(\Lambda)}_\mathrm{F}\le \bar{P}$ for some finite $\bar{P}>0$. Because of this, the cost matrix of the LE \eqref{eq:grad_Pi}, i.e., its last four terms, is uniformly bounded, so $\Pi(\Lambda)$ also remains bounded uniformly, i.e., $\textrm{sup}_{\Lambda\in\mathcal{S}_0}\norm{\Pi(\Lambda)}_\mathrm{F}\le \bar{\Pi}$ for some finite $\bar{\Pi}>0$. \frQED

\textit{Proof of Lemma \ref{le:lipschitz}}: 
Let $\Lambda_1,\Lambda_2\in\mathcal{S}_0$. Denote $\tilde{\Lambda}=\Lambda_1-\Lambda_2$, $\tilde{P_u}=P_u(\Lambda_1)-P_u(\Lambda_2)$, $\tilde{\Pi}=\Pi(\Lambda_1)-\Pi(\Lambda_2)$. Then, using the formula \eqref{eq:grad_formula}:
\begin{align*}
\frac{\mathrm{d}\tilde{J}(\Lambda_1)}{d\Lambda}&-\frac{\mathrm{d}\tilde{J}(\Lambda_2)}{d\Lambda}=2\Gamma(\Lambda_1-\Lambda_2)\\&+2B_u^\mathrm{T}(P_u(\Lambda_1)\Pi(\Lambda_1)-P_u(\Lambda_2)\Pi(\Lambda_2))\\&=2\Gamma\tilde{\Lambda}+2B_u^\mathrm{T}(\tilde{P_u}\Pi(\Lambda_1)+P_u(\Lambda_2)\tilde{\Pi}).
\end{align*}
Using Lemma \ref{le:uniformly_bounded}, this equation implies that:
\begin{multline}\label{eq:dJ1dJ2}
\norm{\frac{\mathrm{d}\tilde{J}(\Lambda_1)}{d\Lambda}-\frac{\mathrm{d}\tilde{J}(\Lambda_2)}{d\Lambda}}_{\mathrm{F}}\le 2\norm{\Gamma}_{\mathrm{F}}\norm{\tilde{\Lambda}}_{\mathrm{F}}\\+2\bar{\Pi}\norm{B_u^\mathrm{T}}_{\mathrm{F}}\norm{\tilde{P}_u}_{\mathrm{F}}+2\bar{P}\norm{B_u^\mathrm{T}}_{\mathrm{F}}\norm{\tilde{\Pi}}_{\mathrm{F}}.
\end{multline}
Hence, to get a Lipschitz continuity result, one needs to relate the errors $\norm{\tilde{P}_u}_{\mathrm{F}}$ and $\norm{\tilde{\Pi}}_{\mathrm{F}}$ back to $\norm{\tilde{\Lambda}}_{\mathrm{F}}$. To that end, recall that $P_u(\Lambda_1)$ and $P_u(\Lambda_2)$ are the minimal positive definite solutions of the AREs:
\begin{align*}\nonumber
&(A+B_u\Lambda_1)^\mathrm{T}P_u(\Lambda_1)+P_u(\Lambda_1)(A+B_u\Lambda_1)\\&\qquad\qquad\qquad\qquad+Q+P_u(\Lambda_1)B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda_1)=0,\\
&(A+B_u\Lambda_2)^\mathrm{T}P_u(\Lambda_2)+P_u(\Lambda_2)(A+B_u\Lambda_2)\\&\qquad\qquad\qquad\qquad+Q+P_u(\Lambda_2)B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda_2)=0.
\end{align*}
Subtracting these equations yields the following quadratic matrix equation for the error $\tilde{P}_u$:
\begin{multline}\label{eq:temp_lips1}
\left(A+B_u\Lambda_1+B_aK_u(\Lambda_1)-\frac{1}{2}B_aR^{-1}B_a^\mathrm{T}\tilde{P}_u\right)^{\mathrm{T}}\tilde{P}_u\\+\tilde{P}_u\left(A+B_u\Lambda_1+B_aK_u(\Lambda_1)-\frac{1}{2}B_aR^{-1}B_a^\mathrm{T}\tilde{P}_u\right)\\
+P_u(\Lambda_2)B_u\tilde{\Lambda}+\tilde{\Lambda}^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda_2)=0.
\end{multline}
Note that this is an equation that yields more than one solutions. Nevertheless, the solution of interest has the property that $\tilde{P}_u\rightarrow0$ as $\tilde{\Lambda}\rightarrow0$. For this solution, since $A+B_u\Lambda_1+B_aK_u(\Lambda_1)$ is Hurwitz as $P_1\in\mathbb{S}_+$, it follows that $\tilde{A}_1(\tilde{P}_u)=A+B_u\Lambda_1+B_aK_u(\Lambda_1)-\frac{1}{2}B_aR^{-1}B_a^\mathrm{T}\tilde{P}_u$ is also Hurwitz for some small $\epsilon>0$ such that $\norm{\tilde{\Lambda}}_{\mathrm{F}}<\epsilon$. Hence, for this solution $\tilde{P}_u$ and for $\norm{\tilde{\Lambda}}_{\mathrm{F}}<\epsilon$, we get from \eqref{eq:temp_lips1} the implicit formula
\begin{equation*}
\tilde{P}_u=\int_0^\infty \mathrm{e}^{\tilde{A}_1^\mathrm{T}(\tilde{P}_u)\tau}(P_u(\Lambda_2)B_u\tilde{\Lambda}+\tilde{\Lambda}^\mathrm{T}B_u^\mathrm{T}P_u(\Lambda_2)) \mathrm{e}^{\tilde{A}_1(\tilde{P}_u)\tau} \mathrm{d}\tau.
\end{equation*}
Therefore, 
\begin{equation}\label{eq:temp_lips2}
\norm{\tilde{P}_u}_{\textrm{F}}\le 2\bar{P}\norm{B_u}_{\textrm{F}}\norm{\tilde{\Lambda}}_{\textrm{F}}\int_0^\infty \norm{\mathrm{e}^{\tilde{A}_1(\tilde{P}_u)\tau}}^2_{\textrm{F}}\mathrm{d}\tau.
\end{equation}
Recall that $\tilde{A}_1(\tilde{P}_u)\rightarrow A+B_u\Lambda_1+B_aK_u(\Lambda_1)$ as $\tilde{\Lambda}\rightarrow0$, and $A+B_u\Lambda_1+B_aK_u(\Lambda_1)$ is strictly stable uniformly for all $\Lambda_1\in\mathcal{S}_0$ owing to Lemma \ref{le:uniformly_bounded}. Hence, the real parts of the eigenvalues of $\tilde{A}_1(\tilde{P}_u)$ remain in the left half plane for some small $\epsilon>0$ such that $\norm{\tilde{\Lambda}}_{\mathrm{F}}<\epsilon$. Hence, for all $\norm{\tilde{\Lambda}}_{\mathrm{F}}<\epsilon$ there exists a finite constant $c_1>0$  such that $\int_0^\infty \norm{\mathrm{e}^{\tilde{A}_1(\tilde{P}_u)\tau}}^2_{\mathrm{F}}\mathrm{d}\tau<c_1$. Putting this in \eqref{eq:temp_lips2} we get the following inequality, locally for $\norm{\tilde{\Lambda}}_{\mathrm{F}}<\epsilon$:
\begin{equation}\label{eq:temp_lips3}
\norm{\tilde{P}_u}_{\mathrm{F}}\le 2c_1\bar{P}\norm{B_u}_{\mathrm{F}}\norm{\tilde{\Lambda}}_{\mathrm{F}}.
\end{equation}
Subsequently, we proceed to derive a similar bound for $\tilde{\Pi}$. To that end, note that subtracting \eqref{eq:grad_Pi} for $\Lambda=\Lambda_1$ and $\Lambda=\Lambda_2$ yields
\begin{multline}\nonumber
(A+B_u\Lambda_1+B_aK_u(\Lambda_1))\tilde{\Pi}+\tilde{\Pi}(A+B_u\Lambda_1{+}B_aK_u(\Lambda_1))^\mathrm{T}\label{eq:grad_Pi}\\+\tilde{P_u}B_aR^{-2}B_a^\mathrm{T}+B_aR^{-2}B_a^\mathrm{T}\tilde{P_u}+B_u\tilde{\Lambda}\Pi(\Lambda_2)+\Pi(\Lambda_2)\tilde{\Lambda}^\mathrm{T}B_u^\mathrm{T}\\+B_aR^{-1}B_a^\mathrm{T}\tilde{P}_u\Pi(\Lambda_2)+\Pi(\Lambda_2)\tilde{P}_uB_aR^{-1}B_a^\mathrm{T}=0.\nonumber
\end{multline}
Denote $\tilde{A}(\Lambda_1)=A+B_u\Lambda_1+B_aK_u(\Lambda_1)$ and $\tilde{Q}_1=\tilde{P_u}B_aR^{-2}B_a^\mathrm{T}+B_aR^{-2}B_a^\mathrm{T}\tilde{P_u}+B_u\tilde{\Lambda}\Pi(\Lambda_2)+\Pi(\Lambda_2)\tilde{\Lambda}^\mathrm{T}B_u^\mathrm{T}\\+B_aR^{-1}B_a^\mathrm{T}\tilde{P}_u\Pi(\Lambda_2)+\Pi(\Lambda_2)\tilde{P} _uB_aR^{-1}B_a^\mathrm{T}$. Since $\tilde{A}(\Lambda_1)$ is Hurwitz, we obtain the explicit formula $\tilde{\Pi}=\int_0^\infty \mathrm{e}^{\tilde{A}(\Lambda_1)\tau}\tilde{Q}_1\mathrm{e}^{\tilde{A}^\mathrm{T}(\Lambda_1)\tau}\mathrm{d}\tau$, 
and thus
\begin{equation}\label{eq:temp_lipsPi1}
\norm{\tilde{\Pi}}_{\mathrm{F}}\le \norm{\tilde{Q}_1}_{\mathrm{F}}\int_0^\infty \norm{\mathrm{e}^{\tilde{A}(\Lambda_1)\tau}}_{\mathrm{F}}^2\mathrm{d}\tau\le c_2\norm{\tilde{Q}_1}_{\mathrm{F}},
\end{equation}
where $c_2=\sup_{\Lambda\in\mathcal{S}_0}\int_0^\infty \norm{\mathrm{e}^{\tilde{A}_1(\Lambda)\tau}}_{\mathrm{F}}^2\mathrm{d}\tau>0$ is finite since $\tilde{A}(\Lambda)$ is Hurwitz uniformly in $\mathcal{S}_0$ by Lemma \ref{le:uniformly_bounded}.  
On the other hand, we have 
\begin{multline}\label{eq:temp_lipsPi2}
\norm{\tilde{Q}_1}_{\mathrm{F}}\le 2(\norm{B_aR^{-2}B_a^\mathrm{T}}_\mathrm{F}+\norm{B_aR^{-1}B_a^\mathrm{T}}_\mathrm{F}\bar{\Pi})\norm{\tilde{P}_u}_{\mathrm{F}}\\+2\bar{\Pi}\norm{B_u}_{\mathrm{F}}\norm{\tilde{\Lambda}}_{\mathrm{F}}.
\end{multline}
Combining \eqref{eq:temp_lips3}, \eqref{eq:temp_lipsPi1} and \eqref{eq:temp_lipsPi2}, we conclude
\begin{multline}\label{eq:Ptildeineq}
\norm{\tilde{\Pi}}_{\mathrm{F}}\le c_2\Big(4c_1\bar{P}\norm{B_u}_{\mathrm{F}}\big(\norm{B_aR^{-2}B_a^\mathrm{T}}_\mathrm{F}\\+\norm{B_aR^{-1}B_a^\mathrm{T}}_\mathrm{F}\bar{\Pi}\big)+2\bar{\Pi}\norm{B_u}_{\mathrm{F}}\Big)\norm{\tilde{\Lambda}}_{\mathrm{F}}.
\end{multline}
Therefore, in view of \eqref{eq:dJ1dJ2}, \eqref{eq:temp_lips3} and \eqref{eq:Ptildeineq}, we conclude that $\frac{\mathrm{d}\tilde{J}(\Lambda)}{\mathrm{d}\Lambda}$ is locally Lipschitz on $\mathcal{S}_0$.


Next, note that the set $\mathcal{S}_0$ is bounded; for if $\Lambda\in\mathcal{S}_0$ and $\norm{\Lambda}_{\mathrm{F}}^2>\lambda_{\textrm{max}}(\Gamma)\norm{K^\star-\bar{K}}_\mathrm{F}^2$, then $\tilde{J}(\Lambda)>\tilde{J}(0) $ by definition, and thus $\Lambda\notin\mathcal{S}_0$, which is contradicting. In addition, the set $\mathcal{S}_0$ is closed. To prove this, let $\{\Lambda_n\}_{n\in\mathbb{N}}\in\mathcal{S}_0$ be a sequence such that $\Lambda_n\rightarrow{\Lambda}_{\infty}\in\mathbb{R}^{m_u\times n}$.  Then, based on Lemma \ref{le:uniformly_bounded}, the eigenvalues of the matrix sequence $A+B_u\Lambda+B_aK_u(\Lambda_n)$ remain in the left half plane uniformly on $n\in\mathbb{N}$ while satisfying \eqref{eq:uni_stable}. Therefore, the sequence of minimal positive definite solutions $P_u(\Lambda_n)$ is bounded, and following \cite{rudin1964principles} one can extract a subsequence $\{\Lambda_{n_k}\}_{k\in\mathbb{N}}$ such that $P_u(\Lambda_{n_k})\rightarrow P_u^\infty$ and $K_u(\Lambda_{n_k})\rightarrow R^{-1}B_a^\textrm{T}P_u^{\infty}=K_u^\infty$  for some positive semi-definite $P_u^\infty\in\mathbb{R}^{n\times n}$. Note that $A+B_u\Lambda_{\infty}+B_aK_u^\infty$ will be strictly stable, because $A+B_u\Lambda_{n_k}+B_aK_u(\Lambda_{n_k})$ are strictly stable uniformly in the sense of \eqref{eq:uni_stable} and converge to $A+B_u\Lambda_\infty+B_aK_u^\infty$. Thus, plugging $\Lambda=\Lambda_{n_k}$ in \eqref{eq:PL} and taking the limit as $k\rightarrow\infty$, we obtain:
\begin{multline}\nonumber
(A+B_u\Lambda_{\infty})^\mathrm{T}P_u^\infty+P_u^\infty(A+B_u\Lambda_{\infty})\\+Q+P_u^\infty B_aR^{-1}B_a^\mathrm{T}P_u^\infty=0,
\end{multline}
meaning that $P(\Lambda_\infty)$ exists and is equal to $P_u^\infty$, and is also in $\mathbb{S}_+$ since $A+B_u\Lambda_{\infty}+B_aK_u^\infty$ was proved to be strictly stable.  Given this, the continuity of $\tilde{J}$ implies 
\begin{multline*}
\tilde{J}(0)\ge \tilde{J}(\Lambda_{n_k}) \Longrightarrow  \tilde{J}(0)\ge \lim_{k\rightarrow\infty}\tilde{J}(\Lambda_{n_k})\\= \tilde{J}\left(\lim_{k\rightarrow\infty}\Lambda_{n_k}\right)=\tilde{J}(\Lambda_{\infty}).
\end{multline*}
Hence $\Lambda_{\infty}$ is such that $\exists P_{u}(\Lambda_{\infty})\in\mathbb{S}_+$ and $\tilde{J}(0)\ge \tilde{J}(\Lambda_{\infty})$, hence $\Lambda_{\infty}\in\mathcal{S}_0$, which means $\mathcal{S}_0$ is closed. Since $\mathcal{S}_0$ is a finite-dimensional set that is closed and bounded, it is compact. Therefore, since $\frac{\mathrm{d}\tilde{J}(\Lambda)}{\mathrm{d}\Lambda}$ is locally Lipschitz on $\mathcal{S}_0$, it is also globally Lipschitz on $\mathcal{S}_0$. \frQED

\textit{Proof of Theorem \ref{th:convergence}}: 
To prove item 1, it suffices to show that $\Lambda^i\in\mathcal{S}_0$ for all $i\in\mathbb{N}$, because in this case both the ARE \eqref{eq:it1} and the LE \eqref{eq:it2} admit the solutions of interest. We will use induction for that purpose.

- For $i=0$ we have $\Lambda^i\in\mathcal{S}_0$ by design. 

- For a general $i\in\mathbb{N}$, suppose that $\Lambda^i\in\mathcal{S}_0$. We want to show that $\Lambda^{i+1}\in\mathcal{S}_0$. To that end, suppose in seek of contradiction that $\Lambda^{i+1}\notin\mathcal{S}_0$. Define $\hat{\Lambda}(a)=a\Lambda^{i+1}+(1-a)\Lambda^{i}$. Then, there must exist some  $a^\star\in(0,1]$ for which the ARE \eqref{eq:RicL} does not admit a strictly stabilizing solution for $\Lambda=\hat{\Lambda}(a^\star)$, whereas it does for $\Lambda=\hat{\Lambda}(a)$ and for all $a\in[0,a^\star)$. For the latter, it follows that $\tilde{J}(\hat{\Lambda}(a))\le\tilde{J}(\Lambda^i)$ because $\hat{\Lambda}(a)$ is in the direction of the negation of the gradient and $\omega<\frac{2}{L}\frac{\lambda_{\mathrm{min}}(\Gamma^{-1})}{\lambda_{\mathrm{max}}^2(\Gamma^{-1})}$\footnote{This follows from standard argument regarding the convergence of gradient descent; see \cite{bertsekas1997nonlinear}.}. Therefore, since $\Lambda^i\in\mathcal{S}_0$ we obtain $\tilde{J}(\hat{\Lambda}(a))\le\tilde{J}(0)$, and thus $\hat{\Lambda}(a)\in\mathcal{S}_0$ for all $a\in[0,a^\star)$. Using Lemma \ref{le:uniformly_bounded} it follows that $A+B_u\hat{\Lambda}(a)+B_aK_u(\hat{\Lambda}(a))$ remains strictly stable uniformly for all $a\in[0,a^\star)$. Therefore, following continuity arguments similar to those of Lemma \ref{le:lipschitz}, it follows that \eqref{eq:RicL} admits a stabilizing solution also for $\Lambda=\hat{\Lambda}(a^\star)$, which is contradicting. Hence, $\Lambda^{i+1}\in\mathcal{S}_0$. This completes the induction and shows equations \eqref{eq:it1}-\eqref{eq:it3} admit solutions for all $i\in\mathbb{N}$.

To prove items 2-3, note that they follow from i) standard arguments regarding the convergence of gradient descent and the selection of the step size $\omega$ \cite{bertsekas1997nonlinear}; ii)  the fact that the iteration of Algorithm 1 on $\Lambda^i$ is equivalent to \eqref{eq:grad_update}; and iii) the fact that the sequence of iterates $\Lambda^i$ always remains inside $\mathcal{S}_0$ for all $i\in\mathbb{N}$.

To prove item 4, using Lemma \ref{le:grad} we have
\begin{align}\nonumber
\frac{1}{2}\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{ij}\mathrm{d}\Lambda_{kl}}&=\frac{1}{2}\frac{\mathrm{d}}{\mathrm{d}\Lambda_{kl}}\left[\frac{\mathrm{d}\tilde{J}(\Lambda)}{\mathrm{d}\Lambda}\right]_{ij}
\\\nonumber&=\frac{\mathrm{d}}{\mathrm{d}\Lambda_{kl}}e_i^\textrm{T}(\Gamma\Lambda+B_u^\mathrm{T}P_u(\Lambda)\Pi(\Lambda))e_j\\\nonumber&=e_i^\textrm{T}\Gamma\frac{\mathrm{d}\Lambda}{\mathrm{d}\Lambda_{kl}}e_j+e_i^\mathrm{T}B_u^\mathrm{T}\Big(\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}\Pi(\Lambda)\\&\qquad\qquad\qquad\qquad+P_u(\Lambda)\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}\Big)e_j.\label{eq:hessian1}
\end{align}
In addition, $e_i^\textrm{T}\Gamma\frac{\mathrm{d}\Lambda}{\mathrm{d}\Lambda_{kl}}e_j=e_i^\textrm{T}\Gamma e_ke_l^\textrm{T}e_j=[\Gamma]_{ik}\delta_{l,j}$. Thus, \eqref{eq:hessian1} becomes
\begin{multline}\label{eq:hessian2}
\frac{1}{2}\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{ij}\mathrm{d}\Lambda_{kl}}=[\Gamma]_{ik}\delta_{l,j}\\+e_i^\mathrm{T}B_u^\mathrm{T}\Big(\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}\Pi(\Lambda)+P_u(\Lambda)\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}\Big)e_j.
\end{multline}
Using the bounds of Lemma \ref{le:uniformly_bounded}, which are independent of $\Gamma$, we get from \eqref{eq:hessian2} the inequality:
\begin{multline}\label{eq:hessian3}
\frac{1}{2}\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{ij}\mathrm{d}\Lambda_{kl}}\ge[\Gamma]_{ik}\delta_{l,j}
\\-\norm{B_u^\mathrm{T}}_{\mathrm{F}}\Big(\bar{\Pi}\norm{\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}+\bar{P}\norm{\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}\Big).
\end{multline}

The equation above implies the possibility that if $\Gamma$ is sufficiently large in terms of eigenvalues, then $\tilde{J}$ is strictly convex on $\mathcal{S}_0$. However, it first needs to be shown that $\norm{\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}$ and $\norm{\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}$ remain bounded uniformly as $\lambda_{\textrm{min}}(\Gamma)$ increases. To that end, from \eqref{eq:dPij}, we get
\begin{equation}\nonumber
\norm{\frac{\mathrm{d}P_u}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}{\le}2\norm{B_u}_{\mathrm{F}}\bar{P}\int_0^\infty\norm{\mathrm{e}^{(A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda))\tau}}^2_{\mathrm{F}}\mathrm{d}\tau.
\end{equation}
But by Lemma \ref{le:uniformly_bounded}, $A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda)$ is strictly stable uniformly on $\mathcal{S}_0$ and independently of $\Gamma$ (see \eqref{eq:uni_stable}), so there exists a finite constant $c_1$ independent of $\Gamma$ and $\Lambda$ such that $\int_0^\infty\norm{\mathrm{e}^{(A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda))\tau}}_{\mathrm{F}}^2\mathrm{d}\tau<c_1$, and thus
\begin{equation}\label{eq:DPbound}
\norm{\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}\le2\norm{B_u}_{\mathrm{F}}\bar{P}c_1.
\end{equation}

On the other hand, a differentiation of \eqref{eq:grad_Pi} yields:
\begin{align*}\nonumber
&(A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda))\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}\\&+\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}(A+B_u\Lambda{+}B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda))^\mathrm{T}\label{eq:grad_Pi}\\&+\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}B_aR^{-2}B_a^\mathrm{T}+B_aR^{-2}B_a^\mathrm{T}\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}\\&+B_ue_ie_j^\textrm{T}\Pi(\Lambda)+\Pi(\Lambda)e_je_i^\textrm{T}B_u^\textrm{T}
\\&+B_aR^{-1}B_a^\mathrm{T}\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}\Pi(\Lambda)+\Pi(\Lambda)\frac{\mathrm{d}P_u(\Lambda)}{\mathrm{d}\Lambda_{kl}}B_aR^{-1}B_a^\mathrm{T}=0.
\end{align*}
This is an LE for $\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}$, the plant matrix of which, i.e., $A+B_u\Lambda+B_aR^{-1}B_a^\mathrm{T}P_u(\Lambda)$, is uniformly strictly stable owing to Lemma \ref{le:uniformly_bounded}, and the cost matrix of which, i.e., its last six terms, is uniformly bounded owing to Lemma \ref{le:uniformly_bounded} and \eqref{eq:DPbound}. Hence, following the line of proof of the previous paragraph, we conclude the existence of a finite constant $c_2>0$ such that for all $\Lambda\in\mathcal{S}_0$:
\begin{equation}\label{eq:DPibound}
\norm{\frac{\mathrm{d}\Pi(\Lambda)}{\mathrm{d}\Lambda_{kl}}}_{\mathrm{F}}\le c_2.
\end{equation}
Combining \eqref{eq:hessian3} with \eqref{eq:DPbound}-\eqref{eq:DPibound} we obtain
\begin{multline}\label{eq:hessianineq1}
\frac{1}{2}\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{ij}\mathrm{d}\Lambda_{kl}}\ge[\Gamma]_{ik}\delta_{l,j}
\\-\norm{B_u^\mathrm{T}}_{\mathrm{F}}\Big(2c_1\norm{B_u}_{\mathrm{F}}\bar{P}\bar{\Pi}+\bar{P}c_2\Big).
\end{multline}
To proceed, define the Hessian matrix:
\begin{equation*}
\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\textrm{vec}(\Lambda)^2}=\begin{bmatrix} \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{11}^2} & \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{11}\mathrm{d}\Lambda_{21}} & \ldots &  \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{11}\mathrm{d}\Lambda_{m_u,n}} \\ \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{21}\mathrm{d}\Lambda_{11}} & \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{21}^2} & \ldots   & \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{21}\mathrm{d}\Lambda_{m_u,n}} \\\vdots & \vdots & \ddots & \vdots \\ \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{m_u,n}\mathrm{d}\Lambda_{11}} & \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{m_u,n}\mathrm{d}\Lambda_{21}} & \ldots  & \frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\Lambda_{m_u,n}^2} \end{bmatrix}.
\end{equation*}
Based on the inequality \eqref{eq:hessianineq1}, this Hessian becomes diagonally dominant for sufficiently large values of $[\Gamma]_{ii}$, $i=1,\ldots,m_u$, while keeping $[\Gamma]_{ij}$ constant for $i\ne j$, $i,j=1,\ldots,m_u$. Therefore, there exists $\gamma^\star>0$ such that if $\Gamma\succ\gamma^\star I$ then $\frac{\mathrm{d}^2\tilde{J}(\Lambda)}{\mathrm{d}\textrm{vec}(\Lambda)^2}$ is positive definite uniformly. Therefore, if $\Gamma\succ\gamma^\star I$ then $\tilde{J}$, when viewed as a function of $\textrm{vec}(\Lambda)$, is strictly convex, and thus any stationary point is a minimum. Therefore, by item 3, Algorithm $1$ converges to a minimum of $\tilde{J}$, and thus of \eqref{eq:opt1}. \frQED



\textit{Proof of Proposition \ref{pr:1}:} 
Since $\mathrm{Ran}(B_a)\subseteq\mathrm{Ran}(B_u)$, there exists a matrix $E\in\mathbb{R}^{m_u\times m_a}$ such that $B_a=B_uE$. In light of this, \eqref{eq:RicL} becomes $(A+B_u{\Lambda})^\mathrm{T}P_u+P_u(A+B_u{\Lambda})+Q+P_uB_uER^{-1}E^\textrm{T}B_u^\mathrm{T}P_u=0 $.
Choosing $\Lambda=\bar{\Lambda}=-\frac{1}{2}R_u^{-1}B_u^\mathrm{T}P_u$ for some positive definite matrix $R_u\succ0$ to be selected, this equation becomes
\begin{equation}\label{eq:temprob1}
    A^\mathrm{T}P_u+P_uA+Q+P_uB_u(ER^{-1}E^\textrm{T}-R_u^{-1})B_u^\mathrm{T}P_u=0.
\end{equation}
Selecting $ R_u=(aI+ER^{-1}E^\textrm{T})^{-1}$ for some positive $a>0$, we have $R_u^{-1}=aI+ER^{-1}E^\textrm{T}$. Therefore, \eqref{eq:temprob1} yields
\begin{equation}\label{eq:temprob2}
    A^\mathrm{T}P_u+P_uA+Q-aP_uB_uB_u^\mathrm{T}P_u=0.
\end{equation}
Since $A$ is Hurwitz, we can define a constant matrix $V$ as the unique positive definite solution of the LE
\begin{equation}\label{eq:tempV}
    A^\mathrm{T}V+VA+Q=0.
\end{equation}
Subtracting \eqref{eq:temprob2} from \eqref{eq:tempV}, we obtain $A^\mathrm{T}(V-P_u)+(V-P_u)A+aP_uB_uB_u^\mathrm{T}P_u=0$. Since $A$ is Hurwitz and $aP_uB_uB_u^\mathrm{T}P_u\succeq0$, we obtain $P_u\preceq V$ by the Lyapunov theorem. Since $P_u$ is positive semidefinite, this implies $\norm{P_u}_\mathrm{F}\le \norm{V}_\mathrm{F}$. Next, by applying norms to \eqref{eq:temprob2}:
\begin{multline*}
a\norm{P_uB_uB_u^\mathrm{T}P_u}_\mathrm{F}=\norm{A^\mathrm{T}P_u+P_uA+Q}_{\mathrm{F}}\\\le 2\norm{A}_\mathrm{F}\norm{P_u}_\mathrm{F}+\norm{Q}_\mathrm{F}\le 2\norm{A}_\mathrm{F}\norm{V}_\mathrm{F}+\norm{Q}_\mathrm{F}.
\end{multline*}
Since $A, V, Q$ are constant matrices, as $a\rightarrow\infty$ we have $\norm{P_uB_uB_u^\mathrm{T}P_u}_\mathrm{F}\rightarrow0$, hence $\norm{B_u^\mathrm{T}P_u}_\mathrm{F}\rightarrow0$, and hence,
$\norm{K_u(\bar{\Lambda})}_\mathrm{F}=\norm{R^{-1}B_a^\mathrm{T}P_u(\bar{\Lambda})}_\mathrm{F}=\norm{R^{-1}E^\mathrm{T}B_u^\mathrm{T}P_u(\bar{\Lambda})}_\mathrm{F}\rightarrow0$. Therefore, for every $\epsilon>0$ there exists $\Lambda\in\mathbb{R}^{m_u\times n}$ such that $\norm{K_u(\Lambda)}_{\mathrm{F}}^2<\frac{\epsilon}{2}$. In addition, for this $\Lambda$, one can find $\gamma_1>0$ such that if $\Gamma\prec\gamma_1I$ then $\textrm{tr}(\Lambda^\textrm{T}\Gamma\Lambda)<\frac{\epsilon}{2}$, and hence $\tilde{J}(\Lambda)<\epsilon$ in total. Summarizing, we conclude for every $\epsilon>0$ there exists $\gamma_1>0$ such that if $\Gamma\prec\gamma_1 I$ then $\inf_{\Lambda} \tilde{J}(\Lambda)<\epsilon$.


Next,   let $\{{\Lambda}^n,{P}_u^n\}_{n\in\mathbb{N}}$ be a minimizing sequence of \eqref{eq:opt1}, and $K^n_u=R^{-1}B_a^\textrm{T}P_u^n$. From the constraints of \eqref{eq:opt1} we get:
\begin{multline}\label{eq:tempabove}
    (A+B_u\Lambda^n)^\mathrm{T}P_u^n+P_u^n(A+B_u\Lambda^n)+Q\\+K_u^{n\textrm{T}}RK_u^n=0.
\end{multline} 
Since $P_u^n$ is constrained to be positive definite and $Q\succ0$, it follows from \eqref{eq:tempabove} that $A+B_u\Lambda^n$ is strictly stable for all $n\in\mathbb{N}$. Assume now, in seek for contradiction, that $\sup_{n\in\mathbb{N}}\alpha(A+B_u\Lambda^n)=0$. Then, for every $a>0$ there exists $n^\star>0$ such that if $n\ge n^\star$ then $\alpha(A+B_u\Lambda^n)\ge-a$. In addition, if we choose $a$ sufficiently close to $0$, then this spectral absissa corresponds to an (without loss of generality simple) eigenvalue, denoted as $\lambda_n$, that is not controllable by $B_a$; otherwise, $A+B_u\Lambda^n+B_aK_u^n$ would be unstable for some finite $n$ (because $K_u^n$ is the optimal attack gain against $A+B_u\Lambda^n$, and $A+B_u\Lambda^n$ is bounded), which contradicts $P_u^n\in\mathbb{S}_+$.  Given this, denote the uncontrollable eigenvector of $(A+B_u\Lambda^n, B_a)$ as $v_n$, and let us decompose $\Lambda^n=\Lambda^nv_nv_n^\dagger+\Lambda^n(I-v_nv_n^\dagger )$. Note, $\Lambda^nv_nv_n^\dagger\ne0$ uniformly; otherwise, the eigenvalue $\lambda^n$ corresponding to $v_n$ would not tend to $0$ as $n\rightarrow\infty$, since it is not controllable by $B_a$. Next, define $\hat{\Lambda}^n=\Lambda^n(I-v_n v_n^\dagger)$, which satisfies $\textrm{tr}(\hat{\Lambda}^{n\textrm{T}}\Gamma\hat{\Lambda}^n)<\textrm{tr}({\Lambda}^{n\textrm{T}}\Gamma{\Lambda}^n)$ uniformly. Since the difference between $\hat{\Lambda}^n$ and ${\Lambda}^n$ is only over the space that is uncontrollable by $B_a$, it follows that $K_u(\hat{\Lambda}^n)=K_u(\Lambda^n)$. Therefore, $\tilde{J}(\hat{\Lambda}^n)<\tilde{J}({\Lambda}^n)$ uniformly, i.e., ${\Lambda}^n$ is not a minimizing sequence. Therefore, we arrive at a contradiction, and $\sup_{n\in\mathbb{N}}\alpha(A+B_u\Lambda^n)<0$.

Matrices $\Lambda^n$, $K_u^n$ are uniformly bounded because they are a minimizing sequence of \eqref{eq:opt1}, so there exist subsequences of $\Lambda^{n_k}$, $K_u^{n_k}$, $P_u^{n_k}$ of $\Lambda^{n}$, $K_u^{n}$, $P_u^n$ such that $\Lambda^{n_k}\rightarrow\bar{\Lambda}, K_u^{n_k}\rightarrow\bar{K}_u$ for some bounded limits $\bar{\Lambda},~\bar{K}_u$. Since $\sup_{n\in\mathbb{N}}\alpha(A+B_u\Lambda^n)<0$, $A+B_u\bar{\Lambda}$ is strictly stable, hence there is a strictly positive definite matrix $\bar{P}_u\succ0$ such that
\begin{equation}\label{eq:subtractalt}
(A+B_u\bar{\Lambda})^\mathrm{T}\bar{P}_u+\bar{P}_u(A+B_u\bar{\Lambda})+Q+\bar{K}_u^\textrm{T}R\bar{K}_u=0.
\end{equation}
Defining $\tilde{P}_u^{n_k}=P_u^{n_k}-\bar{P}_u$, $\tilde{\Lambda}^{n_k}=\Lambda^{n_k}-\bar{\Lambda}$, subtracting \eqref{eq:subtractalt} from \eqref{eq:tempabove} for the subsequence we get
\begin{multline}\label{eq:subtractalt2}
(A+B_u\bar{\Lambda})^\mathrm{T}\tilde{P}_u^{{n_k}}+\tilde{P}_u^{{n_k}}(A+B_u\bar{\Lambda})-\bar{K}_u^\textrm{T}R\bar{K}_u\\+K_u^{{n_k}\textrm{T}}RK_u^{n_k}+P_u^{n_k}B_u\tilde{\Lambda}^{n_k}+\tilde{\Lambda}^{\textrm{T}{n_k}}B_u^\textrm{T}P_u^{n_k}=0.
\end{multline}
Note, $K_u^{n_k}\rightarrow\bar{K}_u$ and $\tilde{\Lambda}^{n_k}\rightarrow0$. Moreover, $P_u^{n_k}$ is bounded uniformly because  $A+B_u\Lambda^{n_k}$ is bounded and strictly stable uniformly and because $Q+K_u^{n\textrm{T}}RK_u^n$ is bounded uniformly. Hence, \eqref{eq:subtractalt2} implies $\tilde{P}_u^{n_k}\rightarrow0$ and thus $P_u^{n_k}\rightarrow\bar{P}_u$. Finally, since this implies $\bar{K}_u=R^{-1}B_a^\textrm{T}\bar{P}_u,$ rearranging \eqref{eq:subtractalt} yields
\begin{multline}\nonumber
(A+B_u\bar{\Lambda}+B_a\bar{K}_u)^\mathrm{T}\bar{P}_u+\bar{P}_u(A+B_u\bar{\Lambda}+B_a\bar{K}_u)\\+Q-\bar{K}_u^\textrm{T}R\bar{K}_u=0.
\end{multline}
From the first paragraph, for every $\epsilon$ there is $\gamma^\star>0$ such that if $\Gamma\prec\gamma^\star I$ then $\norm{\bar{K}_u}_{\mathrm{F}}<\epsilon$ and hence $Q-\bar{K}_u^\textrm{T}R\bar{K}_u\succ0$ for small enough $\epsilon$, so the above equation implies $A+B_u\bar{\Lambda}+B_a\bar{K}_u$ is strictly stable.  Thus $(\bar{\Lambda},\bar{P}_u)$ is a feasible solution of \eqref{eq:opt1} that is also minimizing, hence \eqref{eq:opt1} admits a minimizer. 


\begin{comment}
