\title{Enhancing Research Methodology and Academic Publishing: A Structured Framework for Quality and Integrity}

\author[first]{Md. Jalil Piran}
\affiliation[first]{Department of Computer Science and Eingeering, Sejong University, Seoul 05006, South Korea, (email: piran@sejong.ac.kr)} 
