\section{Preliminaries}\label{sec:Preliminaries}

\subsection{Problem Statement}
Consider a system with the following dynamics
\begin{equation}\label{eq:plant}
\dot{X} = f(X,u),
\end{equation}
where $X \in \mathcal X \subset \R^{n_x}$ is the state, $u \in \mathcal U \subset \R^{n_u}$ is the control input, and $f$ is a smooth vector field. The free space is denoted by $\mathcal X_{\mathrm{free}} \subset \mathcal{X}$, where at $X \in \mathcal X_{\mathrm{free}}$, the system~\eqref{eq:plant} does not collide with any obstacles in the environment. %We have some cost function $c(X, u)$ to minimize. 
The kinodynamic planning problem is as follows:

\begin{prob}\label{prob:path_planning}
Given $\mathcal X_{\mathrm{free}}$, an initial state $X_s \in \mathcal X_{\mathrm{free}}$, a goal state $X_g \in \mathcal X_{\mathrm{free}}$, system \eqref{eq:plant}, and a cost function $c(X, u)$, find the optimal trajectory $\mathcal P_t$ that:
\begin{enumerate}[(I)]
\item starts at $X_s$ and ends at $X_g$, while satisfying \eqref{eq:plant};
\item is collision-free $ \mathcal P_t \subset \mathcal X_{\mathrm{free}}$; and
\item minimizes the cost $\int_{0}^{t_{\mathrm{f}}} c(X,u) \, \mathrm{d}\tau$, where $t_{\mathrm{f}}$ is the final time. 
\end{enumerate}
\end{prob}

Problem \ref{prob:path_planning} can be formulated as the following OCP: 
\begin{equation}
\begin{split}
\min_{u, t_{\mathrm{f}}} \ \ & J = \int_{0}^{t_{\mathrm{f}}} c(X,u) \, \mathrm{d}\tau, \\
\mathrm{s.t.} \ \ & \dot{X} = f(X,u), \\
& X(0)=X_s, \ X(t_{\mathrm{f}})=X_g, \\
& u \in \mathcal{U}, \ X \in \mathcal{X}_{\mathrm{free}}, \ \forall t\in [0, t_{\mathrm{f}}].
\label{eq:OCP}
\end{split}
\end{equation}

We solve problem (\ref{eq:OCP}) approximately using MPs. Each MP is generated by solving an OCP similar to (\ref{eq:OCP}), with different boundary conditions and without obstacle constraints. We tackle Problem \ref{prob:path_planning} by repetitively applying MPs. The new planning problem is given below. 

\begin{prob}\label{prob:MP planning}
Given $\mathcal X_{\mathrm{free}}$, an initial state $X_s \in \mathcal X_{\mathrm{free}}$, a goal state $X_g \in \mathcal X_{\mathrm{free}}$, and a set of MPs, find the trajectory as the concatenation of a sequence of $n$ MPs, $\{mp_1, mp_2, \cdots, mp_n\}$, such that
\begin{enumerate}[(I)]
\item starts at $X_s$ and reaches a neighborhood of $X_g$;
\item is collision-free; and
\item minimizes the accumulated cost of $\{mp_1, \cdots, mp_n\}$. 
\end{enumerate}
\end{prob}

\subsection{Trailer Modeling}

Consider the front wheel drive \emph{standard tractor-trailer system} \cite{rouchon1993flatness,altafini2001feedback} shown in Figure \ref{fig:trailer_kinematics_rough}, where $(x,y)^\top$ are the coordinates of the midpoint of the tractor's rear wheel axis, $\theta_0$ is the tractor orientation, and $\theta_1, \theta_2, \theta_3$ are the orientations of trailers. The control inputs are $v_f$ and $\delta$, denoting the front-wheel velocity and the steering angle of the tractor, respectively. Mechanical constraint $|\delta| \le \delta_{\max}$ limits the minimum turning radius $R$.  Since $v_f$ and $\delta$ can be independently controlled, we introduce new control variables: $u = (v,s)^\top = (\cos(\delta) v_f, \tan(\delta)/\tan(\delta_{\max}))^\top$, 
where $\tan(\delta_{\max}) = L/R$, $L$ is the distance between $(x,y)$ and the midpoint of the front wheel axis, and $|s| \le 1$ is the normalized steering angle. Defining $\xi = (\xi_1, \xi_2, \xi_3, \xi_4, \xi_5, \xi_6)^\top = (x,y,\theta_0, \theta_1-\theta_0, \theta_2 - \theta_1, \theta_3 - \theta_2)^\top$, we have
\begin{equation}\label{eq:fwd_car_dynamics2}
	\begin{aligned}
		\dot x & = \cos(\theta_0)v \\
		\dot y & = \sin(\theta_0)v \\
		\dot \theta_0 & =  \frac{vs}{R} \\
		\dot \xi_4 & = -v\frac{d_1s +  \sin(\xi_4)R}{Rd_1} \\
		\dot \xi_5 & = -v \frac{d_1\cos(\xi_4)\sin(\xi_5) - d_2\sin(\xi_4)}{d_1d_2} \\
		\dot \xi_6 & = -v \cos(\xi_4) \frac{d_2\cos(\xi_5)\sin(\xi_6)-d_3\sin(\xi_5)}{d_2d_3}.
	\end{aligned}
\end{equation}
In $\xi$-coordinates, the constraints to avoid jack-knife are
\begin{equation}\label{eq:constraint_jackknife}
    |\xi_k| \le \xi_{\max}, \quad 4 \le k \le 6,
\end{equation}
where $\xi_{\max}$ must be less than $\pi/2$. The trailer system is subject to additional state and control constraints:
\begin{equation}\label{eq:constraint_xu}
    -\pi < \theta_0 \le \pi, \quad |v| \le v_{\max}, \quad |s| \le 1.
\end{equation}

