\subsection{DE-AGT}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\IncMargin{.5em}
\begin{algorithm}
\caption{DE-AGT}
\label{alg:DE-AGT}
$\mathcal{V} \leftarrow \{ x_\mathrm{init} \}$; $\mathcal{E} \leftarrow \emptyset$; $\mathcal{T} \leftarrow (\mathcal{V},\mathcal{E})$\;
$Q \leftarrow \{ x_\mathrm{init} \}$\;
$k \leftarrow 1$; $\mathrm{flag} \leftarrow \mathbf{False}$\;
\While{$k \le K$ $\mathbf{and}$ $\lnot \mathrm{flag}$} 
{
    $k \leftarrow k+1$\;
    $x_{\mathrm{select}} \leftarrow Q._{\mathrm{Top}}$\;
    \eIf {$d(x_\mathrm{select}, x_\mathrm{goal}) \le \epsilon_1$}
    {
        $\mathrm{flag} \leftarrow \mathbf{True}$\;
    }
    {   
            $(\mathcal{T}, Q) = \mathsf{ExpandTree}(\mathcal{T}, Q, x_{\mathrm{select}})$;
    }
}
\KwRet $\mathcal{T}, \mathrm{flag}$;
\end{algorithm}
\DecMargin{.5em}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\IncMargin{.5em}
\begin{algorithm}
\caption{ExpandTree}
\label{alg:ExpandTree}
$P_s \leftarrow \mathsf{FindMPs} (x_\mathrm{select})$\;
\If{$\mathsf{FirstTimeExpand}(x_{\mathrm{select}})$}
{
    $\mathrm{ModeCost} = \mathsf{ComputeModeCost}(x_{\mathrm{select}}, P_s)$\;
}
$\mathcal{M} = \mathsf{BestMode}(\mathrm{ModeCost})$\;
\ForEach{$mp \in \mathcal{M}$}
{
    $(x_{\mathrm{next}}, \tau) = \mathsf{Expand}(x_\mathrm{select}, mp)$\;
    \If{$\mathsf{CollisionFree(\tau})$}
    {
        \If{$d(x_\mathrm{next}, x_\mathrm{goal}) \le \epsilon_2$}
        {
            $(x_{\mathrm{next}}, \tau) = \mathsf{LQRConnect}(x_\mathrm{goal}, \tau)$\;
        }
        $\mathcal{V} \leftarrow \mathcal{V} \cup \{x_{\mathrm{next}}\}$; $\mathcal{E} \leftarrow \mathcal{E} \cup \tau$\;
        $Q._{\mathsf{Push}}(x_{\mathrm{next}})$\;
    }
}
$\mathrm{ModeCost} = \mathsf{UpdateModeCost}$\;
\If{$\mathsf{AllModeExpanded}(x_{\mathrm{select}})$} 
{
    $Q._{\mathsf{Delete}}(x_{\mathrm{select}})$\;
}
\KwRet $\mathcal{T}, Q$;
\end{algorithm}
\DecMargin{.5em}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The complete DE-AGT algorithm is given by Algorithm~\ref{alg:DE-AGT}.
DE-AGT maintains a search tree $\mathcal{T}$ and a priority queue $Q$.
The tree starts with the initial root node $x_{\mathrm{init}}$ and expands outwards by applying the available MPs until it reaches a neighborhood of the goal.
DE-AGT uses an A* heuristic to select the best node in $Q$ for expansion. Each node $x$ is assigned an $f$-value,
\begin{equation}\label{eq:f-value}
    f(x) =  g(x) + \alpha \mathsf{NNCost}(x),
\end{equation}
where $g(x)$ is the cost-to-come and $\alpha > 1$ is an inflation factor \cite{Likhachev2009Planning, wang2019improved}.
The operation $Q._{\mathrm{Top}}$ selects the best node in $Q$, i.e., that with the lowest $f$-value. Since the NN might output unreasonable cost-to-go estimate, we might use the following formula for $f(x)$:
$$
f(x) =  g(x) + \alpha \min(\max(\mathsf{RS}(x),\mathsf{NNCost}(x)),C),
$$
where $\mathsf{RS}(x)$ is the length of the Reeds-Shepp (RS) path for tractor only \cite{reeds1990optimal} and $C$ is a large positive constant. Given two configurations $(x_a, y_a,\theta_a)$ and $(x_b, y_b,\theta_b)$, one can compute the minimum length RS path between them.

In Algorithm~\ref{alg:ExpandTree}, $\mathsf{FindMPs}(x_\mathrm{select})$ finds the the set of MPs $P_s$ applicable at $x_{\mathrm{select}}$ according to the $s$ value of $x_{\mathrm{select}}$.
In lines 2-3, if $x_{\mathrm{select}}$ is selected for the first time, the cost of the MPs in $P_s$ are computed according to~(\ref{mode_cost}), and the cost of the modes of $P_s$ are computed and saved. In our case, the $\mathrm{ModeCost}$ is a vector with four entries since $P_s$ has 4 modes. If there are no MPs for a mode, this mode has infinite cost. 
$\mathsf{BestMode}(\mathrm{ModeCost})$ selects the mode with the lowest cost, and the MPs in $\mathcal{M}$ are used to expand $x_{\mathrm{select}}$ in line 5-11.
$\mathsf{Expand}(x_\mathrm{select}, mp)$ applies $mp$ to expand $x_{\mathrm{select}}$. The resulting trajectory is $\tau$ and the reached node is $x_{\mathrm{next}}$. 
If $x_{\mathrm{next}}$ is close enough to $x_{\mathrm{goal}}$ (line 8), the LQR controller is invoked for goal connection, which will potentially update $\tau$ and $x_{\mathrm{next}}$.
In line 10, the tree is updated by adding a new node $x_{\mathrm{next}}$ and new edge $\tau$.
$x_{\mathrm{next}}$ is pushed into queue $Q$.
After all MPs in $\mathcal{M}$ have been expanded, the mode cost of $\mathcal{M}$ is set to infinity (line 12) so that this mode will not be expanded. If all modes at $x_{\mathrm{select}}$ have been expanded, which also means that the costs of all modes are infinity, $x_{\mathrm{select}}$ is deleted from queue $Q$ (lines 13-14).

\begin{rem}
    Line 1 in Algorithm~\ref{alg:ExpandTree} implicitly imposes the constraint that the $s$ of $x_\mathrm{init}$ should belong to the set $\{s_m\}$.
\end{rem}

The goal connection method is given in Algorithm~\ref{alg:LQRConnect} as detailed in Section~\ref{sec:DE-AGT}.B and also illustrated in Figure \ref{fig:LQRTrackingIllustration}.
In line 1, the trajectory $\tau_{\mathrm{LQR}_1}$ corresponds to the blue trajectory in Figure \ref{fig:LQRTrackingIllustration}(b). In line 3, the trajectory $\tau_{\mathrm{LQR}_2}$ corresponds to the orange trajectory in Figure \ref{fig:LQRTrackingIllustration}(d).
$\mathsf{LQRConnect}$ uses an LQR trajectory tracking controller to update the trajectory $\tau$ such that the final state of the updated trajectory is much closer to the goal state.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\IncMargin{.5em}
\begin{algorithm}
\caption{LQRConnect}
\label{alg:LQRConnect}
$(x_{\mathrm{new}}, \tau_{\mathrm{LQR}_1}) = \mathsf{LQRTracking} (x_\mathrm{goal}, \tau)$\;
\If{$\mathsf{CollisionFree}(\tau_{\mathrm{LQR}_1})$ $\mathbf{and}$ $d(x_\mathrm{select}, x_\mathrm{new}) \le \epsilon_3$}
{
    $(x_{\mathrm{new}}, \tau_{\mathrm{LQR}_2}) = \mathsf{LQRTracking} (x_\mathrm{select}, \tau_{\mathrm{LQR}_1})$\;
    \If{$\mathsf{CollisionFree}(\tau_{\mathrm{LQR}_2})$ $\mathbf{and}$ $d(x_\mathrm{new}, x_\mathrm{goal}) \le \epsilon_4$}
    {
        $\tau \leftarrow \tau_{\mathrm{LQR}_2}$\;
        $x_{\mathrm{next}} \leftarrow x_{\mathrm{new}}$\;
    }
}
\KwRet $\tau, x_{\mathrm{next}}$;
\end{algorithm}
\DecMargin{.5em}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

