\section{Preliminary}
\label{sec:prelim}


\paragraph{Notations.}
We denote the set $\set{1,\ldots, n}$ by $[n]$.
We denote a d-dimensional maximally entangled state (MES) by $\ket{\phi_+} = \frac{1}{\sqrt{d}}\sum_{i=1}^d \ket{i,i}$.
The special case of $d=2$ is the EPR pair, which is denoted by $\ket{\text{EPR}} = \frac{1}{\sqrt{2}}(\ket{00}+\ket{11})$.
We denote a Hilbert space by $\calH$.
For approximations, we use the following notations.
If $a,b \in \C$, we write $a \appd{\epsilon} b$ to mean $\abs{a-b} \leq \epsilon$.
For vectors $\ket{v}$ and $\ket{u}$, we write $\ket{u} \appd{\epsilon} \ket{v}$ to mean $\norm{\ket{u}-\ket{v}} \leq \epsilon$.


\paragraph{$\MIP^*$ and nonlocal games.}
We follow the notations of \cite{neexp} for two-player one-round $\MIP^\ast$ protocols.
For some language $L$, such a protocol is an interaction between a verifier and two noncommunicating provers, who can share arbitrary entanglement.
Given an instance $\ipt$, the verifier first samples a pair of random questions and sends them to the provers, receives
a pair of answers from the provers, and decides whether to accept $\ipt \in L$ or reject it based on the questions and answers.
For $\MIP^*$, the verifier is described by two algorithms: a randomized sampler $Q$ and a deterministic verification algorithm $V$.
Given $\ipt$, the protocol is denoted by $P(\ipt)$.
To execute the protocol, the verifier samples two questions $(x, y) \sim Q(\ipt)$ and gives question $x$
to Alice and question $y$ to Bob.
After receiving answers $a$ and $b$, the verifier accepts if $V(\ipt, x, y, a, b) = 1$.
Let $n = \abs{\ipt}$. Then the question length, answer length, sampling time and verification time of $P(\ipt)$
are denoted by $q(n)$, $a(n)$, $t_Q(n)$ and $t_V(n)$.
When analyzing answer reduction transformation, we break $V$ into two phases. In the first phase, $V$ computes
a predicate circuit $C^{\ipt}_{x,y}$ to check the answers. In the second phase, $V$ runs $C^{\ipt}_{x,y}$ on answers $a,b$ and outputs the output of $C^{\ipt}_{x,y}$. We call the size of $C^{\ipt}_{x,y}$ the \emph{decision complexity} of $P$ and denote it by $d_V(n)$.

Two-player one-round $\MIP^\ast$ protocols are also nonlocal games.
We follow the notations of \cite{re} for nonlocal games.
\begin{definition}[Two-player one-round games]
    A two-player one-round game $G$ is specified by a tuple $(\calX, \calY, \calA, \calB, \mu, V)$ where
    \begin{itemize}
        \item $\calX$ and $\calY$ are finite sets, called the \emph{question sets},
        \item $\calA$ and $\calB$ are finite sets, called the \emph{answer sets},
        \item $\mu$ is a probability distribution over $\calX \times \calY$, called the \emph{question distribution}, and
        \item $V: \calX \times \calY \times \calA \times \calB \to \set{0,1}$ is a function, called the \emph{decision predicate}.
    \end{itemize}
\end{definition}
In the context of $\MIP^*$, $\mu$ is the distribution that $Q(\ipt)$ samples from, and the predicate $V$ has
$\ipt$ hardcoded into it, so $V(x,y,a,b) = V(\ipt, x, y, a, b)$ for all $(x,y,a,b) \in \calX \times \calY \times \calA \times \calB$.

Next, we formally define the strategies for nonlocal games and $\MIP^*$ protocols and the values they achieve.
\begin{definition}[Tensor-product strategies]
    A tensor-product strategy $S$ of a nonlocal game $G = (\calX, \calY, \calA, \calB, \mu, V)$ is a tuple 
    $(\ket{\psi}, A, B)$ where
    \begin{itemize}
        \item a bipartite quantum state $\ket{\psi} \in \calH_A \x \calH_B$ for finite dimensional complex Hilbert
spaces $\calH_A$ and $\calH_B$,
        \item $A$ is a set $\set{A^x}$ such that for every $x \in \calX$, $A^x = \set{A^x_a \mid a \in \calA}$ is 
        a projective measurement over $\calH_A$, and 
        \item $B$ is a set $\set{B^y}$ such that for every $y \in \calY$, $B^y = \set{B^y_b \mid b \in \calB}$ is 
        a projective measurement over $\calH_B$.
    \end{itemize}
\label{def:QStrategy}
\end{definition}
We will not discuss commuting operator strategies in our work, so we also refer to tensor-product strategies as quantum strategies.
Note that we focus on projective measurements in the definition above. This is because 
when we prove the quantum soundness of an $\MIP^\ast$ protocol, we can assume the measurements are projective by Naimark's Dilation theorem \cite[Theorem 5.1]{re}.

\begin{definition}[Tensor product value]
    The tensor-product value of a tensor product strategy $S = (\ket{\psi}, A ,B)$ for a nonlocal game
    $G = (\calX, \calY, \calA, \calB, \mu, V)$ is defined as
    \begin{align*}
        \val^\ast(G,S) = \sum_{x,y,a,b} \mu(x,y)V(x,y,a,b) \bra{\psi} A^x_a \x B^y_b \ket{\psi}.
    \end{align*}
    For $v \in [0,1]$ we say that the strategy passes or wins $G$ with probability $v$ if $\val^\ast(G,S)\geq v$.
    The quantum value or tensor product value of $G$ is defined as
    \begin{align*}
        \val^*(G) = \sup_{S} \val^\ast(G,S)
    \end{align*}
    where the supremum is taken over all tensor product strategies $S$ for $G$.
\end{definition}
In other words, the quantum value of Alice and Bob's strategy is the probability for the verifier to accept Alice and Bob's answers over the distribution of the questions.
We also say a strategy that achieves quantum value 1 is a \textbf{perfect} quantum strategy.
The correlation produced by the strategy $S$ is $\set{ P(a,b\mid x,y) = \bra{\psi} A^x_a \x B^y_b \ket{\psi} }_{a,b,x,y}$.
If $\val^*(G,S)=1$, we say the correlation produced by $S$ is a \textbf{perfect correlation}.


There is
a special subclass of quantum strategies called projective, commuting and consistent (PCC) strategies.
Since we only consider projective measurements in this work, we define commuting strategies and consistent strategies below.
\begin{definition}
    We say a projective strategy $S = (\ket{\psi}, A ,B)$ for a nonlocal game
    $G = (\calX, \calY, \calA, \calB, \mu, V)$ is \emph{commuting} if for any $(x,y) \in \calX \times \calY$ such that
    $\mu(x,y) > 0$, $[A^x_a, B^y_b] = A^x_aB^y_b - B^y_bA^x_a = 0$ for all $a \in \calA$ and $b \in \calB$.
    Moreover, we say $S$ is \emph{consistent} if for all $x \in \calX, a \in \calA$ and $y \in \calY, b\in \calB$
    \begin{align*}
        A^x_a \x \1 \ket{\psi} = \1 \x A^x_a \ket{\psi} && 
         B^y_b \x \1 \ket{\psi} = \1 \x B^y_b \ket{\psi}.
    \end{align*}
\end{definition}
The reason we introduce PCC strategies will be explained after we introduce the complexity class $\MIP^*$ below.

\begin{definition}
    We say a language $L$ is in $\MIP^*_{c,s}[q,a,t_Q,t_V,d_V]$, where $q,a,t_Q, t_V, d_V,c, s$ are functions of the instance size, if there exists a protocol $P = (Q,V)$ whose question length, answer length, sampling time, verification time, and decision complexity
    are upper bounded by $q, a, t_Q, t_V, d_V$ respectively such that:
    \begin{description}
        \item[Completeness] If $\ipt \in L$, there exists a quantum strategy for $P(\ipt)$ whose value is at least $c$.
        \item[Soundness] If $\ipt \notin L$, there is no quantum strategy whose value is larger than $s$ for $P(\ipt)$.
    \end{description}
\end{definition}


When using only the first four parameters, we use $t_V$ as an upper bound of $d_V$.
The decision complexity will be explicit in the analysis of answer reduction.
In this work, we focus on the case that $c=1$ and $s$ is a constant smaller than 1.
To simplify the notation, we sometimes use $V$ to represent a verifier.
If an $\MIP^*$ protocol has a perfect PCC strategy, then the question-reduced and answer-reduced protocols also have perfect PCC strategies. We need this property to argue the completeness of $\MIP^*$ protocols are preserved through question reduction and answer reduction.

\begin{definition}[Zero knowledge $\MIP^*$]
    Let $P=(Q,V)$ be a two-prover one-round $\MIP^*$ protocol for a language $L$ with completeness $1$ and 
    soundness $s$.
    For any $\ipt \in L$, let $\Sim$ be a classical simulator running in a polynomial time of $\abs{\ipt}$,
    and let $\mathrm{D}$ be a distinguisher also running in a polynomial time of $\abs{\ipt}$.
    We say the protocol $P$ is
    \begin{description}   
        \item[Perfect zero-knowledge (PZK),] if there is a perfect quantum strategy $S = (\ket{\psi}, M, N)$, whose correlation can be sampled by a simulator;
        \item[Statistical zero-knowledge (SZK),] if there is a perfect quantum strategy $S = (\ket{\psi}, M, N)$ and a simulator $\Sim$, such that $\Sim$ can sample from a correlation whose statistical distance to the correlation of $S$ is smaller than any inverse polynomial in $\abs{\ipt}$;
        \item[Computational zero-knowledge (CZK),] if there is a perfect quantum strategy $S = (\ket{\psi}, M, N)$ and a simulator $\Sim$, such that $\Sim$ can sample from a correlation that cannot be distinguished from the correlation $S$ by any distinguisher $\mathrm{D}$.
    \end{description}
    The class $\pzkMIP^*_{c,s}$ (resp. $\szkMIP^*_{c,s}$ and $\czkMIP^*_{c,s}$) is the class of languages with a
    perfect zero-knowledge (resp. statistical zero-knowledge and computational zero-knowledge) two-prover one-round $\MIP^*$ protocol
    with completeness $c$ and soundness $s$.
\end{definition}


\paragraph{Binary constraint system games.}

In our results, we shall utilize a special type of nonlocal games inspired by the binary constraint systems (BCS).
Specifically, a BCS consists of $n$ binary variables and $m$ constraints. For later convenience, we use signed variables, where each variable $v_j$ for $j\in[n]$ takes values in $\{\pm1\}$. 
In the following discussions, we shall refer to a variable by its index $j\in[n]$. 
In the BCS, each constraint is a Boolean function over a subset of variables, and we denote the maximum number of a constraint's composing variables as $C$. For the $i$'th constraint, we denote the subset of variables within it as $V_i$. 
Additionally, for the $i$'th constraint, we denote the set of satisfying assignments over its composing variables as $C_i$, which is a subset of $\{\pm1\}^{V_i}$. 
From another viewpoint, since every Boolean function can be represented as a multi-linear polynomial over the real field, we can consider each constraint as defined by a polynomial $c_i$ over the set of composing variables $V_i$, and the constraint is represented as a function in the form of $c_i(V_i)=\pm1$.
BCS is widely used in classical theoretical computer science. For instance, every 3-SAT instance defines a BCS.

Once a BCS is given, we can define an associated nonlocal game~\cite{cleve2014characterization} . In a constraint-constraint BCS nonlocal game, the two players, Alice and Bob, are each given a constraint labelled by $i\in[m]$ and $j\in[m]$, respectively. The players need to output a satisfying assignment to the constraint they each receive. Furthermore, for every variable that shows up in both constraints, i.e., $\forall k\in V_i\cap V_j$, the values assigned to it must be the same.
In a constraint-variable BCS nonlocal game, one of the players, say Alice, is given a constraint $i\in[m]$, and Bob is given a variable $j\in V_i$. In this game, Alice needs to output a satisfying assignment to the constraint, and her assignment to the variable $j$ must take the same value as Bob's.

As a famous BCS example, the Mermin-Peres magic square~\cite{mermin1990simple,peres1990incompatible} is given as:
\begin{equation}
\begin{aligned}
    v_1v_2v_3 &= 1, \\
v_4v_5v_6 &= 1, \\
v_7v_8v_9 &= 1, \\
v_1v_4v_7 &= 1, \\
v_2v_5v_8 &= 1, \\
v_3v_6v_9 &= -1.
\end{aligned}
\end{equation}
This BCS contains nine variables, six constraints, and each constraint contains three variables.
All the constraints in this BCS cannot be simultaneously satisfied. Consequently, the associated BCS game cannot be won perfectly via classical strategies. Nevertheless, by adopting tensor-product strategies in \cref{def:QStrategy}, the nonlocal players can win the game perfectly.
In the perfect-winning strategy, the players needs to share a maximally entangled state, $\ket{\phip}$.
Moreover, the set of quantum measurements of each player can be seen as a operator-valued satisfying assignment to the BCS. That is, for the observables associated with variables measured by Alice (resp. Bob), $\{A^x\}$ (resp. $\{B^y\}$), with respect to each constraint $c_i(V_i)=\pm1$, we have $c_i(\{A^x\}_{x\in V_i})=\pm\1$ (resp. $c_i(\{B^y\}_{y\in V_i})=\pm\1$), where $\1$ is the identity operator.





\section{Constraint-constraint game to constraint-variable game}
The PZK protocols from \cite{mastel2024two} can be viewed as 
constraint-constraint BCS games where each prover gets a uniformly random constraint.
To compress such PZK protocols while preserving perfect completeness, they need to be converted to constraint-variable games.
For a constraint-constraint BCS game with $m$ constraints and $n$ variables,
in its corresponding constraint-variable BCS game, Alice gets a random constraint $i \in [m]$
and Bob gets a random variable $k$ in Alice's constraint. Our first result is the following theorem.


\begin{theorem}
    \label{thm:cc_to_cv}
    Let $G$ be a constraint-constraint BCS game with $n$ variables, $m$ constraints and at most $C$ variables in each constraint, and $G^{cv}$ be the corresponding constraint-variable BCS game.
    \begin{description}
        \item[Completeness] If $G$ has a perfect finite-dimensional quantum strategy, $G^{cv}$ has a perfect PCC quantum strategy whose shared state is maximally entangled.
        \item[Soundness] If $G^{cv}$ has a quantum strategy with winning probability $1-\epsilon$, then $G$ has a quantum strategy achieving quantum value at least $1 - \poly(m, n, C, \epsilon^{1/2})$.
        \item[Zero-knowledge] If the corresponding $\MIP^*$ protocol of $G$ has perfect completeness and is perfect zero-knowledge (resp. statistical zero-knowledge and computational zero-knowledge), so is the corresponding protocol of $G^{cv}$.
    \end{description}
\end{theorem}

Targeting the final result of the succinct zero-knowledge protocol for $\MIP^*$, this theorem guarantees the PCC condition for the perfect strategy. This is vital for answer reduction, as answer reduction can only be applied to an oracularized protocol,
and oracularization preserves completeness only if the original game satisfies the PCC condition \cite{natarajan2023quantum}.
Note that the zero-knowledge protocol from \cite{mastel2024two}, which uses constraint-constraint games, does not satisfy the PCC condition in the complete case.
Moreover, since question reduction and oracularization preserve the PCC condition, we will use this theorem to make sure the original game for question reduction and answer reduction satisfies the PCC condition.


\begin{proof}
For the constraint-constraint BCS game, $G$, let Alice and Bob's quantum strategy be $S = (\ket{\psi}, M, N)$, where
\begin{enumerate}
    \item $\ket{\psi}$ is a finite or countably-infinite dimensional entangled state;
    \item Alice: for a constraint question $i\in[m]$, her measurement is given by projectors $\{M^i_a\}_a$, with $a\in C_i$ giving a satisfying assignment to the constraint;
    \item Bob: for a constraint question $j\in[m]$, his measurement is given by projectors $\{N^i_b\}_b$, with $b\in C_i$ giving a satisfying assignment to the constraint.
\end{enumerate}

\paragraph{Completeness.} 
Suppose the strategy $S$ can win the constraint-constraint game $G$ perfectly. On Alice's side, denote $M^{i,k}=\sum_{a \in C_i} (-1)^{a_k} M^i_a$ with $a_k=\pm1$, representing the observable for the variable labelled by $k$ in the $i$'th constraint, and we take a similar notation on Bob's side. We decompose the entangled state $\ket{\psi}$ on the Schmidt basis:
\begin{equation}\label{eq:Schmidt}
    \ket{\psi}=\sum_{i=1}^{\infty}\alpha_i\ket{\phi_i}\ket{\varphi_i},
\end{equation}
where $\{\ket{\phi_i}\}_i$ and $\{\ket{\varphi_i}\}_i$ form orthonormal bases of $\mathcal{H}$, and $\alpha_i\geq0,\forall i$, and $\sum_{i=1}^\infty\alpha_i^2=1$. In the following discussions, we restrict the Hilbert space to be the support of $\ket{\psi}$, i.e., the spaces of the subsystems are given by $\mathcal{H}=\mathrm{span}(\{\ket{\phi_i}\}_{i:\alpha_i>0})$, which is isomorphic to $\mathrm{span}(\{\ket{\psi_i}\}_{i:\alpha_i>0})$. In addition, we have the following lemma:

\begin{lemma}[Lemma~2, \cite{cleve2014characterization}]
  Consider the quantum state $\ket{\psi}\in\mathcal{H}\x\mathcal{H}$ given in Eq.~\eqref{eq:Schmidt}, and Hermitian operators $B,C_1,C_2$ acting on $\mathcal{H}$, such that $-\1 \leq C_1,C_2,B\leq \1$. If $\bra{\psi}B\x C_1\ket{\psi}=\bra{\psi}B\x C_2\ket{\psi}$, then $C_1=C_2$ \footnote{If some eigenvectors of these operators reside outside $\mathcal{H}$, they do not enter the calculation and their effects are also not observable.}.
\label{lemma:OperatorId}
\end{lemma}

Based on Eq.~\eqref{eq:Schmidt} and Lemma~\ref{lemma:OperatorId}, we prove completeness with several steps. 

\begin{enumerate}
    \item Consider $k\in V_i\cap V_j$, and the following two cases: (1) Alice receives the $i$'th constraint, Bob receives the $i$'th constraint, and (2) Alice receives the $i$'th constraint, Bob receives the $j$'th constraint. Then,
    \begin{align*}
        \bra{\psi}M^{i,k}\x N^{i,k}\ket{\psi}&=1, \\
        \bra{\psi}M^{i,k}\x N^{j,k}\ket{\psi}&=1.
    \end{align*}
    By applying Lemma~\ref{lemma:OperatorId}, we have $N^{i,k}=N^{j,k}$. It follows that Bob's effective observables for the $k$'th variable in the two cases are the same. 
    Hence for any $i$ such that $k\in V_i$, we can denote $N^{i,k}\equiv B^{k}$.

    \item Using a similar argument, Alice's effective observables for the same variable in various constraints are the same, which we denote as $\{A^{k}\}_k$.

    \item As Alice's assignments need to satisfy the constraints, for the $i$'th constraint,
    \begin{align*}
        \bra{\psi}c_i(M^{i,k\in V_i})\otimes \1\ket{\psi}=1,
    \end{align*}
    where $c_i$ represents the multilinear polynomial function that defines the $i$'th constraint in the BCS.
    By applying Lemma~\ref{lemma:OperatorId}, $c_i(M^{i,k\in V_i})\equiv c_i(A^{k\in V_i})=\1$. Therefore, $\{A^k\}_k$ gives an operator-valued satisfying assignment to the BCS. Similarly, $\{B^k\}_k$ also gives an operator-valued satisfying assignment to the BCS.
    \item For every $k$, $A^k$ and $B^{k}$ satisfy
    \begin{align*}
        \bra{\psi}A^k \x B^k\ket{\psi}=1,
    \end{align*}
    hence $A^k\x \1\ket{\psi}=\1\x B^k\ket{\psi}$, given by
    \begin{align*}
        \sum_{i=1}^\infty\alpha_i(A^k\ket{\phi_i})\ket{\varphi_i}=\sum_{i=1}^\infty\alpha_i\ket{\phi_i}(B^k\ket{\varphi_i}).
    \end{align*}
    Both sides are also Schmidt decompositions of the state $\ket{\psi}$. Note that the Schmidt decomposition is unique up to a unitary operator acting on a subspace spanned by vectors of the same Schmidt coefficient. Therefore, for every subspace, we have $\mathcal{H}_{\alpha}=\mathrm{span}(\ket{\phi_i}:\alpha_i\equiv\alpha)$, $A^k\mathcal{H}_{\alpha}=\mathcal{H}_{\alpha},\forall k$. A similar argument can be made on Bob's side. Then, the operators restricted to the subspace $\mathcal{H}_{\alpha}$ also give a quantum satisfying assignment to the BCS, and the effective underlying state is the maximally entangled state $\ket{\phi^+}$. Since
    \begin{align*}
        \bra{\phip}M^{i,k}\otimes N^{i,k}\ket{\phip}=\bra{\phip}M^{i,k}(N^{i,k})^\top\otimes \1\ket{\phip}=1,
    \end{align*}
    and the operators $M^{i,k},N^{i,k}$ have eigenvalues $\pm1$, we have $M^{i,k}=N^{i,k}$.

    \item To win the constraint-variable game perfectly, Alice and Bob share the maximally entangled state $\ket{\phip}$, Alice applies the measurements given by projectors $\{M^i_a\}_{a}$ for each constraint $i$, and Bob applies the measurements given by observables $B^k$ for each variable $k$, where $B^k$ are observables given by $N^{i,k}$ in step~1. This completes the proof.
\end{enumerate}



\paragraph{Soundness.}
Suppose a quantum strategy $(\ket{\psi}, M, N)$ wins $G^{cv}$ with probability at least $1 -\epsilon$.
Then according to \cite{paddock2022rounding}, there exists a quantum strategy $(\ket{\phi_+},M,N)$ winning $G^{cv}$ with probability at least $1 - \poly(m,n,\epsilon^{1/2})$, where $\ket{\phi_+}$ is a maximally entangled state (MES).
Recall that there are $m$ constraints, $n$ variables in the BCS and at most $C$ common variables in the intersection of two constraints.
Then we want to show there is a strategy for the corresponding constraint-constraint BCS game $G$ with a winning probability at least $1 - \poly(m, n, C,\epsilon)$.

Starting with the MES strategy, let $\delta \coloneqq \poly(m,n,\epsilon^{1/2})$.
For each $i \in [m]$ and $k \in V_i$, let $M^{i,k} = \sum_{a \in C_i} (-1)^{a_k} M^i_a$ and $N^k = N^k_0 - N^k_1$.
When they win this constraint-variable check with probability at least $1 - mn\delta$, we have
\begin{align*}
    \bra{\phip} M^{i,k} \x N^k \ket{\phip} = 2\pr{\text{win}}{i,k} - 1\geq 1 - 2 mn\delta,
\end{align*}
or equivalently
\begin{align*}
    \norm{M^{i,k} \x \id \ket{\phip} - N^k \x \id \ket{\phip} }^2 \leq 4 mn\delta \text{ and }
    M^{i,k} \x \id \ket{\phip} \appd{2\sqrt{mn\delta}} N^k \x \id \ket{\phip}.
\end{align*}
Hence for any $i, j \in [m]$ such that $k \in V_i \cap V_j$ and $b = 0,1$,
\begin{align*}
    M^{i,k}_b \x \id \ket{\phip} \appd{\sqrt{mn\delta}} N^k_b \x \id \ket{\phip} \appd{\sqrt{mn\delta}}
    M^{j,k}_b \x \id \ket{\phip}.
\end{align*}
Since $\ket{\phip}$ is an MES and $M^{i,k}$ and $N^k$ are Hermitian, we also have
\begin{align*}
    \id \x M^{i,k}_b \ket{\phip} \appd{\sqrt{mn\delta}} \id \x N^k_b  \ket{\phip} \appd{\sqrt{mn\delta}}
    \id \x M^{j,k}_b \ket{\phip}.
\end{align*}
Then,
\begin{align*}
    M^{i,k}_b \x M^{j,k}_b \ket{\phip} \appd{\sqrt{mn\delta}} M^{i,k}_b \x N^{k}_b \ket{\phip}
    \appd{\sqrt{mn\delta}} N^k_b \x N^{k}_b \ket{\phip} = N^k_b \x \id \ket{\phip},
\end{align*}
where we use the projector property of $(N^k_b)^2=N^k_b$ in the last equation.
By applying the triangle inequality,
\begin{equation}\label{eq:substitute}
    \norm{M^{i,k}_b \x M^{j,k}_b \ket{\phip} - N^k_b \x \id \ket{\phip}} \leq 2\sqrt{mn\delta}.
\end{equation}

Suppose there are two variables labelled by $k_1$ and $k_2$ where $k_1,k_2\in V_i\cap V_j$. The projector for the measurement results $b_1$ and $b_2$ on Alice's side is given by
\begin{equation}
      \sum_{\substack{\vec{a}\in C_i: \\a_{k_1}=b_1 \\a_{k_2}=b_2}}M^i_{\vec{a}} 
    = \sum_{\substack{\vec{a}_1\in C_i:\\
    a_{1_{k_1}}=b_1}}M^i_{\vec{a}_1} 
      \sum_{\substack{\vec{a}_2\in C_i:\\ 
    a_{2_{k_2}}=b_2}}M^i_{\vec{a}_2} =M^{i,k_1}_{b_1}M^{i,k_2}_{b_2},
\end{equation}
where in the first equation, we use the orthogonality between projectors $M^{i}_{\vec{a}_1}M^{i}_{\vec{a}_2}=0$ if $\vec{a}_1\neq\vec{a}_2$. Hence the winning condition is given by
\begin{align*}
    \pr{\text{win}_{k_1} \land \text{win}_{k_2}}{i,j}  &= \sum_{b_1,b_2=0,1}
    \sum_{\vec{a}\in C_i} \sum_{\substack{\vec{a'}\in C_j \\a_{k_1}=a'_{k_1}=b_1 \\a_{k_2}=a'_{k_2}=b_2}}\bra{\phip}M^i_{\vec{a}}\otimes M^j_{\vec{a}'}\ket{\phip} \\
    &= \sum_{b_1=0}^{1}\sum_{b_2=0}^{1}\bra{\phip} (M^{i,k_1}_{b_1} \x M^{j,k_1}_{b_1}) (M^{i,k_2}_{b_2} \x M^{j,k_2}_{b_2}) \ket{\phip},
\end{align*}
where $\text{win}_{k_1}$ is the event that the players give satisfying assignments agreeing on the assignment to the variable labelled by $k_1$.
In general, for $|V_i\cap V_j|=\ell\leq C$, where $k_1,\cdots,k_\ell\in V_i\cap V_j$, we have
\begin{equation}
    \sum_{\substack{\vec{a}\in C_i: \\a_{k_t}=b_t,\,t\in[\ell]}}M^i_{\vec{a}}= \sum_{\substack{\vec{a}_1\in C_i: \\a_{1_{k_1}}=b_1}}M^i_{\vec{a}_1} \sum_{\substack{\vec{a}_2\in C_i: \\ a_{2_{k_2}}=b_2}}M^i_{\vec{a}_2} \cdots \sum_{\substack{\vec{a}_\ell\in C_i: \\ a_{\ell_{k_\ell}}=b_l}}M^i_{\vec{a}_\ell}
    =\prod_{t=1}^\ell M^{i,k_t}_{b_t},
\end{equation}
and
\begin{align*}
    \pr{\land_{t=1}^\ell\text{win}_{k_t}}{i,j} 
    &=\sum_{b_1,\ldots,b_\ell = 0,1}
    \sum_{\vec{a}\in C_i} \sum_{\substack{\vec{a}'\in C_j \\a_{k_t}=a'_{k_t}=b_t,\,t\in[\ell]}}\bra{\phip}M^i_{\vec{a}}\x M^j_{\vec{a}'}\ket{\phip} \\
    &= \sum_{b_1=0}^{1}\cdots\sum_{b_\ell=0}^{1}\bra{\phip} (M^{i,k_1}_{b_1} \x M^{j,k_1}_{b_1}) \cdots (M^{i,k_\ell}_{b_\ell} \x M^{j,k_\ell}_{b_\ell}) \ket{\phip} \\
    &= \bra{\phip} \prod_{t=1}^{\ell}(\sum_{b_t=0}^{1}M^{i,k_t}_{b_t} \x M^{j,k_t}_{b_t})\ket{\phip}.
\end{align*}
Note that the product and the summation can be exchanged due to the orthogonality between different projectors $M^i_{\vec{a}}$.
Together with Eq.~\eqref{eq:substitute}, in the constraint-constraint game, 
\begin{align*}
    \pr{\land_{t=1}^\ell\text{win}_{k_t}}{i,j}
    = &\bra{\phip} \prod_{t=1}^{\ell}(\sum_{b_t=0}^{1}M^{i,k_t}_{b_t} \x M^{j,k_t}_{b_t})\ket{\phip} \\
    \appd{4\sqrt{mn\delta}} &\bra{\phip} \prod_{t=1}^{\ell-1}(\sum_{b_t=0}^{1}M^{i,k_t}_{b_t} \x M^{j,k_t}_{b_t})(N^{k_\ell}_0+N^{k_\ell}_1)\x \1\ket{\phip} \\
    &\cdots \\
    \appd{4\sqrt{mn\delta}} &\bra{\phip} \prod_{t=1}^{\ell}(N^{k_t}_0+N^{k_t}_1)\x \1\ket{\phip} \\
    =&\bra{\phip} \1\x \1\ket{\phip} \\
    =&1.
\end{align*}
There are $\ell$ steps in this deduction. By applying the triangle inequality, we have
\begin{align*}
    1-\pr{\land_{t=1}^\ell\text{win}_{k_t}}{i,j}
    \leq 4\ell\sqrt{mn\delta}.
\end{align*}
The constraint questions are chosen uniformly at random. By averaging over questions $i,j$, 
\begin{align*}
    1-P(\text{win}) =1-\sum_{i,j}P(i,j)\pr{\land_{t=1}^C\text{win}_{k_t}}{i,j}\leq \poly(m, n, C,\epsilon).
\end{align*}
Combining this argument with the result of \cite{paddock2022rounding}, if $\exists(\ket{\psi}, M, N)$ that wins the constraint-variable game $G^{cv}$ with probability at least $1 -\epsilon$, then $(\ket{\phip}, M, M)$ wins the constraint-constraint game $G$ with probability at least $1 - \poly(m, n, C,\epsilon)$.

\paragraph{Zero-knowledge.}
Suppose there is a simulator $\Sim$ that can simulate a perfect correlation for $G$. 
Then a simulator $\Sim'$ for $G^{cv}$ can be constructed as follows. When getting constraint $i$
and a variable in it, $\Sim'$ randomly samples a constraint $j$, feeds $(i,j)$ into $\Sim$, and uses $\Sim$'s answer for constraint $i$ as its answer for constraint $i$ and $\Sim$'s assignment for the variable labelled by $k$ as its answer for $k$. 
The correlation produced by $\Sim'$ is also perfect.

If the correlation produced by $\Sim$ can win $G$ with probability $1-\epsilon$, then for each constraint $i$,
$\Sim$ can give a satisfying assignment with a probability of at least $1 - m^2\epsilon$. Hence the winning probability of $\Sim'$ constructed above is at least $1-m^2\epsilon$. When $\epsilon$ is inverse superpolynomial, so is $m^2\epsilon$, which concludes the statistical zero-knowledge part.

For computational zero-knowledge, suppose there is a distinguisher $D'$ that can distinguish any correlation produced by simulators from perfect correlations of $G'$, we can build a distinguisher $D$ for $G$.
When $D$ receives questions $(i,j)$ and their respective assignments, it selects a random variable from constraint $i$, feeds the assignment to constraint $i$ and the random variable to $D'$ and records the output of $D'$. If it is yes, $D$ repeats the same steps for constraint $j$ and output what $D'$ outputs; otherwise, $D$ outputs no. Then computational zero-knowledge follows from contrapositivity. 

\end{proof}



