\title{SAT-Solving the Poset Cover Problem}

\author{Chih-Cheng Rex Yuan \and
        Bow-Yaw Wang}

\institute{
    Institute of Information Science, Academia Sinica, Taipei, Taiwan \\
    \email{hello@rexyuan.com, bywang@iis.sinica.edu.tw}
