\section{Illustration:  Three players with two actions}\label{App:A0}\ \\[-15pt]

Consider a three-player two-action game. The mixed strategies of the three players are
$$x_1 = \Pmatrix{x_{11}\\ x_{12}},\quad x_2 = \Pmatrix{x_{21}\\ x_{22}}\und x_3 = \Pmatrix{x_{31}\\ x_{32}}.$$
The payoff vector of player 1 is
$$
P_1(x_{-1})= \Pmatrix{r_{111} x_{21}x_{31}+ r_{112} x_{21}x_{32}+ r_{121} x_{22}x_{31}+ r_{122} x_{22}x_{32}\\ r_{211} x_{21}x_{31}+
r_{212} x_{21}x_{32}+ r_{221} x_{22}x_{31}+ r_{222} x_{22}x_{32}},
$$
where we use the shorthand notation $r_{abc}$ for $r_1(a,b,c)$. 

Then 
$$\nabla_{x_2} P_1(x^*_{-1}) = M_{12} = 
\Pmatrix{r_{111}x_{31}^*+r_{112}x_{32}^*&\quad&r_{121}x_{31}^*+r_{122}x_{32}^*\\
r_{211}x_{31}^*+r_{212}x_{32}^*&\quad&r_{221}x_{31}^*+r_{222}x_{32}^*}$$
$$\nabla_{x_3} P_1(x^*_{-1}) = M_{13} = 
\Pmatrix{r_{111}x_{21}^*+r_{121}x_{22}^*&\quad& r_{112}x_{21}^*+r_{122}x_{22}^*\\
r_{211}x_{21}^* + r_{221}x_{22}^*&\quad&r_{212}x_{21}^*+r_{222}x_{22}^*}$$

Define
$$x_i=x_i^*+Nw_i \quad \text{for }i=1,2,3,$$
where $N\tr=\Pmatrix{\frac{1}{\sqrt{2}} & -\frac{1}{\sqrt{2}}}.$
The payoff vector of player 1 in the vicinity of a completely mixed-strategy NE, $x^*$, takes the form  
 \begin{align*}
 P_1&(x_2^*+Nw_2,x_3^*+Nw_3)\\
 &=
 \Pmatrix{
 r_{111} (x^*_{21}+\frac{1}{\sqrt{2}} w_2)(x^*_{31}+\frac{1}{\sqrt{2}} w_3)\\ 
 r_{211}(x^*_{21}+\frac{1}{\sqrt{2}} w_2)(x^*_{31}+\frac{1}{\sqrt{2}} w_3)} +
 \Pmatrix{
r_{112}(x^*_{21}+\frac{1}{\sqrt{2}} w_2)(x^*_{32}-\frac{1}{\sqrt{2}} w_3)\\ 
r_{212}(x^*_{21}+\frac{1}{\sqrt{2}} w_2)(x^*_{32}-\frac{1}{\sqrt{2}} w_3)}\\
&+
\Pmatrix{r_{121} (x^*_{22}-\frac{1}{\sqrt{2}} w_2)(x^*_{31}+\frac{1}{\sqrt{2}} w_3)\\ 
r_{221} (x^*_{22}-\frac{1}{\sqrt{2}} w_2)(x^*_{31}+\frac{1}{\sqrt{2}} w_3)} +
\Pmatrix{r_{122} (x^*_{22}-\frac{1}{\sqrt{2}} w_2)(x^*_{32}-\frac{1}{\sqrt{2}} w_3)\\
r_{222} (x^*_{22}-\frac{1}{\sqrt{2}} w_2)(x^*_{32}-\frac{1}{\sqrt{2}} w_3)}.
\end{align*} 
Rearranging terms, we have
\begin{align*}
P_1(x_2^*+Nw_2,x_3^*+Nw_3)=P_1(x_{-1}^*)+M_1 \mathcal{N} w+\Tilde{P}_{1}(w_{-1}),
\end{align*}
where
$$\mathcal{N} = \bdiag{N,N,N}, \quad M_1 = \Pmatrix{0_{2\times 2}&M_{12}&M_{13}},$$ 
and 
$$\Tilde{P}_{1}(w_{-1})=\frac{1}{2}\Pmatrix{r_{111}-r_{112}-r_{121}+r_{122} \\r_{211}-r_{212}-r_{221}+r_{222}}w_2w_3.$$
When $x^*$ is a completely mixed-strategy NE,
$$P_1(x^*_1) = \alpha_1 \one $$
for some constant $\alpha_1$, and so $N\tr P_1(x^*_1) = 0$.  The reduced-order payoff vector becomes 
\begin{align*}
 N\tr P_1(x_2^*+Nw_2,x_3^*+Nw_3)= 
\underbrace{ N\tr M_1 \mathcal{N}}_{\mathcal{M}_1} w + N\tr \Tilde{P}_{1}(w_{-1}),
\end{align*} 
where $\mathcal{M}_1$ is $1\times 3$. The full $3\times 3$ matrix
 $$\mathcal{M} = \Pmatrix{\mathcal{M}_1\\ \mathcal{M}_2\\ \mathcal{M}_3}$$ 
 can be constructed by going through the similar steps for players 2 and 3. 

\section{Background material}\ \\[-15pt]

The notation of each of these sections is independent from the remainder of the paper.

\subsection{Local stabilization of nonlinear dynamical systems}\label{sec:ofStabilization}

Consider the nonlinear dynamical system
\begin{subequations}\label{eq:nominalSystem}
\begin{align}
\dot{x} &= f(x,u)\\
y &= g(x)
\end{align}
\end{subequations}
with $f:\mathbb{R}^n\times \mathbb{R}^m\rightarrow \mathbb{R}^n$ and $g:\mathbb{R}^n\rightarrow \mathbb{R}^m$ both continuously differentiable. Let $(x^*,0)\in \mathbb{R}^n\times \mathbb{R}^m$ be an equilibrium point, i.e., 
$$0 = f(x^*,0)$$
such that
$$0 = g(x^*).$$

Now introduce linear dynamic feedback of the form
\begin{subequations}\label{eq:linearCompensator}
\begin{align}
\dot{\xi} &= E \xi + Fy\\
u &= G\xi + Hy
\end{align}
\end{subequations}
with state $\xi\in\mathbb{R}^p$.

The overall closed-loop dynamical system becomes
\begin{subequations}\label{eq:ofStabilization}
\begin{align}
\dot{x} &= f(x,G\xi + Hg(x))\\
\dot{\xi} &= E\xi + Fg(x)
\end{align}
which has an equilibrium $(x^*,0)\in \mathbb{R}^n\times \mathbb{R}^p$. 
\end{subequations}

Our goal is to provide conditions on the feedback matrices $(E,F,G,H)$ so that the equilibrium $(x^*,0)$ of (\ref{eq:ofStabilization}) is locally asymptotically stable. Towards this end, define the matrices
\begin{align*}
A &= \nabla_x f(x^*,0)  \in \mathbb{R}^n\times \mathbb{R}^n\\
B &= \nabla_u f(x^*,0)  \in \mathbb{R}^n\times \mathbb{R}^m\\
C &= \nabla_x g(x^*)    \in \mathbb{R}^m\times \mathbb{R}^n
\end{align*}
and define $\tilde{x} = x - x^*$. The \textit{linearized dynamics} of (\ref{eq:ofStabilization}) at the equilibrium point $(x^*,0)$ are
$$\Pmatrix{\dot{\tilde{x}}\\ \dot{\xi}} = 
\Pmatrix{A + BHC & BG\\FC& E}\Pmatrix{\tilde{x}\\ \xi}.$$

\begin{Theorem}\label{thm:ofStabilization} If the matrix
$$\bar{A} = \Pmatrix{A + BHC & BG\\FC& E}$$
is a stability matrix, i.e., $\mathbf{Re}[\lambda_i] < 0$ for every eigenvalue, $\lambda_i$, then
the dynamics (\ref{eq:ofStabilization}) are locally exponentially stable at the equilibrium point $(x^*,0)$.
\end{Theorem}

This result is standard in the analysis of nonlinear systems, e.g., \cite[Theorem 4.7]{khalil2002nonlinear}.

\begin{Theorem}\label{thm:robustStability} Under the conditions of Theorem~\ref{thm:ofStabilization}, there exists a $\gamma > 0$ such that
$$\bar{A}' = \Pmatrix{A' + B'HC' & B'G\\FC'& E}$$
is a stability matrix for all $A'$, $B'$, and $C'$, such that
$$\norm{A - A'} < \gamma, \quad \norm{B - B'}<\gamma, \und \norm{C-C'} < \gamma.$$
\end{Theorem}

Again, the result is standard, e.g., \cite[Lemma 9.1]{khalil2002nonlinear}. The implication here is that if the nominal system (\ref{eq:nominalSystem}) is perturbed, albeit with a possibly shifted equilibrium $(x',0)$, then the \textit{same} feedback (\ref{eq:linearCompensator}) results in $(x',0)$ being asymptotically stable for the perturbed system as long as the perturbations are sufficiently small.

\subsection{Linear systems: Stabilizability and strong stabilizability}\label{sec:linearSystems}

The material in this section are standard and can be found in textbooks such as \cite{hespanha18linear} and \cite{rugh1996linear}.

Consider the linear system: 
\begin{subequations}\label{eq:linear}
\begin{align}
\dot{x}&=Ax+Bu,\quad x(0)=x_o\\
y&=Cx 
\end{align}
\end{subequations}
where $x \in \mathbb{R}^n,$ $u\in \mathbb{R}^m$, and $y \in \mathbb{R}^p$.  The system is called stable if the matrix $A$ is a stability matrix. 

The linear dynamic feedback 
\begin{subequations}\label{eq:efghcontroller}
\begin{align}
\dot{\xi}&=E\xi+Fy\\
u&=G\xi+Hy
\end{align}
\end{subequations}
stabilizes \eqref{eq:linear} if the overall system 
\begin{subequations}\label{eq:linearoverall}
\begin{align}
\Pmatrix{ \dot{x} \\ \dot{\xi}}=\Pmatrix{A+BHC & BG\\FC & E} \Pmatrix{x\\ \xi}
\end{align}
\end{subequations}
is stable. 

The following conditions are necessary and sufficient for the existence of feedback stabilizing dynamics for \eqref{eq:linear}:
\begin{itemize}
\item The pair $(A,B)$ is stabilizabile:
$$\Pmatrix{A-\lambda I & B}$$
has full row rank for all $\lambda\in \mathbb{C}$ with $\mathbf{Re}[\lambda] \geq 0.$
\item The pair $(A,C)$ is detectable: 
$$\Pmatrix{A-\lambda I \\ C}$$
has full column rank for all $\lambda\in \mathbb{C}$ with $\mathbf{Re}[\lambda] \geq 0.$
\end{itemize}

The matrix
$$\mathcal{T}(s)=C(sI-A)^{-1}B$$
is called the transfer matrix of \eqref{eq:linear} and is used to study the input-output properties of the system. Poles and zeros of a system are defined as follows (several definitions of zeros exist, we adopt the one relevant to our context): 
\begin{itemize}
\item A \textit{zero} is a value $\sigma \in  \mathbb{C}$ such that $\mathcal{T}(\sigma)=0.$
\item A \textit{pole} is a value $\mu \in \mathbb{C}$ such that for some $i$, $j$, 
$\magn{\mathcal{T}_{ij}(\mu)}=\infty,$
where $\mathcal{T}_{ij}(s)$ is the entry at the $i^{\text{th}}$ row and $j^{\text{th}}$ column of $\mathcal{T}$. The multiplicity of a pole is the largest multiplicity it has as a pole of  any minor of $\mathcal{T}(s).$ 
\end{itemize}

A stabilizable and detectable linear system of the form \eqref{eq:linear} is called \textit{strongly stabilizable} if there exist stabilizing dynamics of the form \eqref{eq:efghcontroller} with $E$ being a stability matrix.  The ``parity interlacing principle" \cite{youla1974singleloop} provides a necessary and sufficient condition for strong stabilizability. The principle  states that there should be an \emph{even} number of real poles, counting with multiplicities, between each pair of real unstable blocking zeros. 

\subsection{Washout filters}\label{App:WashoutFilters}

Washout filters are linear systems that take the form
\begin{align*}
\dot{x}&=-x+u\\
y&=-x+u,
\end{align*}
where $x\in\mathbb{R}^n$, $u\in\mathbb{R}^n$, and $y\in\mathbb{R}^n$. 
These systems have the property that if 
$$\lim_{t\rightarrow \infty} u(t)= u^*, \quad \text{then} \quad \lim_{t\rightarrow \infty}y(t)= 0.$$
For an extended discussion, see \cite{hassouneh2004washout}. 

\subsection{Decentralized stabilization} \label{App:Decentralized}

 Consider the linear system 
\begin{subequations}\label{eq:linear1}
\begin{align}
\dot{x}&=Ax+\sum_{i=1}^{k} B_i u_i, \\  y_i&=C_ix \quad \quad  i=1,\hdots,k ,
\end{align}
\end{subequations}
with $k$ inputs and $k$ outputs, and $A\in \mathbb{R}^{n\times n}$.
If there exist $(E_i,F_i,G_i,H_i)$, $i=1,\hdots,k$, such that the collective system
\begin{align*}
\dot{x}&=Ax+\Pmatrix{B_1 & \hdots & B_k}\Pmatrix{G_1 \xi_1 + H_1 y_1 \\ \vdots \\ G_k \xi_k + H_k y_k}\\
\dot{\xi}_i & = E_i \xi_i + F_i y_i, \quad i=1,\hdots, k 
\end{align*}
is stable, then the system is stabilized in a decentralized manner. 

A necessary and sufficient condition for decentralized stabilizability is presented in \cite{davison1990decentralized}. First, for any partition $\mathcal{U}\cup \mathcal{Y} = \theset{1,2,...,k}$
define $B\vert^\mathcal{U}$ as the matrix formed by all $B_i $ with indices in $\mathcal{U}$, i.e.,
$$B\vert^\mathcal{U} = \Pmatrix{B_{q_1}&...&B_{q_\magn{\mathcal{U}}}}$$
with $\theset{q_1,...,q_\magn{\mathcal{U}}} = \mathcal{U}$. Likewise, define $C\vert_\mathcal{Y}$ as the matrix 
formed by all $C_i$ with indices in $\mathcal{Y}$, i.e.,
$$C\vert_\mathcal{Y} = \Pmatrix{C_{e_1}\\ \vdots\\ C_{e_\magn{\mathcal{Y}}}}$$
with $\theset{e_1,...,e_\magn{\mathcal{Y}}} = \mathcal{Y}$.

\begin{Theorem}[\cite{davison1990decentralized}, Theorem 3]\label{thm:davison} 
System \eqref{eq:linear1} is stabilizable in a decentralized manner if and only if
$$\mathbf{rank}\Pmatrix{A - \lambda I&B\vert^\mathcal{U}\\ C\vert_\mathcal{Y}&0} = n$$
for all complex $\lambda$ with $\mathbf{Re}[\lambda]\ge 0$ and all partitions, $\mathcal{U}\cup \mathcal{Y} = \theset{1,2,...,k}$.
\end{Theorem}

\subsection{ODE method of stochastic approximation}\label{sec:ODEMethod}

The following proposition serves as the main tool for proving our results in the bandit setting.  

\begin{Proposition}[\cite{Benaim1999Dynamics}]\label{Prop:SI}
Consider the following stochastic iterates
\begin{equation}\label{eq:SI}
\zeta(t+1)=\zeta(t)+\kappa(t)\left[F(\zeta(t))+H(t)\right]
\end{equation}
where the following conditions hold:
\begin{enumerate}
\item The step-sizes $\kappa(t) > 0$ satisfy:
$$\sum_{t=1}^{\infty} \kappa(t) = \infty,\quad \sum_{t=1}^{\infty} \kappa(t)^2 < \infty.$$

\item The iterates evolve in a compact set $K.$

\item $F(\zeta)$ is uniformly Lipschitz over $K$:
$$\exists L \quad s.t \quad \norm{F(\zeta) - F(\zeta')}  \leq L \norm{\zeta-\zeta'} \text{ } \forall \zeta,\zeta' \in K.$$

\item $H(t)$ is a stochastic noise such that 
$$\mathbf{E}[H(t)\vert \zeta(t)]=0 \quad \text{and} \quad \mathbf{E}[H(t)\tr H(t)]<\infty.$$

\item The equilibrium point $x^*\in K$ satisfying $F(x^*)=0$ is attainable, i.e., for each $t>0$ and every open neighborhood $U$ of $x^*$, 
$\mathbf{Prob}[\exists s \geq t : \zeta(s) \in U]>0$\label{enum:A6}.

\end{enumerate}
Under these conditions, if $x^*$ is a locally asymptotically stable fixed point of the mean dynamics
\begin{equation}\label{eq:Mean} 
\dot{x}= F(x),
\end{equation}
 then 
 $$\mathbf{Prob} \left[\lim_{t\rightarrow \infty} \zeta(t) = x^*\right]>0.$$
\end{Proposition}

If $x^*$ is a globally asymptotically stable fixed point of \eqref{eq:Mean}, the result in the above proposition strengthens to almost sure convergence. 




