    add_node_data!(dg, prod_data[i, 1], 1, "Product") |\label{line:prod_data}|
    add_node_data!(dg, prod_data[i, 1], prod_data[i, 2], "Demand Limit")
end

for i in 1:size(int_data, 1)
    add_node!(dg, int_data[i, 1]) 
    add_node_data!(dg, int_data[i, 1], 1, "Intermediate") |\label{line:int_data}|
end

for i in 1:size(tech_data, 1)
    add_node!(dg, tech_data[i, 1])
    add_node_data!(dg, tech_data[i, 1], 1, "Technology") |\label{line:tech_data}|
    add_node_data!(dg, tech_data[i, 1], tech_data[i, 2], "Cost")
    add_node_data!(dg, tech_data[i, 1], tech_data[i, 3], "CO2 Cost")
end

# Add edges and edge data
for i in 1:size(edge_data, 1) |\label{line:edge_data_start}|
    edge = (edge_data[i, 1], edge_data[i, 2])
    PlasmoData.add_edge!(dg, edge)
