\quad\textbf{r2}: \textit{torch.Tensor} -- covered variance.


\section*{Sample code to run ECA decomposition and inverse}

\begin{lstlisting}
## import necessary modules to handle data
import numpy as np
from eca import ECA
## Load the data, for example:
data_x = np.loadtxt(...)
data_y = np.loadtxt(...)
# convert data to torch.tensor if necessary: 
data_x_t, data_y_t = map(lambda x: torch.tensor(x, dtype=torch.float32), [data_x, data_y]) 
## Initialize an instance of the ECA class with an emulator
# For pytorch, a torch.nn.Module object can be called as an emulator as well as its forward() method
eca = ECA(model)
# define options
options = {
    "tol"       : 1E-4, 
    "epochs"    : 10000, 
    "lr"        : 1E-3, 
    "batch_size": 200,
    "seed"      : 123
}
# Carry out ECA decomposition
vectors, y_variance, x_variance = eca.fit(data_x_t, data_y_t, n_comp=3, options=options)

## Example: recalculate the last component with another seed
# set a new seed 
eca.set_seed(42)
# keep the first two (already calculated) components and redo the third one with a new seed
vectors, y_variance, x_variance  = eca.fit(data_x_t, data_y_t, n_comp=3, keep=-1)  

# Calculate scores for data_x
t_k = eca.transform(data_x_t)
# Directly project data_x on ECA subspace
data_x_k = eca.project(data_x_t)
# Search iteratively for scores matching the spectral data points
options_inv = {
    "tol"     : 1E-4, 
    "epochs"  : 1000, 
    "lr"      : 0.05, 
}
t_k_prime = eca.inverse(data_y_t, options=options_inv)

# Search for approximate data_x_appr matching the spectral data points. 
data_x_appr = eca.reconstruct(data_y_t)

\end{lstlisting}

