\section{Supplementary Materials for Section~\ref{sec:settingandalgorithm}}
This section contains the proof of an auxiliary result, Lemma~\ref{lem:technicalKotlarski}, used to establish Theorem~\ref{thm:kotlarski}.


\begin{lemma}[Path-wise exponential representation]\label{lem:technicalKotlarski}
    Suppose that $\xi:\R^d \to \C$ is a continuously differentiable function and 
    let $\Re \xi, \Im \xi : \R^d \to \R$ denote the real and imaginary parts of $\xi$, respectively, so that $\xi = \Re \xi+ i \Im \xi.$ Then for any $\omega_1, \omega_2 \in \R^d$ for which $\xi$ is non-vanishing on the straight-line path from $\omega_1$ to $\omega_2,$ which we denote by $\gamma: [0,1] \to \C$,  we have
    \begin{align*}
        \frac{\xi(\omega_2)}{\xi(\omega_1)} = \exp \inparen{\int_0^1 \frac{\nabla \xi(\gamma(\alpha) )}{\xi(\gamma(\alpha))} \cdot (\omega_2-\omega_1) d\alpha},
    \end{align*}
    where $\nabla \xi(\omega) \cdot \omega := \nabla \Re \xi(\omega) \cdot \omega +i\nabla \Im \xi(\omega)\cdot \omega$. 
\end{lemma}
\begin{proof}
    Fix $\omega_1, \omega_2 \in \R^d$ for which the stated assumption holds and let $\gamma: [0,1] \to \R^d$ be the straight line path from $\omega_1$ to $\omega_2$ (i.e. $\gamma(\alpha)= (1-\alpha) \omega_1 + \alpha \omega_2$). Let $\mcL(\alpha) := \log_c \xi( \gamma(\alpha))$, where $\log_c$ denotes the continuously chosen branch of the complex logarithm along the path $\alpha \mapsto \xi(\gamma(\alpha)),$ with initial condition $\mcL(0) = \log \xi(\omega_1).$ Note that this is well-defined since $\xi\circ \gamma : [0,1] \to \C$ is continuously differentiable and non-vanishing. Further, $\mcL$ is smooth on $[0,1].$ We then have 
    \begin{align}\label{eq:complexChainRule}
        \frac{d}{d\alpha} \mcL(\alpha) = 
        \frac{\nabla \xi( \gamma(\alpha) )}{\xi(\gamma(\alpha))} \cdot (\omega_2 - \omega_1).
    \end{align}
    The above can be justified as follows. Write
    \begin{align*}
        \log_c \xi  = \log |\xi| + i \arg (\xi),
    \end{align*}
    where $|\xi |$ is the magnitude and $\arg(\xi )$ is the continuously chosen argument of $\xi$ along the curve. Below, all functions are evaluated at $\gamma(\alpha)$. Standard calculation then yields
    \begin{align*}
        \frac{d}{d\alpha} \log |\xi| 
        &= \frac{1}{|\xi|}\frac{d}{d\alpha} |\xi|
        = \frac{\Re \xi \frac{d}{d\alpha} R + \Im \xi \frac{d}{d\alpha} \Im \xi }{\Re \xi^2 + \Im \xi^2 }
        = 
        \frac{
        (\Re \xi \nabla \Re \xi+\Im \xi \nabla \Im \xi) \cdot (\omega_2-\omega_1)
        }{\Re \xi^2 + \Im \xi^2 },\\
        \frac{d}{d\alpha} \arg(\xi )  
        &=
        \frac{
            (\Re \xi \nabla \Im \xi -\Im \xi \nabla \Re \xi)\cdot (\omega_2-\omega_1)
        }{\Re \xi^2 + \Im \xi^2}.
    \end{align*}  
    Therefore, 
    \begin{align*}
        \frac{d}{d\alpha} \log |\xi| 
        +i\frac{d}{d\alpha} \arg(\xi )  
        &=
        \frac{
        (\Re \xi \nabla \Re \xi 
        +
        \Im \xi \nabla \Im \xi
        + i \Re \xi \nabla \Im \xi
        -
        i \Im \xi \nabla \Re \xi )\cdot (\omega_2-\omega_1)
        }{\Re \xi^2 + \Im \xi^2 }\\
        &=
        \frac{
        ((\nabla \Re \xi + i \nabla \Im \xi)(\Re \xi - i \Im \xi))\cdot (\omega_2-\omega_1)
        }{R^2 + \Im \xi^2 }\\
        &= \frac{\nabla \Re \xi + i \nabla \Im \xi}{ \Re \xi + i \Im \xi}\cdot (\omega_2-\omega_1) = \frac{\nabla \xi}{\xi} \cdot (\omega_2-\omega_1).
    \end{align*}
    Now, integrating both sides of \eqref{eq:complexChainRule} yields
    \begin{align*}
        \mcL(1) - \mcL(0) 
        = \int_0^1 \frac{d}{d\alpha} \mcL(\alpha) d \alpha
        =  \int_0^1 \frac{\nabla \xi(\gamma(\alpha))}{\xi(\gamma(\alpha))} \cdot (\omega_2-\omega_1) d\alpha,
    \end{align*}
    and so the final result follows by exponentiating both sides of the previous display.
\end{proof}


\section{Supplementary Materials for Section~\ref{sec:theory}}\label{sec:appendixtheory}
\subsection{Background}

\subsubsection{Auxiliary bounds}
\begin{lemma}[$\fft$ bounds]\label{lem:fftnbound}
	For $f$ as in Assumption~\ref{assumption:psiestimates} and any $\omega \in \C$
	\begin{align*}
    |(\fft)^{(\ell)}(\omega)|
    \le \int_D |t|^\ell f(t) dt
    \leq c \|f\|_\infty, \qquad \ell =0,1,2,\dots,
	\end{align*}
    where $c$ is a positive constant depending only on $D, \ell.$
\end{lemma}
\begin{proof}
    Observe that for any $\ell \in \{ 0,1,2,3\}$ and $\omega \in \C$
\begin{align*}
	|(\fft)^{(\ell)}(\omega)| &= |(\omega^{\ell}\cdot f)^{ft}(\omega)| = \left|\int_D e^{-i\omega t} t^\ell f(t)dt \right|
			\le \|f\|_\infty \text{vol(D)} \sup_{t \in D} |t^\ell|  \le c \|f\|_\infty.
\end{align*}
\end{proof}

\subsubsection{Sub-Gaussian processes}

\begin{definition}[Sub-Gaussian process]\label{def:subgaussian}
A stochastic process $\{X(t): t \in D\}$ whose sample paths lie almost surely in the Sobolev space $H^s(D)$ is said to be sub-Gaussian if there exists a positive constant $K$ such that, for every bounded linear functional $L: H^s(D) \to \R$ with $\|L\| \le 1$, the scalar random variable $L(X)$ is $K$ sub-Gaussian. In other words, the Orlicz norm satisfies
$$
\|L(X)\|_{\psi_2} := \inf\left\{ m > 0 : \E \left[e^{L(X)^2 / m^2}\right] \le 2 \right\} \le K.
$$
\end{definition}
\begin{lemma}[$y$ is sub-Gaussian]\label{lem:processIsSubgaussian}
    Under Assumption \ref{assumption:psiestimates}, the process $y(t)$ defined in \eqref{eq:MRADataGeneratingModel} is sub-Gaussian.
\end{lemma}
\begin{proof}
For any bounded linear functional $L:H^s(D) \to \R,$ we have that 
\begin{align*}
    |L(f(\cdot - \zeta))| \le \|L\| \|f(\cdot - \zeta)\|_{H^s(D)} = \|L\| \|f\|_{H^s(D)} < \infty,
\end{align*}
where the last equality holds since the Sobolev norm is invariant under shifts, since both signal and the shifted signal are supported on $D$. It follows that, for $\|L\| \le 1,$ $|L(f(\cdot - \zeta))|$ is bounded by a constant independent of $L$ and is therefore sub-Gaussian. Further, since $\eta$ is a Gaussian process supported on $H^s(D)$, $s>d/2,$ it is  sub-Gaussian. Therefore, $y$ is a sum of two sub-Gaussian processes and so is itself a sub-Gaussian process.
\end{proof}

\subsubsection{Properties of Fourier transformed processes}
In this section, we recall some  properties of the Fourier transform of a stochastic process. Throughout, we consider a generic separable sub-Gaussian process $\{X(t): t \in D\}$ supported on $H^s(D)$ with $s > d/2$, 
and $D = [-1,1]^d,$ with mean function, autocorrelation function, and covariance functions $m_X(t)$, $r_X(t,t'),$ and $k_X(t,t')$ respectively. The Fourier transformed process is then:
\begin{align*}
    \Xft(\omega) = \int_D X(t) e^{-i \omega \cdot t}dt, \qquad \omega \in\R^d.
\end{align*}
    The following lemma shows that the mean function of the transformed process is the Fourier transform of the mean function of the original process. Similarly, the autocorrelation and covariance functions are the Fourier transforms of the autocorrelation and covariance functions of the original process up to a flip in sign of the second argument.
\begin{lemma}[Properties of Fourier transformed process]\label{lem:propertiesOfFourierProcess}
    For $\omega, \omega_1, \omega_2 \in \R^d$, the Fourier transformed process $\{\Xft(\omega): \omega \in \R^d\}$ has the following properties:
    \begin{enumerate}
        \item Mean function: $m_{\Xft}(\omega) = \mft_X(\omega);$
        \item Autocorrelation function: $r_{\Xft}(\omega_1, \omega_2) =\rft_X (\omega_1, -\omega_2);$
        \item Covariance function: $k_{\Xft}(\omega_1, \omega_2) =\kft_X (\omega_1, -\omega_2).$
    \end{enumerate}
\end{lemma}
\begin{proof}
    For the mean, we have
    \begin{align*}
    m_{\Xft}(\omega)
    := \E[\Xft(\omega)] 
    = \int_D \E[X(t)] e^{-i \omega t}dt
    = \int_D m_X(t) e^{-i \omega t}dt
    = \mft_X(\omega).
\end{align*}
The second equality is justified by Fubini's theorem. To verify this, note that the Sobolev embedding theorem guarantees that all point evaluation functionals have unit norm when $s > d/2$. Since $X$ takes values in $H^s(D)$, we can express $X(t)$ as $\mcE_t(X),$ where $\mcE_t$ is the evaluation functional at $t$. The sub-Gaussian property of the process $Z$ then immediately implies that each $X(t)$ is a sub-Gaussian random variable i.e. that $\|X(t)\|_{\psi_2} \le K.$

This implies (see e.g. \cite[Proposition 2.5.2]{vershynin:HDP2017}) that for any $p,$ $\|X(t)\|_{L_p} \lesssim c_p K$ for a constant $c_p$ depending only on $p$. In particular, for $p=1,$ we have $\E|X(t)| \le  c_1 K.$ Since $D \subset \R^d$ is compact, we have  
\begin{align*}
    \int_D \E |X(t)| dt \le (\sup_{t \in D} \E|X(t)|) \text{vol}(D) < \infty.
\end{align*}
For the autocorrelation, we have 
\begin{align*}
    r_{\Xft}(\omega_1, \omega_2)
    &=\E[\Xft(\omega_1) \overline{\Xft(\omega_2)}] 
    = \iint_{D \times D} \E [X(t)X(t')] e^{-i\omega_1t} e^{i\omega_2t'} dt' dt\\
    &= \iint_{D \times D} r_X(t,t') e^{-i\omega_1t} e^{i\omega_2t'} dt' dt
    =\rft_X(\omega_1,-\omega_2),
\end{align*}
where the second equality again follows by Fubini since
\begin{align*}
    \iint_{D \times D} \E|X(t)X(t')| dt' dt
    &\le 
    \iint_{D \times D} \|X(t)\|_{L_2} \|X(t')\|_{L_2} dt' dt\\
    &\le C_2^2 
    \sup_{t \in D} \|X(t)\|^2_{\psi_2} (\text{vol}(D))^2 
    <\infty,
\end{align*}
where the first inequality holds by Cauchy-Schwarz, and the second by properties of sub-Gaussian variables. The proof for the covariance function follows similarly and is omitted for brevity.
\end{proof}



\subsubsection{Autocorrelation estimation for sub-Gaussian processes}
Suppose now that we have access to $N$ i.i.d. copies of $X(\cdot),$ denoted $X_1(\cdot),\dots, X_N(\cdot)$, and that we wish to estimate the autocorrelation function $r_X.$ The natural estimator is the sample autocorrelation function
\begin{align*}
    \hatr_X(t,t') := \frac{1}{N} \sum_{n=1}^N X_n(t)X_n(t').
\end{align*}
We then have the following high-probability supremum-norm bound.

\begin{lemma}[Concentration of $\hatr_X$] \label{lem:SecondMomentHPBound}
    There exist positive universal constants $c_1,c_2$ such that, for any $\tau \ge 1,$ it holds with probability at least $1-c_1e^{-c_2 \tau}$ that
    \begin{align}\label{eq:SecondMomentHPBound}
        \sup_{t,t' \in D} |\hatr_X(t,t')-r_X(t,t')|
        \lesssim 
        \|r_X\|_\infty
        \left (
        \sqrt{\frac{\tau}{N}}
        \lor 
        \frac{\tau}{N}
        \lor 
     \frac{\Gamma(X)}{\sqrt{N}}
        \lor 
        \frac{\Gamma(X)^2}{N}
        \right),
    \end{align}
    where 
    \begin{align*}
        \Gamma(X) := \frac{\E[\sup_{t\in D} X(t)]}{\|r_X\|_\infty^{1/2}},
        \qquad 
        \|r_X\|_\infty:= \sup_{t \in D} r_X(t,t).
    \end{align*}
\end{lemma}
\begin{proof}
    First, we deal with the centered case. We write the quantity of interest as a product empirical process indexed by the class of linear evaluation functionals:
    \begin{align}\label{eq:prodEmpProcess}
        \sup_{s,t\in D} |\hatr_X(t,t') - r_X(t,t')|
        &= 
        \sup_{s,t\in D} \abs{\frac{1}{N} \sum_{n=1}^n X_n(t)X_n(t') - \E[X_n(t) X_n(t')]}\nonumber\\
        &= 
        \sup_{f, g \in \mcF} \abs{\frac{1}{N} \sum_{n=1}^n f(X_n) g(X_n) - \E[f(X) g(X)]} ,
    \end{align}
    where $\mcF := \{\mcE_t \}_{t \in D}$ is the family of evaluation functionals. By Theorem~\cite[Theorem 1.13]{mendelson2016upper}, with probability at least $1-c_1 e^{-c_2 \tau}$, \eqref{eq:prodEmpProcess} is bounded above by
    \begin{align*} 
         d^2_{\psi_2}(\mcF)
        \inparen{
            \sqrt{\frac{\tau}{N}}
            \lor 
            \frac{\tau}{N}
            \lor 
            \frac{\gamma_2(\mcF, \psi_2)}{\sqrt{N} d_{\psi_2}(\mcF)}
            \lor 
            \frac{\gamma^2_2(\mcF, \psi_2)}{N d^2_{\psi_2}(\mcF)}
        },
    \end{align*}
    where $\gamma_2$ denotes Talagrand's generic complexity \cite[Definition 2.7.3]{talagrand2022upper} and we write $d_{\psi_2}(\mcF) := \sup_{f \in \mcF}\|f\|_{\psi_2}$ where $\|\cdot\|_{\psi_2}$ denotes the Orlicz (sub-Gaussian) norm. By \cite[Proposition 3.1]{al2025covariance}) $d_{\psi_2}^2(\mcF) \lesssim \sup_{t\in D} g(t,t)$ and $\gamma_2(\mcF, \psi_2) \lesssim \E[\sup_{t\in D} X(t)],$ which completes the proof. 

    In the non-centered case, write $\barf(X_n) := f(X_n) - \E f(X_n)$ and $\barg(X_n) := g(X_n) - \E g(X_n)$. Then,
    \begin{align*}
        f(X_n) g(X_n) 
        &= 
        \barf(X_n) \barg(X_n) 
        +
        \barg(X_n) \E f(X_n) 
        +
        \barf(X_n) \E g(X_n) 
        +
        \E f(X_n) \E g(X_n).
    \end{align*}
    By the triangle inequality, we have that
    \begin{align*}
            \sup_{f,g \in \mcF} &
            \abs{
            \frac{1}{N} \sum_{n=1}^N 
                f(X_n)
                g(X_n)
                -
                \E [f(X_n) g(X_n)]} 
            \le 
            \sup_{f,g \in \mcF} 
            \abs{
            \frac{1}{N} \sum_{n=1}^N 
                \barf(X_n)
                \barg(X_n)
                -
                \E [\barf(X_n) \barg(X_n)]} \\
            &\qquad \qquad +
            2 \sup_{f \in \mcF} |\E f(X)|
            \sup_{g \in \mcF} 
            \abs{
            \frac{1}{N} \sum_{n=1}^N 
                \barg(X_n)
                -
                \E [\barg(X_n)]} 
                =: \textbf{(I)} + \textbf{(II)}. 
    \end{align*}
    $\textbf{(I)}$ can be controlled by invoking the result in the centered setting. For $\textbf{(II)}$, by the equivalence of $L_2$ and $\psi_2$ norms for linear functionals, we have $\sup_{f \in \mcF} |\E f(X)| \lesssim d_{2}(\mcF) \lesssim d_{\psi_2}(\mcF),$ where $d_2(\mcF):=\sup_{f\in\mcF}\|f\|_{L_2}.$ Combining this with \cite[Theorem 2.5]{mendelson2010empirical} yields that with probability at least $1-2e^{-ct}$, $\textbf{(II)} \lesssim d_{\psi_2}(\mcF) \gamma_2(\mcF, \psi_2)/\sqrt{N}.$
\end{proof}

Suppose instead that we were given the Fourier transformed observations, $\Xft_1(\cdot),\dots, \Xft_N(\cdot)$ and wished to estimate the autocorrelation function $r_{\Xft}$. It turns out that Lemma~\ref{lem:SecondMomentHPBound}, which concerns the original process in the spatial domain, readily leads to a high-probability bound in the Fourier domain. We first define the sample version of $\hatr_{\Xft}$, 
\begin{align*}
    \hatr_{\Xft}(\omega_1, \omega_2) 
    := \iint_{D \times D} \hatr_X(t,t')e^{-i\omega_1 \cdot t} e^{i \omega_2 \cdot t'}dt\, dt'.
\end{align*}

\begin{lemma}[Concentration of $\hatr_{\Xft}$]
    There exist positive universal constants $c_1,c_2$ such that, for any $\tau \ge 1,$ it holds with probability at least $1-c_1e^{-c_2 \tau}$ that
    \begin{align*}
        \sup_{\omega_1,\omega_2 \in \R^d} |\hatr_{\Xft}(\omega_1,\omega_2)-r_{\Xft}(\omega_1,\omega_2)|
        \lesssim 
        \| r_X \|_\infty 
        \left (
        \sqrt{\frac{\tau}{N}}
        \lor 
        \frac{\tau}{N}
        \lor 
     \frac{\Gamma(X)}{\sqrt{N}}
        \lor 
        \frac{\Gamma(X)^2}{N}
        \right).
    \end{align*}
\end{lemma}
\begin{proof}
We have
    \begin{align*}
    \sup_{\omega_1,\omega_2 \in \R^d} |\hatr_{\Xft}(\omega_1,\omega_2)-r_{\Xft}(\omega_1,\omega_2)|
    &\le 
    \sup_{\omega_1,\omega_2 \in \R^d}
    \iint_{D \times D} |\hatr_X(t,t') - r_X(t,t')| |e^{-i \omega_1 \cdot t}| |e^{i\omega_2 \cdot t'}| dt dt'\\
    &
    \le 
    \sup_{t,t' \in D}|\hatr_X(t,t') - r_X(t,t')| 
    \iint_{D \times D}  
    dt dt'\\
    &= \sup_{t,t' \in D}|\hatr_X(t,t') - r_X(t,t')| (\text{vol}(D))^2,
\end{align*}
where the second equality holds by the fact that $|e^{-i\omega \cdot t}| = 1$ for any $t, \omega$. By assumption $\text{vol}(D) < \infty$. The result then follows by Lemma~\ref{lem:SecondMomentHPBound}.
\end{proof}

\subsection{Proof of Lemma~\ref{lem:psiestimates}}\label{ssec:estimatePsi}


\begin{proof}[Proof of Lemma~\ref{lem:psiestimates}]
    Recall that $\Psi(\omega_1, \omega_2) = r_{\yft}(\omega_1, \omega_2) - k_{\etaft}(\omega_1, \omega_2)$ and $\hatPsi(\omega_1, \omega_2) = \hatr_{\yft}(\omega_1, \omega_2) - k_{\etaft}(\omega_1, \omega_2),$ where $\hatr_{y}$ is the empirical version of the autocorrelation function $r_{y}$. It follows that 
    \begin{align*}
        &\sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        |\hatPsi( \omega, \omega) -\Psi( \omega, \omega) |
        \le 
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d}
        \int_{D \times D} |\hatr_{y}(t,t')-r_{y}(t,t')| |e^{-i\omega\cdot t}||e^{i \omega \cdot t'}| dt dt'
        \\
        &\quad = 
        \int_{D \times D} |\hatr_{y}(t,t')-r_{y}(t,t')| dt dt'
        \lesssim \sup_{t,t' \in D} |\hatr_{y}(t,t')-r_{y}(t,t')| (\text{vol}(D))^2
        \lesssim \rho_N,
    \end{align*}
    where the final inequality holds with probability at least $1-c_1e^{-c_2 \tau}$ by Lemma~\ref{lem:SecondMomentHPBound}. 


    Next we consider the gradient term $\nabla_1 \Psi(\omega,\omega).$ Note first that 
    \begin{align*}
        \nabla_1 \Psi(\omega,\omega)
        = -i \int_{D\times D}  t r_{y}(t,t')  e^{-i\omega \cdot t +i\omega \cdot t'} dt dt',
    \end{align*}
    and 
    \begin{align*}
        \widehat{\nabla_1\Psi}(\omega,\omega)
        :=
        \nabla_1 \hatPsi(\omega,\omega)
        = -i \int_{D\times D}  t \hatr_{y}(t,t')  e^{-i\omega \cdot t + i \omega \cdot t'} dt dt'.
    \end{align*}
    Therefore, we have 
    \begin{align*}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \|\nabla_1 \hatPsi( \omega, \omega) - \nabla_1 \Psi( \omega, \omega)\|_2
        &\le 
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_{D\times D}  
        \|t\|_2
        |\hatr_{y}(t,t')-r_{y}(t,t')|  
        dt dt'\\
        &\le 
        \sup_{t,t' \in D} 
        |\hatr_{y}(t,t')-r_{y}(t,t')|
        \int_{D\times D}   \|t\|_2  dt dt'
        \lesssim
        \rho_N,
    \end{align*}
    where the final inequality holds with probability at least $1-c_1e^{-c_2 \tau}$ by Lemma~\ref{lem:SecondMomentHPBound}.
\end{proof}

\subsection{Kernels satisfying Assumption \ref{assumption:kernel}}
Here, we give a simple example of a class of kernels satisfying Assumption~\ref{assumption:kernel}. As is standard (see e.g. \cite{kurisu2022uniform} for the univariate case), we specify the Fourier transform of the kernel. Let $\Kft_0:\R \to \R$ be the Fourier transform of a univariate kernel that is even $(\Kft_0(\omega)= \Kft_0(-\omega))$, supported on $[-1,1]$, $(p+2)$-times continuously differentiable and satisfying 
    \begin{align*}
        (\Kft_0)^{(\ell)}(0) = \begin{cases}
            1 \qquad \text{if}\qquad \ell=0,\\
            0 \qquad \text{if}\qquad \ell=1,\dots, p-1,
        \end{cases}
    \end{align*}
    where $(\Kft_0)^{(\ell)}$ denotes the $\ell$-th derivative. Define the univariate kernel by the inverse Fourier transform, $K_0(t) = \frac{1}{2\pi} \int_{\R} e^{-i\omega t} \Kft(\omega) d \omega,$ and define the multivariate kernel $K:\R^d \to \R$ as the tensor product kernel with components $K_0,$ that is, $K(t) = \prod_{j=1}^d K_0(t_j).$ As we will show, $K$ satisfies Assumption~\ref{assumption:kernel}. Standard choices for $\Kft_0$ are $\Kft_0(\omega) = (1-\omega^2)^a \mathbf{1}\{\omega \in [-1,1]\}$ for $a \ge p+3$ and
    \begin{align*}
    \Kft_0(\omega) = 
    \begin{cases}
         1 \qquad                         & \text{if } \qquad|\omega| \le c_0,\\
         \exp\inparen{
         \frac{-b \exp(-b/(|\omega|-c_0)^2)}{(|\omega|-1)^2}
         } \qquad & \text{if } \qquad c_0 < |\omega| < 1,\\
         0 \qquad                         & \text{if } \qquad |\omega| \ge 1,
    \end{cases}
\end{align*}
    for $c_0 \in (0,1), b > 0,$ which is commonly referred to as the flat-top kernel. Now, we prove that $K$ satisfies Assumption~\ref{assumption:kernel} (i)-(v). 
   \begin{enumerate}[label=(\roman*)]

    \item By the Fourier inversion theorem, $\int_{\R} K_0(t_j) dt_j = \Kft_0(0)=1.$ Therefore 
    $$
    \int_{\R^d} K(t)dt
     = \inparen{\int_{\R} K_0(t_1) dt_1}^d = 1.
    $$

    \item For any multi-index $\nu$ with $1 \le |\nu| \le p-1,$ we have 
    \begin{align*}
        \int_{\R^d} t^\nu K(t)dt = \prod_{j=1}^d \int_{\R} t_j^{\nu_j} K_0(t_j) dt_j,
    \end{align*}
    and so the assumption holds if at least one of the univariate moments is zero, i.e. if $\int_{\R} t_j^{\nu_j} K_0(t_j) dt_j = 0$ for some $j$ where $1 \le \nu_j \le p-1.$ Note that $\int_\R t_j^{\nu_j} K_0(t_j) dt_j = i^{-v_j} (\Kft_0)^{(v_j)}(0) = 0$ by assumption on $\Kft_0.$

    \item By \cite[remark 1]{kurisu2022uniform}, $|K_0(t_j)| = o(|t_j|^{-p-2})$ as $|t_j| \to \infty.$ Therefore, for sufficiently large $t_j,$ $|t_j|^p |K_0(t_j)| \le c|t_j|^{-2} \in L^1(\R),$ and so $|t_j|^{\nu_j} |K_0(t_j)| \le c|t_j|^{-2} \in L^1(\R)$ for any $1 \le \nu_j \le p.$ Hence, for $|\nu| = p$, 
    \begin{align*}
        \int_{\R^d} |t^\nu K(t)|dt = \prod_{j=1}^d \int_{\R} |t_j^{\nu_j}||K_0(t_j)| dt_j < \infty,
    \end{align*}
    since each $v_j \le p.$

    \item Using that $\|t\|_2^p \le d^{p/2} \|t\|_p^p,$ we have 
    \begin{align*}
        \int_{\R^d} \|t\|^p_2 |K(t)|dt
        &\le d^{p/2} \sum_{j=1}^d \int_{\R^d}|t_j|^p \prod_{l=1}^d |K_0(t_k)| dt\\
        &= d^{p/2} \sum_{j=1}^d 
        \inparen{\int_{\R} |t_j|^p |K_0(t_j)|  dt_j}
        \prod_{ k \neq j} \inparen{\int_{\R} |K_0(t_k)| dt_k }
        \le C_K < \infty.
    \end{align*}
    In the above display, the equality holds by Fubini's theorem and the fact that the integral factorizes, and the second inequality holds since $t_j^p K_0(t_j), K_0(t_k) \in L^1(\R^d)$ for any $j,k \le p.$

    \item Since $\Kft(\omega_j)$ is supported on $[-1,1]$ by assumption and $\Kft(\omega) = \prod_{j=1}^d \Kft(\omega_j),$ it follows immediately that $\Kft$ has support $\{ \omega: \|\omega\|_\infty \le 1\}.$
\end{enumerate}


\subsection{Proof of Theorem~\ref{thm:FTDeviation}}\label{app:thmFTDeviation}
 \begin{proof}[Proof of Theorem~\ref{thm:FTDeviation}]
    Define
    \begin{align*}
        \Delta(\omega) 
        = \int_0^1 \inparen{
        \frac{\nabla_1 \hatPsi(\alpha\omega, \alpha\omega)}{\tildePsi(\alpha\omega,\alpha\omega)} \cdot \omega - 
        \frac{\nabla_1 \Psi(\alpha\omega, \alpha\omega)}{\Psi(\alpha\omega,\alpha\omega)} \cdot \omega
        } d\alpha.
    \end{align*}
    We claim  that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta(\omega)| \lesssim \|f\|_{\infty}^{-2} \rho_N h^{-3\beta - 1}$ with probability $1 - c_1 e^{-c_2 \tau}$, and that it holds with the same probability that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta(\omega)| \lesssim \|f\|_{\infty}^{-2} \rho_N h^{-2\beta - 1}$ under the additional assumption that 
    $ \sup_{\omega \in [-h^{-1}, h^{-1}]^d}\frac{\|\nabla \fft(\omega)\|_2}{|\fft(\omega)|} \lesssim 1.$ We first show that this claim implies the result. Indeed, since by assumption $\rho_N \lesssim \|f\|_\infty^2 h^{3\beta+1}$, the claim implies that, with probability $1 - c_1 e^{-c_2 \tau}$, $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta(\omega)| \le 1$ and hence, with the same probability, 
    \begin{align*}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\hatfft(\omega) - \fft(\omega)| 
        &=
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\fft(\omega)| |1-e^{\Delta(\omega)}|\\
        &\le \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 2|\fft(\omega)| |\Delta(\omega)|
        \lesssim \|f\|_\infty \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta(\omega)|,
    \end{align*}
    where the equality holds by definition of $\Delta(\omega),$ the first inequality holds by the fact that $|1-e^z| \le 2 |z|$ for $z \in \C $ with $|z| \le 1,$ and the second inequality holds by Lemma~\ref{lem:fftnbound}. 

    We now prove the claimed high-probability bound on $\Delta(\omega)$. Write
\begin{align*}
    \Delta(\omega) 
    &= 
    \int_0^1 \frac{ (\nabla_1 \hatPsi(\alpha \omega, \alpha \omega) - \nabla_1 \Psi(\alpha \omega, \alpha \omega)) \cdot \omega }{\Psi(\alpha \omega, \alpha \omega)} ~d \alpha\\
    &+\int_0^1 \inparen{\frac{1}{\Psi(\alpha \omega, \alpha \omega)}-\frac{1}{\tildePsi(\alpha \omega, \alpha \omega)}} \nabla_1 \Psi(\alpha \omega, \alpha \omega) \cdot \omega ~d \alpha\\
    &+\int_0^1 \inparen{\frac{1}{\Psi(\alpha \omega, \alpha \omega)}-\frac{1}{\tildePsi(\alpha \omega, \alpha \omega)}} \bigl(\nabla_1 \hatPsi(\alpha \omega, \alpha \omega) - \nabla_1 \Psi(\alpha \omega, \alpha \omega)\bigr)\cdot \omega ~ d \alpha\\
    &=: \Delta_1(\omega) +\Delta_2(\omega) +\Delta_3(\omega),
\end{align*}
and so it suffices to control 
$\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_l(\omega)|$ for $l=1,2,3.$ Let $\mathsf{E}$ denote the event where
\begin{equation*}
    \sup_{ \omega \in [-h^{-1}, h^{-1}]^d} |\hatPsi(\omega,\omega) - \Psi(\omega,\omega)| \lesssim \rho_N 
    \quad \text{and} \quad 
    \sup_{ \omega \in [-h^{-1}, h^{-1}]^d} \|\nabla_1 \hatPsi(\omega,\omega) - \nabla_1 \Psi(\omega,\omega)\|_2  \lesssim \rho_N,
\end{equation*}
which by Lemma~\ref{lem:psiestimates} holds with probability at least $1-c_1e^{-c_2 \tau}.$ For the remainder of the proof, we condition on the event $\mathsf{E}.$ We make regular use of the fact that for any $\omega \in [-h^{-1}, h^{-1}]^d$ and $\alpha \in [0,1]$, it holds that $\alpha \omega \in [-h^{-1}, h^{-1}]^d$. We can bound each term as follows:

    \textit{Controlling $\Delta_1$:}
    \begin{align*}
   \sup_{ \omega \in [-h^{-1}, h^{-1}]^d} |\Delta_1(\omega)|
    &\le 
    \sup_{ \omega \in [-h^{-1}, h^{-1}]^d} \sup_{0 \le \alpha \le 1} |(\nabla_1 \hatPsi( \alpha\omega, \alpha\omega) - \nabla_1 \Psi(\alpha\omega,\alpha\omega)) \cdot \omega |\\ 
    &\times \inparen{\int_0^1 \frac{1}{|\Psi(\alpha \omega,\alpha \omega)|} d\alpha}\\
    &\le 
    \sup_{ \omega \in [-h^{-1}, h^{-1}]^d} \inparen{ \| \omega \|_2 
    \|\nabla_1 \hatPsi(\omega,\omega) - \nabla_1 \Psi(\omega, \omega) \|_2 
    \int_0^1 \frac{1}{|\Psi(\alpha \omega,\alpha \omega)|} d\alpha}\\
    &\lesssim
    \sqrt{d} h^{-1} \rho_N
    \int_0^1 \frac{1}{|\Psi(\alpha\omega, \alpha \omega)|} d\alpha
    \lesssim 
    \frac{d^{\beta+\frac{1}{2}}
    h^{-2\beta - 1}}{ (2\beta + 1) \|f\|_\infty^2}
    \rho_N,
\end{align*}
where the second inequality holds by Cauchy-Schwarz and in the third inequality we use that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} \|\omega\|_2 = \| h^{-1} 1_d\|_2 = \sqrt{d} h^{-1}$. For the last inequality, we note that $\Psi( \alpha\omega,  \alpha\omega) = \fft( \alpha\omega) \overline{\fft(\alpha\omega)}$, and since $|\fft| = |\overline{\fft}|,$ by Assumption~\ref{assumption:smoothness} we have
\begin{align*}
    \sup_{\omega \in [-h^{-1}, h^{-1}]^d} \int_0^1 \frac{1}{|\Psi(\alpha\omega, \alpha \omega)|} d\alpha
    &\lesssim 
    \|f\|_\infty^{-2} \sup_{\omega \in [-h^{-1}, h^{-1}]^d} \| \omega \|_2^{2\beta} \int_0^1 \alpha^{2\beta} d\alpha
    = \frac{d^{\beta} h^{-2\beta}}{ (2 \beta + 1)\|f\|_\infty^{2}}.
\end{align*}

\textit{Controlling $\Delta_2$:} 
    \begin{align*}
        &\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_2(\omega)|
        =
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \abs{
        \int_0^1 \inparen{\frac{\nabla_1 \Psi(\alpha \omega, \alpha \omega) \cdot \omega}{\Psi(\alpha \omega, \alpha \omega)}-
        \frac{\nabla_1 \Psi(\alpha \omega, \alpha \omega) \cdot \omega}{\tildePsi(\alpha \omega, \alpha \omega)}}  ~d \alpha
        }\\
        &\qquad=
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \abs{
        \int_0^1 
        \inparen{\frac{\nabla_1 \Psi(\alpha \omega, \alpha \omega)}{\Psi(\alpha \omega, \alpha \omega)} \cdot \omega}
        \inparen{\frac{\tildePsi(\alpha \omega, \alpha \omega)- \Psi(\alpha \omega, \alpha \omega)}{\tildePsi(\alpha \omega, \alpha \omega)}}  ~d \alpha
        }\\
        &\qquad\le 
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \abs{\frac{\tildePsi( \omega, \omega)- \Psi( \omega,  \omega)}{\tildePsi(\omega, \omega)}}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_0^1 
        \abs{\frac{\nabla_1 \Psi(\alpha \omega, \alpha \omega)}{\Psi(\alpha \omega, \alpha \omega)} \cdot \omega}
        ~d \alpha
        \\
        &\qquad\le 
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \abs{\frac{\tildePsi( \omega, \omega)- \Psi( \omega,  \omega)}{\tildePsi(\omega, \omega)}}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} \| \omega\|_2 \int_0^1 \left \| \frac{\nabla_1 \Psi(\alpha \omega,\alpha \omega)}{\Psi(\alpha \omega,\alpha \omega)} \right \|_2 d\alpha 
        \\
        &\qquad\le \sqrt{d} h^{-1}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \abs{\frac{\tildePsi( \omega, \omega)- \Psi( \omega,  \omega)}{\tildePsi(\omega, \omega)}}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_0^1 \left \|  \frac{\nabla_1 \Psi(\alpha \omega,\alpha \omega)}{\Psi(\alpha \omega,\alpha \omega)} \right \|_2 d\alpha\\
        &\qquad=: \sqrt{d} h^{-1} \times \textbf{(I)} \times \textbf{(II)}.
    \end{align*}
    For the numerator of $\textbf{(I)}$
    \begin{align*}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\tildePsi(\omega, \omega)- \Psi(\omega, \omega)|
        \le 
        \frac{2}{\sqrt{N}} + \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\hatPsi(\omega, \omega)- \Psi(\omega, \omega)| \lesssim  \rho_N,
    \end{align*}
    where the first inequality holds by \cite[Lemma 3]{kurisu2022uniform}. For the denominator, by Assumption~\ref{assumption:smoothness} we have
    \begin{align*}
        \inf_{\omega \in [-h^{-1}, h^{-1}]^d} |\Psi( \omega, \omega)|
        =
        \inf_{\omega \in [-h^{-1}, h^{-1}]^d} |\fft(\omega)\overline{\fft(\omega)}|
        \gtrsim 
        \|f\|_\infty^2 \inf_{\omega \in [-h^{-1}, h^{-1}]^d} \|\omega\|_2^{-2\beta}
        =
        \|f\|_\infty^2 h^{2\beta},
    \end{align*}
    and so
    \begin{align*}
        \inf_{\omega \in [-h^{-1}, h^{-1}]^d} |\tildePsi(\omega, \omega)|
        &\ge 
        \inf_{\omega \in [-h^{-1}, h^{-1}]^d} |\hatPsi(\omega, \omega)|\\
        &\ge 
        \inf_{\omega \in [-h^{-1}, h^{-1}]^d} |\Psi(\omega, \omega)|
        -
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\hatPsi(\omega, \omega)- \Psi(\omega, \omega)|\\
        &\gtrsim 
        \|f\|_\infty^2 h^{2\beta} - \rho_N 
        \gtrsim \|f\|_\infty^2 h^{2\beta},
    \end{align*}
    where the first inequality holds by definition of $\tildePsi$, and the final inequality holds by the assumption $\rho_N \lesssim \|f\|_\infty^2 h^{3\beta+1} \le \|f\|_\infty^2 h^{2\beta}$ for $h < 1$. Therefore
    \begin{align*}
        \textbf{(I)}
        &\le 
        \frac{\sup_{\omega \in [-h^{-1}, h^{-1}]^d}  |\tildePsi( \omega,  \omega)- \Psi( \omega,  \omega)|}{ \inf_{\omega \in [-h^{-1}, h^{-1}]^d}|\tildePsi( \omega, \omega)|}
        \lesssim \frac{\rho_N h^{-2\beta} }{\|f\|_\infty^2}.
    \end{align*}
    For $\textbf{(II)}$, direct calculation shows that 
    \begin{align*}
        \Psi(\omega_1,\omega_2) 
        &= r_{\yft}(\omega_1,\omega_2)  - k_{\etaft}(\omega_1,\omega_2) 
        = \E[e^{-i(\omega_1-\omega_2)\zeta}] \fft(\omega_1) \overline{\fft(\omega_2)},
    \end{align*}
    and so 
    \begin{align*}
        \nabla_1 \Psi(\omega_1,\omega_2) 
        &=
        -i \E[\zeta e^{-i(\omega_1-\omega_2)\zeta}]  \fft(\omega_1) \overline{\fft(\omega_2)}
        +
        \E[e^{-i(\omega_1-\omega_2)\zeta}]  \overline{\fft(\omega_2)}\nabla \fft(\omega_1),
    \end{align*}
    which gives 
    $\nabla_1 \Psi(\omega, \omega)= -i \fft(\omega) \overline{\fft(\omega)}
        +
         \overline{\fft(\omega)}\nabla \fft(\omega).$ Therefore 
    \begin{align*}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_0^1 \left \| \frac{\nabla_1 \Psi(\alpha \omega,\alpha \omega)}{\Psi(\alpha \omega,\alpha \omega)} \right \|_2 d\alpha
         \le 
        1 + 
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_0^1 \left \| 
        \frac{ \nabla \fft(\alpha \omega)}{\fft(\alpha \omega)} \right \|_2 d\alpha.
    \end{align*}
    We then note that 
    \begin{align*}
        \left \| 
        \frac{ \nabla \fft(\alpha \omega)}{\fft(\alpha \omega)} \right \|_2
        &\le 
        \frac{\int_D |i| \|t\| |e^{-it \cdot \alpha \omega} |f(t)| dt}{|\fft(\alpha \omega)|}
        =
        \frac{\int_D  \|t\| |f(t)| dt}{|\fft(\alpha \omega)|}
        \lesssim \frac{\sqrt{d} \|f\|_\infty}{|\fft(\alpha \omega)|}
        \lesssim \frac{\sqrt{d}}{\alpha^{-\beta} \| \omega\|^{-\beta}},
    \end{align*}
    where the last inequality follows by Assumption~\ref{assumption:smoothness}. Putting it together, we have
    \begin{align*}
        \sup_{\omega \in [-h^{-1}, h^{-1}]^d} 
        \int_0^1 \left \| \frac{\nabla_1 \Psi(\alpha \omega,\alpha \omega)}{\Psi(\alpha \omega,\alpha \omega)} \right \|_2 d\alpha
        \lesssim 
        1+ \frac{1}{1+\beta} h^{-\beta},
    \end{align*}
    and so 
    $$
    \sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_2(\omega)| \lesssim \|f\|_\infty^{-2} \rho_N h^{-3\beta-1}. 
    $$
    If we assumed additionally that $ \sup_{\omega \in [-h^{-1}, h^{-1}]^d}\frac{\|\nabla \fft(\omega)\|_2}{|\fft(\omega)|} \lesssim 1,$ then $\textbf{(II)} \lesssim 1$ and so it follows that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_2(\omega)| \lesssim \rho_N h^{-2\beta-1}.$


    \textit{Controlling $\Delta_3$:} By identical arguments to the ones used to control $\Delta_1$ and $\Delta_2$, it holds that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_3(\omega)| \lesssim \rho_N^2 h^{-4\beta - 1}$. Note that this term is negligible since $\rho_N^2$ decays like $N^{-1}$. Under the additional assumption $ \sup_{\omega \in [-h^{-1}, h^{-1}]^d} \frac{\|\nabla \fft(\omega)\|_2}{|\fft(\omega)|}  \lesssim 1$, it follows similarly to the analysis of $\Delta_2$ that $\sup_{\omega \in [-h^{-1}, h^{-1}]^d} |\Delta_3(\omega)| \lesssim \rho_N^2 h^{-2\beta - 1}.$ 
\end{proof}

\subsection{Supplementary Materials for Subsection~\ref{subsec:snr}}\label{app:highNoiseRegime}
\begin{proof}[Proof of Corollary~\ref{corr:highNoiseRegime}]
        Under the additional assumptions of this subsection, we have 
        \begin{align*}
            \|r_y\|_\infty \frac{\Gamma(y)}{\sqrt{N}} 
            &= \|r_y\|_\infty^{1/2} \frac{\E[\sup_{t\in D} y(t)]}{\sqrt{N}} 
            \le \frac{1}{\sqrt{N}} (\|f\|_\infty + \|k_\eta \|^{1/2}_\infty) ( \|f\|_\infty +  \E [\sup_{t \in D} \eta(t)])\\
            &\lesssim  \frac{1}{\sqrt{N}} \|k_\eta \|^{1/2}_\infty \E [\sup_{t \in D} \eta(t)]
            = \frac{\mathsf{snr}^{-1} \|f\|_\infty^2}{\sqrt{N}}.
        \end{align*}
        The last inequality follows since by assumption $\|k_\eta\|^{1/2}_\infty \ge \|f\|_\infty$, and the fact that for any centered Gaussian process, we have, for any $t \in D,$
    $$
    \E[\sup_{t\in D} \eta(t)]
    \asymp 
    \E[\sup_{t\in D} |\eta(t)|]
    \ge 
    \E|\eta(t)|
    \ge 
    \sqrt{\E|\eta(t)|^2}
    = \sqrt{k_\eta(t,t)},
    $$
    where the last inequality holds by Jensen's inequality. Theorem~\ref{thm:ErrorBoundDeconvolutionEstimator} then implies that with probability at least $1-c_1e^{-c_2 \tau },$ 
    \begin{align}\label{eq:corr1-prelim}
        \frac{\|\hatf - f\|_\infty}{\|f\|_\infty}
        \lesssim
        \inparen{\|r_y\|_{\infty}
        \sqrt{\frac{\tau}{N}}
        \lor 
        \frac{\mathsf{snr}^{-1}}{\sqrt{N}}} h^{-3\beta - d - 1} + h^{\beta-d}.
    \end{align}
    The optimal bandwidth is chosen to minimize the right-hand side of the above display, and a calculation yields 
    \begin{align*}
        h^* \asymp \inparen{
        \|r_y\|_{\infty}
        \sqrt{\frac{\tau}{N}}
        \lor 
        \frac{\mathsf{snr}^{-1}}{\sqrt{N}}
        }^{\frac{1}{4 \beta + 1}},
    \end{align*}
    which can be plugged into \eqref{eq:corr1-prelim} to give the desired relative error bound, after noting that  $\| r_y\|_\infty \le \|f\|_\infty^2 + \|k_\eta\|_\infty \lesssim \|k_\eta\|_\infty$.
    \end{proof}


\begin{proof}[Proof of Corollary~\ref{corr:largesigma}]
         Clearly, $k_\eta^{\text{SE}}(t,t) = \sigma^2$ for any $t \in D$. Further, we may write $\eta = \sigma z$ where $z$ is a Gaussian process with covariance function $\exp(-\|t-t'\|^2_2/2\lambda^2),$ and so $\E[\sup_{t \in D} \eta(t)]=\sigma \E[\sup_{t \in D} z(t)],$ with the second term having no dependence on $\sigma.$ Therefore, 
         $\E[\sup_{t \in D} \eta(t)] \asymp \sigma.$ 
         The result follows from Corollary~\ref{corr:highNoiseRegime} after noting that $\Gamma(y) \asymp 1$ and $\|k_\eta\|_\infty = \sigma^2.$
    \end{proof}

\begin{proof}[Proof of Corollary~\ref{corr:smallLengthscale}]
        Clearly, $k_\eta^{\text{SE}}(t,t) = \sigma^2$ for any $t \in D$, and by \cite[Lemma 4.3]{al2025covariance}, there exists a universal constant $\lambda_0>0$ such that, for any $\lambda < \lambda_0,$ $\E [\sup_{t \in D} \eta(t)] \asymp \sigma \sqrt{\log\frac{1}{\lambda^d}}.$ 
       The result follows  from Corollary~\ref{corr:highNoiseRegime} by taking $\tau = \Gamma(y)^2$ and noting that 
        \begin{align*}
            \Gamma(y) 
            = \frac{\E[\sup_{t \in D} y(t)]}{\|r_y\|_\infty^{1/2}}
            \le 
            \frac{\|f\|_\infty + \E[\sup_{t \in D} \eta(t)]}{\|k_\eta\|_\infty^{1/2}}
            \lesssim
             \frac{\E[\sup_{t \in D} \eta(t)]}{\|k_\eta\|_\infty^{1/2}} \asymp \sqrt{\log \lambda^{-d}}.
        \end{align*}
    \end{proof}




\section{Supplementary Materials for Section~\ref{sec:vanishing}}
\label{app:vanishing}

\begin{lemma}[Power Spectrum bounds]\label{PSderivbounds}
Suppose $f$ satisfies Assumption \ref{assumption:psiestimates}. Let $P(\omega) = \Psi(\omega, \omega)=\fft(\omega)\fft(-\omega)$. Then, $\|P^{(\ell)}\|_\infty \lesssim \|f\|^2_\infty$ for $\ell=0,1,2,3.$
\end{lemma}


\begin{proof}
Direct calculation shows:
\begin{align*}
	P(\omega) &= \Psi(\omega, \omega) = \fft(\omega) \fft(-\omega),\\
	P'(\omega) &= \partial_1 \Psi(\omega, \omega) + \partial_2 \Psi(\omega, \omega)=  (\fft)'(\omega) \fft(-\omega)-\fft(\omega) (\fft)'(-\omega),\\
	P''(\omega)&= 
	\partial_1^2 \Psi(\omega, \omega) + \partial_2^2 \Psi(\omega, \omega)
	+2\partial_2\partial_1 \Psi(\omega, \omega)\\
	&= 
	(\fft)''(\omega)\fft(-\omega) + \fft(\omega)(\fft)''(-\omega) - 2 (\fft)'(\omega) (\fft)'(-\omega),\\
	P'''(\omega) &= \partial_1^3 \Psi(\omega,\omega)+ \partial_2^3\Psi(\omega,\omega) + 3\partial_2 \partial_1^2\Psi(\omega,\omega) + 3\partial_1 \partial_2^2\Psi(\omega,\omega)\\
	&= (\fft)'''(\omega)\fft(-\omega)-(\fft)'''(-\omega)\fft(\omega)\\
	&\quad+(\fft)'(-\omega)(\fft)''(\omega)-(\fft)'(\omega)(\fft)''(-\omega).
\end{align*}
The result follows immediately by Lemma~\ref{lem:fftnbound}.
\end{proof}


\begin{proof}[Proof of Lemma \ref{zeros_location_control}]
	Defining $ P^{(\ell)}(\omega), \, \ell = 0,1,2,3$, to be the power spectrum and its derivatives, as in Lemma \ref{PSderivbounds}, note that $P^{(\ell)}$ is real for $\ell = 0,1,2,3$. Likewise, since by assumption $\hatP$ is real, it follows that $\hatP^{(\ell)}$ is real for $\ell = 0,1,2$. By Lemma \ref{lem:psiestimates} and a slight modification of its proof to handle estimation of $\nabla_2\Psi$, it follows that there exist universal constants $ c_1,c_2 $ such that, for any $ \tau \geq 1 $, it holds with probability at least $ 1-c_1 e^{-c_2 \tau} $ that
	\[
	\sup_{\omega\in[0,\hinv]} | P^{(\ell)}(\omega)-\hatP^{(\ell)}(\omega) | 
	\lesssim \rho_N, \qquad \ell=0,1,2.
	\]
    Define $\checkep := h^{-\beta}\|f\|_\infty^{-1}\sqrt{\thresh}$. Then, by Assumption \ref{assumption:thresholding}, $\xi_{k(\hinv)}+h^{-\beta}\|f\|_\infty^{-1}\sqrt{\thresh} \leq \hinv$, so we can assume going forwards that $[\xi_i-\checkep, \xi_i+\checkep] \subset [0,\hinv]$ for all $\xi_i \in Z_P$. Additionally, by the assumptions,
    \begin{align}
        \checkep
        &\lesssim h^{2\beta} \leq \epsilon_{\max},\label{eq:checkep}\\
        \rho_N &\lesssim \checkep^2h^{4\beta}\|f\|_\infty^2.\label{eq:rhocheckep}
    \end{align}
    We will reference these bounds later on. Note that $ \checkep \leq \epsilon_{\max}$ in \eqref{eq:checkep} implies that there exist $L,B>0$ satisfying the inequalities in Assumption \ref{assumption:nice_oscillations}.\\ \textbf{(I)} We first show that
\begin{equation}\label{eq:P''lowerbound}
    	\min_{\xi_i\in Z_{P}} |\omega-\xi_i| \leq \checkep \implies |P''(\omega)| \gtrsim h^{2\beta}\|f\|_\infty^2 .
\end{equation}
	Let $ \xi_i \in Z_P $ and $ \checkep \in [0, \epsilon_{\max}] $. Note that $ Z_P $ and $ Z_{\fft} $ are identical. Then, $ (\fft)'(\xi_i) = o_f'(\xi_i)(\xi_i)^{-\beta} - \beta o_f(\xi_i)\xi_i^{-\beta-1} = o_f'(\xi_i)\xi_i^{-\beta} $, and so by Assumption \ref{assumption:nice_oscillations} and the fact that $ \xi_i\leq \hinv $, $ |P''(\xi_i)| = 2|(\fft)'(\xi_i)|^2 \geq 2B^2\| f\|_\infty^2 h^{2\beta} \gtrsim 2\| f\|_\infty^2 h^{2\beta}$. By the mean value theorem, there exists a $ \omega_1 \in [\xi_i,\xi_i+\checkep] $ such that 
	\[
	P''(\xi_i+\checkep) =  P''(\xi_i) + P'''(\omega_1)\cdot \checkep.
	\]
	By Lemma \ref{PSderivbounds}, $ |P'''(\omega)| \lesssim \| f\|_\infty^2$, so there exists some constant $C_3 > 0 $ such that
	\[
	|P''(\xi_i+\checkep)| \geq \left|  |P''(\xi_i)| - C_3\|f\|_\infty^2\checkep \right|.
	\] 
	   By \eqref{eq:checkep}, $ \checkep \lesssim h^{2\beta}$, so $|P''(\xi_i+\checkep)| \gtrsim h^{2\beta}\|f\|_\infty^2$. Extending to $ \xi_i-\checkep $ without loss of generality yields
	\[
	\min_{\xi_i\in Z_{P}} |\omega-\xi_i| \leq \checkep \implies |P''(\omega)| \gtrsim h^{2\beta}\|f\|_\infty^2 .
	\]
	\textbf{(II)} Next, we show that     \begin{equation}\label{eq:exists0}
        \forall\, \xi_i \in Z_P, \, \exists\, \hatxi_i \in Z_{\hatP'} \,: \, \hatxi_i \in  [\xi_i-\checkep, \xi_i+\checkep].
    \end{equation} 
    Suppose this were not true, and fix a $\xi_i\in Z_P$. It follows that $\hatP'$ could not have a zero on $(\xi_i-\checkep, \xi_i+\checkep)$, and so without loss of generality, we say that $\hatP'(\omega) > 0$ for all $\omega \in [\xi_i-\checkep, \xi_i+\checkep]$. Specifically, we have (i) $\hatP'(\xi_i+\checkep) > 0$. As $Z_P \subset Z_{P'}$, by (\ref{eq:P''lowerbound}), $|P''(\omega)| \gtrsim h^{2\beta}\|f\|_\infty^2 >0$ on $(\xi_i-\checkep, \xi_i+\checkep)$. Thus, $P'$ must be monotonically increasing or decreasing on $(\xi_i-\checkep, \xi_i+\checkep)$. Note that $P'(\xi_i) = 0$. Since $[\xi_i-\checkep, \xi_i+\checkep] \subset [0,\hinv]$ for all $\xi_i \in Z_P$, without loss of generality we can say that $P'(\xi_i-\checkep) > 0$ and (ii) $P'(\xi_i+\checkep)<0$. Additionally, we observe that (iii) $|P'(\xi_i+\checkep)| \geq B^2h^{2\beta}\|f\|_\infty^2 \checkep$, as otherwise by the mean value theorem there would exist an $\omega_2 \in (\xi_i, \xi_i+\checkep)$ such that 
	\begin{align*}
		B^2h^{2\beta}\|f\|_\infty^2 \leq |P''(w_2)| &= \frac{|P'(\xi_i+\checkep)-P'(\xi_i))|}{|\xi_i+\checkep-\xi_i|} = \frac{|P'(\xi_i+\checkep)|}{\checkep}\\
		&<B^2h^{2\beta}\|f\|_\infty^2 \checkep/\checkep = B^2 h^{2\beta}\|f\|_\infty^2 ,
	\end{align*}
	yielding $B^2h^{2\beta}\|f\|_\infty^2 < B^2h^{2\beta}\|f\|_\infty^2 $, a contradiction. Collecting all the pieces, we have that, since 
    \begin{enumerate}
        \item $P'(\xi_i+\checkep)<0;$ 
        \item $|P'(\xi_i+\checkep)| \gtrsim  h^{2\beta}\| f\|_\infty^2;$
        \item $\hatP'(\xi_i+\checkep) > 0$,
    \end{enumerate}
    it follows that
	\[
	h^{2\beta}\|f\|_\infty^2 \checkep \lesssim | P'(\xi_i+\checkep)| < | P'(\xi_i+\checkep) - \hatP'(\xi_i+\checkep) | < \rho_N,
	\]
	a contradiction by \eqref{eq:rhocheckep}, and so there must exist a $\hatxi_i\in (\xi_i-\checkep, \xi_i+\checkep)$ such that $\hatP'(\hatxi_i) = 0.$ \\
	\textbf{(III)} Next, we show that 
\begin{equation}\label{eq:unique0}
        \forall\, \xi_i \in Z_P, \, \exists\,!\, \hatxi_i \in Z_{\hatP'} \,: \, \hatxi_i \in  [\xi_i-\checkep, \xi_i+\checkep].
    \end{equation} 
	We have already shown in \textbf{(II)} that there exists such a $\hatxi_i$. Now we show that such a $\hatxi_i$ is unique. We proceed by contradiction. If such a $\hatxi_i$ was not unique in $(\xi_i-\checkep, \xi_i+\checkep)$, i.e. there existed a $\hatxi_i^1 < \hatxi_i^2$ such that $\hatP'(\hatxi_i^1) = \hatP'(\hatxi_i^2) = 0$, then there would exist a $\omega_3 \in (\hatxi_i^1, \hatxi_i^2)$ such that $\hatP''(\omega_3) = 0$. But this is a contradiction, as if $\hatP''(\omega_3) = 0$,
	\[
	h^{2\beta}\|f\|_\infty^2  \lesssim   \left|  |P''(\omega_3)| - | \hatP''(\omega_3) |   \right| \leq |P''(\omega_3) - \hatP''(\omega_3)| < \rho_N,
	\]
	which is impossible by \eqref{eq:rhocheckep}.\\
    \textbf{(IV)} Define $ \delta = \rho_N/(h^{2\beta}\|f\|_\infty^2 )$. Finally, we show that
    \begin{equation}\label{eq:0bound}
        \forall \, \xi_i\in Z_P, |\xi_i-\hatxi_i| \lesssim \delta,
    \end{equation}
    where $\hatxi_i$ is the unique element of $Z_{\hatP'}$ in $[\xi_i-\checkep, \xi_i+\checkep]$ that we attain in equations (\ref{eq:exists0}) and (\ref{eq:unique0}). Indeed, by the mean value theorem and equation (\ref{eq:P''lowerbound}), there exists a $\omega_4 \in (\xi_i-\checkep, \xi_i+\checkep)$ such that
	\[
	h^{2\beta}\|f\|_\infty^2 \lesssim |P''(\omega_4)| = \frac{|P'(\xi_i)-P'(\hatxi_i)|}{|\xi_i-\hatxi_i|}.
	\] 
    Note that $P'(\xi_i)=0$ and $\hatP'(\hatxi_i)=0$. Thus by our assumptions, $|P'(\hatxi_i)-\hatP'(\hatxi_i)| \leq \rho_N$, so $|P'(\hatxi_i)| \leq \rho_N$.
    Consequently,
    \[
    h^{2\beta}\|f\|_\infty^2 \lesssim \frac{|P'(\xi_i)-P'(\hatxi_i)|}{|\xi_i-\hatxi_i|} = \frac{|P'(\hatxi_i)|}{|\xi_i-\hatxi_i|}
    \leq \frac{\rho_N}{|\xi_i-\hatxi_i|},
    \]
    which ultimately implies that
    \[ |\xi_i-\hatxi_i|  \lesssim \rho_N/(h^{2\beta}\|f\|_\infty^2), 
    \]
    as desired. We have now shown that for each $ \xi_i \in Z_P $, there exists a unique $ \hatxi_i \in Z_{\hatP'} $ such that $ |\xi_i - \hatxi_i| \lesssim\delta $.\\	
	\textbf{(V)} Recall that $\checkep := h^{-\beta}\|f\|_\infty^{-1}\sqrt{2\thresh}$ and let $\rho_N h^{-2\beta} \lesssim \thresh \lesssim \|f\|_\infty^2h^{6\beta}$, as assumed. We now show that for 
    \begin{align}
        \hatxi_i\in Z_{\hatP'}\, \text{ and }\hatP(\hatxi_i) > \thresh &\implies\hatxi_i \not\in Z_P^{\checkep},\\
        \hatxi_i\in Z_{\hatP'} \text{ and } \hatP(\hatxi_i) < \thresh &\implies \hatxi_i \in Z_P^{\checkep}.
    \end{align}

	We proceed by proving the contrapositive of the two statements. Suppose that $\hatxi_i \not\in \cup_{\xi_i\in Z_P} (\xi_i-\checkep, \xi_i+\checkep)$. Then $|\hatxi_i-Z_P| \geq \checkep$ and so $|\hatxi_i-Z_{\fft} | \geq \checkep$. Thus by Assumption \ref{assumption:nice_oscillations}, $|P(\hatxi_i)| \geq L^2\|f\|_\infty^2\checkep^2h^{2\beta} \gtrsim \|f\|_\infty^2\checkep^2h^{2\beta}$. Additionally, as $| \hatP(\hatxi_i)-P(\hatxi_i) | < \rho_N$, $\hatP(\hatxi_i) \geq P(\hatxi_i)-\rho_N \gtrsim \|f\|_\infty^2\checkep^2h^{2\beta}- \rho_N$, so since $\rho_B \lesssim h^{2\beta}\thresh$ and by \eqref{eq:rhocheckep} $\rho_N \lesssim \checkep^2h^{4\beta}\|f\|_\infty^2$, it must be that $\hatP(\hatxi_i) > \thresh$, completing the first part of the proof.

	Now suppose that $\hatxi_i \in\cup_{\xi_i\in Z_P} (\xi_i-\checkep, \xi_i+\checkep)$. Then, since the zeros of $\fft$ and therefore $P$ are well isolated, there exists a unique $\xi_i\in Z_P$ such that $|\xi_i - \hatxi_i| < \checkep$. But we have already shown that for such a $\xi_i\in Z_P$, there can be at most one $\hatxi_i\in Z_{\hatP'}$ such that $|\xi_i - \hatxi_i| < \checkep$ and in fact for such a $\hatxi_i$, it must be that $|\xi_i - \hatxi_i| \lesssim\delta$.

	By the mean value theorem, assuming without loss of generality that $\xi_i < \hatxi_i$, there exists an $\omega_5 \in [\xi_i, \hatxi_i]$ such that $|P'(\omega_5)| = | P(\hatxi_i)-P(\xi_i)|/ |\hatxi_i - \xi_i|$. But $P(\xi_i) = 0$, so by Lemma \ref{PSderivbounds} there exists a constant $C >0$ such that
	\[
	|P(\hatxi_i) |= | P'(\omega^*)|\cdot |\hatxi_i - \xi_i| \leq \frac{C}{h^{2\beta}\|f\|_\infty^2}\|f\|_\infty^2\rho_N = {C\cdot h^{-2\beta}}\rho_N.
	\]
	Finally, $\hatP(\hatxi_i) < P(\hatxi_i) + \rho_N < ({h^{-2\beta }C}+1)\rho_N$. Since by \eqref{eq:rhocheckep}, $\rho_N \lesssim \|f\|_\infty^2\checkep^2 h^{4\beta}$, it must be that $\hatP(\hatxi_i) < \thresh$.\\	
	\textbf{(VI)} We conclude by defining $ \mathcal{Z}_\thresh := \{ \hatxi \in Z_{\hatP'} \, : \, \hatP(\xi) < \thresh  \} $.  We began by showing that for any element $\xi \in Z_P$ there is a unique element $\hatxi \in Z_{\hatP'}$ such that $|\xi - \hatxi| \lesssim \delta$, and now we have shown that every element of $\mathcal{Z}_\thresh$ is in $\cup_{\xi_i\in Z_P} (\xi_i-\checkep, \xi_i+\checkep)$ and thus is $\delta $ away from a unique element of $Z_P$. Thus $|\mathcal{Z}_\thresh| = |Z_P|$ and the lemma is proved.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:error_from_zeros}]
	We first show that \eqref{equ:error_intermediate} holds when $\omega \in \hatomega_\epsilon$, i.e. $|\omega - \hatxi_i|\geq \epsilon$ for all the estimated zeros $\hatxi_i$. Note that in this case, $\hatk(\omega)=k(\omega)$, and for brevity we denote the number of zeros less than $\omega$ simply by $k$ in the following argument. Note that $\frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}=\frac{(\fft)'(\xi)}{\fft(\xi)}$ and so $\frac{\fft(\xi_2)}{\fft(\xi_1)}=\exp\left(\int_{\xi_1}^{\xi_2} \frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right)$ by Lemma \ref{lem:technicalKotlarski}, as long as $\fft \ne 0$ on the straight-line path connecting $\xi_1,\xi_2$.  We thus obtain: 
	\begin{align}
&\exp\left(\int_{\hatomega_\epsilon} \frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right) \nonumber \\&  = \exp\left(\int_0^{\hatxi_1^-} \frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right)\exp\left(\int_{\hatxi_1^+}^{\hatxi_2^-}\frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right) \cdots \nonumber
		\exp\left(\int_{\hatxi_{k}^+}^{\omega}\frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right) \\
		\hspace{1cm}& = \left(\frac{\fft(\hatxi_1^-)}{\fft(\hatxi_1^+)}\right)\left(\frac{\fft(\hatxi_2^-)}{\fft(\hatxi_2^+)}\right) \cdots \left(\frac{\fft(\hatxi_k^-)}{\fft(\hatxi_k^+)}\right)\fft(\omega) \label{equ:initial_formula}\, ,
	\end{align}
	where $\hatxi^{-}_i = \hatxi_i-\epsilon$, $\hatxi^{+}_i=\hatxi_i+\epsilon$.
	Taylor expanding $\fft$ about $\xi_i$, we have 
	\begin{align*}
		\fft(\xi) &= (\fft)'(\xi_i)(\xi-\xi_i) +  \frac{(\fft)''(\xi_i)}{2}(\xi-\xi_i)^2 +\frac{(\fft)^{(3)}(\xi^*)}{6}(\xi-\xi_i)^3 \\
		&:= c_1(\xi-\xi_i)+c_2(\xi-\xi_i)^2+c_3(\xi-\xi_i)^3
	\end{align*}
	for some $\xi^*$ on the line segment containing $\xi_i$ and $\xi$. Plugging in $\hatxi_i^+,\hatxi_i^-$ and letting $\Delta \xi_i = \hatxi_i - \xi_i$ gives:
	\begin{align*}
		\fft(\hatxi_i^+) &= c_1(\hatxi_i +\epsilon - \xi_i)+ c_2(\hatxi_i +\epsilon - \xi_i)^2 + c^+_3(\hatxi_i +\epsilon-\xi_i)^3 \\
		&= c_1(\epsilon +\Delta \xi_i)+ c_2(\epsilon +\Delta \xi_i)^2 + O(\epsilon^3), \\
		\fft(\hatxi_i^-) &= c_1(\hatxi_i - \epsilon - \xi_i)+ c_2(\hatxi_i -\epsilon - \xi_i)^2 + c^-_3(\hatxi_i - \epsilon-\xi_i)^3 \\
		&= c_1(-\epsilon +\Delta \xi_i)+ c_2(- \epsilon +\Delta \xi_i)^2 + O(\epsilon^3) \, .
	\end{align*}
	We thus obtain:
	\begin{align*}
		\frac{\fft(\hatxi_i^+)}{\fft(\hatxi_i^-)} &= \frac{ c_1(\epsilon +\Delta \xi_i)+ c_2(\epsilon +\Delta \xi_i)^2 + O(\epsilon^3) }{c_1(-\epsilon +\Delta \xi_i)+ c_2(- \epsilon +\Delta \xi_i)^2 + O(\epsilon^3) } \\
		&= \frac{ \frac{\epsilon +\Delta \xi_i}{-\epsilon +\Delta \xi_i} + \frac{c_2}{c_1}\frac{(\epsilon +\Delta \xi_i)^2}{(-\epsilon +\Delta \xi_i)} + O(\epsilon^2) }{ 1 + \frac{c_2}{c_1}(-\epsilon +\Delta \xi_i) + O(\epsilon^2)} \\
		&= -1 \frac{ \left(\frac{\epsilon +\Delta \xi_i}{\epsilon -\Delta \xi_i} + \frac{c_2}{c_1}\frac{(\epsilon +\Delta \xi_i)^2}{(\epsilon -\Delta \xi_i)} + O(\epsilon^2) \right)}{ \left(1 + \frac{c_2}{c_1}(-\epsilon +\Delta \xi_i) + O(\epsilon^2)\right)}
		:= -1\cdot \frac{\textbf{(I)}}{\textbf{(II)}}\, ,
	\end{align*}
	where $\textbf{(I)}$ denotes the numerator and $\textbf{(II)}$ the denominator. We will show that both factors are close to 1, starting with $\textbf{(I)}$. Note:
	\begin{align*}
		\textbf{(I)} &=  \textbf{(A)} + \textbf{(B)} + O(\epsilon^2)\, , \quad\quad \textbf{(A)} = \frac{1+\frac{\Delta \xi_i}{\epsilon}}{1-\frac{\Delta \xi_i}{\epsilon}} \, , \quad\quad \textbf{(B)} = \frac{c_2}{c_1}\textbf{(A)}(\epsilon+\Delta\xi_i)\, .
	\end{align*}
	We thus obtain:
	\begin{align}
		\label{equ:bound_for_A}
		\textbf{(A)} = 1 + O\left(\delta \epsilon^{-1}\right) \, , \quad\quad \textbf{(B)} = \frac{c_2}{c_1}\left(1 + O\left(\delta \epsilon^{-1}\right)\right)(\epsilon+\Delta\xi_i) = \frac{c_2}{c_1}O(\epsilon)\, .
	\end{align}
    Note that by Assumption \ref{assumption:FT_decay}, we have at the zero $\xi_i$:
	\begin{align*}
		(\fft)'(\xi_i) &= \frac{o'(\xi_i)}{\xi_i^\beta} \, , \quad\quad (\fft)''(\xi_i) =-2\beta\frac{o'(\xi_i)}{\xi_i^{\beta+1}} + \frac{o''(\xi_i)}{\xi_i^\beta} \, ,
	\end{align*}
	so that utilizing $\xi_i\geq 1$ we obtain
	\begin{align*}
		\left|\frac{c_2}{c_1}\right| &= \left|\frac{(\fft)''(\xi_i)}{2(\fft)'(\xi_i)}\right| \leq \frac{\beta}{\xi_i} + \left|\frac{o_f''(\xi_i)}{2o_f'(\xi_i)}\right| \leq \beta + \frac{C}{2B},
	\end{align*}
    which ensures
    \begin{align*}
    \textbf{(I)} &= 1+O(\delta\epsilon^{-1}+\epsilon).
    \end{align*}
	Next we bound $\textbf{(II)}$. Note:
	\begin{align*}
		\textbf{(II)} &= 1+ O(\epsilon) \quad\implies\quad \textbf{(II)}^{-1} = 1+ O(\epsilon) \, .
	\end{align*}
	Combining the bounds for $\textbf{(I)}$, $\textbf{(II)}^{-1}$, we obtain:
	\begin{align*}
		\frac{\textbf{(I)}}{\textbf{(II)}} &= \left(1+O(\delta\epsilon^{-1}+\epsilon)\right)\bigl(1+ O(\epsilon)\bigr) = 1 + O(\delta\epsilon^{-1}+\epsilon).
	\end{align*}
	Since the above bounds hold for all $i$, i.e. for all the zeros, and since $\hatk(\omega)=k(\omega)$ since $|\omega-Z_{\fft}|>\delta$, we have from \eqref{equ:initial_formula} that
	\begin{align*}
		\fft_\epsilon(\omega)=(-1)^{\hatk(\omega)}\exp\left(\int_{\hatomega_\epsilon} \frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)}\, d\xi\right) &= \left(1+ O(\delta\epsilon^{-1}+\epsilon)\right)^{k(\omega)}\fft(\omega) .
	\end{align*}
	Utilizing $k(\omega)\leq \omega \leq \hinv$ gives $\left(1+ O(\delta\epsilon^{-1}+\epsilon)\right)^{k(\omega)}=1+ O \bigl(\hinv(\delta\epsilon^{-1}+\epsilon) \bigr)$, i.e. $|\fft_\epsilon(\omega)-f(\omega)| \lesssim \hinv\|f\|_\infty(\delta\epsilon^{-1}+\epsilon)$ for $\delta\epsilon^{-1}+\epsilon \lesssim h$, proving \eqref{equ:error_intermediate}.

    Finally, we check that \eqref{equ:error_intermediate} holds when $\omega \notin \hatomega_\epsilon$, i.e. when there exists an estimated zero $\hatxi_i$ such that $|\omega - \hatxi_i|<\epsilon$. Note by definition of the estimator in \eqref{equ:GeneralizedKotlarskiIntermediate}, we have
    \[ \fft_\epsilon(\omega) = \fft_\epsilon(\hatxi_i^-) \, ,\]
    but since $\hatxi_i^-$ is distance $\epsilon$ from all estimated zeros, we have by the previous analysis that
    \[ |\fft_\epsilon(\hatxi_i^-) - \fft(\hatxi_i^-)| \lesssim \hinv\|f\|_\infty(\delta\epsilon^{-1}+\epsilon)\, . \]
    Furthermore, Taylor expanding $\fft$ about $\omega$ gives
    \[ \fft(\hatxi_i^-)  - \fft(\omega)=(\fft)'(\omega)O(\hatxi_i^- -\omega)=\|f\|_\infty O(\epsilon) \, ,\]
    (see proof of Lemma \ref{PSderivbounds} for last equality). Thus:
    \begin{align*}
        |\fft_\epsilon(\omega)-\fft(\omega)| &= |\fft_\epsilon(\hatxi_i^-) - \fft(\omega)| \\
        &\leq |\fft_\epsilon(\hatxi_i^-) - \fft(\hatxi_i^-)|+|\fft(\hatxi_i^-) - \fft(\omega)| \\
        &\lesssim \hinv\|f\|_\infty(\delta\epsilon^{-1}+\epsilon)\, ,
    \end{align*}
    giving \eqref{equ:error_intermediate}.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:error_from_integrand}]
Recall the estimator
\begin{align*}
\hatfft_\epsilon(\omega) &= (-1)^{\hatk(\omega)}\exp\left(\int_{\hatomega_\epsilon}\frac{\partial_{1} \hatPsi(\xi,\xi)}{\tildePsi(\xi,\xi)} d\xi \right).
\end{align*}
A straightforward modification of Theorem~\ref{thm:FTDeviation} which invokes Assumptions~\ref{assumption:FT_decay} and \ref{assumption:nice_oscillations} to bound terms involving $|\Psi|$ implies that there exist positive universal constants $c_1,c_2$ such that, for any $\tau \ge 1$, it holds with probability at least $1-c_1 e^{-c_2 \tau}$ that
\begin{align}
\label{equ:bound_on_integrand}
	\sup_{\xi \in \hatomega_{\epsilon}}\left|\frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)} - \frac{\partial_{1} \hatPsi(\xi,\xi)}{\tildePsi(\xi,\xi)} \right| &\lesssim 
	\frac{\rho_N h^{-3\beta} }{ \epsilon^3 \|f\|_\infty^2} \, ,
\end{align}
as long as $ \rho_N \lesssim \epsilon^2 \|f\|_\infty^2 h^{2\beta}$, which holds by the assumption on $\rho_N$.
We omit the details for brevity, as the calculation is nearly identical. For notational convenience, define 
    \[E(\xi) := \frac{\partial_{1} \hatPsi(\xi,\xi)}{\tildePsi(\xi,\xi)} -\frac{\partial_{1} \Psi(\xi,\xi)}{\Psi(\xi,\xi)} 
    \] 
    so that
    \begin{align*}
       \hatfft(\omega)  &=  \fft_\epsilon(\omega)\exp\left(\int_{\hatomega_\epsilon}E(\xi)\, d\xi\right).
       \end{align*}
 It follows that
 \begin{align*}
       |\hatfft(\omega) -\fft_\epsilon(\omega)| &\leq |\fft_\epsilon(\omega)|\cdot\left|\exp\left(\int_{\hatomega_\epsilon}E(\xi)\, d\xi\right)-1\right|  \leq 2\|f\|_\infty\left|\int_{\hatomega_\epsilon}E(\xi)\, d\xi\right| \lesssim \frac{\rho_N h^{-3\beta-1} }{ \epsilon^3 \|f\|_\infty}
    \end{align*}
    with probability at least $1-c_1 e^{-c_2 \tau}$,
    where we have utilized $|e^z-1|\leq 2|z|$ for $|z|\leq 1$ for the next to last inequality and \eqref{equ:bound_on_integrand} for the last one. Note $\rho_N \lesssim \epsilon^3 \|f\|^2_\infty h^{3\beta+1}$ guarantees that $|z| = \left| \int_{\hatomega_\epsilon}E(\xi)\, d\xi\right| \leq 1$.
