\subsection{3D Gaussian Splatting Mapping}\label{sec_sub_map}


The proposed system reconstructs the scene by 3DGS, utilizing a collection of anisotropic 3D Gaussians, represented by $\mathcal{G}$.
Each 3D Gaussian $i$ contains the properties of mean $\bm \mu^{[i]}_\mathcal{W}$ and covariance $\bm \Sigma^{[i]}_\mathcal{W}$, representing the geometrical position and ellipsoidal shape in the world frame $\mathcal{W}$, and also optical properties including color $c^{[i]}$ and opacity $\alpha^{[i]}$. 
By splatting and blending a series of ordered Gaussians $\mathcal{N}$, the color ${C}^{[j]}$ and depth ${D}^{[j]}$ for each pixel are synthesized as
\begin{equation}\label{eq_color_raster}
{C}^{[j]}
= \sum_{i \in\mathcal{N}}{ c^{[i]}T^{[i]} } 
= \sum_{i \in\mathcal{N}}{c^{[i]}\alpha^{[i]} \prod_{n = 1}^{i-1} (1-\alpha^{[n]})}
\end{equation}
\begin{equation}\label{eq_depth_raster}
{D}^{[j]}
= \sum_{i \in\mathcal{N}}{ d^{[i]}T^{[i]} } 
= \sum_{i \in\mathcal{N}}{d^{[i]}\alpha^{[i]} \prod_{n = 1}^{i-1} (1-\alpha^{[n]}) }
\end{equation}
where $d^{[i]}$ represents the distance from camera pose $\bm\sigma$ to the position $\bm \mu^{[i]}_\mathcal{W}$ of Gaussian $i$ along the camera ray. 
We denote
\begin{equation}
T^{[i]}= \alpha^{[i]} \prod_{n = 1}^{i-1} (1-\alpha^{[n]})
\end{equation}
as the cumulative transmittance of Gaussian $i$ along the ray. 

At each reconstruction step, the 3D Gaussians are extended and initialized using the collected RGB-D image and estimated camera pose \cite{Matsuki2024CVPR}. 
Then the Gaussians iteratively optimize both their geometric and optical parameters to represent the captured scene with high visual fidelity.


\subsection{3D Gaussian probability} \label{subsec_3dgs_prob}
% {\color{red} correct $->$ reliable}

To model the information obtained from the 3DGS map $\mathcal{G}$ by a random observation $z$, we first construct a random variable $r$ for each Gaussian.
As we are going to optimize the rendering result, we define the probability of a 3D Gaussian $i$ is \textit{reliable} for rendering as $P(r^{[i]}) \in(0,1)$. 
Then, the probability of the 3D Gaussian $i$ is \textit{unreliable} for rendering is $P(\bar r^{[i]}) = 1-P(r^{[i]})$. 
Additionally, we denote the odds ratio $o^{[i]}\in(0,+\infty)$ and log odds $l^{[i]}\in(-\infty,+\infty)$ of a Gaussian by
\begin{equation}\label{eq_pol_define}
    l^{[i]} := \log(o^{[i]}) := \log(\frac{ P(r^{[i]}) }{  P(\bar r^{[i]})  })
        = \log(\frac{  P(r^{[i]})  }{  1-P(r^{[i]}) })
\end{equation}


We assume each probability of the 3D Gaussian is independent. 
At the initial stage of the mapping, we assume that the agent has no prior information on the environment, i.e.,
\begin{equation}\label{eq_imple_init_prob} 
    P_0(r^{[i]}) = P_0(\bar r^{[i]}) =0.5
 \quad\forall i\in\mathcal{G}
\end{equation}
Once a new observation $Z_k$ is obtained at time $k$, the standard binary Bayesian filter can be used to update the probability
\begin{equation}
\begin{aligned}    \label{eq_prob_update} 
    o^{[i]} (Z_{1:k}) :&=
    \frac{  P(r^{[i]}|Z_{1:k})  }{  P(\bar r^{[i]}|Z_{1:k})}    
    \\
    & = 
        \frac{P(r^{[i]}|Z_k)}         {P(\bar r^{[i]}|Z_k)} 
        \frac{P(r^{[i]}|Z_{1:k-1})}   {P(\bar r^{[i]}|Z_{1:k-1})}
    \\
    & = \delta^{[i]} (Z_k)    o^{[i]} (Z_{1:k-1})
\end{aligned}
\end{equation}
where $P(r^{[i]}|Z_k)$ is the \textit{reliable} probability of Gaussian $i$ under the observation $Z_k$.
We refer to $P(r^{[i]}|Z_k)$ as the inverse sensor model, thereby $\delta^{[i]} (Z_k)$ is the odds ratio of the inverse sensor model, which will be constructed and used for updating the \textit{reliable} probability $P(r^{[i]}|Z_{1:k})$. 
% In the remainder of this section, we use $o^{[i]}_{1:k}$ as a shorthand of $o^{[i]} (Z_{1:k})$, referring to the odds ratio for Gaussian $i$ based on the observations from start to time $k$. 
We further use $o^{[i]}_{1:k}$ and $l^{[i]}_{1:k}$ as a shorthand of $o^{[i]} (Z_{1:k})$ and $l^{[i]} (Z_{1:k})$ respectively, referring to the odds ratio for Gaussian $i$ based on the observations from start to time $k$. 


Given the observation $Z_k$, we construct the $P(r^{[i]}|Z_k)$ as
\begin{equation}    \label{eq_inv_sensor_p}
    P(r^{[i]}|Z_k) = \frac{1}{(\lambda_L L_k)^{\lambda_TT^{[i]}} +1}
\end{equation}
Therefore, the odds ratio of inverse sensor model $\delta^{[i]} (Z_k)$ can be derived as
\begin{equation}    \label{eq_inv_sensor}
    \delta^{[i]} (Z_k) 
        = \frac{  P(r^{[i]}|Z_k)  }{  1- P( r^{[i]}|Z_k)}
        = (\lambda_L L_k)^{-\lambda_TT^{[i]}}
\end{equation}
where $\lambda_L, \lambda_T>0$ are hyperparameters. 
$L_k$ denotes the loss between the observation $Z_k$ and the map, i.e., a loss image between the observed groundtruth image and the rendered image. We compute the loss image by
% $L_k$ is a loss image between the observation $Z_k$ with the 3DGS map, i.e., a loss image between the observed groundtruth image and the rendered image. We compute the loss image by
\begin{equation}    \label{eq_loss_image}
    L_k = \lambda_c\|C-\hat{C}_k\| + (1-\lambda_c)\|D-\hat{D}_k\|
\end{equation}
where $C, D$ denote the rendered color and depth images from the reconstructed 3DGS map, $\hat{C}_k$, $\hat{D}_k$ are the groundtruth color and depth images from observation $Z_k$.

As the 3DGS map optimizes the Gaussians by minimizing the image loss, we use this loss to construct the inverse sensor model, and the cumulative transmittance to regulate the update rate. 
We further visualize the inverse sensor model \eqref{eq_inv_sensor_p}\eqref{eq_inv_sensor} in Figure~\ref{fig_prob_model} to illustrate the probability update. 
The Gaussians associated with observation $Z_k$ have $T^{[i]}>0$, resulting in the inverse sensor model $P(r^{[i]}|Z_k)$ and $\delta^{[i]} (Z_k)$ being monotonically decreasing with loss $L_k$. 
This suggests that lower loss $L_k$ corresponds to a higher \textit{reliable} probability of Gaussian $P(r^{[i]}|Z_k)$. 
Additionally, a lower cumulative transmittance $T^{[i]}$ implies less impact of Gaussian $i$ on observation $Z_k$. 
Consequently, a smaller $T^{[i]}$ results in less observed information within the inverse sensor model, e.g., when $T^{[i]}=0$, we have $P(r^{[i]}|Z_k)=0.5$ and $\delta^{[i]}(Z_k)=1$.

\begin{figure}[t] 
    \centering
    \includegraphics[width=\linewidth]{plot_prob_model_v3-eps-converted-to.pdf}
    \caption{
        Inverse sensor model visualization.
        The hyperparameters $\lambda$ are omitted in the figure for simplicity.
    }
    \label{fig_prob_model}
\end{figure}

To accelerate computation, in implementation, we update the probability $P(r^{[i]}|Z_{1:k})$ by computing log odds $l_{1:k}^{[i]}$.
Take $\log$ of \eqref{eq_prob_update} and substitute \eqref{eq_inv_sensor},
\begin{equation}\label{eq_imple_update_prob} 
    l_{1:k}^{[i]} = 
    -\lambda_TT^{[i]}\log{\lambda_L L_k}    +
    l_{1:k-1}^{[i]}
\end{equation}
Therefore, the log odds of inverse sensor model can be computed by rasterizing the mapping loss $L_k$ as \eqref{eq_color_raster}.
% At each observation step, we compute the mapping loss $L_k$ and rasterize it as \eqref{eq_color_raster}
The probability update algorithm is summarized in Algorithm~\ref{alg_prob_update}.



\begin{algorithm}[t]
\caption{Probability Update}\label{alg_prob_update}

\begin{algorithmic}[1]
\Require 3DGS map $\mathcal{G}$; Observations $\hat{C}_k, \hat{D}_k$ from $\bm\sigma_k$
    \State $\mathcal{N} \gets \mathtt{SortGaussians} (\bm\mu, \bm\sigma_k)$
    \State $C, D \gets\mathtt{ImageRender} (c, \alpha, \bm\mu, \mathcal{N})$
    \State $L_k = \lambda_c||C-\hat{C}_k|| + (1-\lambda_c)||D-\hat{D}_k||$  \Comment{Loss image}
    \State $l_k =0$
    \For {$j \gets  1$ \textnormal{to} $n_z$}              \Comment{Per pixel}
        \State $T^{[j]} = 1$
        \For {$i \gets 1$ \textnormal{to} $\mathcal{N}^{[j]}$}      \Comment{Per gaussian}
            \State $T^{[i]} =  \alpha^{[i]}T^{[j]}$             \Comment{Gaussian's transmittance}
            \State $l_k^{[i]} \mathrel{{-}{=}} \lambda_TT^{[i]}\log{\lambda_L L_k^{[j]}}$ \Comment{Log odds of \eqref{eq_inv_sensor_p}}
            \State $T^{[j]} =  (1-\alpha^{[i]})T^{[j]}$         \Comment{Update pixel transmittance}
        \EndFor
    \EndFor
    \State $l_{1:k} = l_k+ l_{1:k-1} $
    \State $P_{1:k} \gets \mathtt{InvertLogodds} (l_{1:k})$        \Comment{Update probability}
    \State \textbf{return} $P_{1:k}$
\end{algorithmic}
\end{algorithm}



\subsection{Gaussian Splatting Shannon Mutual Information }\label{subsec_GSSMI}
Based on the proposed probability model and Shannon Mutual Information theory, we then construct the Gaussian Splatting Shannon mutual information (GauSS-MI) for visual quality assessment of novel viewpoints.

% \subsubsection{Shannon Mutual Information}
Given the previous observations $Z_{1:k-1}$, we are interested in minimizing the expected uncertainty, i.e., conditional entropy, of the map after receiving the agent's next observation $z_k$. 
In information theory, the conditional entropy relates to Mutual Information (MI) by 
\begin{equation}\label{eq_Ent_MI_full}
    H(r|z_{k}, Z_{1:k-1}) = H(r|Z_{1:k-1}) - I(r; z_{k}|Z_{1:k-1})
\end{equation}
To minimize the conditional entropy $H(r|z_{k}, Z_{1:k-1})$ is to maximize the MI $I(r; z_{k}|Z_{1:k-1})$. 
Note here that we use $z_k$ and $Z_k$ to distinguish random variable and realized variable for the observation at time $k$. 

As we assume that the previous observations $Z_{1:k-1}$ are given and try to compute the MI for the new observation $z_k$,
in the subsequent of this subsection, we omit the probability condition $Z_{1:k-1}$ and simplify $z_k$ into $z$.
Therefore, the \eqref{eq_Ent_MI_full} can be simplified as
\begin{equation}\label{eq_Ent_MI_simp}
    H(r|z) = H(r) - I(r; z)
\end{equation}

As $z$ is a random variable with independence among elements, the total MI can be expressed as the summation of $ I(r ; z^{[j]})$ between $z^{[j]}$ over all measurement beams $j\in\{1,\cdots,n_z \}$ \cite{julian2014mutual}.
\begin{equation}\label{eq_I_decomp}
    I(r; z) = \sum_{j=1}^{n_z} I(r ; z^{[j]})
    =\sum_{j=1}^{n_z} 
    \sum_{i \in\mathcal{N}^{[j]}}{
     I(r^{[i]} ; z^{[j]})  T^{[i]}
    }
\end{equation}
Here, the measurement beams $j\in\{1,\cdots,n_z \}$ refer to each picture pixel. 
% where $\mathcal{N}^{[j]}$ denotes the set of Gaussians that can be seen in the beam $z^{[j]}$.

From information theory \cite{cover1991information, julian2014mutual}, the mutual information between two random variables is defined and can be organized as
\begin{equation}
\begin{aligned}    \label{eq_MI_definition} 
    I(r^{[i]} &; z^{[j]})   
\\ :=&
    P(r^{[i]}, z^{[j]}=Z) 
    \log(\frac  { P(r^{[i]}, z^{[j]}=Z )  }
                { P(r^{[i]} )  
                    P(z^{[j]}=Z  ) } )
\\ = &
    P(z^{[j]}=Z)
% \\  &
    P(r^{[i]}|z^{[j]}=Z  )
    \log(\frac{ P(r^{[i]}|z^{[j]}=Z) }
                { P(r^{[i]} )  } )
\\ = &
    P(z^{[j]}=Z)f(\delta^{[i]}(Z), o^{[i]}_{1:k-1})
\end{aligned}
\end{equation}
where $P(z^{[j]}=Z)$ is only related to the observation, which is referred to as the measurement prior. 
% $f(\delta^{[i]}(z), o_{k-1}^{[i]})$ 
$f(\delta^{[i]}(Z), o^{[i]}_{1:k-1})$ 
can be derived and written in shorthand as
\begin{equation}    \label{eq_info_gain}
    f(\delta, o) = 
    \frac{ o }{o+\delta^{-1}} 
    \log(\frac{o+1}{o+\delta^{-1}}) 
\end{equation}
The detailed derivation is presented in the Appendix~\ref{apn_sec_infogainf}. 
The function $f(\delta, o)$ can be interpreted as an information gain function.



We define the mutual information \eqref{eq_MI_definition} between the 3DGS map and the observation as Gaussian Splatting Shannon Mutual Information, GauSS-MI.


\subsection{Computation of Expected GauSS-MI}
We further derive the computation of the expected mutual information \eqref{eq_MI_definition} for random viewpoints. 

\subsubsection{Measurement prior}
% For the measurement prior probability $P(z)$, 
We refer to the noise model of RGB camera in \cite{foi2008practical}, in which the expectation of the measurement noise is related to luminance.
Thus, we construct the measurement prior $P(z)$ for each pixel $j$ as
% As our measurement sensor is the RGB camera, the measurement beams $j\in\{1,\cdots,n_z \}$ refer to each picture pixel. 
% The measurement prior for each pixel $j$ can be expressed as functions of the sensor model \cite{foi2008practical}.
\begin{equation}    \label{eq_measure_prior}
    P(z^{[j]} ) = \sum_{m^{[j]}=0}^{255} P(z^{[j]}|m^{[j]})P(m^{[j]})
\end{equation}
% \begin{equation}    
%     P(z^{[j]} ) = P(z^{[j]}|j)P(j)
% \end{equation}
where $P(z^{[j]}|m^{[j]})$ is the prior probability distribution of the sensor with respect to luminance $m\in\{0,\cdots,255\}$.
To compute the expected measurement prior, we define $P(m^{[j]})$ as
\begin{equation}
P(m^{[j]}) =
\begin{cases}
    1   & \text{for}\, m^{[j]}=M^{[j]} \\
    0   & \text{otherwise}
\end{cases}
\end{equation}
where $M^{[j]}$ is the pixel's expected luminance, which can be computed from the expected RGB color $(R, G, B)$ by the luminance formula $M = 0.299R + 0.587G + 0.114B$.
Thus the measurement prior \eqref{eq_measure_prior} can be simplified as
\begin{equation}\label{eq_exp_pz}
    P(z^{[j]} ) =  P(z^{[j]}|M^{[j]})
\end{equation}

\subsubsection{Information gain function}


As there are no observations from random viewpoints, computing the loss image $L_k$ for $\delta(Z_k)$ is infeasible; thus, an expectation of $L_k$ is required.
We expect that the rendering result after reconstruction is \textit{reliable}, i.e., there is no loss between groundtruth and the 3DGS map $\mathcal{G}$. 
Thus, we assume $L_k=0$ so that $\delta^{-1}=0$ in $f(\delta,o)$.
Then the information gain function \eqref{eq_info_gain} can be derived as,
\begin{equation}    \label{eq_info_gain_comp}
    f^{[i]}
    = \log(  \frac{o^{[i]}+1}{o^{[i]}}  ) 
    = -\log(  P(r^{[i]}))
\end{equation}
The equation shows that when the \textit{reliable} probability $P(r^{[i]})$ is low, the information gain function $f$ will be high, consistent with the intuition of information gain.


Overall, integrating \eqref{eq_I_decomp}\eqref{eq_MI_definition}\eqref{eq_exp_pz}\eqref{eq_info_gain_comp}, the expected GauSS-MI can be computed as
\begin{equation}
\begin{aligned}    \label{eq_MI_compute} 
    I(r; z) = &
    \sum_{j=1}^{n_z} 
    \sum_{i \in\mathcal{N}^{[j]}}{
     I(r^{[i]} ; z^{[j]})  T^{[i]}
    }
\\ = &
    \sum_{j=1}^{n_z} P(z^{[j]}|M^{[j]})
    \sum_{i \in\mathcal{N}^{[j]}}{ f^{[i]} T^{[i]} }
\\ = &
    \sum_{j=1}^{n_z} P(z^{[j]}|M^{[j]})
    \sum_{i \in\mathcal{N}^{[j]}}{  - T^{[i]}\log(  P(r^{[i]}))}
\end{aligned}
\end{equation}
The computation procedure of GauSS-MI is summarized in Algorithm~\ref{alg_mutual_info}.

\begin{algorithm}[t]
\caption{GauSS-MI}
% \caption{Gaussian Splatting Shannon Mutual Information}
\label{alg_mutual_info}

\begin{algorithmic}[1]
\Require 3DGS map $\mathcal{G}$; Novel view $\bm\sigma$

    \State $I=0$
    \State $\mathcal{N} \gets \mathtt{SortGaussians} (\bm\mu, \bm\sigma)$
    \For {$j \gets  1$ \textnormal{to} $n_z$}              \Comment{Per pixel}
        \State // Rasterize color and $f$  \eqref{eq_info_gain_comp} on each pixel
        \State ${C}^{[j]} = 0$; $f^{[j]} = 0$; $T^{[j]} = 1$
        % \State $f^{[j]} = 0$
        % \State $T^{[j]} = 1$
        \For {$i \gets 1$ \textnormal{to} $\mathcal{N}^{[j]}$}  \Comment{Per gaussian}
            \State $T^{[i]} =  \alpha^{[i]}T^{[j]}$             \Comment{Gaussian's transmittance}
            \State ${C}^{[j]} \mathrel{{+}{=}} c^{[i]}T^{[i]}$                \Comment{Rasterize color}
            \State $f^{[j]} \mathrel{{-}{=}} \log(P^{[i]})T^{[i]}$            \Comment{Rasterize \eqref{eq_info_gain_comp}}
            \State $T^{[j]} =  (1-\alpha^{[i]})T^{[j]}$         \Comment{Update pixel transmittance}
        \EndFor
        \State $M^{[j]} \gets \mathtt{Color2Luminance} ({C}^{[j]})$
        \State $P(z^{[j]} | M^{[j]}) \gets \mathtt{SensorModel} (M^{[j]})$
        \State $I \mathrel{{+}{=}}P(z^{[j]} | M^{[j]}) f^{[j]}$               \Comment{Update MI}
    \EndFor
    \State \textbf{return} $I$
\end{algorithmic}
\end{algorithm}

