\subsection{View Planning}
\label{sec_viewplanner}



\subsubsection{Viewpoint Primitive Library}\label{sec_vpll}

% To determine the next best viewpoint, we design a viewpoint candidates generation library and choose the next best view within the library. 
To determine the next best viewpoint, we design an action library to generate a set of candidate viewpoints, and choose the next best view within the candidates. % \mathcal{A} -> \mathcal{sigma} - > the best sigma %
Inspired by the action generation method proposed in \cite{yang2017framework}, we design the action to the next viewpoint by
%each candidate viewpoint can be derived by an action
%we design the viewpoint library by sampling the action 
$$\bm \alpha=[v_{\rm xy}, v_{\rm z}, \omega_{\rm z}]$$
where $v_{\rm xy}$ and $v_{\rm z}$ represent the body frame linear velocity in ${\rm x}_\mathcal{B} - {\rm y}_\mathcal{B}$ plane and ${\rm z}_\mathcal{B}$ direction, 
%the horizontal linear velocity and vertical linear velocity in the body frame, 
and $\omega_{\rm z}$ is the body frame angular velocity around the ${\rm z}_\mathcal{B}$ axis. 
We simplify the action of 2-dimensional horizontal movement into 1 dimension, which can be compensated through the $\omega_{\rm z}$ rotation.
% The action space is given by uniformly sampled under the customized maximum velocity bounds
The action space is given by sampling each velocity that,
\begin{equation}
    \mathcal{A} = \{
        \bm \alpha| v_{\rm xy}\in \mathcal{V}_{\rm xy},  
        v_{\rm z}\in\mathcal{V}_{\rm z}, 
        \omega_{\rm z}\in{\Omega_{\rm z}} \}
\end{equation}


%% generate the viewpoint
In this paper, we assume that the sensor, normally with a limited field of view, is equipped forward, i.e., facing the ${\rm x}_\mathcal{B}$ axis. 
Thus, in the further forward propagation derivation, we design the horizontal movement action $v_{\rm xy}$ works on the ${\rm y}_\mathcal{B}$ axis. 

Given the action 
$\bm \alpha=[v_{\rm xy}, v_{\rm z}, \omega_{\rm z}] \in\mathcal{A}$
%$\bm \alpha^k=[v_{\rm xy}^k, v_{\rm z}^k, \omega_{\rm z}^k] \in\mathcal{A}$
, the next viewpoint is designed by forward propagation with duration time $T$, 
\begin{equation}\label{eq_viewpoint_i}
\begin{split}
    \bm\sigma_f &= \bm\sigma_0 +
    \begin{bmatrix}
        - v_{\rm xy} T\sin{(\psi_0+ \omega_{\rm z}  T)}
        \\ 
        v_{\rm xy}  T  \cos{(\psi_0+ \omega_{\rm z}  T)}
        \\
        v_{\rm z} T
        \\
        \omega_{\rm z}  T
    \end{bmatrix} 
\\
    \bm\sigma^{(n)}_f &= \bm 0 \quad  {\rm for}\,\, n=1,2,3
\end{split}
\end{equation}
where ${(\cdot)}^{(n)}$ denotes the $n$-th derivatives, which constraints the final state to ensure a stable picture taking on the next viewpoint.
A motion primitive trajectory $\bm\sigma_T$ from current state $\bm\sigma(t) = \bm\sigma_0$ to the next viewpoint $\bm\sigma(t+T) = \bm\sigma_f$ can be derived in closed-form \cite{mueller2015computationally} (detailed in the Appendix~\ref{apd_sec_minsnap_planner}). 


Overall, by defining the set of actions $\mathcal{A}$, given the current state $\bm\sigma_0$, a library of candidate viewpoints $\bm\Sigma_f=\{\bm\sigma_f \}$ along with the primitive trajectories $\bm\Sigma_T=\{\bm\sigma_T\}$ can be formed as a viewpoint primitive library. 

\subsubsection{Next Best View Selection}
\label{sec_nbv_select}

The total reward for the next best view evaluation includes the mutual information $I$ \eqref{eq_MI_compute} and the motion cost $J$ as
\begin{equation}
    \label{eq_nbv_reward}
    R = w_II-w_JJ
\end{equation}
where $w_I, w_J>0$ are constant reward weights to balance the range of two components. 
The motion cost $J$ can be calculated based on the trajectory $\bm\sigma_T$ with respect to a specific mobile robot. 
The next best view with primitive $\bm\sigma^{*}_T$ is selected by optimizing $R$ over all feasible primitives, which is then assigned to the controller for tracking.
The complete procedure for view and motion planning is summarized in Algorithm~\ref{alg_viewplanner}. 



\begin{algorithm}[t]
\caption{View and Motion Planner}
\label{alg_viewplanner}

\begin{algorithmic}[1]
\Require Full Quadrotor States $\mathcal{X}(t)$; Action Space $\mathcal{A}$

    \State $R=0$
    \For {$\bm \alpha \in \mathcal{A}$}              %\Comment{Per pixel}
        \State $\bm \sigma (t+T)\gets \mathtt{ForwardPropagate}(\bm\sigma(t)$,$ \bm \alpha)$
        \State $\bm\sigma_T \gets \mathtt{MotionPrimitive}(\mathcal{X}(t)$,$\bm \sigma (t+T))$

        \If{$\mathtt{SafetyCheck}(\bm\sigma_T)$}
            \State $I\gets \mathtt{GauSS\_MI} (\bm\sigma (t+T))$ \Comment{Algorithm\ref{alg_mutual_info}}
            \State $J\gets \mathtt{MotionCost} (\bm\sigma_T)$

            \If{$R<w_II-w_JJ$}
                \State ${R}=w_II-w_JJ$
                \State $\bm\sigma ^*_T=\bm\sigma _T$
            \EndIf
        \EndIf
    \EndFor
    \State \textbf{return} $\bm\sigma^*_T$
\end{algorithmic}
\end{algorithm}

