\subsection {Information Gain Function Derivation}
\label{apn_sec_infogainf}

The information gain function $f(\delta(Z), o_{1:k-1})$ is defined by \eqref{eq_MI_definition} that, 
\begin{equation}
\begin{aligned}
\label{eq_apn_info_gain_define} 
f(\delta&(Z), o_{1:k-1}) = \\
    &P(r|z_k=Z,Z_{1:k-1} )
    \log(\frac{ P(r|z_k=Z,Z_{1:k-1}) }
                { P(r |Z_{1:k-1})  } )
\end{aligned}
\end{equation}
Based on the definition of $o_{1:k-1}$ in \eqref{eq_pol_define}, we have
\begin{equation}\label{eq_apn_pzk_1}
P(r |Z_{1:k-1}) = \frac{ 1+o_{1:k-1} }
                { o_{1:k-1}  }
\end{equation}
Substitute the probability update \eqref{eq_prob_update} into \eqref{eq_apn_pzk_1}, we can derive
\begin{equation}\label{eq_apn_pzk}
P(r |z_k=Z, Z_{1:k-1}) = \frac{ 1+\delta(Z)o_{1:k-1} }
                { \delta(Z)o_{1:k-1}  }
\end{equation}
Substitute \eqref{eq_apn_pzk_1} and \eqref{eq_apn_pzk} into \eqref{eq_apn_info_gain_define},
the information gain function can be derived and simplified as,
\begin{equation}    \label{eq_apn_reward_func_f}
    f(\delta, o) = 
    \frac{ o }{o+\delta^{-1}} 
    \log(\frac{o+1}{o+\delta^{-1}}) 
\end{equation}



