%% any flat output can be followed, 
As quadrotor dynamics has been demonstrated differentially flat \cite{mellinger2011minimum}, any smooth trajectory with physically bounded derivatives in the space of flat outputs can be followed by the under-actuated quadrotor. 
%Considering the aim of the planning viewpoint,
Aiming at view planning, we choose the flat outputs as $\bm\sigma= [x, y, z, \psi]^T$, which includes the drone's position $\bm p=(x, y, z)$ and yaw $\psi$. 
Then, the full quadrotor states $\mathcal{X}$ can be expressed by the algebraic functions of flat outputs and their derivatives that
% $\mathcal{X}_f=[p_f,v_f,a_f,j_f]^T$
\begin{equation}\label{eq_quad_full_state}
	\mathcal{X} %% the \psi, \dot\psi here maybe confusing
		=  [\bm p, {\bm v}, {\bm a}, {\bm j}, \psi, \dot\psi]
		%:= [\bm p, \dot{\bm p}, \bm p^{(2)}, \bm p^{(3)}, \psi, \dot\psi] 
\end{equation}
where the velocity $\bm v$, acceleration $\bm a$, jerk $\bm j$ are derivatives of position $\bm p$.

As the control input, thrust and torque, can be formulated by at-most the fourth derivatives, we design trajectories that minimize the snap $\bm s$, %${\bm s}:={\bm p}^{(4)}$,
\begin{equation}
\begin{aligned}
    \label{apd_eq_min_snap_problem}
    \min \quad 
    &\frac{1}{T}\int^T_0||{\bm s(t)}||^2 dt\\
    \textrm{s.t.} \quad
    &\mathcal{X}(t) = \mathcal{X}_0\\
    &\mathcal{X}(t+T) = \mathcal{X}_f
\end{aligned}
\end{equation}
where $\mathcal{X}_0$ and $\mathcal{X}_f$ represent the initial state and final state respectively. %, $\mathcal{X}(t)$ and $\mathcal{X}(t+T)$ denotes the current state and objective state with duration time $T$. 


%% trajectory generation
To efficiently generate the trajectory from current state to the next viewpoint, %we employ the closed-form motion primitives\cite{mueller2015computationally}. 
we extend the result of the work \cite{mueller2015computationally} and derive the closed-form minimum-snap primitives. 
The optimal trajectory generation problem \eqref{apd_eq_min_snap_problem} can be decoupled into three orthogonal axes that,
% The cost of each primitive in \eqref{apd_eq_min_snap_problem} can be decoupled into three orthogonal axes.
\begin{equation}
    \label{apd_eq_motion_cost}
    J = \frac{1}{T}\int^T_0||{\bm s(t)}||^2 dt 
    = \sum_{k\in\{x,y,z\}} \frac{1}{T}\int^T_0s_k^2(t) dt
\end{equation}
The axis subscript $k$ for vectors will be simplified for the remainder of this section.
Employing Pontryagin’s minimum principle, the optimal control input for each axis can be solved for,
\begin{equation}\label{apd_eq_min_s}
	{ s}^*(t)=%\frac{1}{2}{\eta_1} t^3 +\frac{3}{2}{\eta_2} t^2 + 3{\eta_3} t +3{\eta_4}
    \frac{1}{2}\alpha t^3 +\frac{3}{2}\beta t^2 + 3\gamma t +3\delta
\end{equation}
from which the optimal position for each axis follows from integration,
\begin{equation}\label{apd_eq_prim_p}
\begin{split}
    p^*(t)= &\frac{1}{1680}\alpha t^7 +\frac{1}{240}\beta t^6 + \frac{1}{40}\gamma t^5 +\frac{1}{8}\delta t^4 \\&+\frac{1}{6}j_0t^3+\frac{1}{2}a_0t^2+v_0t+p_0\\
\end{split}
\end{equation}
% where velocity $ v:=\dot{ p}$, acceleration $ a :=  p^{(2)}$, jerk $ j:= p^{(3)}$ are derivatives of position $ p$; the subscript $0$ refers to the starting state. 
The minimum cost for each axis can be derived by substituting optimal snap \eqref{apd_eq_min_s} into \eqref{apd_eq_min_snap_problem},
\begin{equation}
\label{eq_cost}
\begin{split}
    J_k =& \frac{1}{28}\alpha^2T^6+\frac{1}{4}\alpha\beta T^5 +(\frac{9}{20}\beta^2+\frac{3}{5}\alpha\gamma)T^4 \\
    &+(\frac{3}{4}\alpha\delta+\frac{9}{4}\beta\gamma)T^3 +(3\gamma^2+3\beta\delta)T^2 
    \\&+9\gamma\delta T +9\delta^2
\end{split}
\end{equation}
The constant coefficients $\alpha$, $\beta$, $\gamma$ and $\delta$ can be expressed by algebraic functions of initial state $\mathcal{X}_0$ and final state $\mathcal{X}_f$ as
\begin{equation}\label{eq_apn_abcd_1111}
\setlength{\arraycolsep}{1.0pt}
    \begin{bmatrix}
        \alpha \\ \beta \\ \gamma \\ \delta
    \end{bmatrix}
    =
    \frac{1}{T^7}
    \begin{bmatrix}
        -33600 &  16800T  & -3360T^2 & 280T^3\\
        16800T & -8160T^2 &  1560T^3 & -120T^4\\
        -3360T^2 & 1560T^3 & -280T^4 & 20T^5\\
        280T^3 & -120T^4 &  20T^5 & -\frac{4}{3}T^6
    \end{bmatrix} 
    \begin{bmatrix}
        \Delta p \\ \Delta v \\ \Delta a \\ \Delta j
    \end{bmatrix}
\end{equation}
where the constants $\Delta p$, $\Delta v$, $\Delta a$, $\Delta j$ are defined as,
\begin{equation}\label{eq_apn_delta_pvaj}
    \begin{bmatrix}
        \Delta p \\ \Delta v \\ \Delta a \\ \Delta j
    \end{bmatrix} =
    \begin{bmatrix}
        p_f - p_0 - v_0T -\frac{1}{2}a_0T^2 -\frac{1}{6}j_0T^3\\
        v_f - v_0 - a_0T - \frac{1}{2}j_0T^2\\
        a_f - a_0 - j_0T\\
        j_f - j_0
    \end{bmatrix} 
\end{equation}
Therefore, given the current state $\mathcal{X}_0$ and the desired state $\mathcal{X}_f$, the optimal motion primitive and control input for the fully defined end state can be solved by \eqref{apd_eq_min_s}\eqref{apd_eq_prim_p}\eqref{eq_apn_abcd_1111}\eqref{eq_apn_delta_pvaj}.





