\section{Basics on Languages}

This section introduces notation for manipulating words and languages.\\

Let $\omega = \{0,1,\ldots\}$ be the first infinite ordinal, identified with $\N$. Let $\Sigma$ be a set called the \emph{alphabet}. Let $\Sigma^* = \bigcup_{n \in \omega} \Sigma^n$ be the set of finite words on $\Sigma$, $\Sigma^\omega$ be the set of infinite words on $\Sigma$, and $\Sigma^\infty = \Sigma^* + \Sigma^\omega = \bigcup_{\alpha \in \omega + 1} \Sigma^\alpha$ be the set of all words. Letters in a word are numbered starting from $1$. The length of a word $w$ is denoted by $|w|$, defining a length map $|-| : \Sigma^\infty \to \omega + 1$. Words will be typically written
\begin{align*}
     & w = w_1 w_2 \ldots w_n & \text{if } w \in \Sigma^n      & \text{ i.e. } |w| = n      \\
     & w = w_1 w_2 \ldots     & \text{if } w \in \Sigma^\omega & \text{ i.e. } |w| = \omega
\end{align*}
There is a unique word of length $0$ called the empty word and denoted by $\varepsilon$. Words of length $1$ and letters are identified, i.e., $\Sigma^1 \cong \Sigma$.


\paragraph{Concatenation.}
Concatenation of words has type $\Sigma^\infty \times \Sigma^\infty \to \Sigma^\infty$ and is denoted by juxtaposition. With the convention that left-concatenating an infinite word overwrites whatever is on the right, concatenation is associative with neutral element $\varepsilon$. For instance, $a^\omega b^\omega = a^\omega$. Fixing the first argument $u \in \Sigma^\infty$ yields a map $u : \Sigma^{\infty} \to \Sigma^\infty$. Applying covariant and contravariant powerset to this map generates
\begin{align*}
    u(\cdot) \colon & P(\Sigma^\infty) \to P(\Sigma^\infty) & u^{-1}(\cdot) \colon & P(\Sigma^\infty) \to P(\Sigma^\infty)           \\
                    & L \mapsto \{uv \mid v \in L\}         &                      & L \mapsto \{v \in \Sigma^\infty \mid uv \in L\}
\end{align*}
Note that these maps are degenerate when $u$ is an infinite word, as in that case $uL = \{u\}$ if $L \neq \emptyset$, $\emptyset$ else and $u^{-1}L = \Sigma^\infty$ if $u \in L$, $\emptyset$ else.
\begin{proposition}
    For all $u, v \in \Sigma^\infty$ and $L \in P(\Sigma^\infty)$
    \begin{enumerate}
        \item $u(vL) = (uv)L$
        \item $u^{-1}(v^{-1}L) = (vu)^{-1}L$
        \item $uu^{-1}L = L \cap u\Sigma^\infty$
        \item $u^{-1}uL = L$ if $u \in \Sigma^*$, $\emptyset$ if $L = \emptyset$, $\Sigma^\infty$ else
    \end{enumerate}
\end{proposition}
\begin{proof} Sketch:
    \begin{enumerate}
        \item This is functoriality of the covariant powerset.
        \item This is functoriality of the contravariant powerset.
        \item We have $uu^{-1}L = \{uv \mid uv \in L\} = L \cap u\Sigma^\infty$.
        \item We have $u^{-1}uL = \{v \in \Sigma^\infty \mid uv \in uL\}$. If $u \in \Sigma^*$, $uv \in uL \iff v \in L$ whence the result, else and if $L \neq \emptyset$, $uv \in uL \iff u \in \{u\}$ whence the result.
    \end{enumerate}
\end{proof}

Concatenation of languages $P(\Sigma^\infty) \times P(\Sigma^\infty) \to P(\Sigma^\infty)$ is also denoted by juxtaposition.

\paragraph{Restriction and Co-Restriction.}

The restriction of a word $w  \in \Sigma^\infty$ to a finite length $n \in \omega$ is defined by $w_{\mid n} = w_1 w_2 \ldots w_n$ if $n \leq |w|$, $w_{\mid n} = w$ else. For instance, $w_{|0} = \varepsilon$ is the empty word. The co-restriction of a word $w \in \Sigma^\infty$ to a finite length $n \in \omega$ is the unique word $w^{\mid n} \in \Sigma^\infty$ such that $w = w_{\mid n} w^{\mid n}$. For instance, $w^{\mid 0} = w$ and $w^{\mid n} = \varepsilon$ for any $n \geq |w|$. Note that $w^{\mid n} = w_{n+1} w_{n+2} \ldots$ for infinite words. Furthermore, for every $w \in \Sigma^\infty$ and $p,q \in \omega$ the equality
$w_{\mid p+q} = w_{\mid p} (w^{\mid p})_{\mid q}$ holds.

\paragraph{Prefixing.}

The map $\Pref : \Sigma^\infty \to P(\Sigma^*)$ assigns to a word the set of its finite prefixes, i.e., $\Pref(w) = \{w_{\mid n} \mid n \in \omega\}$. It is extended to $\Pref : P(\Sigma^\infty) \to P(\Sigma^*)$ by union. We have
\[ \Pref(L) = \{w_{\mid n} \mid w \in L, n \in \omega\} = \{u \in \Sigma^* \mid L \cap u\Sigma^\infty \neq \emptyset \} \]

\begin{proposition}
    For any $L, M \in P(\Sigma^\infty)$,
    \begin{enumerate}
        \item $L \cap \Sigma^* \subseteq \Pref(L)$
        \item $L \subseteq M \Rightarrow \Pref(L) \subseteq \Pref(M)$
        \item $\Pref(\Pref(L)) = \Pref(L)$
        \item $\Pref(LM) = \Pref(L) \cup L\Pref(M)$ if $M \neq \emptyset$
    \end{enumerate}
\end{proposition}
\begin{proof} The first three statements are obvious. Note that this makes the restriction $\Pref : P(\Sigma^*) \to P(\Sigma^*)$ a closure operator. For the last one:
    \begin{enumerate}
        \item[4.] A prefix of a word in $LM$ is either a prefix of a word in $L$, or a word in $L$ then a prefix of a word in $M$, and conversely because $M$ is non-empty.
    \end{enumerate}
\end{proof}

\begin{example}[The binary alphabet]
    The \emph{binary alphabet} is $\Sigma = \{a,b\}$ where $a$ is interpreted as 'going left' and $b$ as 'going right'. The map $(-)^\perp : \Sigma \to \Sigma$ reverses directions as $a \mapsto b$ and $b \mapsto a$. It is extended letterwise to a map $(-)^\perp : \Sigma^\infty \to \Sigma^\infty$, for instance $(abba)^\perp = baab$.
\end{example}

\section{Basics on Trees}

This section introduces trees as they are usually defined in descriptive set theory. These trees can have finite or infinite depth, and they can have finite or infinite width depending on the alphabet $\Sigma$.\\

A language $L \in P(\Sigma^\infty)$ is \emph{prefix-closed} if $\Pref(L) = L$.

\begin{definition}[Tree]
    A \emph{tree} is a prefix-closed subset of $\Sigma^*$. The set of trees over $\Sigma$ is denoted by $T(\Sigma)$.
\end{definition}

\begin{proposition}
    The image of $\Pref : P(\Sigma^\infty) \to P(\Sigma^*)$ is $T(\Sigma)$.
\end{proposition}
\begin{proof}
    As $\Pref(\Pref(L)) = \Pref(L)$, the image is included in $T(\Sigma)$. Conversely, let $L \subseteq \Sigma^*$ be prefix-closed, then $L = \Pref(L)$ is in the image of $\Pref$.
\end{proof}

\begin{definition}
    Given a tree $T \in T(\Sigma)$, its set of infinite branches is
    \[ [T] = \{w \in \Sigma^\omega \mid \forall n \in \omega, w_{\mid n} \in T\} = \{w \in \Sigma^\omega \mid \Pref(w) \subseteq T\} \]
\end{definition}

\begin{proposition}
    For a tree $T \in T(\Sigma)$, $[T] = \{w \in \Sigma^\omega \mid \Pref(w) \cap T \text{ is infinite}\}$.
\end{proposition}

\begin{proof}
    We must show that for a tree $T$ and a word $w \in \Sigma^\omega$, $\Pref(w) \subseteq T$ iff $\Pref(w) \cap T$ is infinite. The left-to-right direction is obvious as $\Pref(w)$ is infinite. For the other direction, assume $\Pref(w) \cap T$ is infinite and let $n \in \omega$, we must show $w_{\mid n} \in T$. As $\Pref(w) \cap T$ is infinite, there is $N \geq n$ such that $w_{\mid N}  \in T$. As $T$ is prefix-closed and $n \leq N$, $w_{\mid n} = (w_{\mid N})_{\mid n} \in T$, whence the result.
\end{proof}

\begin{proposition}
    On the binary alphabet, taking infinite branches commutes with reversing directions: $[T^\perp] = [T]^\perp$.
\end{proposition}
\begin{proof}
    Compute
    \begin{align*}
        [T^\perp] & = \{w \in \Sigma^\omega \mid \forall n \in \omega, w_{\mid n} \in T^\perp\}    \\
                  & = \{w \in \Sigma^\omega \mid \forall n \in \omega, w_{\mid n}^\perp \in T\}    \\
                  & = \{w^\perp \mid w \in \Sigma^\omega, \forall n \in \omega, w_{\mid n} \in T\} \\
                  & = [T]^\perp
    \end{align*}
\end{proof}

\begin{proposition}
    Taking infinite branches commutes with taking arbitrary intersections: $[\bigcap_{i \in I} T_i] = \bigcap_{i \in I}[T_i]$.
\end{proposition}
\begin{proof}
    For any $w \in \Sigma^\omega$, $\forall n . \forall i . w_{\mid n} \in T_i \iff \forall i. \forall n . w_{\mid n} \in T_i$.
\end{proof}

\paragraph{Concatenation and Infinite Branches.}

\begin{proposition}
    For any $T \in T(\Sigma)$, $u \in \Sigma^*$, $a \in \Sigma$,
    \begin{enumerate}
        \item $u[T] = [\Pref(u) \cup uT]$
        \item $a[T] = [\{\varepsilon\} \cup aT]$
        \item $u^{-1}[T] = [u^{-1}T]$
    \end{enumerate}
\end{proposition}
\begin{proof}
    Let us prove the statements.
    \begin{enumerate}
        \item First check that $\Pref(u) \cup uT$ is a tree. We can assume $T$ is non-empty. Then $\Pref(uT) = \Pref(u) \cup u\Pref(T) = \Pref(u) \cup uT$ because $T$ is a tree, hence $\Pref(u) \cup uT$ is a tree. Now let us prove the wanted equality by double inclusion. Let $uw \in u[T]$, where $w \in [T]$. Then prefixes of $uw$ are, depending of their length, either in $\Pref(u)$, or in $uT$, so that $uw \in [\Pref(u) \cup uT]$. Conversely, let $w \in [\Pref(u) \cup uT]$. Let $n = |u|$. As $w_{\mid n} \in \Pref(u) \cup uT$ and the only element of length $n$ of that set is $u$ itself, we have $w_{\mid n} = u$. Furthermore, for length reasons $w_{\mid n+m} \in uT$ for every $m \in \omega$, therefore $w^{\mid n} \in [T]$. Whence $w = w_{\mid n} w^{\mid n} = uw^{\mid n} \in u[T]$.
        \item This is a special case of the previous point.
        \item First check that $u^{-1}T$ is a tree. We have
              \begin{align*}
                  \Pref(u^{-1}T) & = \{w_{\mid n} \mid w \in u^{-1}T \text{ and } n \in \omega\} \\
                                 & = \{w_{\mid n} \mid uw \in T \text{ and } n \in \omega\}      \\
                                 & \subseteq \{w \mid uw \in \Pref(T)\}                          \\
                                 & = u^{-1}\Pref(T) = u^{-1}T
              \end{align*}
              Now let us prove the wanted equality by double inclusion. We have
              \begin{align*}
                   & u^{-1}[T] = \{w \mid uw \in [T]\} = \{w \mid \Pref(uw) \subseteq T\}                 \\
                   & [u^{-1}T] = \{w \mid \Pref(w) \subseteq u^{-1}T\} = \{w \mid u\Pref(w) \subseteq T\}
              \end{align*}
              As $\Pref(uw) = \Pref(u) \cup u\Pref(w)$ and $T$ is prefix-closed, $\Pref(uw) \subseteq T$ iff $u\Pref(w) \subseteq T$, whence the result.
    \end{enumerate}
\end{proof}

Note that, given $u \in \Sigma^*$, the map $u^{-1}(\cdot) : T(\Sigma) \to T(\Sigma)$ recovers the sub-tree rooted at the node $u$. In particular
\begin{itemize}
    \item The tree $u^{-1}T$ is the sub-tree rooted at $u$ extracted from $T$.
    \item The language (usually not tree) $uu^{-1}T$ is that sub-tree viewed in its place inside $T$.
    \item The tree $\Pref(u) \cup uu^{-1}T$ is the sub-tree of $T$ given by keeping only the finite branch $u$ and the sub-tree rooted at $u$.
\end{itemize}

\paragraph{Graphical Representations.}
Any tree $T$ has a graphical representation given by drawing the relation $\{(u,ua) \mid u \in \Sigma^*, a \in \Sigma, ua \in T\}$. Unless $T$ is empty, this graph has a root $\varepsilon$ and branches that follow the spelling of words in $T$.

\begin{example}[The hat]
    The hat is the binary tree $H = \Pref(\{a^\omega,b^\omega\}) = \{a^n \mid n \in \omega\} \cup \{b^n \mid n \in \omega\}$. It has exactly two infinite branches, a left one and a right one, as $[H] = \{a^\omega,b^\omega\}$.
    \[
        \tikzfig{hat_tree}
    \]
\end{example}

\begin{example}[The $n$-branches] \label{ex:nbranches}
    We define inductively a family $\{B_n \mid n \in \omega\}$ of binary pruned trees.
    \begin{align*}
         & B_0 = \emptyset                                                        \\
         & B_{n+1} = \bigcup_{k \in \omega} a^k(\{\varepsilon\} \cup b B^\perp_n)
    \end{align*}
    Explicitly, we have $B_1 = \{a^k \mid k \in \omega\}$, $B_2 = \{a^k b^{k'} \mid k, k' \in \omega\}$ and more generally $B_n = \{a^{k_1} b^{k_2} \ldots (b^{\perp^n})^{k_n} \mid k_1, \ldots, k_n \in \omega\}$.
    These trees have the following infinite branches.
    \begin{align*}
         & [B_0] = \emptyset                                                \\
         & [B_1] = \{a^\omega\}                                             \\
         & [B_{n+1}] = \bigcup_{\alpha \in \omega + 1} a^\alpha [B_n]^\perp
    \end{align*}
    Explicitly, $[B_n] = \{a^{\alpha_1} b^{\alpha_2} \ldots (b^{\perp^{n-1}})^{\alpha_{n-1}} (b^{\perp^n})^{\omega} \mid \alpha_1, \ldots, \alpha_{n-1} \in \omega + 1\}$.
    \[ \tikzfig{branching1_tree} \]
    \[ \tikzfig{branching2_tree} \]
\end{example}

\begin{example}[The growing tree] \label{ex:growing}
    The \emph{growing tree} $G$ is defined as
    \begin{equation*}
        G = \bigcup_{k \in \omega} a^k (\{\varepsilon\} \cup b B^\perp_{k+1})
    \end{equation*}
    It consists in plugging all of the non-trivial $n$-branches into a lefmost infinite branch. Its infinite branches are
    \begin{equation*}
        [G] = \{a^k b^{\alpha_1} a^{\alpha_2} \ldots (a^{\perp^k})^{\alpha_k} (a^{\perp^{k+1}})^\omega \mid k \in \omega, \alpha_1, \ldots, \alpha_k \in \omega +1\}
    \end{equation*}
    \[ \tikzfig{growing_tree} \]
\end{example}

\subsection{Construction and Destruction of Trees}

