There are two remarkable viewpoints on a tree: lying down and staring at what is around the root, or climbing along a branch.

\subsubsection{Around the Root}

Destructively speaking, a non-empty tree is the union of the root and its children subtrees.
\begin{proposition}
    For all $T \in T(\Sigma) \setminus \{\emptyset\}$, $T = \{\varepsilon\} \cup \biguplus_{a \in \Sigma} a a^{-1} T$.
\end{proposition}
\begin{proof}
    We have $T = \{\varepsilon\} \cup \biguplus_{a \in \Sigma} (T \cap a\Sigma^*) = \{\varepsilon\} \cup \biguplus_{a \in \Sigma} aa^{-1} T$.
\end{proof}

Constructively speaking, given a $\Sigma$-indexed family of trees $(T_a)_{a \in \Sigma}$, one can define
\[ T = \{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a \]

This yields a tree whose infinite branches are obtained from those of the children subtrees.

\begin{proposition} \label{prop:root_construct}
    If $(T_a)_{a \in \Sigma} \in T(\Sigma)$ is a family of trees, then
    \begin{enumerate}
        \item $\{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a \in T(\Sigma)$
        \item $[\{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a] = \bigcup_{a \in \Sigma} a[T_a]$
    \end{enumerate}
\end{proposition}

\begin{proof}
    Let $T$ be the set $\{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a$.
    \begin{enumerate}
        \item Let us show that $T$ is prefix-closed. Let $u \in T$, the case $u = \varepsilon$ is obvious so we can assume $u = av$ for some $a \in \Sigma$ and some $v \in T_a$. As $T_a$ is a tree, $\Pref(v) \subseteq T_a$ hence $a\Pref(v) \subseteq aT_a \subseteq T$. Therefore $\Pref(u) = \{\varepsilon\} \cup a\Pref(v) \subseteq T$, so that $T$ is prefix-closed.
        \item Let $w \in \Sigma^\omega$. Assume $w \in [T]$. We have for every $n \in \omega$, $w_{\mid n} \in \{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a$. If $n$ is non-zero, the only possibility is that $w_{\mid n} \in w_1 T_{w_1}$. Therefore, every prefix of $w^{\mid 1}$ is in $T_{w_1}$, whence $w^{\mid 1} \in [T_{w_1}]$ so that $w \in w_1[T_{w_1}] \subseteq \bigcup_{a \in \Sigma} a[T_a]$. Conversely, let $w \in \bigcup_{a \in \Sigma} a[T_a]$, then there is $a \in \Sigma$ such that $w \in a[T_a]$. For every $n \in \omega$, either $n = 0$ and $w_{\mid 0} = \varepsilon \in T$, or $n > 0$ and $w_{\mid n} = au$ for some $u \in T_a$, therefore $w_{\mid n} \in aT_a \subseteq T$. This shows that $w \in [T]$.
    \end{enumerate}
\end{proof}

And as expected, we then have
\begin{proposition}
    If $T = \{\varepsilon\} \cup \biguplus_{a \in \Sigma} aT_a$ and $a \in \Sigma$, then $T_a = a^{-1}T$.
\end{proposition}
\begin{proof} As $a^{-1}a L = L$ and $a^{-1}b L = \emptyset$ for $b \neq a$, we have
    \[ a^{-1}T = a^{-1}\left(\{\varepsilon\} \cup \biguplus_{b \in \Sigma} bT_b \right) = a^{-1}\{\varepsilon\} \cup \biguplus_{b \in \Sigma} a^{-1}bT_b = T_a  \]
\end{proof}

In particular, for any non-empty tree $T \in T(\Sigma)$ we have
\begin{align*}
     & T = \{\varepsilon\} \uplus \biguplus_{a \in \Sigma} aa^{-1}T \\
     & [T] = \biguplus_{a \in \Sigma} aa^{-1}[T]
\end{align*}

\subsubsection{Along a Branch}

Destructively speaking, a tree with at least one infinite branch is the union of the subtrees plugged along that branch.

Given a infinite word $w \in \Sigma^\omega$, the set of \emph{off-words} of $w$ is defined as $w^\circ = \{w_{\mid n} a \mid n \in \omega, a \in \Sigma \setminus \{w_{n+1}\}\} \in P(\Sigma^*)$.

\begin{proposition} \label{prop:destruct_stream}
    For all $T \in T(\Sigma)$ and $w \in [T]$,
    \begin{align*} T & = \Pref(w) \cup \biguplus_{u \in w^\circ} uu^{-1}T                                                                                            \\
                 & = \biguplus_{n \in \omega} w_{\mid n} \left( \{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} a(w_{\mid n}a)^{-1} T\right)
    \end{align*}
\end{proposition}
\begin{proof}
    The set $\{\Pref(w)\} \cup \{u\Sigma^* \mid u \in w^\circ\}$ is clearly a partition of $\Sigma^*$. Therefore,
    \begin{align*}
        T = T \cap \Sigma^*
         & = (T \cap \Pref(w)) \cup \biguplus_{u \in w^\circ} (T \cap u\Sigma^*)                                                                         \\
         & = \Pref(w) \cup \biguplus_{u \in w^\circ} uu^{-1}T                                                                                            \\
         & = \biguplus_{n \in \omega} \left(\{w_{\mid n}\} \cup \biguplus_{u \in w^\circ \cap \Sigma^{n+1}} uu^{-1}T\right)                              \\
         & = \biguplus_{n \in \omega} \left(\{w_{\mid n}\} \cup \biguplus_{a \in \Sigma} w_{\mid n} a (w_{\mid n} a)^{-1}T\right)                        \\
         & = \biguplus_{n \in \omega} w_{\mid n} \left( \{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} a(w_{\mid n}a)^{-1} T\right)
    \end{align*}
    % Let $S = \biguplus_{n \in \omega} w_{\mid n} \left( \{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} a(w_{\mid n}a)^{-1} T\right)$. Let $u \in T$ be written $u = w_{\mid n} v$ where $n \in \omega$ is maximal. Then either $v = \varepsilon$ so that $u \in w_{\mid n}\{\varepsilon\} \subseteq S$. Or $v = az$ for some $a \in \Sigma \setminus \{w_{n+1}\}$ (by maximality of $n$) and $z \in \Sigma^*$. In that case, as $w_{\mid n} az \in T$, we have $z \in (w_{\mid n}a)^{-1} T$ and therefore $az \in a(w_{\mid n} a)^{-1} T$, therefore $u \in S$. Conversely, let $u \in S$. There is $n \in \omega$ such that $u \in w_{\mid n} \left(\{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} a(w_{\mid n}a)^{-1} T\right)$. Either $u = w_{\mid n}$, which is in $T$ because $w \in [T]$, or $u = w_{\mid n} a v$ for some $v \in (w_{\mid n}a)^{-1} T$, which means $w_{\mid n} a v \in T$, that is, $u \in T$. 
\end{proof}

Constructively speaking, given a countable family of non-empty $\Sigma$-trees $(T_n)_{n\in \omega}$ and an infinite word $w \in \Sigma^\omega$, one can define

\begin{equation*}
    T = \bigcup_{n\in \omega} w_{\mid n} T_n
\end{equation*}

This yields a tree whose infinite branches are the main branch $w$ and the ones obtained from the subtrees $T_n$.

\begin{proposition} \label{prop:branch_construct}
    If $w \in \Sigma^\omega$ and $(T_n)_{n\in \omega} \in T(\Sigma)$ is a countable family of non-empty trees, then
    \begin{enumerate}
        \item $\bigcup_{n \in \omega} w_{\mid n} T_n \in T(\Sigma)$
        \item $\left[ \bigcup_{n \in \omega} w_{\mid n} T_n \right] = \{w\} \cup \bigcup_{n \in \omega} w_{\mid n} [T_n]$
    \end{enumerate}
\end{proposition}
\begin{proof}
    In the whole proof, let $U = \bigcup_{n \in \omega} w_{\mid n} T_n$.
    \begin{enumerate}
        \item Let $u \in w_{\mid n} T_n$ for some $n \in \omega$. Then $u = w_{\mid n} v$ for some $v \in T_n$. Prefixes of $u$ are either prefixes of $w$, which belong to $U$ because every $T_i$ contains $\varepsilon$, or of the form $w_{\mid n} v'$ for some $v'$ prefix of $v$. As $v \in T_n$ and $T_n$ is prefix-closed, $v' \in T_n$, hence $w_{\mid n} v' \in w_{\mid n} T_n$ is in $U$ as well.
        \item $\boxed{\supseteq}$ First consider $w$. For all $n \in \omega$, as $\varepsilon \in T_n$ we have $w_{\mid n} \in w_{\mid n} T_n$, therefore $w$ is an infinite branch of $U$. Now let $x \in [T_n]$ for some $n \in \omega$, let us show that $w_{\mid n} x$ is an infinite branch of $U$ as well. Every prefix of $w$ is in $U$, so consider $w_{\mid n} u$ where $u$ is a prefix of $x$. As $x \in [T_n]$ we have $u \in T_n$ therefore $w_{\mid n} u \in U$, which completes the proof.
        \item[] $\boxed{\subseteq}$ Let $b \in \left[ \bigcup_{n \in \omega} w_{\mid n} T_n \right] \setminus \{w\}$. Let $n_0 \in \omega$ be such that $b_{\mid n_0} \neq w_{\mid n_0}$ and minimal with that property. We know that for all $m \in \omega$, $b_{\mid m} \in \bigcup_{n \in \omega} w_{\mid n} T_n$, henceforth for all $m \geq n_0$, $b_{\mid m} \in \bigcup_{n < n_0} w_{\mid n} T_n$. Pick $n_1 < n_0$ such that there are infinitely many $b_{\mid m}$ ($m \geq n_0$) in $w_{\mid n_1} T_{n_1}$. Therefore, there are infinitely many prefixes of $b^{\mid n_1}$ in $T_{n_1}$. As $T_{n_1}$ is prefix-closed, this yields $b^{\mid n_1} \in [T_{n_1}]$. Hence $b = b_{\mid n_1} b^{\mid n_1} = w_{\mid n_1} b^{\mid n_1} \in w_{\mid n_1} [T_{n_1}]$, which completes the proof.
    \end{enumerate}
\end{proof}

% Maybe the following generalisation holds.
% \begin{conjecture}
%     More generally, if $(T_i)_{i \in I}$ are trees, then $[\bigcup_{i \in I} T_i] = \overline{\bigcup_{i \in I} [T_i]}$.
% \end{conjecture}

The aforementioned way to construct trees along an infinite branch is not very handy, because the union may not be disjoint as trees $T_n$ can 'overflow' along the branch $w$. It is more convenient to ask for a family $(T_u)_{u \in w^\circ}$ parametrised by the off-words of $w$, following the destructive vision.

\begin{proposition}
    If $w \in \Sigma^\omega$ and $(T_u)_{u \in w^\circ}$ is a family of trees, let
    \[ T = \Pref(w) \cup \biguplus_{u \in w^\circ} uT_u = \biguplus_{n \in \omega} w_{\mid n} \left( \{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} aT_{w_{\mid n}a}\right) \]
    Then
    \begin{enumerate}
        \item $T \in T(\Sigma)$
        \item $[T] = \{w\} \cup \biguplus_{u \in w^\circ} u[T_u]$
    \end{enumerate}
\end{proposition}

\begin{proof} Let be the non-empty trees $T_n = \{\varepsilon\} \cup \biguplus_{a \in \Sigma \setminus \{w_{n+1}\}} aT_{w_{\mid n} a}$ for every $n \in \omega$, so that $T = \bigcup_{n \in \omega} w_{\mid n} T_n$.
    \begin{enumerate}
        \item The $T_n$ are trees according to Proposition~\ref{prop:root_construct}. Therefore, using Proposition~\ref{prop:branch_construct}, $T = \bigcup_{n \in \omega} w_{\mid n} T_n$ is a tree.
        \item Proposition~\ref{prop:root_construct} yields $[T_n] = \bigcup_{a \in \Sigma \setminus \{w_{n+1}\}} a[T_{w_{\mid n}a}]$. Proposition~\ref{prop:branch_construct} yields $[T] = \left[ \bigcup_{n \in \omega} w_{\mid n} T_n \right] = \{w\} \cup \bigcup_{n \in \omega} w_{\mid n} [T_n]$. Combining the two results,
              \[ [T] = \{w\} \cup \bigcup_{n \in \omega} \bigcup_{a \in \Sigma \setminus \{w_{n+1}\}} w_{\mid n} a [T_{w_{\mid n}a}] = \{w\} \cup \biguplus_{u \in w^\circ} u[T_u] \]
    \end{enumerate}
\end{proof}

And as expected, we then have
\begin{proposition}
    If $T = \Pref(w) \cup \biguplus_{u \in w^\circ} uT_u$ and $u \in w^\circ$, then $T_u = u^{-1}T$.
\end{proposition}

\begin{proof}
    As $u^{-1}uL = L$ and $u^{-1}vL = \emptyset$ for $v \in w^\circ \setminus \{u\}$ (because $u$ and $v$ are not a prefix of each other), we have
    \[ u^{-1} T = u^{-1}\left( \Pref(w) \cup \biguplus_{u \in w^\circ} uT_u \right) = u^{-1} \Pref(w) \cup \bigcup_{v \in w^\circ} u^{-1}v T_v = T_u \]
\end{proof}


In particular, for any tree $T \in T(\Sigma)$ and $w \in [T]$ we have
\begin{align*}
     & T = \Pref(w) \uplus \biguplus_{u \in w^\circ} uu^{-1}T  \\
     & [T] = \{w\} \uplus \biguplus_{u \in w^\circ} uu^{-1}[T]
\end{align*}

\section{The Cantor-Bendixson Derivative}

This section introduces the Cantor-Bendixson derivative, an operation on topological spaces which consists in deleting isolated points. We will then see that trees themselves are topological spaces and how derivation works on them.

\subsection{Derivating Topological Spaces}

We assume familiarity with elementary topology and only give some of the basics definitions to fix notation.

A topological space is a set $X$ equipped with a set $\Omega(X) \subseteq P(X)$ such that $\emptyset, X \in \Omega(X)$ and $\Omega(X)$ is closed under arbitrary unions and finite intersections. Elements of $\Omega(X)$ are called the \emph{open sets} of $X$. Their complements $C(X)$ are called \emph{closed sets} of $X$.

Given a subset $Y \subseteq X$ of a topological space $X$, the subset topology is defined as
\[ \Omega(Y) = \{U \cap Y \mid U \in \Omega(X)\} \]

A point $x \in X$ is \emph{isolated} if $\{x\} \in \Omega(X)$.

\begin{definition}[Cantor-Bendixson derivative]
    The \emph{derivative} of a topological space $X$ is the set
    \[ X' = X \setminus \{ x \in X \mid x \text{ is isolated}\} \]
    equipped with the subset topology inherited from $X$.
\end{definition}
As $X \setminus X'$ is the union of its open singletons, the set $X'$ is closed in $X$.

\begin{lemma} \label{lem:isolated_subset}
    Let $Z$ be a topological space and $X \subseteq Y \subseteq Z$ with the subset topologies. For any $x \in X$, if $x$ is isolated in $Y$, then $x$ is isolated in $X$.
\end{lemma}
\begin{proof}
    Let $x \in X$. Assume $x$ is isolated in $Y$, then $\{x\} \in \Omega(Y)$ so there is $U \in \Omega(Z)$ such that $\{x\} = U \cap Y$. As $x \in X$, $\{x\} = \{x\} \cap X = U \cap Y \cap X = U \cap X \in \Omega(X)$ so that $x$ is isolated in $X$.
\end{proof}

As a consequence, the Cantor-Bendixson derivative is monotone.
\begin{corollary}
    Let $Z$ be a topological space and $X \subseteq Y \subseteq Z$ with the subset topologies. Then $X' \subseteq Y'$.
\end{corollary}
\begin{proof}
    Let $x \in X'$. As $X' \subseteq X$ we have $x \in X$. If $x$ is isolated in $Y$, then by Lemma~\ref{lem:isolated_subset}, $x$ is isolated in $X$ which is contradicting $x \in X'$. So $x$ is not isolated in $Y$, that is, $x \in Y'$.
\end{proof}

The Cantor-Bendixson derivative preserves the fact of being homeomorphic.
\begin{proposition}
    Let $X$ and $Y$ be homeomorphic topological spaces. Then $X'$ and $Y'$ are homeomorphic.
\end{proposition}
\begin{proof}
    Let $f : X \to Y$ be a homeomorphism. We show that it restricts to a homeomorphism $f' : X' \to Y'$.
    \begin{itemize}
        \item First see that if $f(x) \in Y$ is isolated, then $f^{-1}(\{f(x)\}) = \{x\}$ is open, hence $x \in X$ is isolated. This proves that the restriction $f' : X' \to Y'$ is well-defined.
        \item Similarly, the restriction $(f^{-1})' : Y' \to X'$ is well-defined. It is straightforward to check that $f'$ and $(f^{-1})'$ are inverse to each other, showing that $f'$ is a bijection.
        \item Let $U \cap Y' \in \Omega(Y')$, where $U \in \Omega(Y)$. Then $f'^{-1}(U \cap Y') = f^{-1}(U) \cap X' \in \Omega(X')$, whence $f'$ is continuous. \item Similarly, $(f^{-1})'$ is continuous, hence $f' : X' \to Y'$ is a homeomorphism.
    \end{itemize}
\end{proof}


\subsection{Derivating Trees}

\paragraph{Topologies on Trees}

\begin{proposition}
    The sets $\{u\Sigma^\omega \mid u \in \Sigma^*\}$ form a clopen basis of the product topology of $\Sigma^\omega$, where $\Sigma$ is given the discrete topology.
\end{proposition}

\begin{proof}
    Let $C = \{u\Sigma^\omega \mid u \in \Sigma^*\}$ be the set of \emph{cones}.
    Recall that the product topology of $\Sigma^\omega$ is generated by products $\prod_{n \in \omega} U_n$ where $U_n \in \Omega(X)$, with $U_n = \Sigma$ for all but finitely many $n$s. First we see that $C \subseteq \Omega(\Sigma^\omega)$ because $u\Sigma^\omega = \{u_1\} \times \ldots \times \{u_n\} \times \Sigma^\omega$ and every letter is open in the discrete topology of $\Sigma$. Conversely, any basic open of $\Omega(\Sigma^\omega)$ can be written
    \[ \prod_{1 \leq i \leq n} U_i \times \Sigma^\omega = \bigcup_{u \in \Sigma^n, u_i \in U_i} u\Sigma^\omega \]
    so that the topology generated by $C$ is exactly the product topology. Moreover, for any $w \in u\Sigma^\omega \cap v\Sigma^\omega$, assuming without loss of generality that $|u| \geq |v|$, we have $w \in u\Sigma^\omega \subseteq u\Sigma^\omega \cap v\Sigma^\omega$. As, additionally, $C$ covers $\Sigma^\omega$ because $\Sigma^\omega = \varepsilon\Sigma^\omega \in C$, we have that $C$ is a base of the topology its generates. Finally, let us show that every $u\Sigma^\omega$ is also closed. We have
    \[ \Sigma^\omega \setminus u\Sigma^\omega = \bigcup_{v \in \Sigma^{|u|} \setminus \{u\}} v\Sigma^\omega \in \Omega(\Sigma^\omega)\]
\end{proof}

% \TBD{What about topologies on $\Sigma^\infty$?} \\
% \TBD{Distance $d(w,w')=2^{-\min\{n\in\omega\mid w'_n \neq w'_n\}}$ generates the same topology. Therefore we have notions of sequential convergence. A subset is closed iff every sequence converges inside the subset.}

\paragraph{Steady Convergence.}
Let $w^{(n)} \in \Sigma^\omega$ for every $n \in \omega$. If there is $w \in \Sigma^\omega$ such that $\bigcap_{n \in \omega} w^{(n)}_{\mid n} \Sigma^\omega = \{w\}$, then we write $w^{(n)} \to w$ and say that the sequence $w^{(n)}$ converges steadily to $w$.

% \TBD{
%     \begin{proposition}
%         Steady convergence implies metric convergence. A subset if closed iff limits of metric convergent sequences stay in the subset, iff limits of steady convergence sequences stay in the subset, or equivalently: steady convergence generates the same topology as metric convergence.
%     \end{proposition}
% }

\begin{lemma} \label{lem:sequential_convergence}
    Let $C \in C(\Sigma^\omega)$ and $w^{(n)} \to w$ with all $w^{(n)} \in C$, then $w \in C$.
\end{lemma}
\begin{proof}
    As $C$ is closed, $\Sigma^\omega \setminus C$ is open, hence we can write
    \[ \Sigma^\omega \setminus C = \bigcup_{i \in I} u_i \Sigma^\omega \]
    for some finite words $u_i \in \Sigma^*$. Assume towards a contradiction that $w \notin C$. Let $i \in I$ be such that $w \in u_i\Sigma^\omega$. Let $n = |u_i|$, then as $w \in w^{(n)}_{\mid n} \Sigma^\omega$ we have $u_i = w^{(n)}_{\mid n}$. Hence $w^{(n)} \in u_i \Sigma^\omega \subseteq \Sigma^\omega \setminus C$ which is a contradiction.
\end{proof}


\paragraph{Closed Subsets are exactly Pruned Trees.}


A \emph{pruned tree} is a tree $T \in T(\Sigma)$ such that for every $u \in T$, there is some $a \in \Sigma$ with $ua \in T$. Intuitively, a tree is pruned if it has no \emph{finite} branch. The set of pruned trees is denoted by $pT(\Sigma) \subseteq T(\Sigma)$.


\begin{proposition} \label{prop:closed_pruned_bij}
    There is a bijective correspondence between closed subsets of $\Sigma^\omega$ and the set of pruned trees on $\Sigma$:
    \[ C(\Sigma^\omega) \cong pT(\Sigma) \]
\end{proposition}

\begin{proof}
    Define the maps
    \begin{align*}
        \varphi \colon & C(\Sigma^\omega) \to pT(\Sigma)                                                    \\
                       & C \mapsto \Pref(C) = \{u \in \Sigma^* \mid C \cap u\Sigma^\infty \neq \emptyset \} \\
        \psi \colon    & pT(\Sigma) \to C(\Sigma^\omega)                                                    \\
                       & T \mapsto [T] = \{w \in \Sigma^\omega \mid \Pref(w) \subseteq T\}
    \end{align*}
    First we show that $\varphi$ and $\psi$ are well-defined. Let $C \in C(\Sigma^\omega)$. Then $\Pref(C)$ is prefix-closed hence a tree. Let us show that it is pruned. Let $w_{\mid n} \in \Pref(C)$ for some $w \in C$ and $n \in \omega$. Then, because $w \in \Sigma^\omega$, we have $w_{\mid n+1} = w_{\mid n} w_{n+1} \in \Pref(C)$, hence $\Pref(C)$ is pruned and $\varphi$ is well-defined. Now let $T \in T(\Sigma)$ be a (not necessarily pruned) tree and let us show that $[T]$ is closed in $\Sigma^\omega$. Because
    \begin{align*}
        w \in \Sigma^\omega \setminus [T]
         & \iff \exists n \in \omega, w_{\mid n} \in \Sigma^* \setminus T \\
         & \iff \exists u \in \Sigma^* \setminus T, w \in u\Sigma^\omega  \\
         & \iff w \in \bigcup_{u \in \Sigma^* \setminus T} u\Sigma^\omega
    \end{align*}
    we have
    \begin{align*}
        \Sigma^\omega \setminus [T]
         & = \bigcup_{u \in \Sigma^* \setminus T} u\Sigma^\omega \in \Omega(\Sigma^\omega)
    \end{align*}
    Now let us show that $\psi \circ \varphi$ and $\varphi \circ \psi$ are identities. Let $T \in pT(\Sigma)$ and let us show that $\Pref([T]) = T$ by double inclusion. Let $u \in \Pref([T])$, we can find $w \in [T]$ and $n \in \omega$ such that $u = w_{\mid n}$. As $w \in [T]$, we know $w_{\mid n} \in T$, hence $u \in T$. Conversely, let $u \in T$. As $T$ is pruned, we can define, by repetitively extending $u$ into arbitrarily long words in $T$, some $w \in [T]$ such that $w_{\mid n} = u$. Hence $u \in \Pref([T])$.


    Now let $C \in C(\Sigma^\omega)$ and show that $[\Pref(C)] = C$ by double inclusion. Let $w \in C$ and $n \in \omega$, then $w_{\mid n} \in \Pref(C)$ hence $w \in [\Pref(C)]$. Conversely, let $w \in [\Pref(C)]$. For any $n \in \omega$, we know $w_{\mid n} \in \Pref(C)$, hence there is $w^{(n)} \in C$ such that $w^{(n)}_{\mid n} = w_{\mid n}$. We have $\bigcap_{n \in \omega} w^{(n)}_{\mid n} \Sigma^\omega = \{w\}$ i.e. $w^{(n)} \to w$. According to Lemma~\ref{lem:sequential_convergence}, the limit $w \in C$.
\end{proof}

\begin{corollary} \label{cor:pruning}
    For any tree $T \in T(\Sigma)$, the tree $\Pref([T])$ is the unique pruned tree that has the same infinite branches as $T$.
\end{corollary}

\begin{proof}
    Let $T \in T(\Sigma)$. Let $u \in \Pref([T])$, we can write $u = w_{\mid n}$ for some $w \in [T]$ and $n \in \omega$. Then $w_{\mid n+1} \in \Pref([T])$ as well, so that $\Pref([T])$ is pruned. Now let us show that $[T] = [\Pref([T])]$. According to the proof of Proposition~\ref{prop:closed_pruned_bij}, $[T]$ is closed. Therefore as $\psi \circ \varphi$ is the identity, we have $[\Pref([T])] = [T]$. Moreover, $\Pref([T])$ is the unique pruned tree with that property. Indeed, let $T_1, T_2 \in pT(\Sigma)$ be such that $[T_1] = [T_2]$. Then, using that $\varphi \circ \psi$ is the identity, $T_1 = \Pref([T_1]) = \Pref([T_2]) = T_2$.
\end{proof}

From now on, we completely identify $C(\Sigma^\omega)$ and $pT(\Sigma)$, using explicitly or implicitly the bijection from Proposition~\ref{prop:closed_pruned_bij}. That implies identifying a pruned tree with its set of infinite branches. The map $T(\Sigma) \to pT(\Sigma)$ from Corollary~\ref{cor:pruning} given by $T \mapsto \Pref([T])$ consists in pruning a tree, which is, cutting its finite branches. It allows to sometimes identify also non-necessarily pruned trees with their set of infinite branches.

Any tree $T \in T(\Sigma)$ is given the subset topology inherited from the canonical topology on $\Sigma^\omega$.

\begin{proposition}
    Let $T \in T(\Sigma)$. For an infinite branch $w \in [T]$, the following are equivalent:
    \begin{enumerate}
        \item The point $w$ is isolated in $[T]$.
        \item There exists $N \in \omega$ such that $w_{\mid N}\Sigma^\omega \cap [T] = \{w\}$.
        \item The set $\{n \in \omega \mid \exists w' \in [T] \setminus \{w\}, w_{\mid n} = w'_{\mid n}\}$ is finite.
        \item There is no sequence $w^{(n)} \in [T] \setminus \{w\}$ such that $w^{(n)} \to w$.
    \end{enumerate}
\end{proposition}
\begin{proof} A $w \in [T]$ is isolated iff $\{w\}$ is open in the subset topology inherited from $\Sigma^\omega$, that is, iff there is $U \in \Omega(\Sigma^\omega)$ such that $U \cap [T] = \{w\}$.

    $\boxed{1 \Leftrightarrow 2}$ Let $U \in \Omega(\Sigma^\omega)$ such that $U \cap [T] = \{w\}$. Using the clopen basis, find $u \in \Sigma^*$ such that $w \in u\Sigma^\omega \subseteq U$. Let $n = |u|$, then $u = w_{\mid n}$ and by intersecting both sides of $U \cap [T] = \{w\}$ with $w_{\mid n}\Sigma^\omega$ we get $w_{\mid n} \Sigma^\omega \cap [T] = \{w\}$. Conversely, if for some $n \in \omega$ we have $w_{\mid n} \Sigma^\omega \cap [T] = \{w\}$ then $w$ is isolated in $[T]$ because $w_{\mid n} \Sigma^\omega \in \Omega(\Sigma^\omega)$.

    $\boxed{2 \Leftrightarrow 3}$ Let $N \in \omega$ such that $w_{\mid N} \Sigma^\omega \cap [T] = \{w\}$. For any $n \geq N$, if $w' \in [T]$ and $w_{\mid n} = w'_{\mid n}$ then $w' \in w_{\mid n} \Sigma^\omega \cap [T] \subseteq w_{\mid N} \Sigma^\omega \cap [T] = \{w\}$ hence $w' = w$. Therefore, $B := \{n \in \omega \mid \exists w' \in [T] \setminus \{w\}, w_{\mid n} = w'_{\mid n}\} \subseteq \{0,\ldots,N-1\}$ is finite. Conversely, if $B$ is finite then letting $N = \max B + 1 \in \omega$, we have $w_{\mid n} \cap [T] = \{w\}$.

    $\boxed{2 \Leftrightarrow 4}$ If $w^{(n)} \in [T] \setminus \{w\}$ is a sequence such that $w^{(n)} \to w$, then for all $n \in \omega$ we have $w_{\mid n} \Sigma^\omega \cap [T] \supseteq \{w,w^{(n)}\}$ so this set can never be a singleton. Conversely, if for every $n \in \omega$ there is $w^{(n)} \in [T] \setminus \{w\}$ such that $w^{(n)}_{\mid n} = w_{\mid n}$ then $\bigcap_{n \in \omega} w^{(n)}_{\mid n} \Sigma^\omega = \{w\}$ i.e. $w^{(n)} \to w$.
\end{proof}


\begin{lemma} \label{lem:convergence_corestrict}
    Let $w^{(n)} \to w$.
    \begin{enumerate}
        \item For any $p\in\omega$, $w^{(p+n)\mid p} \to w^{\mid p}$. Moreover, for every $n \in \omega$, $w^{(p+n)\mid p} = w^{\mid p} \iff w^{(p+n)} = w$.
        \item For any $u \in \Sigma^*$, $uw^{(n)} \to uw$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    \begin{enumerate}

        \item Assume $w^{(n)} \to w$ i.e. $\bigcap_{n \in \omega} w^{(n)}_{\mid n} \Sigma^\omega = \{w\}$. That is, for every $n \in \omega$ we have $w^{(n)}_{\mid n} = w_{\mid n}$. We must prove that for every $n \in \omega$ we have $(w^{(p+n)\mid p})_{\mid n} = (w^{\mid p})_{\mid n}$. This follows from
              \[ w^{(p+n)}_{\mid p} (w^{(p+n)\mid p})_{\mid n} = w^{(p+n)}_{\mid p+n} = w_{\mid p+n} = w_{\mid p} (w^{\mid p})_{\mid n} \]
              Moreover, if for some $n \in \omega$ we have $w^{(p+n)\mid p} = w^{\mid p}$, then as $w^{(p+n)}_{\mid p+n} = w_{\mid p+n}$ we have $w^{(p+n)}_{\mid p} = w_{\mid p}$ so that
              \[ w^{(p+n)} = w^{(p+n)}_{\mid p} w^{(p+n)\mid p} = w_{\mid p} w^{\mid p} = w \]
              and the converse implication is obvious.

        \item Let $p = |u|$. For every $n \leq p$ we have $(uw^{(n)})_{\mid n} = u_{\mid n} = (uw)_{\mid n}$. For $n > p$ we have $(uw^{(n)})_{\mid n} = uw^{(n)}_{\mid n-p} = uw_{\mid n-p} = (uw^{(n)})_{\mid n}$.

    \end{enumerate}
\end{proof}

\begin{proposition}
    For any $T \in T(\Sigma)$ and $u \in \Sigma^*$,
    \begin{enumerate}
        \item The set $u[T]$ is closed and $(u[T])' = u[T]'$.
        \item The set $u^{-1}[T]$ is closed and $(u^{-1}[T])' = u^{-1}[T]'$.
    \end{enumerate}
\end{proposition}

\begin{proof}
    Let $T \in T(\Sigma)$ and $u \in \Sigma^*$.
    \begin{enumerate}
        \item As $u[T] = [\Pref(u) \cup uT]$, $u[T]$ is closed.
        \item[] $\boxed{\subseteq}$ Let $w \in (u[T])'$. As $w$ is not isolated in $u[T]$, we can find $w^{(n)} \in u[T] \setminus \{w\}$ such that $w^{(n)} \to w$. Let $p = |u|$. By Lemma~\ref{lem:convergence_corestrict}, we have $w^{(p+n)\mid p} \to w^{\mid p}$ and $w^{(p+n)\mid p} \in [T] \setminus \{w^{\mid p}\}$. Therefore $w^{\mid p} \in [T]'$ so that $w \in u[T]'$.
        \item[] $\boxed{\supseteq}$ Let $w \in u[T]'$ and $p = |u|$. Then $w^{\mid p} \in [T]'$ so that there is a sequence $z^{(n)} \to w^{\mid p}$ with $z^{(n)} \in [T] \setminus \{w^{\mid p}\}$. According to Lemma~\ref{lem:convergence_corestrict}, we have $uz^{(n)} \to uw^{\mid p} = w_{\mid p}w^{\mid p} = w$, and obviously $uz^{(n)} \in u[T] \setminus \{w\}$, therefore $w \in (u[T])'$.
        \item As $u^{-1}[T] = [u^{-1}T]$, $u^{-1}[T]$ is closed.
        \item[] $\boxed{\subseteq}$ Let $w \in (u^{-1}[T])'$. Let be a sequence $w^{(n)} \to w$ with $w^{(n)} \in u^{-1}[T]$, i.e. $uw^{(n)} \in [T]$, and $w^{(n)} \neq w$ for all $n \in \omega$. We have $uw^{(n)} \in [T] \setminus \{uw\}$. Also, by Lemma~\ref{lem:convergence_corestrict}, we have $uw^{(n)} \to uw$. Hence $uw \in [T]'$ so $w \in u^{-1}[T]'$.
        \item[] $\boxed{\supseteq}$ Let $w \in u^{-1}[T]'$, that is, $uw \in [T]'$. Find a sequence $v^{(n)} \to uw$ with $v^{(n)} \in [T] \setminus \{uw\}$ for all $n \in \omega$. Let $p = |u|$. As $v^{(n)} \to uw$ we have $v^{(p+n)}_{\mid p} = u$ for every $n \in \omega$, hence $uv^{(p+n)\mid p} = v^{(p+n)}_{\mid p} v^{(p+n)\mid p} = v \in [T]$, that is, $v^{(p+n)\mid p} \in u^{-1}[T]$. By Lemma~\ref{lem:convergence_corestrict}, we have $v^{(p+n)\mid p} \to (uw)^{\mid p} = w$. Still by Lemma~\ref{lem:convergence_corestrict}, as $v^{(n)} \neq uw$ we have $v^{(p+n)\mid p} \neq w$. Therefore $w \in (u^{-1}[T])'$.
    \end{enumerate}
\end{proof}

\section{The Cantor-Bendixson Rank}

The Cantor-Bendixson derivative can be transfinitely iterated. The derivating process always stabilises at some ordinal $\alpha$. This $\alpha$ is called the Cantor-Bendixson rank of the topological space. This section studies the interplay between rank and tree decompositions.

\subsection{On Topological Spaces}

One can transfinitely iterate the topological derivative as follows. For a topological space $X$, let
\begin{align*}
     & X^{(0)} =  X                                          &                               \\
     & X^{(\alpha+1)} = (X^{(\alpha)})'                      &                               \\
     & X^{(\lambda)} = \bigcap_{\beta < \lambda} X^{(\beta)} & \lambda \text{ limit ordinal}
\end{align*}

The sequence $X^{(\alpha)}$ is decreasing, hence stationary.

\begin{definition}[Cantor-Bendixson rank]
    For any topological space $X$, there is a least ordinal $\alpha$ such that $X^{(\alpha)} = X^{(\alpha+1)}$. This ordinal is called the \emph{Cantor-Bendixson rank} of $X$ and is denoted as $\alpha = \CB(X)$.
\end{definition}

By definition, the space $X^{(\CB(X))}$ is \emph{perfect} in the sense that it has no isolated points. It is called the \emph{perfect kernel} of $X$.

\subsection{On Trees}

\begin{definition}[Thin tree]
    A tree $T \in T(\Sigma)$ is \emph{thin} if its perfect kernel is empty, that is, $[T]^{(\CB(T))} = \emptyset$.
\end{definition}

\begin{proposition}
    If $\Sigma$ is countable, thin trees in $T(\Sigma)$ are exactly the trees with countably many infinite branches.
\end{proposition}
\begin{proof}
    %For any infinite branch $w \in [T]$, let $\alpha_w$ be the minimal ordinal $\alpha$ such that $w \notin [T]^{(\alpha)}$.
    %\TBD{TBD ?}
    %\\
    % \TBD{Here is a more classical proof:}
    The proof relies on some basic descriptive-set-theoretic notions that have not been introduced above. The reader can use~\cite{Kechris95} as a general reference. Assume $\Sigma$ is countable. Then $\Sigma^\omega$ is Polish. Moreover, as any closed subset of a Polish space is polish, any tree in $T(\Sigma)$ is Polish. Any Polish space $X$ can be written as a disjoint union $X = P \uplus U$ where $P$ is its maximal perfect Polish subspace (the perfect kernel) and $U$ is the union of all its countable open subsets (itself countable). Non-empty perfect sets in a Polish space have the cardinality of the continuum.
    \begin{enumerate}
        \item[$\Rightarrow$] Let $T \in T(\Sigma)$ thin. Then the perfect kernel $P$ of $[T]$ is empty, so its countable complement is $U = [T]$. Therefore, $T$ has countably many infinite branches.
        \item[$\Leftarrow$] Let $T \in T(\Sigma)$ have countably many infinite branches. The perfect kernel $P$ of $[T]$ cannot have the cardinality of the continuum, therefore it is empty, so that $T$ is thin.
    \end{enumerate}
    %\TBD{Can probably be simplified.}
\end{proof}

\begin{remark}
    At the contrary, when there is no restriction on the cardinality of $\Sigma$, thin trees can have many infinite branches. For instance, the tree $\Pref(\{s^\omega \mid s \in \Sigma\})$ is thin, but has $|\Sigma|$-many infinite branches.
\end{remark}

