  Predicate abstraction allows to approximate program
  invariants~\cite{DBLP:journals/csur/JhalaM09}.  Given a set of
  predicates $\mathit{Pred} \subseteq \pow{\mathit{Env}}$ (where any
  $p\in \mathit{Pred}$ has a representation
  $p = \set{\rho \in \mathit{Env} \mid \rho \models p}$), the
  predicate abstraction domain $\mathbb{P}$ is defined by adding to
  $\mathit{Pred}$ the complement predicates
  $\overline{\mathit{Pred}}\triangleq \set{\overline{p}\mid p\in
    \mathit{Pred}}$, and then by closing
  $\mathit{Pred}\cup \overline{\mathit{Pred}}$ under logical
  conjunction.  We define a function
  $\pi: \pow{\mathit{Env}} \to \mathbb{P}$ that associates to each set
  of environments the strongest predicate it satisfies.  For example,
  given the two predicates $p \triangleq (z = 0)$ and
  $q \triangleq (x = y)$, the predicate abstraction domain
  $\mathbb{P}$ induced by the set $\mathit{Pred} =\set{ p, q}$ is
  depicted in Figure~\ref{fig:predicate}. Correspondingly, the product
  abstraction $\mathbb{P}^N$ allows us to represent the abstract state
  of the program as a function that associates to each program point
  $n$ the strongest predicate in $\mathbb{P}$ that holds at
  $n$. Hence, for instance, the set of all possible initial states of
  {\tt{c}}, which is $\set{(s, xyzw) \mid x, y, z, w \in \mathbb{V}}$,
  is represented by the function
  $(s \mapsto \top, 1 \mapsto \bot, 2 \mapsto \bot, 3 \mapsto \bot, e
  \mapsto \bot)$, often written $(s \mapsto \top)$, omitting the
  program points which are mapped to $\bot$.  \qed
\end{example}


%
An abstract interpreter computes in the underlying abstract domain through
correct (and effective) abstract approximations of concrete functions.
%
Given
$A_{\alpha, \gamma} \in \operatorname{Abs}(C)$ and a function $f: C
\to C$, an abstract function $f^{\sharp}: A \to A$ is a
correct approximation of $f$ if $\alpha \circ f \leq
f^{\sharp}\circ \alpha$, and it is
%
a \emph{complete} approximation of $f$ when $\alpha
\circ f = f^{\sharp}\circ \alpha$.
%
The \emph{best correct approximation}
(bca) of $f$ in $A$,
%
is defined as $f^{A}
\triangleq \alpha \circ f \circ \gamma: A \to A$,
and turns out to be the most precise correct abstraction, i.e., $f^{A}
\leq f^{\sharp}$ for any other correct approximation $f^{\sharp}$ of $f$.
%
When $f^{\sharp}$ is complete, then
%
$f^{\sharp} = f^A$,
thus making completeness an abstract domain property defined by the equation
$\alpha \circ f=\alpha \circ f \circ \gamma \circ \alpha$.
%
In program
analysis, abstract domains are commonly endowed with correct but
incomplete abstract transfer functions. When
completeness holds, the abstract interpreter is
as precise as possible for the given abstract domain and cannot raise
false alarms when verifying properties
that are expressible in the abstract domain
\cite{DBLP:journals/jacm/GiacobazziRS00}.
%

\subsection{Transition Systems and Logics}

Temporal logics are typically interpreted
over unlabeled, finite, directed
graphs, whose nodes and edges model states and
%
transitions between them (i.e., state changes), respectively.

%
A \emph{transition system} $T$ is a
tuple $(\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, where
$\Sigma$ is a finite set of states ranged over by $\sigma$,
$\operatorname{I} \subseteq \Sigma$ is the set of initial
states, $\trel \subseteq \Sigma \times \Sigma$ is the
transition relation, $\mathbf{P}$ is a (finite) set of atomic
propositions, ranged over by $p$, and $\mathbin{\vdash} \subseteq \Sigma
\times \mathbf{P}$ is the
satisfaction relation.
%
We assume that for any $p \in
\mathbf{P}$ also its negation $\neg p$ is in $\mathbf{P}$,
%
such that for $\sigma \in \Sigma$
either $\sigma \vdash p$ or $\sigma
\vdash \neg p$ holds (also written $\sigma \centernot \vdash p$), and that
$\mathsf{tt}\in\mathbf{P}$ such that $\sigma \vdash \mathsf{tt}$ for
all $\sigma\in\Sigma$.
%

% 
We write $\sigma \trel \sigma'$ instead of $(\sigma, \sigma') \in
\trel$ and let $\operatorname{post}(\sigma) = \set{\sigma' \mid \sigma \trel
\sigma'}$ denote
the set of direct successors of $\sigma \in
\Sigma$.
%
As common in model checking~\cite{CGKPV:MC-book}, we consider systems whose transition
relation is total, %
i.e., for all $\sigma \in \Sigma$ there exists $\sigma' \in \Sigma$
such that $\sigma \trel \sigma'$.

%
A path is an infinite denumerable state sequence
$(\sigma_i)_{i \in \N}$ such that $\sigma_i \trel \sigma_{i+1}$
for all $i \in \N$.

\begin{example}[Control flow graphs as transition systems]
  \label{ex:lts}
  A CFG $(N,E,s,e)$ can be viewed as a transition system with states
  $\Sigma = N \times \mathit{Env}$ and transition relation defined by
  $(n,\rho) \trel (n', \rho')$ if there is an edge $(n, f, n') \in E$
  such that $\rho' \in f(\set{\rho})$. Additionally, in order to make the
    transition relation total we add self-loops to all the states
    $(e,\rho)$ involving the end node $e$.
  %
  For instance, by using the
  shorthand $(n,xyzw)$ for the states in
  Example~\ref{ex:cfg}, the transition $(s,0111) \trel (1,1101)$ is
  induced by the edge $(s, x:= y  \ z := 0, 1)$ in
  Figure~\ref{fig:cfg}, while $(3,1111) \trel
  (e,1111)$ by $(3, x = y, e)$ in Figure~\ref{fig:cfg}.   


  Let us point out that the predicate abstraction  in
  Example~\ref{ex:cfg} naturally lifts to the powerset of states with
  codomain $A= \mathbb{P}^N$, with the abstraction map
  $\alpha(X)(n) \triangleq \pi(\set{\rho \mid (n, \rho) \in X})$ for
  $X \in \pow{\Sigma} = \pow{N \times \mathit{Env}}$.
  %
  Given $\sigma^{\sharp} \in A$, we define
  $\supp{\sigma^{\sharp}} \triangleq \set{n \in N \mid \sigma^{\sharp}(n) \neq \bot}$. 
  \qed
\end{example}

\subparagraph{ACTL.}
ACTL is the fragment of CTL whose temporal formulae are universally
quantified over all
paths leaving the current state. Thus,
given a set of atomic propositions $p\in \mathbf{P}$: 
\begin{center}
  $\text{ACTL}\ni \varphi \ ::=  \ p \mid
  \neg p \mid
  \varphi_1 \lor \varphi_2 \mid
  \varphi_1 \land \varphi_2 \mid
  \AX \varphi_1 \mid
  \AF \varphi_1 \mid
  \AG \varphi_1 \mid
  \varphi_1 \AU \varphi_2$
\end{center}
%

\begin{definition}[ACTL semantics]\label{ACTL-semantics}
  Given a transition system
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, the
  semantics %
  $\sem[]{\varphi} \subseteq \Sigma$ of
  {\rm \text{ACTL}} formulae over $T$ is as follows:
  \begin{center}
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l@{\hspace{-130pt}}r@{\hspace{2pt}}c@{\hspace{2pt}}l}
      $\sem[]{p}$ & $\triangleq$ & $\set{\sigma \in \Sigma \mid
      \sigma \vdash p}$ & 
      $\sem[]{\neg p}$ & $\triangleq$ &$\set{\sigma \in \Sigma \mid
      \sigma \vdash \neg p}$ \\
      $\sem[]{\varphi_1 \lor \varphi_2}$  & $\triangleq$ &
      $\sem[]{\varphi_1} \cup \sem[]{\varphi_2}$ &
      $\sem[]{\varphi_1 \land \varphi_2}$ & $\triangleq$ &
      $\sem[]{\varphi_1} \cap \sem[]{\varphi_2}$ \\
      $\sem[]{\AX \varphi_1}$ & $\triangleq$ & $\set{\sigma \in \Sigma
        \mid \forall \sigma' . \sigma \trel
      \sigma' \Rightarrow \sigma' \in \sem[]{\varphi_1}}$ \\
      $\sem[]{\AF \varphi_1}$ & $\triangleq$ & $\set{\sigma_0 \in \Sigma \mid
        \textrm{for all path}\ (\sigma_i)_{i \in \N}~\exists
      k\in\mathbb{N}.~ \sigma_k\in \sem[]{\varphi_1}}$ \\
      $\sem[]{\AG \varphi_1}$ & $\triangleq$ & $\set{\sigma_0 \in \Sigma \mid
        \textrm{for all path}\ (\sigma_i)_{i \in \N}~\forall
      j\in\mathbb{N}.~ \sigma_j\in \sem[]{\varphi_1}}$ \\
      $\sem[]{\varphi_1 \AU \varphi_2}$ & $\triangleq$ &
      $\set{\sigma_0 \in \Sigma \mid
        \textrm{for all path}\ (\sigma_i)_{i \in \N}~ \exists k \in
        \mathbb{N} . ~ (\sigma_k \in \sem[]{\varphi_2} \land \forall j <
      k . ~ \sigma_j \in \sem[]{\varphi_1})}$ \\
    \end{tabular}
  \end{center}
\end{definition}
%

\subparagraph{Universal fragment of single variable
$\mu$-calculus.}
The modal $\mu$-calculus is a well known extension of propositional modal logic
with least and greatest fixed point operators.  We will focus on its universal
fragment only allowing the $\Box$ modal operator that
quantifies over all transitions. Moreover, for the sake of
simplicity, we restrict to
the single variable fragment where, roughly speaking,
%
nested fixpoints cannot have mutual dependencies.

%
Given a set of atomic propositions $p\in \mathbf{P}$, the
$\mu_\Box$-calculus is defined as follows: 
\begin{center}
  $\mu_\Box \ni \varphi \ ::= \ p \mid \neg p \mid \varphi_1 \lor
  \varphi_2 \mid \varphi_1
  \land \varphi_2
  \mid \Box \varphi_1  \mid x \mid \mu x . \varphi_x \mid \nu x. \varphi_x$
\end{center}
%

%

%

%

%

\begin{definition}[$\mu_\Box$-calculus semantics]
  \label{mu-semantics}
  Given
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$,
  %
  and a valuation $\mathcal{V}: \LVar \to \pow{\Sigma}$,
  the semantics
  %
  $\sem[\mathcal{V}]{\varphi}
  \subseteq \Sigma$ of
  $\mu_\Box$-calculus formulae over $T$ 
  is as follows:
  \begin{center}
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l
      r@{\hspace{2pt}}c@{\hspace{2pt}}l}
      $\sem[\mathcal{V}]{p}$ & $\triangleq$ & $\set{\sigma \in \Sigma
      \mid \sigma \vdash p}$  &  $\sem[\mathcal{V}]{\neg p}$ & $\triangleq$ & $\set{\sigma \in \Sigma
      \mid \sigma \vdash \neg p}$  \\
      $\sem[\mathcal{V}]{\varphi_1 \lor \varphi_2}$ & $\triangleq$ & 
      $\sem[\mathcal{V}]{\varphi_1} \cup
      \sem[\mathcal{V}]{\varphi_2}$ &
      $\sem[\mathcal{V}]{\varphi_1
      \land \varphi_2}$ & $\triangleq$ &
      $\sem[\mathcal{V}]{\varphi_1} \cap \sem[\mathcal{V}]{\varphi_2}$  \\
      %
      %
      %
      $\sem[\mathcal{V}]{\Box \varphi_1}$ & $\triangleq$ & $\set{\sigma
        \in \Sigma \mid \forall \sigma' . \sigma \trel \sigma'
      \Rightarrow \sigma' \in \sem[\mathcal{V}]{\varphi_1}}$ &
      $\sem[\mathcal{V}]{x}$ & $\triangleq$ & $\mathcal{V}(x)$ \\
      $\sem[\mathcal{V}]{\mu x . \varphi_x}$ & $\triangleq$ &
      $\operatorname{lfp}(\lambda S. \llbracket \varphi_x
      \rrbracket_{\mathcal{V}[x \mapsto S]})$ &
      $\sem[\mathcal{V}]{\nu x . \varphi_x}$ & $\triangleq$ &
      $\operatorname{gfp}(\lambda S. \llbracket \varphi_x
      \rrbracket_{\mathcal{V}[x \mapsto S]})$ \\
    \end{tabular}
  \end{center}
  \noindent
  where $\mathcal{V}[x \mapsto S]$ is the usual notation for function update.
\end{definition}

%
\noindent
  We write $\sem[]{\varphi}$ instead of
  $\sem[\mathcal{V}]{\varphi}$ when the valuation is inessential,
and $\sigma\models\varphi$ when $\sigma\in\sem[]{\varphi}$. 
%

%

%

%

%

\section{The Language {$\MOKA$}}
\label{sec:mocha}

%
We define a meta-language, called $\MOKA$ (for $\mathsf{MO}$del
checking as abstract interpretation of $\mathsf{K}$leene $\mathsf{A}$lgebras), as a
(generalised) Kleene Algebra with a
set
of basic expressions suited for identifying counterexamples to the validity of
temporal formulae.
%


\subparagraph{$\kaf$.}
%
We rely on Kozen's Kleene Algebra with
tests~\cite{DBLP:journals/toplas/Kozen97}
%
with
a Fixpoint operator~\cite{DBLP:conf/csl/Leiss91},
$\kaf$ for short.
%
Given a set $\mathsf{Exp}$
of basic expressions $\mathsf{e}$, $\kaf$ is defined below:
\begin{center}
  $\kaf \ni \r  :: = \one \mid \zero \mid \mathsf{e} \mid
  \r_1;\r_2 \mid
  \r_1 \oplus \r_2 \mid \r_1^* \mid \X \mid \upmu \X. \r_1$
\end{center}
The term $\one$ represents the identity, i.e.\ no
action,  $\zero$ represents divergence,
%
$\r_1; \r_2$
represents sequential composition,
%
$\r_1 \oplus \r_2$ represents non-deterministic choice,
%
$\r_1^{*}$ represents the Kleene
iteration of $\r_1$, i.e.\ $\r_1$
%
performed zero or any finite number of times,
%
$\X$ is a variable ranging in a set $\RVar$, and
%
$\upmu \X. \r_1$
represents the least fixpoint
operator with respect to variable $\X$.

Commands are interpreted as functions over a complete
lattice $C$.  Given a semantics
$\bsem{\cdot}: \mathsf{Exp} \to C \to C$ for basic
expressions,
%
the semantics of regular
expressions $\sem{\cdot}: \kaf \to C \to
C$ is
inductively defined as follows, where $\eta: \RVar \to
C \to C$ is an
environment:
\begin{center}
  \begin{tabular}{r c l c c r c l}
    $\sem{\one}$ & $\triangleq$ & $\lambda x.\, x$ & & &
    $\sem{\zero}$ & $\triangleq$ &
    $\lambda x.\, \bot$ \\
    $\sem{\e}$ & $\triangleq$ & $\bsem{\e}$ & & &
    $\sem{\mathsf{r_1; r_2}}$ & $\triangleq$ &
    $\sem{\mathsf{r_2}}\circ \sem{\mathsf{r_1}}$ \\
    $\sem{\mathsf{r_1 \oplus r_2}}$ & $\triangleq$ & $\sem{\mathsf{r_1}}
    \lor \sem{\mathsf{r_2}}$ & & &  $\sem{\mathsf{r_1^*}}$ &
    $\triangleq$ & $ \bigvee
    \set{\sem{\mathsf{r_1}}^k \mid k \in \N}$ \\
    $\sem{\X}$ & $\triangleq$ & $\eta(\X)$ & & &  $\sem{\upmu \X.
    \mathsf{r_1}}$ &
    $\triangleq$ & $\operatorname{lfp}(\lambda
    f: C \to C. \sem[{\eta[\X \mapsto f]}]{\r_1})$ \\
  \end{tabular}
\end{center}

It can be seen that the Kleene star $\r^*$ can be encoded as a
fixpoint  $\upmu \X . (\one \oplus \r; \X)$, 
%
and, when the semantics of basic expressions
$\bsem{\cdot}$ is additive, also as $\r^* = \upmu \X . (\one
\oplus \X; \r)$
(Lemma~\ref{le:encoding-fix2})
while this fails in
general for non-additive semantics (Example~\ref{ex:non-additive-fix}).
%
Even if redundant, we include the Kleene star in our language as it allows to simplify some encodings  whenever the full expressiveness of least fixpoint calculation is not required (see the remark at the end of Section~\ref{sec:s4}). The same applies to the proof logic: as discussed in Section~\ref{sec:lcl}, basic LCL suffices for the fragment of $\kaf$ without least fixpoint operator, while the extension $\upmu$LCL is needed for dealing with the full language.
%
For closed $\kaf$ terms the environment is inessential
and we write just $\sem[]{\mathsf{r}}$ instead of $\sem{\mathsf{r}}$.
%
\begin{toappendix}
  \begin{lemma}
    \label{le:additivity-regular-expressions}
    If the semantics of the basic expressions
    is additive and $\eta$ maps each variable to an
    additive function, then $\sem{\r}$ is additive for any $\kaf$ term $\r$.
  \end{lemma}

  \begin{proof}

    We want to prove that, for any $\kaf$ term $\r$ and any $\a, \b \in C$, 
    it holds $\sem{\r}(\a \lor \b) = \sem{\r}\a \lor \sem{\r}\b$.
    The proof is by structural induction on the term $\r$.
    Let $\a, \b \in C$.

    \subparagraph*{($\r = \e$)} $\sem{\e} = \bsem{\e}$ is additive by
    hypothesis.

    \subparagraph*{($\r = \r_1; \r_2$)} By inductive hypothesis $\sem{\r_1},
    \sem{\r_2}$ are additive. Since the composition of additive functions is additive, so is 
    $\sem{\r_1; \r_2}=\sem{\r_2}\circ \sem{\r_1}$.

%

%

%

    \subparagraph*{($\r = \r_1 \oplus \r_2$)} By inductive hypothesis $\sem{\r_1},
    \sem{\r_2}$ are additive. Since the join of additive functions is additive, so is 
    $\sem{\r_1\oplus \r_2}=\sem{\r_1}\vee \sem{\r_2}$.

%

%

%

    \subparagraph*{($\r = \r_1^*$)} 
    By definition $\sem{\r_1^*} = \bigvee_k \set{\sem{\r_1}^k \mid k
    \in \N}$, where $\sem{\r_1}$ is additive 
    by inductive hypothesis.
    First, we observe that each $\sem{\r_1}^k$ is additive is additive because it is the composition of $k$ additive functions.
    %
    And then we can conclude because the join of additive
    functions is additive.

    \subparagraph*{($\r = \X$)} $\sem{\X} = \eta(\X)$
    is additive by the hypothesis on $\eta$.  

    \subparagraph*{($\r = \upmu \X. \r_1$)} Let $G : C^C \to C^C$ be defined by
    $G(f) = \sem[{\eta[\X \mapsto f]}]{\upmu \X. \r_1}$. Then by Kleene
    fixpoint theorem we have $\sem{\r} = \operatorname{lfp}(G) =
    G^\alpha(\bot_\to)$ for some
    ordinal $\alpha$, where $\bot_\to = \lambda c.\, \bot_{C}$. We prove
    the statement by transfinite induction.

    \begin{itemize}
      \item If $\alpha = 0$ we have $G^0(\bot_\to) = \bot_\to$
        which is additive.
      \item If $\alpha = n + 1$ (non-limit ordinal) we have
        \begin{align*}
          G^{n+1}(\bot_\to)(\a \lor \b)
          & = G(G^n(\bot_\to)(\a \lor \b))
          & [\mbox{definition of $G$}] \\
          & = G ( G^n(\bot_\to)(\a) \lor
          G^n(\bot_\to)(\b) ) & [\mbox{inductive hypothesis}] \\
          & = G ( G^n(\bot_\to)(\a) ) \lor
          G  ( G^n(\bot_\to)(\b)  )
          & [\mbox{inductive hypothesis}] \\
          & =  G^{n+1}(\bot_\to)(\a) \lor
          G^{n+1}(\bot_\to)(\b)
          & [\mbox{definition of  $G^{n+1}$}] \\
        \end{align*}
      \item If $\alpha$ is a limit ordinal we have
        \begin{equation*}
          G^{\alpha}(\bot_\to) = \bigvee_{\beta \leq \alpha}
          G^{\beta}(\bot_\to)
        \end{equation*}
        which is additive since it is the join of additive functions
        (by inductive hypothesis).
    \end{itemize}
  \end{proof}


  \begin{lemma}
    \label{le:encoding-fix}
    The encoding of $\r^*$ as $\upmu \X. (\one \oplus \r; \X)$ is correct.
  \end{lemma}
  \begin{proof}
    Observe that $\sem{\upmu \X. (\one \oplus \r; \X)} =
    \operatorname{lfp}(G)$ where $G: C^C \to C^C$  
    is defined by
    \begin{center}
      $G(f) = \sem[{\eta[\X \mapsto f]}]{\one \oplus \r; \X}
      = \lambda c.\, c \lor f(\sem{\r}c)$
    \end{center}
    Let $\bot_\to = \lambda c. \bot_{C}$  be the bottom element of
    $C^{C}$. One can show that $G^0(\bot_\to) = \bot_\to$ and, inductively,

    \[
      G^n(\bot_\to) = \lambda c.\, \bigvee_{i \leq n-1} \sem{\r}^i(c).
    \]
    Therefore
    $\sem{\upmu \X. (\one \oplus \r; \X)} = \operatorname{lfp}(G) =
    G^\omega(\bot_\to) = \lambda c.\, \bigvee_{i < \omega}
    \sem{\r}^i(c) = \sem{\r^*}$.
  \end{proof}

  \begin{lemma}
    \label{le:encoding-fix2}
    When the semantics is additive $\r^*$ can be also encoded as
    $\upmu \X. (\one \oplus \X;r)$
  \end{lemma}
  \begin{proof}
    Observe that $\sem{\upmu \X. (\one \oplus \X;\r)} =
    \operatorname{lfp}(G)$ where $G: C^C \to C^C$ is defined by
   \begin{center}
      $G(f) = \sem[{\eta[\X \mapsto f]}]{\one \oplus \X;\r}
      = \lambda c.\, c \lor \sem{\r}(f(c))$
    \end{center}
    Let $\bot_\to = \lambda c. \bot_C$  be the bottom element of
    $C^C$. One can show that $G^0(\bot_\to) = \lambda c.\, c$
    and, inductively,
    \[
      G^n(\bot_\to) = \lambda c.\, \bigvee_{i \leq n} \sem{\r}^i(c).
    \]
    In fact,
    $G^{n+1}(\bot_\to) = G(G^n(\bot_\to)) = \lambda c.\, c \lor
    \sem{\r}(\bigvee_{i \leq n} \sem{\r}^i(c)) = \lambda c.\, c \lor
    \bigvee_{i \leq n} \sem{\r}^{i+1}(c) = \lambda c.\, \bigvee_{i
    \leq n+1} \sem{\r}^i(c)$, where the second last passage is
    allowed by additivity of $\sem{\r}$.
%
    Hence we conclude as in Lemma~\ref{le:encoding-fix}.
  \end{proof}

  \begin{example}[Non-additive $f$ fixpoint encoding]
    \label{ex:non-additive-fix}
    The equation $\r^* = \upmu \X . (\one \oplus \r;\X)$ does not
    generally hold if the semantics is not additive. Consider for
    example $U=\set{a, b, c}$ and the function
    $u: \pow{U} \to \pow{U}$ such that
    $u(\set{a,b}) = u(U) = U$, $u(S) = \set{b}$
    for any other $S \in \pow{U}$ and let $\mathsf{u}$ be a basic
    expression such that $\bsem{\mathsf{u}}=u$. Then
    \begin{align*}
      \sem{\e}^*(\set{a})
      & = \set{a} \cup u^1(\set{a})
      \cup u^2(\set{a}) \cup \dots \\
      & = \set{a} \cup \set{b} \cup u(\set{b}) = \set{a, b}
    \end{align*}
    while instead
    $\sem{\upmu \X . (\one \oplus \X;\mathsf{u})}= \operatorname{lfp}(G)$
    where, for $f : \pow{\set{a,b,c}} \to  \pow{\set{a,b,c}}$ it holds
    \begin{center}
      $G(f) = \sem[{[X \mapsto \beta]}]{\one \oplus \X;\mathsf{u}} = \lambda
      S.\, (S \cup u(f(S)))$
    \end{center}
    If we denote by $\bot = \lambda S.\, \varnothing$ we have
    \begin{align*}
      G^1(\bot) & = \lambda S.\ S \cup \set{b} \\
      G^2(\bot) & = \lambda S.\ S \cup u(S \cup \set{b})
      % 
      % 
    \end{align*}
    One can see that $G^2(\bot)(S) = U$ if $a \in S$, 
      while $G^2(\bot)(S)=S \cup \set{b}$ otherwise. 
      %
      Therefore,      
      $G^2(\bot) = \operatorname{lfp}(G)$ and
      thus $\sem{\upmu \X . (\one \oplus \X;\mathsf{u})}(\set{a}) =
      G^2(\bot)(\set{a}) = U \supsetneq \sem{\mathsf{u}}^*(\set{a})$.
      \qed
    \end{example}
  \end{toappendix}
