  \begin{toappendix}
    %
    %
    We write $\subst{\r}{\X}{\s}$ for the (capture
    free) substitution of the free occurrences of $\X$ for $\s$ in $\r$.

    %

    \begin{lemma}[Substitution lemma]
      \label{le:substitution-lemma}
      Let $\eta$ be an environment, $\r, \s$ be $\kaf$ terms,
      $\X \in \RVar$. Then we have
      $\llbracket \r
        \rrbracket_{\eta[\X\mapsto\sem{\s}]} =
        \sem{\subst{\r}{\X}{\s}}$.
       \end{lemma}

    \begin{proof}
      The proof goes by structural induction on $\r$.

      \subparagraph*{($\r = \e$)}
      In this case $\llbracket
      \e\rrbracket_{\eta[\X \mapsto \sem{\s}]} =
      \sem{\e} = \sem{\subst{\e}{\X}{\s}}$.

      \subparagraph*{($\r = \Y$)}
      If $\Y=\X$ then $\llbracket \X\rrbracket_{\eta[\X
      \mapsto \sem{\s}]} =
      \eta[\X \mapsto \sem{\s}](\X) = \sem{\s} =
      \sem{\subst{\X}{\X}{\s}}$. Otherwise
      $\llbracket \Y\rrbracket_{\eta[\X
      \mapsto \sem{\s}]} =
      \eta[\X \mapsto \sem{\s}](\Y) = \eta(\Y) =
      \sem{\subst{\Y}{\X}{\s}}$

      \subparagraph*{($\r = \ \r_1 \oplus \r_2$)} 
      %
      %
      %
      %
      %
      Let $c \in C$. We have
      \begin{align*}
        \llbracket \r_1 \oplus \r_2 \rrbracket_{\eta[\X \mapsto
        \sem{\s}]} (c)
        & =
        \llbracket \r_1\rrbracket_{\eta[\X \mapsto \sem{\s}]} (c)
        \vee \llbracket \r_2\rrbracket_{\eta[\X \mapsto
        \sem{\s}]} (c) \\
        & \overset{\clubsuit}{=} \sem{\subst{\r_1}{\X}{\s}}c \vee
        \sem{\subst{\r_2}{\X}{\s}}c \\
        & = \sem{\subst{\r_1}{\X}{\s} \oplus
        \subst{\r_2}{\X}{\s}}c \\
        & = \sem{\subst{(\r_1 \oplus \r_2)}{\X}{\s}}c
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis.
      \subparagraph*{($\r = \ \r_1; \r_2$)} 
      %
      %
      %
      %
      %
      %
      %
      \begin{align*}
        \llbracket \r_1 ; \r_2 \rrbracket_{\eta[\X \mapsto \sem{\s}]}
        & = \llbracket \r_2 \rrbracket_{\eta[\X \mapsto \sem{\s}]}
        \circ \llbracket \r_1 \rrbracket_{\eta[\X \mapsto
        \sem{\s}]} \\
        & \overset{\clubsuit}{=} \sem{\subst{\r_2}{\X}{\s}} \circ
        \sem{\subst{\r_1}{\X}{\s}}  \\
        & = \sem{\subst{\r_1}{\X}{\s} ; \subst{\r_1}{\X}{\s}} \\
        & = \sem{\subst{(\r_1; \r_2)}{\X}{\s}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis.
      \subparagraph*{($\r = \upmu \Y. \r_1$)} 
      %
      %
      %
      %
      %
      If $\Y=\X$, i.e., $\r = \upmu \X. \r_1$ then we conclude trivially
      since $\subst{(\upmu \X . \r_1)}{\X}{\s} = \upmu \X .
      \r_1$, and thus:
      \begin{align*}
        \llbracket \upmu \X . \r_1 \rrbracket_{\eta[\X
        \mapsto \sem{\s}]}
        & = \sem{\upmu \X . \r_1} 
        %
        = \sem{\subst{(\upmu \X . \r_1)}{\X}{\s}}
      \end{align*}
      as desired, where, in the first equality, we used the fact that if $\eta(\Y) =
      \eta'(\Y)$ for all
      $\Y \in \mathsf{fv}(\r)$ then $\sem{\r} = \sem[\eta']{\r}$.

      \noindent
      Let instead $\r = \upmu \Y. \r_1$ with $\Y \neq \X$. By alpha-renaming, we can assume without
      loss of generality $\Y \notin \mathsf{fv}(\s)$. Then, letting 
      $F(g) = \llbracket \r_1  \rrbracket_{\eta[\X \mapsto
        \sem{\s}][\Y \mapsto g]}$,
      by definition of least fixpoint we
      have
%

%

%
      \begin{align*}
        \llbracket\upmu \Y. \r_1  \rrbracket_{\eta[\X \mapsto \sem{\s}]}
        & = \bigwedge \set{g \mid F(g) \leq g} \\
        & = \bigwedge \set{g \mid \llbracket \r_1
          \rrbracket_{\eta[\X \mapsto \sem{\s}][\Y \mapsto g]}
        \leq g} \\
        & = \bigwedge \set{g \mid \llbracket \r_1
          \rrbracket_{\eta[\Y \mapsto g][\X \mapsto \sem{\s}]}
        \leq g} \\
        & \overset{\clubsuit}{=} \bigwedge \set{\llbracket \subst{\r_1}{\X}{\s}
        \rrbracket_{\eta[\Y \mapsto g]} \leq g} \\
        & = \sem{\upmu \Y . (\subst{\r_1}{\X}{\s})} \\
        & = \sem{\subst{(\upmu \Y . \r_1)}{\X}{\s}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis.
      \hfill
    \end{proof}

    \begin{remark}
      Notice that
      $\sem{\upmu \X . \r} = \sem{\subst{\r}{\X}{\upmu \X.\r}} =
      \llbracket \r
      \rrbracket_{\eta[\X\mapsto\sem{\upmu \X . \r}]}$ where the first
      equality follows from the substitution lemma
      (Lemma~\ref{le:substitution-lemma}), while
      $ \sem{\upmu \X . \r} = \llbracket \r
      \rrbracket_{\eta[\X\mapsto\sem{\upmu \X . \r}]}$ since
      if we define
      $F_{\r} : C^C \to C^C$ 
      to be such that
      $F_{\r}(f) = \llbracket \r \rrbracket_{\eta[\X
      \mapsto f]}$ then
      $\sem{\upmu \X . \r} = \operatorname{lfp}(F_{\r})$ by definition,
      hence
      $\sem{\upmu \X . \r} = F_{\r} \Bigl ( \sem{\upmu \X . \r} \Bigr)=
      \llbracket \r \rrbracket_{\eta[\X\mapsto\sem{\upmu \X . \r}]}$.
    \end{remark}

  \end{toappendix}

