  \subparagraph{The Language $\MOKA$.} Given a transition system
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, 
  $\MOKA$ is an instance of $\kaf$ interpreted
  over stacks of frames,
  each frame representing a computation path. %
  %

  \begin{definition}[Frame, stack]
    A \emph{frame} is a pair
    $\frame{\sigma, \Delta} \in \Sigma \times \pow{\Sigma}$. We
    denote by $\operatorname{F}_{\Sigma}$ the set of frames. A
    \emph{stack} is a finite non-empty sequence of frames, i.e.
    an element of
    $\str{\operatorname{F}_{\Sigma}}$,
    %
    %
    denoted by $\frame{\sigma, \Delta}\concat S$, where $S$
    is a stack or the empty sequence $\varepsilon$.
  \end{definition}

  A frame $\frame{\sigma, \Delta}$ represents
  a computation in $T$ where $\sigma$ is the current state and $\Delta$
  is the set of
  traversed states, used for loop-detection.   The
  order of the traversed states and their possible multiple occurrences
  are abstracted
  away as they are irrelevant when checking the satisfaction of a
  formula. Frames are stacked to deal with formulae with
  nested operators.

  The language ${\MOKA}$ is defined as instance of $\kaf$ with basic expressions
  for extending and filtering
  %
  frames, for (de)constructing
  %
  stacks, and to keep
  track of fixed-point equations. \label{ref:mocha-b.e.}

  \begin{definition}[$\MOKA$ language]
    The language $\MOKA$ is an instance of
    $\kaf$ with the
    following basic expressions, where $\ps$ ranges over atomic
    propositions:
    \begin{center}
      $\e :: = \p \mid \np \mid \loops \mid \nexte \mid \add \mid \reset
      \mid  
      %
      \push \mid \pop$
      %
      %
      %
    \end{center}
  \end{definition}

  The (concrete) semantics of $\MOKA$ is given over the powerset of the
  set of stacks, $C = \pow{\str{\operatorname{F}_{\Sigma}}}$,
  ordered by subset inclusion.
  %
  Although we could focus on stacks of uniform length, we use a larger domain to simplify the notation.

  %

  The semantics of $\MOKA$ commands
  $\sem{\r} : \pow{\str{\operatorname{F}_{\Sigma}}} \to
  \pow{\str{\operatorname{F}_{\Sigma}}}$ follows from the general
  definition for $\kaf$, once we specify the
  semantics of its basic expressions.

  \begin{definition}[Basic expression semantics]
  Given 
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$,
    the semantics of $\MOKA$ basic expressions 
     is
    %
    the additive extension of the functions below, where
    %
    %
    $\frame{\sigma, \Delta}\concat S \in \str{\operatorname{F}_{\Sigma}}$:
    \begin{center}
      \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l
        r@{\hspace{2pt}}c@{\hspace{2pt}}l}
        $\bsem{\p}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma, \Delta}\concat S \mid \sigma \vdash p }$
        & $\bsem{\np}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma, \Delta}\concat S \mid \sigma \vdash \neg p }$
        \\ 
        %
        $\bsem{\loops}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma, \Delta}\concat S \mid \sigma \in \Delta }$ &
        $\bsem{\nexte}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma', \Delta}\concat S \mid \sigma
        \trel \sigma' }$ \\
        %
        $\bsem{\add}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma, \Delta \cup \set{\sigma}}\concat S }$
        %
        & $\bsem{\reset}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{\frame{\sigma, \varnothing}\concat S }$ \\
        %
        %
        %
        %
        %
        %
        $\bsem{\push}\set{\frame{\sigma, \Delta} \concat S}$ & $\triangleq$
        & $\set{ \frame{\sigma, \Delta}\concat\, \frame{\sigma,
        \Delta}\concat S }$
        & $\bsem{\pop}\set{\frame{\sigma, \Delta} \concat S}$ &
        $\triangleq$ & $\set{S \mid S \neq \varepsilon}$
      \end{tabular}
    \end{center}
  \end{definition}

  The basic expressions $\p$, $\np$, $\loops$, $\nexte$,
  $\add$, $\reset$  %
  operate on the top frame.
  %
  The filter $\p$ (resp. $\np$) checks the validity of the
  proposition $p$ (resp. $\neg p$),  $\loops$
  %
  checks if the
  current state loops
  %
  back
  to some state in
  the trace, $\nexte$ extends the trace by
  one step in all possible ways, $\add$ adds
  the current state to the trace and  $\reset$ empties
  the trace.
  %
  Instead,  $\push$ and
  $\pop$ change the stack length:
  %
  $\push$ extends the  stack to start a new
  trace, while 
  %
  $\pop$ restores the previous trace
  from the stack.
  %
  Given a set of states $X \subseteq \Sigma$, we  write
  $\sem{\r}X$ as a shorthand for
  $\sem{\r}(\set{\frame{\sigma, \varnothing} \mid \sigma \in X})$.
  %

  %

  \section{Formulae as $\MOKA$ programs}
  \label{sec:s4}

  We show that ACTL and $\mu_\Box$-calculus formulae $\varphi$
  can be transformed into
  $\MOKA$ programs $\PtoR{\varphi}$
  so that for any transition system $T$, the semantics
  of $\PtoR{\varphi}$ over $T$ consists exactly of
  the counterexamples to the validity of $\varphi$, that is, the states
  which do not satisfy $\varphi$.

  %

  \begin{theorem}[Model checking as program verification]
    \label{th:counterexamples-general}
    %
    Given 
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$,
    for any ACTL or $\mu_{\Box}$ formula 
    $\varphi$ 
    %
    %
    and set of stacks $P \subseteq \str{\operatorname{F}_{\Sigma}}$,
    it holds
    $\sem{\PtoR{\varphi}} P = \set{\frame{\sigma,\Delta}\concat S \in
      P \mid \sigma \not\models \varphi}.$
    %
  \end{theorem}

\noindent
It follows that $\sem{\PtoR{\varphi}} P\subseteq P$ and that $\sem{\PtoR{\varphi}}\{\sigma\}  = \varnothing$ iff $\sigma \models \varphi$. 
%
It is also worth noting that
%
the semantics of $\MOKA$
programs encoding formulae is a lower closure on sets of states, being
monotone, reductive and idempotent (and it preserves arbitrary
unions)~\cite[Section~3.2.3]{mine17}.
%
In this respect, it behaves analogously to the collecting semantics of
Boolean tests which filter out memory states, keeping only those that
satisfy the condition. As a consequence, similarly to what happens
when abstracting Boolean tests, in any abstract domain $A$
approximating sets of states the identity $\lambda a\in A.\, a$, is a
correct (over-)approximation of $\sem{\PtoR{\varphi}}$.

  %
  \subparagraph{ACTL as $\MOKA$.}
  %
  To each ACTL formula $\varphi$ we assign the $\MOKA$ program
  $\PtoR{\varphi}$
  %
  as follows:
  \begin{center}
    %
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l@{\hspace{-130pt}}r@{\hspace{2pt}}c@{\hspace{2pt}}l}
      $\PtoR{\,p}$ & $\triangleq$ & $\np$ & $\PtoR{\,\neg p}$ & $\triangleq$ & $\p$
      \\
      $\PtoR{\varphi_1\land \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_1} \oplus \PtoR{\varphi_2}$
      &
      $\PtoR{\varphi_1\lor \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_1} ; \PtoR{\varphi_2}$ \\
      %
      %
      %
      %
      %
      %
      %
      $\PtoR{\AX \varphi}$ & $\triangleq$ & $\push; 
      \nexte;\PtoR{\varphi}; \pop$ \\
      $\PtoR{\AF \varphi}$ & $\triangleq$ & $\PtoR{\varphi};
      \push; \reset; \left (\add; \nexte;
      \PtoR{\varphi} \right )^*; \loops; \pop$ \\
      $\PtoR{\AG \varphi}$ & $\triangleq$ & $\push;
      \nexte^*;\PtoR{\varphi}; \pop$ \\
      $\PtoR{\varphi_1 \AU \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_2}; \push; \reset; \left
      (\add; \nexte;
      \PtoR{\varphi_2} \right )^*; \left ( \loops \oplus
      \PtoR{\varphi_1} \right ); \pop$ \\
    \end{tabular}
  \end{center}
  %

  The proof of the correctness of this transform can be found in the appendix as Theorem~\ref{th:actl-program}.
  The intuition is that  $\MOKA$ programs $\PtoR{\varphi}$ act
  as (negative) filters: applied to a set of
  frames $\frame{\sigma, \Delta}\concat S$, each
  representing a computation that reached state $\sigma$, they
  filter out states where $\varphi$ is satisfied, keeping only candidate
  counterexamples to the validity of $\varphi$.
  %
  In general, when the check requires exploring
  the future of the current state, a new frame 
  %
  is started with $\push$;
  %
  if the search is successful, a
  closing $\pop$ recovers the starting state violating the formula.
  %
  We explain the main clauses defining 
  $\PtoR{\varphi}$.
  %
  It turns out 
  that $\frame{\sigma, \Delta}\concat S$ is a counterexample for
  \begin{itemize}

    \item $\AX \varphi$ if $\varphi$ is violated in at least
      one successor state of $\sigma$ (as computed by
      $\nexte;\PtoR{\varphi}$). %
      %
      %
      %
      %

    \item $\AF \varphi$ if there is an infinite trace where
      $\varphi$ never holds. This is encoded by saying that
      $\varphi$ does not hold in the current state,
      i.e.\ $\PtoR{\varphi}$,
      and after that, there is an infinite trace traversing only states
      %
      (collected through the command
      $(\add; \nexte;\PtoR{\varphi})^{*}$) that do not satisfy
      $\varphi$. %
      Since we deal with finite state
      systems, infinite
      traces can be identified with looping traces (whence the check
      $\loops$); for this to work, after the $\push$ we $\reset$ the past.

    \item $\AG\varphi$ if we can reach, by repeatedly applying $\nexte$,
      a counterexample to $\varphi$.
      %
      %

    \item $\varphi_1\AU\varphi_2$ if $\varphi_2$ does not hold in the
      current state, i.e.\ $\PtoR{\varphi_2}$, and progressing through
      states that do not satisfy $\varphi_2$ with
      $(\add; \nexte;\PtoR{\varphi_2})^{*}$, either we detect a
      maximal (looping) trace or a state where $\varphi_1$ does not
      hold.
  \end{itemize}


  \begin{example}[Control flow graphs and ACTL encoding]\label{ex:actl} 
    In our running example (see Examples~\ref{ex:cfg}
    and~\ref{ex:lts}), we check the property stating that if
    the program {\tt{c}} terminates then
    the variable $z$ is zero, which in the CFG means
    \emph{``when the exit node $e$ is reached, $z = 0$''} holds. This
    is expressed by
    the \ACTL formula  
    $\varphi = \AG(n = e \to z = 0)$, where we use $p \to \varphi'$ as syntactic sugar for $\neg p \lor \varphi'$.
    The corresponding $\MOKA$ program is:
    $\mathsf{m}_{\varphi} \triangleq \PtoR{\varphi} = \PtoR{\AG (n = e \to z = 0)} = \push; \nexte^*;
    \mathsf{n = e ?} ; \mathsf{z \neq 0?}; \pop$. \qed
  \end{example}

  \begin{toappendix}
    %
    \subparagraph*{ACTL as $\MOKA$}
    \begin{theorem}[Formula satisfaction as program verification
      - ACTL version]
      \label{th:actl-program}
      Given 
      $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, for all frames $\frame{\sigma, \Delta}\concat S \in
      \str{\operatorname{F}_{\Sigma}}$,
      for any \emph{ACTL} formula $\varphi$  and any
      environment $\eta$ it holds: 
      \begin{equation*}
        \sem[]{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
        \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi}}
        %
        %
        %
        %
      \end{equation*}
    \end{theorem}

    \begin{proof}
      %
      %
      %
      %
      %
      %
      We proceed by structural induction on $\varphi$. 
      %
      %

      In the proof we use the shorthand $\sigma\trel^n \sigma_n$ in place of
      $\sigma = \sigma_0 \trel \sigma_1 \trel \dots \trel \sigma_n$ leaving implicit the states
      $\sigma_0,...\sigma_{n-1}$. Similarly, we write $\sigma\trel_\exists^n \sigma_n$ 
      for $\exists \sigma_0,\ldots,\sigma_{n-1}.~\sigma\trel^n \sigma_n$.

      \subparagraph*{($\varphi=p$) or ($\varphi = \neg p$)}
      Trivial, by definition.
%
      \subparagraph*{($\varphi= \varphi_1 \land \varphi_2$ or
      $\varphi= \varphi_1 \lor \varphi_2$)} 
      Just follows using De Morgan's law assuming the
      inductive hypothesis (for $i\in \set{1, 2}$):
      \begin{center}
        $\forall \sigma,\Delta,S.~\sem[]{\PtoR{\varphi_i}}
        \set{\frame{\sigma,
        \Delta}\concat S} = \set{\frame{\sigma, \Delta}\concat S \mid
        \sigma \notin \sem[]{\varphi_i}}$
      \end{center}
%
      \subparagraph*{($\varphi=\AX\varphi_1$)} 
      %
      %
      %
      %
      %
      %
      %
      \begin{align*}
        \sem[]{\PtoR{\AX\varphi_1}}\set{\frame{\sigma, \Delta}\concat S}
        & =
        \sem[]{\push;\nexte;\PtoR{\varphi_1};\pop}\set{\frame{\sigma,
        \Delta}\concat S} \\
        %
        & =
        \sem[]{\nexte;\PtoR{\varphi_1};\pop}\set{
        \frame{\sigma,\Delta}\concat\,
        \frame{\sigma,\Delta}\concat 
        S} \\
        %
        & = \sem[]{\PtoR{\varphi_1};\pop}\set{
               \frame{\sigma',\Delta}\concat\,
               \frame{\sigma, \Delta}\concat 
               S
          \mid \sigma
        \trel \sigma'}\\
        %
        & \overset{\clubsuit}{=} \sem[]{\pop}\set{
        \frame{\sigma', \Delta}\concat\,
          \frame{\sigma, \Delta}\concat 
          S \mid \sigma \trel
          \sigma', \ \sigma'
        \notin \sem[]{\varphi_1}}\\
        %
        & = \set{\frame{\sigma, \Delta}\concat S \mid \exists \sigma' \notin \sem[]{\varphi_1}.~
          \sigma \trel
        \sigma'} \\
        %
        & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma\notin
        \sem[]{\AX \varphi_1}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis about $\varphi_1$.

      \subparagraph*{($\varphi=\AG\varphi_1$)} 
      %
      %
      %
      %
      %
      %
      %
      %
      \begin{align*}
        \sem[]{\PtoR{\AG\varphi_1}} \set{\frame{\sigma,
        \Delta}\concat S} & =
        \sem[]{\push;\nexte^{*};\PtoR{\varphi_1};\pop}
        \set{\frame{\sigma, \Delta}\concat S}\\
        %
        & = \sem[]{\nexte^{*};\PtoR{\varphi_1};\pop}\set{\frame{\sigma,
        \Delta}\concat\, \frame{\sigma, \Delta}\concat S}\\
        %
        & = \sem[]{\PtoR{\varphi_1};\pop}\left (\sem[]{\nexte^{*}}
          \set{\frame{\sigma, \Delta}\concat\,
            \frame{\sigma, \Delta} \concat
        S} \right )\\
        %
        & = \sem[]{\PtoR{\varphi_1};\pop} \left ( \bigcup_{n \in \N}
          (\sem[]{\nexte})^n\set{\frame{\sigma, \Delta}\concat\,
        \frame{\sigma, \Delta}\concat S} \right )\\
        %
        & = \sem[]{\PtoR{\varphi_1};\pop}\left( \bigcup_{n \in \N}
          \set{\frame{\sigma_n, \Delta} \concat\,
            \frame{\sigma, \Delta}
            \concat S \mid \sigma {\textstyle \trel_\exists^n} \sigma_{n}
            %
            } \right ) \\
        %
        & \overset{\clubsuit}{=} \sem[]{\pop}\left ( \bigcup_{n \in \N}
          \set{\frame{\sigma_n, \Delta} \concat\,
            \frame{\sigma, \Delta}
            \concat S \mid \sigma {\textstyle \trel_\exists^n} \sigma_n,
            %
        \ \sigma_n \notin \sem[]{\varphi_1}}\right ) \\
        %
        & = \set{\frame{\sigma, \Delta}\concat S \mid 
        \exists n,\sigma_n.~\sigma {\textstyle \trel_\exists^n} \sigma_n,
        %
        \ \sigma_n \notin
        \sem[]{\varphi_1}} \\
        %
        & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\AG \varphi_1}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis about $\varphi_1$.

      \subparagraph*{($\varphi=\varphi_1\AU\varphi_2$)} 
      %
      %
      %
      %
      %
      %
      %
      %
      \begin{align*}
        & \sem[]{\PtoR{\varphi_1\AU\varphi_2}}
        \set{\frame{\sigma, \Delta}\concat S} \\
        & \qquad =
        \sem[]{\PtoR{\varphi_2};\push;\reset;(\add;\nexte;\PtoR{\varphi_2})^{*};(\PtoR{\varphi_1}
        \oplus \loops);\pop} \set{\frame{\sigma, \Delta}\concat S}\\
        %
        & \qquad \overset{\clubsuit}{=}
        \sem[]{\push;\reset;(\add;\nexte;
          \PtoR{\varphi_2})^{*};(\PtoR{\varphi_1} \oplus
        \loops);\pop} \set{\frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \sem[]{\varphi_2}}\\
        %
        & \qquad =  \sem[]{(\add;
          \nexte;\PtoR{\varphi_2})^{*};(\PtoR{\varphi_1}
        \oplus \loops);\pop} \set{\frame{\sigma, \varnothing} \concat\,
          \frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi_2}}\\
        %
        & \qquad =  \sem[]{(\PtoR{\varphi_1} \oplus \loops);\pop} \left (
          \sem[]{(\add; \nexte;\PtoR{\varphi_2})^{*}}\set{\frame{\sigma,
            \varnothing}\concat\, \frame{\sigma, \Delta}\concat
            S \mid \sigma
        \notin \sem[]{\varphi_2}} \right )\\
        %
        & \qquad =  \sem[]{(\PtoR{\varphi_1} \oplus \loops);\pop} \left (
          \bigcup_{n \in \N}(\sem[]{(\add;\nexte;
            \PtoR{\varphi_2})})^{n}\set{\frame{\sigma,
              \varnothing}\concat\, \frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \sem[]{\varphi_2}}  \right )\\
        %
        & \qquad \overset{\clubsuit}{=} \sem[]{(\PtoR{\varphi_1} \oplus \loops);\pop} \Biggl(
          \bigcup_{n \in \N} \left \{\frame{\sigma_n, \set{\sigma_0,
            \dots, \sigma_{n-1}}}\concat\, \frame{\sigma, \Delta} \concat
            S \mid \sigma {\textstyle \trel^n} \sigma_{n}, \right . \\
            & \hspace{150pt} \left .  \forall i \in [0, n].~ \sigma_i
        \notin \sem[]{\varphi_2} \right \}  \Biggr) \\
        %
        & \qquad \overset{\heartsuit}{=}  \sem[]{\pop} \Biggl( \bigcup_{n \in \N} \left \{
            \frame{\sigma_n, \set{\sigma_0, \dots,
            \sigma_{n-1}}} \concat\,
            \frame{\sigma, \Delta}\concat S \mid \sigma {\textstyle \trel^n} \sigma_n, \right . \\ 
            %
            & \hspace{100pt} \left . \forall i \in [0, n].~ \sigma_i
            \notin \sem[]{\varphi_2}, \ (\sigma_n \notin \sem[]{\varphi_1}
            \ \lor \ \exists i \in [0, n-1] \ \sigma_n = \sigma_i)
        \right \} \Biggr) \\
        %
        & \qquad =  \left \{\frame{\sigma, \Delta}\concat S \mid
        \exists n,\sigma_n.~\sigma {\textstyle \trel_\exists^n} \sigma_n,
          %
          %
          \ \forall i \in [0,
          n]. \ \sigma_i \notin \sem[]{\varphi_2}, 
          \right . \\
          & \hspace{150pt} \left . 
          (\sigma_n \notin \sem[]{\varphi_1}
            \lor \exists i \in [0, n-1] .~
        \sigma_n = \sigma_i) \right \} \\
        %
        & \qquad =  \set{\frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \sem[]{\varphi_1 \AU \varphi_2}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis about $\varphi_2$ and at $(\heartsuit)$ about $\varphi_1$.
      For the last step observe that finiteness of the transition system
      plays an essential role. In fact, in order to falsify
      $\varphi_1\AU\varphi_2$ a state $\sigma$ has to admit a finite
      trace $\sigma=\sigma_0 \trel \cdots \trel \sigma_n$ where $\varphi_2$ is
      never satisfied leading to a state which does not satisfy
      $\varphi_1$, or it can admit an infinite trace where
      $\varphi_2$ is
      never satisfied: since the transition system is finite such an
      infinite trace must eventually be a cycle.

     \subparagraph*{($\varphi=\AF\varphi_1$)}
      Analogous to the previous case, as we have:
      %
      %
      %
      %
      %
      %
      %
      %
      \begin{align*}
        & \sem[]{\PtoR{\AF \varphi_1}}
        \set{\frame{\sigma, \Delta}\concat S} \\
        & \qquad =
        \sem[]{\PtoR{\varphi_1};\push;\reset;(\add;\nexte;\PtoR{\varphi_1})^{*}; \loops;\pop} \set{\frame{\sigma, \Delta}\concat S}\\
        %
        & \qquad \overset{\clubsuit}{=}
        \sem[]{\push;\reset;(\add;\nexte;\PtoR{\varphi_1})^{*};
        \loops;\pop} \set{\frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \sem[]{\varphi_1}}\\
        %
        & \qquad =  \sem[]{(\add;
          \nexte;\PtoR{\varphi_1})^{*}; \loops;\pop} \set{\frame{\sigma, \varnothing} \concat\,
          \frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi_1}}\\
        %
        & \qquad =  \sem[]{\loops;\pop} \left (
          \sem[]{(\add; \nexte;\PtoR{\varphi_1})^{*}}\set{\frame{\sigma,
            \varnothing}\concat\, \frame{\sigma, \Delta}\concat
            S \mid \sigma
        \notin \sem[]{\varphi_1}} \right )\\
        %
        & \qquad =  \sem[]{\loops;\pop} \left (
          \bigcup_{n \in \N} (\sem[]{(\add; \nexte;\PtoR{\varphi_1})})^{n}\set{\frame{\sigma,
              \varnothing}\concat\, \frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \sem[]{\varphi_1}}  \right )\\
        %
        & \qquad \overset{\clubsuit}{=} \sem[]{\loops;\pop} \Biggl(
          \bigcup_{n \in \N} \left \{\frame{\sigma_n, \set{\sigma_0,
            \dots, \sigma_{n-1}}}\concat\, \frame{\sigma, \Delta} \concat
            S \mid 
            \sigma\trel^n \sigma_n,
            %
            \right . \\
            & \hspace{150pt} \left .  \forall i \in [0, n].~ \sigma_i
        \notin \sem[]{\varphi_1} \right \}  \Biggr) \\
        %
        & \qquad =  \sem[]{\pop} \Biggl( \bigcup_{n \in \N} \left \{
            \frame{\sigma_n, \set{\sigma_0, \dots,
            \sigma_{n-1}}} \concat\,
            \frame{\sigma, \Delta}\concat S \mid 
            \sigma\trel^n \sigma_n,
            %
            %
            %
            \right . \\
            %
            & \hspace{150pt} \left . \forall i \in [0, n].~ \sigma_i
            \notin \sem[]{\varphi_1}, \ \exists i \in [0, n-1].~ \sigma_n = \sigma_i
        \right \} \Biggr) \\
        %
        & \qquad =  \left \{\frame{\sigma, \Delta}\concat S \mid 
        %
        %
        \exists n,\sigma_n.~\sigma {\textstyle \trel_\exists^n} \sigma_n,
          \ \forall i \in [0,
          n].~ \sigma_i \notin \sem[]{\varphi_1}, 
          %
          %
          \exists i \in [0, n-1].~
        \sigma_n = \sigma_i \right \} \\
        %
        & \qquad =  \set{\frame{\sigma, \Delta}\concat S \mid \sigma
          \notin \sem[]{\AF \varphi_1}}
      \end{align*}
      where at $(\clubsuit)$ we used the inductive hypothesis about $\varphi_1$.  As in
      the previous case we use the fact that infinite traces are
      identified as (finite) loops.
    \end{proof}
  \end{toappendix}

  \subparagraph*{$\mu_\Box$-calculus as $\MOKA$}

  %
  To each $\mu_\Box$-formula $\varphi$ 
  we assign the $\MOKA$ program $\PtoR{\varphi}$
  as follows:
  \begin{center}
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}lr@{\hspace{2pt}}c@{\hspace{2pt}}l}
      $\PtoR{\,p}$ & $\triangleq$ & $\np$
      & $\PtoR{\,\neg p}$ & $\triangleq$ & $\p$
      \\
      $\PtoR{\varphi_1\land \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_1} \oplus \PtoR{\varphi_2}$ 
      &
      $\PtoR{\varphi_1\lor \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_1} ; \PtoR{\varphi_2}$ \\
      %
      %
      %
      %
      %
      %
      %
      %
      $\PtoR{\Box \varphi}$ & $\triangleq$ &
      $\push; \nexte;\PtoR{\varphi}; \pop$ & %
      $\PtoR{x}$ & $\triangleq$ & $\X$  \\
      %
      %
      %
      $\PtoR{\mu x.\varphi_x}$ & $\triangleq$ & $\push; \reset; \upmu
      \X. \Bigl ( \loops \oplus (\add; \PtoR{\varphi_x}) \Bigr ); \pop$  \qquad\qquad %
      & $\PtoR{\nu x.\varphi_x}$ & $\triangleq$ & $\upmu
      \X. 
      \PtoR{\varphi_x} $ \\
    \end{tabular}
  \end{center}
  %


  The second component of a frame $\frame{\sigma, \Delta}$ is still
  used to identify looping computations. This intervenes in the encoding
  of least fixpoints $\mu x. \varphi_x$: when checking the
  formula, the current state first logged to the current frame
  ($\add; \PtoR{\varphi_x}$ branch); a counterexample is found when we
  try to verify the fixpoint property in a state where the check has
  already been tried (filtered by $\loops$).
  %
  The encoding of greatest fixpoints $\nu x. \varphi_x$ instead is
  simpler: searching for counterexamples 
  naturally translates to a least fixpoint, which is offered
  natively by $\MOKA$.


  The correctness of this transform (see Theorem~\ref{th:programs-mu} and Corollary~\ref{co:programs-mu} in the appendix) leverages
  a small variation of the tableau construction
  in~\cite{DBLP:conf/tapsoft/StirlingW89},
  with judgements roughly of the form $\sigma, \Delta \vdash \varphi$,
   meaning that the formula $\varphi$ holds in a state $\sigma$
  assuming that all the states in $\Delta$ 
 have been visited
  while checking the
  current fixpoint subformula. Then, we show that given a formula
  $\varphi$ and a stack $\frame{\sigma, \Delta}\concat S$,
  if there is no
  successful tableau for $\sigma, \Delta \vdash \varphi$ then
  $\sem{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
  \set{\frame{\sigma, \Delta}\concat S}$ holds,  while
  $\sem{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat
  S} = \varnothing$
  otherwise.

  \begin{toappendix}
    \subparagraph{$\mu_\Box$-calculus as $\MOKA$.}
    In order to prove an analogous result in the case of the
    $\mu_\Box$-calculus we first introduce an intermediate encoding in
    an extension of $\MOKA$ including an additional basic expression
    $\nloops$, the negation of $\loops$, which checks if the current
    state does not loop back to one of the states in the current
    trace. Hence its semantics is
    \begin{center}
      $\bsem{\nloops}\set{\frame{\sigma, \Delta} \concat S}$ $\triangleq$
      $\set{\frame{\sigma, \Delta}\concat S \mid \sigma
        \notin \Delta }$
    \end{center}

    Then, in the encoding of fixpoint formulae we continue the check
    only for states which have not been already considered, i.e.,
    where $\nloops$ succeeds:

    \begin{center}
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l}
      $\PtoRn{\,p}$ & $\triangleq$ & $\np$ \qquad $\PtoRn{\,\neg p}$ $\triangleq$ $\p$
      \qquad
      $\PtoRn{\varphi_1\land \varphi_2}$ $\triangleq$
      $\PtoRn{\varphi_1} \oplus \PtoRn{\varphi_2}$
      \qquad
      $\PtoRn{\varphi_1\lor \varphi_2}$ $\triangleq$
      $\PtoRn{\varphi_1} ; \PtoRn{\varphi_2}$
       \\
      %
      $\PtoRn{x}$ & $\triangleq$ & $\X$ \hspace{110.3pt} $\PtoRn{\Box \varphi}$ $\triangleq$ 
      $\push; \nexte;\PtoRn{\varphi}; \pop$ \\
      %
      $\PtoRn{\mu x.\varphi_x}$ & $\triangleq$ & $\push; \reset; \upmu
      \X. \Bigl ( (\nloops;
      \add; \PtoRn{\varphi_x}) \oplus \loops \Bigr ); \pop$ \\
      $\PtoRn{\nu x.\varphi_x}$ & $\triangleq$ & $\push; \reset; \upmu
      \X. \Bigl ( \nloops; \add;
      \PtoRn{\varphi_x} \Bigr ); \pop$ \\
    \end{tabular}
  \end{center}


  \begin{itemize}
    \item for $\mu x. \varphi_x$ a counterexample is found when we try
      to verify the fixpoint property in a state where the check has
      been already tried (filtered by $\loops$). Instead, when
      checking on new states (filtered by $\nloops$), these
      are first logged by $\add$ to the current frame and
      then the check continues.

    \item for $\nu x. \varphi_x$ the situation is dual: a
      second check on
      a state already visited witnesses that the formula is satisfied,
      hence the corresponding state must be discharged as it cannot
      provide a counterexample. Instead, when checking on new states
      (filtered by $\nloops$ ) these are logged by $\add$
      to the current frame
      and the check continues.
  \end{itemize}


    \begin{theorem}[Formula satisfaction as program verification
      - $\mu$-calculus version]
      \label{th:programs-mu}
      Given 
      $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, for all frames $\frame{\sigma, \Delta}\concat S \in
      \str{\operatorname{F}_{\Sigma}}$,
      for any $\mu_\Box$-calculus formula $\varphi$,
      environment $\eta$ and valuation $\mathcal{V}$ it holds:
      \begin{equation*}
        \sem{\PtoRn{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
        \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi}}
        %
        %
        %
        %
      \end{equation*}
    \end{theorem}

    \begin{proof}
      We assume, w.l.o.g., that some formula $\varphi$ is fixed
      in which all variables are distinct in a way that we can
      map each variable $y$ uniquely to the corresponding
      formula $\varphi_y$, where $\mu y. \varphi_y$ is the
      subformula in $\varphi$, and for any subformula of
      $\varphi$ we can identify the variable $\bvar{\varphi}$ quantified by the
      enclosing fixpoint.

      We consider the tableau construction
      of~\cite{DBLP:conf/tapsoft/StirlingW89}, with small
      modifications to adapt it to our context. In particular
      our judgements are of the form
      $\sigma, \Gamma \vdash \varphi$, where $\sigma \in \Sigma$
      and $\Gamma \subseteq \LVar \times \Sigma$. 


      The tableau rules are the following:
      \begin{center}
        \begin{tabular}{c c}
          $\inference{\sigma, \Gamma \vdash \varphi_1 \lor \varphi_2}
          {\sigma, \Gamma \vdash \varphi_1}[($\lor_1$)]$
          & $\inference{\sigma, \Gamma \vdash \varphi_1 \lor \varphi_2}
          {\sigma, \Gamma \vdash \varphi_2}[($\lor_2$)]$  \\
          & \\
          $\inference{\sigma, \Gamma \vdash \varphi_1 \land \varphi_2}
          {\sigma, \Gamma \vdash \varphi_1 \qquad \sigma, \Gamma
          \vdash \varphi_2}[($\land$)]$
          & $\inference{\sigma, \Gamma \vdash x}
          {\sigma, \Gamma \cup \set{(x, \sigma)} \vdash
          \varphi_x}[($\X$)]$  \\
          &  \\
          $\inference{\sigma, \Gamma \vdash \mu x. \varphi_x}
          {\sigma, \Gamma \vdash x}[($\mu. x$)]$
          & $\inference{\sigma, \Gamma \vdash \nu x. \varphi_x}
          {\sigma, \Gamma \vdash x}[($\nu. x$)]$ \\
          & \\
          $\inference{\sigma, \Gamma  \vdash \Box \varphi}
          {\sigma_1, \Gamma \vdash \varphi \qquad \dots \qquad
          \sigma_n, \Gamma \vdash \varphi}[($\Box$)]$
          & $\sigma \trel \sigma_i, \ i = 1, \dots, n$ \\
        \end{tabular}
      \end{center}

      A leaf is \emph{successful} if it is of the form
      $\sigma, \Gamma
      \vdash x$ with
      $(x, \sigma) \in \Gamma$ and $x$ associated with a
      greatest fixpoint (namely bound in a subformula $\nu x. \varphi_x$), or
      $\sigma, \Gamma \vdash p$ with $\sigma \vdash p$.
      %
      %
      A leaf is a \emph{failure} if it is of the form
      $\sigma, \Gamma \vdash x$ with
      $(x, \sigma) \in \Gamma$ and $x$ such that is associated
      to a least fixpoint (namely bound in a subformula
      $\mu x. \varphi_x$), or
      $\sigma, \Gamma \centernot \vdash p$ with
      $\sigma \centernot \vdash p$.
      A tableau is successful if all its leaves are successful.

      Let us give a name to the programs corresponding to
      subformulae $\mu x. \varphi_x$ or $\nu x. \varphi_x$ of
      $\varphi$.  Recall that
      \begin{align*}
        \PtoRn{\mu x.\varphi_x} & = \push; \reset;\underset{=
        \r_x}{\underbrace{\upmu \X.\Bigl ((\nloops;
        \add; \PtoRn{\varphi_x}) \oplus \loops  \Bigr )}}; \pop \\
        \PtoRn{\nu x.\varphi_x} & = \push; \reset;  \underset{=
        \r_x}{\underbrace{\upmu \X. \Bigl ( \nloops; \add;
        \PtoRn{\varphi_x} \Bigr ) }}; \pop
      \end{align*}
      As indicated above we name $\r_x$ the underbraced programs
      and call $\X$ the $\MOKA$ variable corresponding to the
      logical variable $x$. Then we define an environment $\eta$
      for $\MOKA$ programs by letting
      $\eta(\X) = \sem[]{\r_{x}}$. Note that the semantics of
      $\r_{x}$ is independent from the environment since
      $\r_{x}$ is closed.

      \medskip

      Now we prove that for all subformulae $\psi$ of $\varphi$,
      for all stacks $\frame{\sigma, \Delta}\concat S$, if $y=\bvar{\psi}$ is the
      variable bound in the enclosing fixpoint and $\Gamma \subseteq
      \left (\Var \setminus \set{y} \right) \times \Sigma$, then we have
      \begin{equation*}
        \sem{\PtoRn{\psi}} \set{\frame{\sigma, \Delta}\concat S} =
        \begin{cases}
          \set{\frame{\sigma, \Delta}\concat S} &
          \mbox{if there is no successful tableau }
          \sigma, \Gamma \cup \left ( \set{y} \times \Delta \right
          )\vdash \psi \\
          \varnothing & \mbox{otherwise}
        \end{cases}
      \end{equation*}

      Now the proof goes by induction on
      $\frame{\sigma, \Delta}\concat S$ and $\psi$ ordered
      by
      \begin{equation*} \frame{\sigma, \Delta}\concat S, \psi
        < \frame{\sigma', \Delta'}\concat S', \psi'
      \end{equation*}
      if one of the following holds

      \begin{itemize}
        \item $\psi = \varphi_z$ and $\psi' = \eta z.
          \varphi_z$ for
          some $\eta \in \set{\mu, \nu}$ and $z$ variable;
        \item The previous condition is not satisfied, $\bvar{\psi}=\bvar{\psi'}$ and either
          \begin{itemize}
            \item $\Delta' \subset \Delta$
            \item $\Delta=\Delta'$ and $\psi$ is a subformula of
              $\psi'$;
          \end{itemize}
      \end{itemize}

      \subparagraph*{($\psi = p$)}
      We have
      \begin{equation*}
        \sem{\PtoRn{p}} \set{  \frame{\sigma, \Delta}\concat S} =
        \set{  \frame{\sigma, \Delta}\concat S \mid \sigma
        \centernot\vdash p}
      \end{equation*}
      which is the empty set if and only if $\sigma \vdash p$, i.e.,
      $\sigma,  \Gamma \cup  \left ( \set{y} \times \Delta \right )
      \vdash p$ alone is a
      successful tableau.

      \subparagraph*{($\psi = \neg p$)} Analogous to the case $\psi = p$.

      \subparagraph*{($\psi = \psi_1 \lor \psi_2$)}
      \begin{align*}
        \sem{\PtoRn{\psi_1 \lor \psi_2}} \set{  \frame{\sigma,
        \Delta}\concat S} & = \sem{\PtoRn{\psi_1}};
        \sem{\PtoRn{\psi_2}}
        \set{  \frame{\sigma, \Delta}\concat S} \\
        & = \sem{\PtoRn{\psi_2}} \set{  \frame{\sigma,
        \Delta}\concat S} \\
        & = \set{  \frame{\sigma, \Delta}\concat S}
      \end{align*}
      if and only if, by inductive hypothesis, since both $\psi_1,
      \psi_2$ are subformulae of $\psi_1 \lor \psi_2$,
      there is no
      successful tableau neither for $\sigma, \Gamma \cup \left (\set{y}
      \times \Delta \right ) \vdash \psi_1$
      nor for $\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
      \right ) \vdash
      \psi_2$, since a tableau for
      $\sigma, \Gamma \cup  \left ( \set{y} \times \Delta \right )
      \vdash \psi_1 \lor
      \psi_2$ is of the shape
      \begin{equation*}
        \inference{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
          \right ) \vdash \psi_1 \lor
        \psi_2}{\inference{\sigma,  \Gamma \cup  \left ( \set{y}
            \times \Delta \right ) \vdash
        \psi_1}{T}} \qquad
        \qquad  \inference{\sigma, \Gamma \cup  \left ( \set{y}
          \times \Delta \right )
          \vdash \psi_1 \lor
        \psi_2}{\inference{\sigma, \Gamma \cup  \left ( \set{y}
            \times \Delta \right )
        \vdash \psi_2}{T'}}
      \end{equation*}
      with $T, T'$ successful tableaux.

      \subparagraph*{($\psi = \psi_1 \land \psi_2$)}
      \begin{align*}
        \sem{\PtoRn{\psi_1 \land \psi_2}} \set{  \frame{\sigma,
        \Delta}\concat S}  & = \sem{\PtoRn{\psi_1} \oplus
        \PtoRn{\psi_2}}
        \set{  \frame{\sigma, \Delta}\concat S} \\
        & = \sem{\PtoRn{\psi_1}}\set{  \frame{\sigma,
        \Delta}\concat S}
        \cup \sem{\PtoRn{\psi_2}} \set{  \frame{\sigma,
        \Delta}\concat S} \\
        & = \set{  \frame{\sigma, \Delta}\concat S}
      \end{align*}
      if and only if, by inductive hypothesis, since both $\psi_1,
      \psi_2$ are subformulae of $\psi_1 \land
      \psi_2$, either there
      is no successful tableau for $\sigma, \Gamma \cup \left (\set{y} \times
      \Delta \right ) \vdash \psi_1$ or
      for $\sigma, \Gamma \cup  \left ( \set{y} \times \Delta \right
      ) \vdash \psi_2$,
      since a tableau for
      $\sigma, \Gamma \cup  \left ( \set{y} \times \Delta \right )
      \vdash \psi_1 \land
      \psi_2$ is of the shape
      \begin{equation*}
        \inference{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
          \right ) \vdash \psi_1 \land
        \psi_2}{\inference{\sigma, \Gamma \cup  \left ( \set{y}
            \times \Delta \right )
          \vdash \psi_1}{T} \qquad
          \inference{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
        \right ) \vdash \psi_2}{T'}}
      \end{equation*}
      with $T, T'$ successful tableaux.
      %
      \subparagraph*{($\psi = \Box \psi_1$)}
      \begin{align*}
        \sem{\PtoRn{\Box{\psi_1}}}\set{  \frame{\sigma, \Delta}\concat
        S} & = \sem{\push{}; \nexte; \PtoRn{\psi_1}; \pop} \set{
        \frame{\sigma, \Delta}\concat S} \\
        & = \sem{\pop}\Bigl ( \sem{\PtoRn{\psi_1}}\set{
            \frame{\sigma', \Delta}\concat\, \frame{\sigma,
            \Delta}\concat S
        \mid \sigma \trel \sigma'}\Bigr ) \\
        & \overset{\clubsuit}{=} \sem{\pop}\Bigl ( \left \{
            \frame{\sigma', \Delta} \concat\, \frame{\sigma, \Delta} \concat S
            \mid \sigma \trel \sigma', \right . \\ 
        & \left . \hspace{50pt} \mbox{no successful tableau
            for } \sigma', \Gamma \cup  ( \{y\} \times \Delta) 
            \vdash \psi_1 \right \} \Bigr ) \\
        & =
        \begin{cases}
          \set{\frame{\sigma, \Delta}\concat S} & \mbox{if no successful tableau for } 
          \sigma, \Gamma \cup  \left (
          \set{y} \times \Delta \right )
          \vdash \Box\psi_1 \\
          \varnothing & \mbox{otherwise}
        \end{cases}
      \end{align*}
      where at $(\clubsuit)$ we applied the inductive hypothesis
      since $\psi_1$ is a subformula of $\Box \psi_1$.
      %
      \subparagraph*{($\psi = y$ variable associated with $\mu  y. \varphi_y$)}
      We have
      \begin{equation*}
        \sem{\PtoRn{y}} = \sem{\Y} = \eta(\Y) = \sem{\r_y}
      \end{equation*}
      where
      \begin{equation*}
        \r_{y} = \upmu \Y. \Bigl ((\nloops; \add;
        \PtoRn{\varphi_y}) \oplus \loops \Bigr )
      \end{equation*}
      We have two possible cases:
      \begin{itemize}
        \item if $\sigma \in \Delta$ then
          \begin{equation*}
            \sem{\Y} \set{\frame{\sigma, \Delta}\concat S} =
            \sem{\r_y} \set{\frame{\sigma, \Delta}\concat S} =
            \set{\frame{\sigma, \Delta}\concat S}
          \end{equation*}
          and indeed $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \vdash
          y$ alone is a failed tableau
          since $y$ corresponds to a minimal fixpoint formula $\mu
          y. \varphi_y$.
        \item if $\sigma \notin \Delta$ then
          \begin{align*}
            \sem{\Y} \set{\frame{\sigma, \Delta}\concat S}
            & = \sem{\r_y} \set{\frame{\sigma, \Delta}\concat S} \\
            & = \sem{(\nloops; \add;
            \PtoRn{\varphi_y}) \oplus \loops}\set{\frame{\sigma, \Delta}\concat S}\\
            & = \sem{\PtoRn{\varphi_y}}\set{\frame{\sigma,
            \Delta\cup \set{\sigma}}\concat S} \\
            & \overset{\clubsuit}{=} \set{\frame{\sigma,
            \Delta\cup \set{\sigma}}\concat S}
          \end{align*}
      \end{itemize}
      if and only if there is no successful tableau $\sigma, \Gamma
      \cup \left (\set{y} \times (\Delta
      \cup \set{\sigma}) \right ) \vdash \varphi_y$, if and only if
      there is no successful tableau $\sigma, \Gamma \cup \left ( \set{y}
      \times \Delta \right ) \vdash y$,
      since the only applicable rule is
      \begin{equation*}
        \inference{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta \right )
        \vdash y}{\sigma, \Gamma \cup \left ( \set{y} \times (\Delta \cup
        \set{\sigma}) \right ) \vdash \varphi_y}
      \end{equation*}
      At $(\clubsuit)$ we can apply the inductive hypothesis since
      $\Delta \subseteq \Delta \cup \set{\sigma}$.
      %
      \subparagraph*{($\psi = \mu z. \varphi_z$)}
      \begin{align*}
        \sem{\PtoRn{\mu z. \varphi_z}}\set{\frame{\sigma,
        \Delta}\concat S} & = \sem{\push{}; \upmu \Z. \Bigl ( \loops
          \oplus (\nloops; \add; \PtoRn{\varphi_z}) \Bigr ); \pop
        }\set{\underset{= S'}{\underbrace{\frame{\sigma,
        \Delta}\concat S}}} \\
        & = \sem{\pop}\Bigl [ \sem{ \upmu \Z. \Bigl ( \loops \oplus
          (\nloops; \add; \PtoRn{\varphi_z}) \Bigr )}
        \set{\frame{\sigma, \varnothing}\concat S'} \Bigr ] \\
        & \overset{\diamond}{=} \sem{\pop} \Bigl ( \sem{\loops
            \oplus (\nloops; \add;
          \PtoRn{\varphi_z})}\set{\frame{\sigma, \varnothing}\concat
        S'} \Bigr ) \\
        & = \sem{\pop}\Bigl (
          \underset{(\heartsuit)}{\underbrace{\sem{
        \PtoRn{\varphi_z}}\set{\frame{\sigma, \set{\sigma}}\concat S'}}} \Bigr )
      \end{align*}
      where at $(\diamond)$ we use the fact that $\sem{\upmu \Z. \r} =
      \llbracket \r \rrbracket_{\eta[\Z \mapsto \sem{\upmu \Z. \r}]}$.
      Now the first clause of
      the order holds, since we have $\psi = \varphi_z$ and
      $\psi' = \mu z. \varphi_z$, hence by inductive hypothesis we
      deduce that $(\heartsuit)$ is
      \begin{itemize}
        \item $\set{\frame{\sigma, \set{\sigma}}\concat S'}$ if and
          only if there is no successful tableau $\sigma, \Gamma \cup
          \left ( \set{y} \times \Delta \right ) \cup
          \set{(z,\sigma)} \vdash \varphi_z$,
          if and only if there is no
          successful tableau $\sigma, \Gamma \cup \left
          (\set{y}\times\Delta \right )
          \vdash \mu z.
          \varphi_z$ since the only applicable rule is
          \begin{equation*}
            \inference{\sigma, \Gamma \cup  \left ( \set{y} \times
              \Delta \right ) \vdash \mu z.
            \varphi_z}{\inference{\sigma, \Gamma \cup  \left (
                \set{y} \times \Delta \right ) \vdash
              z}{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
                \right ) \cup
            \set{(z,\sigma)} \vdash \varphi_z}}
          \end{equation*}
        \item $\varnothing$ if and only if there is a successful
          tableau for $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \cup
          \set{(z, \sigma)} \vdash \varphi_z$,
          hence for $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \vdash \mu
          z. \varphi_z$.
      \end{itemize}
      %
      \subparagraph*{($\psi = y$ variable associated with $\nu y.
      \varphi_y$)}   We have
      \begin{equation*}
        \sem{\PtoRn{y}} = \sem{\Y} = \eta(\Y) = \sem{\r_y}
      \end{equation*}
      where
      \begin{equation*}
        \r_{y} = \upmu \Y. \Bigl (\nloops; \add; \PtoRn{\varphi_y} \Bigr )
      \end{equation*}
      We have two possible cases:
      \begin{itemize}
        \item if $\sigma \in \Delta$ then
          \begin{equation*}
            \sem{\Y} \set{\frame{\sigma, \Delta}\concat S} =
            \sem{\r_y} \set{\frame{\sigma, \Delta}\concat S} = \varnothing
          \end{equation*}
          and indeed $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \vdash y$
          alone is a successful
          tableau since $y$ corresponds to a maximal fixpoint formula
          $\nu y. \varphi_y$.
        \item if $\sigma \notin \Delta$ then
          \begin{align*}
            \sem{\Y} \set{\frame{\sigma, \Delta}\concat S} & =
            \sem{\r_y} \set{\frame{\sigma, \Delta}\concat S} \\
            & = \sem{\nloops; \add;
            \PtoRn{\varphi_y}}\set{\frame{\sigma, \Delta}\concat S}\\
            & = \sem{\PtoRn{\varphi_y}}\set{\frame{\sigma,
            \Delta\cup \set{\sigma}}\concat S} \\
            & \overset{\clubsuit}{=} \set{\frame{\sigma,
            \Delta\cup \set{\sigma}}\concat S}
          \end{align*}
      \end{itemize}
      if and only if there is no successful tableau $\sigma, \Gamma
      \cup  \left ( \set{y} \times \Delta \right ) \cup \set{(y, \sigma)} \vdash
      \varphi_y$, if and only if there
      is no successful tableau $\sigma, \Gamma \cup  \left ( \set{y}
      \times \Delta \right )
      \vdash y$, since the
      only applicable rule is
      \begin{equation*}
        \inference{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
          \right ) \vdash
        y}{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta \right ) \cup
        \set{(y, \sigma)} \vdash \varphi_y}
      \end{equation*}
      At $(\clubsuit)$ we can apply the inductive hypothesis since
      $\Delta \subseteq \Delta \cup \set{\sigma}$.
      %
      \subparagraph*{($\psi = \nu z. \varphi_z$)}
      \begin{align*}
        \sem{\PtoRn{\nu z. \varphi_z}}\set{\frame{\sigma,
        \Delta}\concat S} & = \sem{\push{}; \upmu \Z. \Bigl ( \nloops; \add;
        \PtoRn{\varphi_z} \Bigr ); \pop }
        \set{\frame{\sigma, \Delta}\concat S} \\
        %
        & = \sem{\pop}\Bigl ( \sem{ \upmu \Z. (\nloops; \add;
          \PtoRn{\varphi_z})} \set{\frame{\sigma, \varnothing}\concat\,
        \frame{\sigma, \Delta}\concat S} \Bigr ) \\
        & \overset{\diamond}{=} \sem{\pop} \Bigl ( \sem{\nloops;
          \add; \PtoRn{\varphi_z}}\set{\frame{\sigma, \varnothing}\concat\,
        \frame{\sigma, \Delta}\concat S} \Bigr ) \\
        & = \sem{\pop}\Bigl ( \underset{(\heartsuit)}{\underbrace{\sem{
              \PtoR{\varphi_z}}\set{\frame{\sigma,
        \set{\sigma}}\concat\, \frame{\sigma, \Delta}\concat S}}} \Bigr )
      \end{align*}
      where at $(\diamond)$ we use the fact that $\sem{\upmu \Z. \r} =
      \llbracket \r \rrbracket_{\eta[\Z \mapsto \sem{\upmu \Z. \r}]}$.
      Now the first clause of
      the order holds, since we have $\psi = \varphi_z$ and
      $\psi' = \mu z. \varphi_z$, by inductive hypothesis we deduce
      that $(\heartsuit)$ is
      \begin{itemize}
        \item $\set{\frame{\sigma, \set{\sigma}}\concat S'}$ if and only
          if there is no successful tableau $\sigma, \Gamma
      \cup  \left ( \set{y} \times \Delta \right ) \cup \set{(z, \sigma)}
          \vdash \varphi_z$, if and only if there is no successful
          tableau $\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
          \right ) \vdash \nu z.
          \varphi_z$ since
          the only applicable rule is
          \begin{equation*}
            \inference{\sigma, \Gamma \cup  \left ( \set{y} \times
              \Delta \right ) \vdash \nu z.
            \varphi_z}{\inference{\sigma, \Gamma \cup  \left (
                \set{y} \times \Delta \right ) \vdash
              z}{\sigma, \Gamma \cup  \left ( \set{y} \times \Delta
                \right ) \cup
            \set{(z, \sigma)} \vdash \varphi_z}}
          \end{equation*}
        \item $\varnothing$ if and only if there is a successful
          tableau for $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \cup
          \set{(z, \sigma)} \vdash \varphi_z$,
          hence for $\sigma, \Gamma \cup  \left ( \set{y} \times
          \Delta \right ) \vdash \nu
          z. \varphi_z$.
      \end{itemize}
      \hfill
    \end{proof}

    In order to conclude, we need to show that the result above still
    works for the original encoding $\PtoR{\varphi}$. This can be
    obtained as an easy corollary.

    \begin{corollary}
      \label{co:programs-mu}
      For all frames
      $\frame{\sigma, \Delta}\concat S \in
      \str{\operatorname{F}_{\Sigma}}$, for any $\mu_\Box$-calculus
      formula $\varphi$, environment $\eta$ and valuation
      $\mathcal{V}$ it holds
      $\sem{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
      \sem{\PtoRn{\varphi}} \set{\frame{\sigma, \Delta}\concat S}$ and
      thus
      \begin{equation*}
        \sem{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
        \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
          \sem[]{\varphi}}
      \end{equation*}
    \end{corollary}

    \begin{proof}
      The non-trivial cases are those concerning fixpoints formulas.
      \begin{itemize}
      \item For least fixpoints $\mu x.\, \varphi_x$, recall that
        \begin{quote}
          $\PtoRn{\mu x.\varphi_x}$ $\triangleq$ $\push; \reset; \mu
          \X. \Bigl ( (\nloops;
          \add; \PtoRn{\varphi_x}) \oplus \loops \Bigr ); \pop$ \\
          %
          $\PtoR{\mu x.\varphi_x}$ $\triangleq$ $\push; \reset; \mu
          \X. \Bigl ( (\add; \PtoR{\varphi_x}) \oplus \loops \Bigr ); \pop$ \\
        \end{quote}

        Thus
        $\sem{\PtoRn{\mu x.\varphi_x}} = \bsem{\pop} \circ
        \operatorname{lfp}(F_n) \circ \bsem{\reset} \circ
        \bsem{\push}$ and
        $\sem{\PtoR{\mu x.\varphi_x}} = \bsem{\pop} \circ
        \operatorname{lfp}(F) \circ \bsem{\reset} \circ \bsem{\push}$
        where $F_n, F : C^C \to C^C$, with
        $C = \pow{\str{\operatorname{F}_{\Sigma}}}$, are the operators
        below:
        \[
          F_n(f) = \sem[{\eta[\X \mapsto f]}]{(\nloops; \add; \PtoR{\varphi_x}) \oplus \loops}\\
          F(f) = \sem[{\eta[\X \mapsto f]}]{(\add; \PtoR{\varphi_x}) \oplus \loops}
        \]
        We conclude simply by observing that, in our setting we can
        restrict to functions $f \in C^C$ which are reductive, i.e.,
        such that $f(X) \subseteq X$  
        for $X \in C$, and on such
        functions $F_n(f) =F(f)$.
        %
        In fact, we have that
        \begin{itemize}
        \item if $\sigma \not\in \Delta$
          then  $F_n(f)(\frame{\sigma, \Delta} \concat S) = \sem[{\eta[\X \mapsto f]}]{\PtoR{\varphi_x}}(\frame{\sigma, \Delta\cup\set{\sigma}} \concat S) = F(f)(\frame{\sigma, \Delta} \concat S)$
    \item if $\sigma \in \Delta$
      then
      \begin{align*}
        F_n(f)(\frame{\sigma, \Delta} \concat S)
        & = \set{\frame{\sigma, \Delta} \concat S}\\
        & \overset{\clubsuit}{=}  \set{\frame{\sigma, \Delta} \concat S} \cup \sem[{\eta[\X \mapsto f]}]{\PtoR{\varphi_x}}(\frame{\sigma, \Delta} \concat S) \\
        & \overset{\heartsuit}{=} \set{\frame{\sigma, \Delta} \concat S} \cup \sem[{\eta[\X \mapsto f]}]{\PtoR{\varphi_x}}(\frame{\sigma, \Delta\cup\set{\sigma}} \concat S) \\
        & = F(f)(\frame{\sigma, \Delta} \concat S)
      \end{align*}
      where the second passage $(\clubsuit)$ is motivated by the fact that 
      $\sem[{\eta[\X \mapsto f]}]{\PtoR{\varphi}}(\frame{\sigma,
        \Delta} \concat S) \subseteq \set{\frame{\sigma, \Delta}
        \concat S}$ and the third $(\heartsuit)$ by the hypothesis $\sigma\in\Delta$.
    \end{itemize}

  \item For greatest fixpoints $\nu x.\, \varphi_x$, instead, we
    provide a direct proof of the fact that
    $\PtoR{\nu x. \varphi} \triangleq \upmu \X.  \PtoR{\varphi_x}$ is
    correctly computing the counterexamples, i.e., we show directly
    that
    \begin{center}
      $\sem{\PtoR{\nu x. \varphi}} \set{\frame{\sigma, \Delta}\concat S} =
      \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi}}$
    \end{center}      

    To this aim consider the approximants for
    $\nu x.\, \varphi$, i.e., $\nu^{0} x. \varphi = \true$ and
    $\nu^{n+1} x. \varphi = \varphi [(\nu^{n} x. \varphi)/x]$.
    %
    Similarly, consider the approximants for the encoding
    $\upmu \X. \PtoR{\varphi}$, i.e., $\upmu^0 \X. \PtoR{\varphi} = \zero$
    and
    $\upmu^{n+1} \X. \PtoR{\varphi} = \PtoR{\varphi} [(\upmu^{n}
    \X. \PtoR{\varphi})/\X]$.

    Then one can show that for all $n$ it holds that
    $\PtoR{\nu^{n} x. \varphi} = \upmu^{n} \X. \PtoR{\varphi}$ (this
    immediately follows from the fact that
    $\PtoR{\psi_1[\psi_2/x]} = \PtoR{\psi_1}[\PtoR{\psi_2}/\X]$) and thus
    we can conclude. In fact
    \begin{align*}
      \sem{\PtoR{\nu x. \varphi}} \set{\frame{\sigma, \Delta}\concat S}
      & = \sem{\upmu \X. \PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S}\\
      %
      & = \bigcup_{n \in \N} \sem{\upmu^n \X. \PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S}\\
      %
      & = \bigcup_{n \in \N} \sem{\PtoR{\nu^{n} x. \varphi}} \set{\frame{\sigma, \Delta}\concat S}\\
      & = \bigcup_{n \in \N} \set{\frame{\sigma, \Delta}\concat S \mid \sigma \not\models \nu^{n} x. \varphi }\\
      & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma \not\models \bigwedge_{n \in \N} \nu^{n} x. \varphi}\\
      & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma \not\models  \nu x. \varphi}
    \end{align*}
  \end{itemize}
\end{proof}

  \end{toappendix}

  %

  \begin{example}[Control flow graphs and $\mu_\Box$-calculus encoding]
    \label{ex:mu}
    Consider again Examples~\ref{ex:cfg} and~\ref{ex:lts}. We now
    check the property \emph{``if after three
      steps we end up in program point $3$ then we will loop forever,
    every $4$ steps, on this program point 3.''} It is known that regular
    properties of this kind cannot be expressed in $\ACTL$
    (see, e.g.,~\cite{PW83}). This property can be expressed in the
    $\mu_\Box$-calculus as
    $\psi \triangleq \Box^3 (n=3\ \to \nu x.\, (n=3\ \land\ \Box^4 x))$, 
    %
    where
    $\Box^k$ is a shortand for $\Box \ldots \Box$ repeated $k$ times.
    %
    Letting $\r^k$ as a shorthand for
    a $k$ times composition
    $\r; \ldots; \r$ of a $\MOKA$ program $\r$,
    the $\MOKA$ program encoding $\psi$ is
    $\PtoR{\psi}= (\push;\nexte)^3;(\mathsf{n = 3} ;
      \PtoR{\nu x.\, (n=3\
    \land\ \Box^4 x)});\pop^3$, with
    $\PtoR{\nu x.\, (n=3\ \land\ \Box^4 x)} = \upmu \X.\, ([\mathsf{n \neq 3?} \oplus ((\push;\nexte)^4; \X;
    \pop^4)])$.
    \qed
  \end{example}

It is well known that all ACTL formulae can be expressed as
$\mu_\Box$-calculus formulae.
For example,
$\AX \varphi = \Box \varphi$,
$\AF \varphi = \mu x.\, (\varphi \lor \Box x)$, and
$\AG \varphi = \nu x.\, (\varphi \land \Box x)$.
%
  Hence one could  obtain programs generating
  counterexamples for $\ACTL$ by encoding $\ACTL$
  in the
  $\mu_{\Box}$-calculus and then generating the corresponding program.
  However, this in general produces programs which are
  (unnecessarily) more complex than those
  produced for ACTL formulae. For instance, the program for $\AF
  \varphi$ obtained through the $\mu_\Box$-calculus encoding above would be
  $\push; \reset; \upmu \X. \Bigl (\loops \oplus (\add;
  \PtoR{\varphi}; \push; \nexte; \X; \pop)   \Bigr ); \pop$.
  %

  \begin{toappendix}
    \begin{remark}[ACTL counterexamples programs as
      $\mu$-calculus formulae]
      For completeness, we explicitly write the programs $\PtoR{\varphi}$
      that correspond to (the modal fragment of) ACTL formulae
      $\varphi$ in the $\mu$-calculus encoding of ACTL formulae. 
      Let us note that, as expected, $\AX \varphi$ encoding as $\Box \varphi$ 
      is exactly the encoding of $\AX \varphi$.


      \begin{align*}
        %
        %
        %
        \PtoR{\AF \varphi}
        & = \push; \reset; \upmu \X. \Bigl ( (\add; \PtoR{\varphi}; \push; \nexte; \X; \pop) \oplus  \loops \Bigr ); \pop\\
        %
        \PtoR{\AG \varphi}
        & = \upmu \X. \Bigl (\PtoR{\varphi} \oplus (\push;\nexte; \X; \pop) \Bigr ) \\
        %
        \PtoR{\varphi_1 \AU \varphi_2}
        & = \push; \reset;\upmu \X. \Bigl [ 
          \add; \Bigl ( \PtoR{\varphi_2}; (\PtoR{\varphi_1} \oplus
          \push; \nexte; \X; \pop) \Bigr ) \oplus \loops \Bigr ]; \pop
      \end{align*}
    \end{remark}
  \end{toappendix}

  \section{%
  Abstract Interpretation of $\MOKA$}
  \label{sec:stackabs}

  We show how to lift an abstraction over the states
  of a transition system to an abstraction over the domain of
  stacks. This is achieved stepwise by first considering
  an abstraction
  applied to each single stack, and then by merging classes of
  stacks through a
  suitable equivalence. The resulting stack abstraction will induce
  the abstract interpretation of $\MOKA$ programs.

  %

  \subparagraph{Lifting the abstraction.}
  Let $(\Sigma, I, \trel)$  be a fixed transition system and let
  $\langle \alpha,\gamma \rangle: \pow{\Sigma} \rightleftarrows A$
  %
  be an abstraction of state properties.
  %
  We consider the lattice
  $\operatorname{F}_{A} \triangleq A \times A$,
  with componentwise order, whose elements $\frame{\sigma^{\sharp}, \delta^{\sharp}}$ are called \emph{abstract
  frames}, and, in turn,
  $\str{\operatorname{F}_{A}}$ whose elements $\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}$ are called
  \emph{abstract stacks}.
  %
  As in the concrete case, we abbreviate $\frame{\sigma^{\sharp}, \bot_A}$ as $\sigma^{\sharp}$.

  The abstraction map $\alpha$ on state properties can be extended to
  a frame abstraction, that by abusing the notation, we still
  denote by $\alpha$,
  and is defined by
  $\alpha(\frame{\sigma, \Delta}) \triangleq
  \frame{\alpha(\set{\sigma}), \alpha(\Delta)}$. In turn, the
  abstraction is inductively defined
  on stacks as
%
  $\alpha(\frame{\sigma, \Delta}\concat S^{n}) \triangleq
  \alpha(\frame{\sigma, \Delta}) \concat
  \alpha(S^{n})$.

  Now,  a set of
  stacks is abstracted to a set of abstract stacks by first applying $\alpha$
  pointwise using the
  image adjunction  (see Example~\ref{ex:image})
  %
  and then joining classes of abstract stacks
  in a way which is parameterised by a suitable equivalence.
  %
  Given an equivalence  $\mathbin{\sim} \subseteq L \times L$,
  we let $\class{x}{\sim}$
  %
  denote the equivalence class of $x\in L$ w.r.t.~$\sim$. Given $x \in L$ we
  let  
$\cone{x} \triangleq \set{y \in L \mid y \leq x}$.
  %

  \begin{definition}[Equivalence adjunction]
    \label{de:compatible-equivalence}
    Given a complete lattice
    $L$, a \emph{compatible equivalence} is an equivalence
    $\sim\subseteq L \times L$ such that for all $x \in
    L$, it holds that
    $\class{x}{\sim}$ is closed by joins of non-empty subsets. Let
    $\poweq{L}{\ssim} \triangleq \set{X \in \pow{L} \mid \forall x \in
      X.\, \class{x}{\sim} \cap X = \set{x}}$, ordered as follows: $X
    \leq_\ssim Y$ if for all $x \in X$ there is $y \in Y$ such that $x
    \sim y$ and $x \leq y$.

    \noindent
    Then, the pair $\langle \alpha_\ssim, \gamma_\ssim \rangle : \pow{L}
    \rightleftarrows
    \poweq{L}{\ssim}$
    defined, for $X \in \pow{L}$, $Y \in \poweq{L}{\ssim}$, by
    \begin{center}
      $\alpha_\ssim(X) \triangleq \set{ \bigvee (X \cap \class{x}{\sim})
      \mid x \in X}$
      \qquad
      $\gamma_\ssim(Y) \triangleq \bigcup \set{ \class{y}{\sim} \cap \cone{y}
      \mid y \in Y}$
    \end{center}
    is a Galois connection, called \emph{equivalence adjunction}
    (see Lemma~\ref{le:equiv}).
  \end{definition}
  %
  In words, $\poweq{L}{\ssim}\subseteq \pow{L}$
  consists of the subsets of $L$ containing at most one
  representative for each
  equivalence class, and $\alpha_\ssim(X)$ abstracts $X$ in
  the subset (in $\poweq{L}{\ssim}$) consisting of the least upper bounds of
  $\sim$-equivalent elements in $X$.

  \begin{toappendix}
    Given a complete lattice $L$ and a compatible equivalence $\sim$ on
    $L$, note that given $W \subseteq \poweq{L}{\ssim}$ we have
    $\bigvee W = \alpha_\ssim(\bigcup W)$.  With the additional
    observation that $\alpha_\ssim$ is idempotent, this immediately shows
    that $\alpha_\ssim$ is additive and thus part of a Galois
    connection. A detailed proof is below.

    \begin{lemma}
      \label{le:equiv}
      Let $L$ be a lattice and $\sim$ be a compatible equivalence on
      $L$. Then the equivalence adjunction $\langle \alpha_\ssim,
      \gamma_\ssim \rangle : \pow{L} \rightleftarrows \poweq{L}{\ssim}$ is a Galois
      connection.
    \end{lemma}

    \begin{proof}
      We start observing that $\leq_\ssim$ is a partial order on
      $\poweq{L}{\ssim}$. In fact, let $X, Y, Z \in \poweq{L}{\ssim}$. Then
      \begin{itemize}
        \item
          $X \leq_\ssim X$ since $\sim$ is reflexive.
        \item Assume $X \leq_\ssim Y$ and $Y \leq_\ssim X$. We show
          that $X \subseteq Y$. In fact, for all $x \in X$, since
          $X \leq_\ssim Y$, there exists $y \in Y$ such that
          $x \sim y$ and $x \leq y$. In turn, by $Y \leq_\ssim X$
          there is $x' \in X$ such that $x' \sim y$ and $y \leq
          x'$. Therefore $x \sim x'$ from which we obtain $x=x'$ and
          thus $x=y$ by antisymmetry of $\leq$. Dually, one can show
          $Y \subseteq X$ and thus $X=Y$, as desired.

        \item Assume $X \leq_\ssim Y \leq_\ssim Z$. Then for all
          $x \in X$, since $X \leq_\ssim Y$, there exists $y \in Y$
          such that $x \sim y$ and $x \leq y$. In turn, by
          $Y \leq_\ssim Z$ this implies that there is $z \in Z$ such
          that $y \sim z$ and $y \leq z$. Hence $x \sim z$ and
          $x \leq z$. Thus $X \leq_\ssim Z$.
      \end{itemize}
      %
      %

      We now observe that $\poweq{L}{\ssim}$ is a complete lattice,
      by showing that, for a collection of elements
      $X_i \in \poweq{L}{\ssim}$ for $i \in I$, it holds
      \begin{center}
        $\bigvee_{i \in I} X_i = \alpha_\ssim(\bigcup_{i\in I} X_i)$
      \end{center}
      In fact, let $i \in I$ and $x \in X_i$. Then, if we define
      $y = \bigvee (\class{x}{\sim} \cap \bigcup_i X_i)$ we have
      that $x \sim y$ and
      $y \in \alpha_\ssim(\bigcup_{i\in I} X_i)$. Therefore
      $X_i \leq_\ssim \alpha_\ssim(\bigcup_{i\in I} X_i)$, i.e.,
      $\alpha_\ssim(\bigcup_{i\in I} X_i)$ is an upper bound.

      Let us show that it is the least upper bound. Given any other
      upper bound $Z$ for the $X_i$'s, take
      $y \in \alpha_\ssim(\bigcup_{i\in I} X_i)$. By definition of
      $\alpha_\ssim$,
      $y = \bigvee \class{x}{\sim} \cap \bigcup_{i\in I, X_i \cap
      \class{x}{\sim} \neq \varnothing} X_i$ for some $x \in
      L$. Now, for all $i\in I$ such that
      $X_i \cap \class{x}{\sim} \neq \varnothing$ let
      $X_i \cap \class{x}{\sim} = \{x_i\}$. Since $X_i \leq_\ssim Z$
      there is $z_i \in Z$ such that $z_i \sim x_i$ and
      $x_i \leq z_i$. Now all the $x_i$'s are equivalent and thus
      all the $z_i$'s are so. This implies that they all coincide
      with some $z \in Z$. Now
      $y = \bigvee \{ x_i \mid X \cap \class{x}{\sim} \cap X_i =
      \{x_i\}\} \leq z$ and $x \sim x_i \sim z$. Thus
      $\alpha_\ssim(\bigcup_{i\in I} X_i) \leq_\ssim Z$.

      From the above characterisation of the least upper bound in
      $\poweq{L}{\ssim}$, it follows immediately that $\alpha_\ssim$
      is additive. Then an easy calculation proves that
      $\gamma_\ssim$, as given in the statement, is its adjoint.
    \end{proof}

    \begin{definition}[Pointwise lifting]
      \label{de:pointwise-lifting}
      Given
      $\langle \alpha, \gamma \rangle: \pow{\Sigma} \rightleftarrows
      A$ we call the corresponding image adjunction
      $\langle \dirIm{\alpha}, \invIm{\alpha} \rangle:
      \pow{\str{\operatorname{F}_{\Sigma}}} \to
      \pow{\str{\operatorname{F}_{A}}}$ the \emph{pointwise lifting} of
      $\langle \alpha, \gamma \rangle$.
    \end{definition}

    \begin{note}
      \label{no:BCAs}
      Observe that the fact that
      %
      the lifting is a Galois connection does
      not depend on the fact that
      $\langle \alpha, \gamma \rangle$ is a Galois
      connection. However this is useful to have BCAs of relevant
      operators, like $\loops$ and $\add$, that are directly computable in the
      abstract domain
      %
      %
      %
      %
      %
      %
      %
      %
      (see Theorem~\ref{th:BCAs}).
    \end{note}
  \end{toappendix}

