  We can now define the stack abstraction parameterised
  by an equivalence on the lattice of abstract
  frames.
  %
  Given an equivalence $\mathbin{\sim}\subseteq X\times X$ on any
  set $X$, $\sim_+$ denotes
  the equivalence on $\str{X}$ induced by $\sim$ as follows: for all
  $x_1 \cdots x_n,\: y_1\cdots y_m \in \str{A}$,
  $x_1 \ldots x_n \sim_+ y_1\ldots y_m \in \str{X}$ if $n=m$ and
  $x_i \sim y_i$ for all $i \in \set{1,\ldots, n}$.

  %

  \begin{definition}[Stack abstraction]
    \label{de:equivalence-abstraction}
    Let $\sim$ be a compatible equivalence on the abstract domain $A$
    and let us extend it to the lattice of abstract frames
    $\operatorname{F}_{A}$ by
    $\frame{\sigma_1^{\sharp},\delta_1^{\sharp}} \sim
    \frame{\sigma_2^{\sharp},\delta_2^{\sharp}}$ if
    $\sigma_1^{\sharp} \sim \sigma_2^{\sharp}$.  The
    \emph{$\sim$-stack abstraction} is the domain $\As \triangleq \poweq{\str{\operatorname{F}_{A}}}{\ssim}$ along with the Galois connection
    $\langle \alpha^s_{\ssim}, \gamma^s_{\ssim} \rangle :
    \pow{\str{\operatorname{F}_{\Sigma}}} \rightleftarrows
    \As$ defined by
    $\alpha^s_\ssim \triangleq \alpha_{\ssimplus} \circ \dirIm{\alpha}$
    and
    $\gamma^s_\ssim \triangleq \invIm{\alpha} \circ \gamma_{\ssimplus}$.
  \end{definition}

  In words, given a set $X$ of stacks, its abstraction
  $\alpha^s_\ssim(X)$ first applies pointwise the underlying $\alpha$
  to each stack in $X$, and then joins equivalent abstract stacks.  As
  corner cases we can have the identity relation $\mathbin{\sim} =
  \mathrm{id}$, which joins
  abstract frames with identical first component, and
  $\mathbin{\sim} =A \times A$,
  the trivial relation, which
  joins all abstract stacks into one.
  %

  \subparagraph{An abstract interpreter for counterexamples.}
  Given an abstraction for state properties
  $\langle \alpha,\gamma \rangle: \pow{\Sigma} \rightleftarrows A$ and
  a compatible equivalence on $A$, following the standard approach in
  abstract interpretation~\cite{cousot21}, we consider an abstract
  semantics
  $\sem{\r}^\sharp: \As \to
  \As$, defined inductively as explained
  %
  in~\S~\ref{sec:mocha} and 
  %
  using as abstract semantics for basic
  expressions $\e$ their BCAs on $\As$, 
  denoted 
  %
  by $\bsem{\e}^{\As}$.
  We write $\sem[]{\mathsf{r}}^{\sharp}$ instead of
  $\sem{\mathsf{r}}^{\sharp}$ when the abstract environment is inessential.
  %
  Notably, the BCAs of basic expressions 
  %
  independent from 
  the underlying system can be effectively defined, 
  and some of them result to be complete.
  %
  \begin{toappendix}
    We next prove technical lemma which shows that if a function $f$ over 
    concrete stacks only acts on the top frame, then also its BCA does.
  %
    \begin{lemma}
      \label{lem:top-frame}
      Let $f: \pow{\operatorname{F}_{\Sigma}^+} \to \pow{\operatorname{F}_{\Sigma}^+}$ and assume that there is a function
      $g : \operatorname{F}_{\Sigma} \to \operatorname{F}_{\Sigma}$ such that $f$ is the additive extension of
      \begin{equation*}
        f(\set{\frame{\sigma, \Delta} \concat S}) = \set{\frame{\sigma', \Delta'}\concat S \mid \frame{\sigma', \Delta'} \in g(\frame{\sigma, \Delta})}
      \end{equation*}
      Then $f^{A} : \pow{\operatorname{F}_{A}^+} \to \pow{\operatorname{F}_{A}^+}$ is the additive extension of
      \begin{equation*}
        f^{A}(\set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}}) = \set{\frame{\sigma^{\flat}, \Delta^{\flat}}\concat S^{\sharp} \mid 
        \frame{\sigma^{\flat}, \Delta^{\flat}} \in g^{A}(\frame{\sigma^{\sharp},\delta^{\sharp}})}
    \end{equation*}
    and $f^{\As} : \poweq{\operatorname{F}_{A}^+}{\ssim} \to \poweq{\operatorname{F}_{A}^+}{\ssim}$ is the additive extension of
      \begin{equation*}
        f^{\As}(\set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}}) = \set{\frame{\sigma^{\flat}, \Delta^{\flat}}\concat S^{\sharp} \mid 
        \frame{\sigma^{\flat}, \Delta^{\flat}} \in g^{\As}(\frame{\sigma^{\sharp},\delta^{\sharp}})}
    \end{equation*}
      \end{lemma}
      \begin{proof}
        %
        \begin{align*}
          f^{A}\left ( \set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}} \right ) 
          & = \dirIm{\alpha} f \invIm{\alpha}\left ( \set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}} \right ) \\
          & = \dirIm{\alpha} f \left ( \set{\frame{\sigma, \Delta} \concat S 
          \mid \alpha(\frame{\sigma, \Delta}) = \frame{\sigma^{\sharp}, \delta^{\sharp}} \land \alpha(S) = S^{\sharp}} \right ) \\
          & = \dirIm{\alpha} \left ( \left \{  \frame{\sigma', \Delta'} \concat S
          \mid \frame{\sigma', \Delta'} \in g(\frame{\sigma, \Delta}) \right . \right . \\ 
          & \qquad \left . \left . \land \ \alpha(\frame{\sigma, \Delta}) = \frame{\sigma^{\sharp}, \delta^{\sharp}} \land \alpha(S) = S^{\sharp} \right \} \right ) \\
          & = \set{\frame{\sigma'^{\sharp}, \delta'^{\sharp}} \concat S^{\sharp} \mid \frame{\sigma'^{\sharp}, \delta'^{\sharp}} 
          \in g^A(\frame{\sigma^{\sharp}, \delta^{\sharp}})}
        \end{align*}
        \begin{align*}
          f^{\As}\left ( \set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}} \right )  
          & = \alpha_{\ssimplus} f^{A} \gamma_{\ssimplus}\left ( \set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}} \right ) \\
          & = \alpha_{\ssimplus} f^{A} \left ( \left \{ \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} 
          \mid \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \sim \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp} \right . \right . \\
          & \qquad \left .  \left . \land \ \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} 
          \leq \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}\right \} \right ) \\
          & = \alpha_{\ssimplus} \left ( \left \{ \frame{\sigma'^{\flat}, \delta'^{\flat}} \concat S^{\flat}
          \mid \frame{\sigma'^{\flat}, \delta'^{\flat}} \in g^A(\frame{\sigma^{\flat}, \delta^{\flat}}) \right . \right . \\
          & \qquad \left . \left . \land \  \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \sim \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp} 
          \land \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \leq \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}
          \right \} \right ) \\
          & = \set{\frame{\sigma'^{\sharp}, \delta'^{\sharp}} \concat S^{\sharp} \mid \frame{\sigma'^{\sharp}, \delta'^{\sharp}} 
          \in g^{\As}(\frame{\sigma^{\sharp}, \delta^{\sharp}})}
        \end{align*}
      \end{proof}

    \begin{theorem}
      \label{th:BCAs}
      Let
      $\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}\in
      \str{\operatorname{F}_{A}}$ such that
      $\sigma^{\sharp} = \alpha(\set{\sigma})$ for some
      $\sigma \in \Sigma$.  Then the BCAs of the basic expressions
      $\loops, \add, \reset, \push, \pop$ in
      $\pow{{\str{\operatorname{F}_{A}}}}$ for the pointwise lifting
      (Definition~\ref{de:pointwise-lifting}) are as follows, where we write
      $\bsem{\cdot}^A$ as a shortcut for
      $\bsem{\cdot}^{\pow{{\str{\operatorname{F}_{A}}}}}$:
      \begin{center}
        \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l}
          $\bsem{\add}^A \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $=$ &
          $\set{\frame{\sigma^{\sharp}, \delta^{\sharp} \vee
          \sigma^{\sharp}} \concat S^{\sharp}}$ \\
          $\bsem{\reset}^{A} \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $=$ &
          $\set{\frame{\sigma^{\sharp}, \bot} \concat S^{\sharp}}$ \\
          $\bsem{\loops}^{A} \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $=$ &
          $\set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat
          S^{\sharp} \mid \sigma^{\sharp} \leq \delta^{\sharp}}$ \\
          $\bsem{\push}^{A} \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $=$ &
          $\set{\frame{\sigma^{\sharp}, \delta^{\sharp}} \concat
          \frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}}$ \\
          $\bsem{\pop}^{A}\set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $=$ & $\set{S^{\sharp}}$ \\
        \end{tabular}
      \end{center}
      Moreover, the three operations $\reset, \push, \pop$ are
      globally complete.
    \end{theorem}

    \begin{proof}
      \textbf{(BCA computation)} By exploiting Lemma~\ref{lem:top-frame}, we can compute the BCAs of $\add, \reset, \loops$
      considering only the top frame.
      \begin{align*}
        \bsem{\add}^{A} \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}}
        & =
        \dirIm{\alpha}(\bsem{\add}(\invIm{\alpha}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})))\\
        %
        & = \dirIm{\alpha}(\bsem{\add}(\set{\frame{\sigma,
              \Delta} \mid \alpha(\set{\sigma}) = \sigma^{\sharp}
        \ \land \ \alpha(\Delta) = \delta^{\sharp}}))\\
        %
        & = \dirIm{\alpha}( \set{ \frame{\sigma, \set{\sigma}
            \cup \Delta}  \mid \alpha(\set{\sigma}) =
        \sigma^{\sharp} \ \land \ \alpha(\Delta) = \delta^{\sharp}})\\
        & =  \set{ \frame{\alpha(\set{\sigma}), \alpha(\set{
          \sigma } \cup \Delta)} \mid \alpha(\set{\sigma}) =
        \sigma^{\sharp} \ \land \ \alpha(\Delta) = \delta^{\sharp}}\\
        %
        & \overset{\clubsuit}{=}  \set{
          \frame{\alpha(\set{\sigma}), \alpha(\set{
          \sigma } ) \vee \alpha(\Delta)}  \mid \alpha(\set{\sigma}) =
        \sigma^{\sharp} \ \land \ \alpha(\Delta) = \delta^{\sharp}}\\
        %
        & =  \set{ \frame{\sigma^{\sharp}, \delta^{\sharp} \vee
        \sigma^{\sharp}}  } %
      \end{align*}
      where the ($\clubsuit$) passage uses additivity of $\alpha$.

      \begin{align*}
      \bsem{\reset}^{A} \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}}
        & =
        \dirIm{\alpha}(\bsem{\reset}(\invIm{\alpha}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}}))) \\
        & = \dirIm{\alpha}(\bsem{\reset}(\set{\frame{\sigma,
              \Delta}
              \mid \alpha(\set{\sigma}) = \sigma^{\sharp}
        \land \alpha(\Delta) = \delta^{\sharp}})) \\
        & = \dirIm{\alpha}(\set{\frame{\sigma,
            \varnothing} \mid \alpha(\set{\sigma}) =
        \sigma^{\sharp}}) \\
        & = \set{\frame{\sigma^{\sharp}, \bot}} %
        %
      \end{align*}
      %
      \begin{align*}
        %
        \bsem{\loops}^{A}  (\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})
        & =
        \dirIm{\alpha}(\bsem{\loops}(\invIm{\alpha}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})))\\
        %
        & = \dirIm{\alpha}( \bsem{\loops}(\set{\frame{\sigma,
              \Delta} \mid \alpha(\set{\sigma}) =
        \sigma^{\sharp}\ \land\ \alpha(\Delta) = \delta^{\sharp}}))\\
        %
        & = \dirIm{\alpha}( \set{\frame{\sigma, \Delta} \mid
            \alpha(\set{\sigma}) =
        \sigma^{\sharp}\ \land\ \alpha(\Delta) = \delta^{\sharp} })\\
        %
        & \overset{\heartsuit}{=} \set{ \frame{\sigma^{\sharp},
          \delta^{\sharp}} \mid \sigma^{\sharp}
          \leq \delta^{\sharp}} %
      \end{align*}
      where the ($\heartsuit$) passage uses the fact that there if there is
      $\sigma$ such that $\sigma^{\sharp} =
      \sigma_\Sigma(\set{\sigma})$, then by the
      properties of the adjunction
      $\set{ \sigma} \leq \gamma(\delta^{\sharp})$ iff
      $\sigma^{\sharp} = \alpha(\set{\sigma}) \leq \delta^{\sharp}$.
      \begin{align*}
        & \bsem{\push}^{A} \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}
        \concat S^{\sharp}} %
        = \dirIm{\alpha}(\bsem{\push}(\invIm{\alpha}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}\concat S^{\sharp}}))) \\
        & = \dirIm{\alpha}(\bsem{\push}(\set{\frame{\sigma,
              \Delta}\concat S \mid
              \alpha(\set{\sigma}) = \sigma^{\sharp}
        \land \alpha(\Delta) = \delta^{\sharp} 
        \ \land \ S \in \invIm{\alpha}(S^{\sharp})})) \\
        & = \dirIm{\alpha}(\set{\frame{\sigma,
            \Delta}\concat\, \frame{\sigma,
            \Delta}\concat S \mid
            \alpha(\set{\sigma}) = \sigma^{\sharp}
        \land \alpha(\Delta) = \delta^{\sharp} 
        \ \land \ S \in \invIm{\alpha}(S^{\sharp})}) \\
        & = \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat\,
        \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}}\\
        & \\ 
        & \bsem{\pop}^{A}  \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}
        \concat S^{\sharp}} %
        = \dirIm{\alpha}(\bsem{\pop}(\invIm{\alpha}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}\concat S^{\sharp}}))) \\
        & = \dirIm{\alpha}(\bsem{\pop}(\set{\frame{\sigma,
              \Delta}\concat S \mid
              \alpha(\set{\sigma}) = \sigma^{\sharp}
        \land \alpha(\Delta) = \delta^{\sharp} 
        \ \land \ S \in \invIm{\alpha}(S^{\sharp})})) \\
        & = \dirIm{\alpha}(\invIm{\alpha}(S^{\sharp})) %
        =  \set{S^{\sharp}}%
      \end{align*}
%
      \textbf{(Global Completeness)} Let $\cel = \set{\frame{\sigma_i,
        \Delta_i}\concat S_i \mid  i
      \in I }$.
%
      \begin{align*}
        (\dirIm{\alpha} \circ \bsem{\reset})(\cel) & =
        \dirIm{\alpha} \left (
          \set{\frame{\sigma_i, \varnothing}
        \concat S_i \mid \ i \in I} \right ) \\
        & = \set{\frame{\alpha(\set{\sigma_i}), \bot} \concat
        \dirIm{\alpha}(S_i) \mid i \in I}\\
        %
        (\bsem{\reset}^{A}\circ \dirIm{\alpha})(\cel) & =
        \bsem{\reset}^{A} \left (
          \set{\frame{\alpha(\set{\sigma_i}),
            \alpha(\Delta_i)}\concat \dirIm{\alpha}(S_i) \mid
        i \in I} \right ) \\
        & = \set{\frame{\alpha(\set{\sigma_i}), \bot} \concat
        \dirIm{\alpha}(S_i) \mid i \in I}
      \end{align*}
      %
      \begin{align*}
        (\dirIm{\alpha} \circ \bsem{\push})(\cel) & =
        \dirIm{\alpha} \left (
          \set{\frame{\sigma_i, \Delta_i}
            \concat\, \frame{\sigma_i, \Delta_i}
        \concat S_i \mid \ i \in I} \right ) \\
        & =
        \set{\frame{\alpha(\set{\sigma_i}),\alpha(\Delta_i)}
          \concat\, \frame{\alpha(\set{\sigma_i}),\alpha(\Delta_i)}
          \concat
        \dirIm{\alpha}(S_i) \mid i \in I}\\
        %
        (\bsem{\push}^{A}\circ \dirIm{\alpha})(\cel) & =
        \dirIm{\alpha} \left (
          \set{\frame{\sigma_i, \Delta_i}
            \concat\, \frame{\sigma_i, \Delta_i}
        \concat S_i \mid \ i \in I} \right ) \\
        & =
        \set{\frame{\alpha(\set{\sigma_i}),\alpha(\Delta_i)}
          \concat\, \frame{\alpha(\set{\sigma_i}),\alpha(\Delta_i)}
          \concat
        \dirIm{\alpha}(S_i) \mid i \in I}
      \end{align*}
      %
      \begin{align*}
        (\dirIm{\alpha} \circ \bsem{\pop})(\cel) & =
        \dirIm{\alpha} \left (
        \set{S_i \mid \ i \in I} \right ) \\
        & =
        \set{\dirIm{\alpha}(S_i) \mid i \in I}\\
        %
        (\bsem{\pop}^{A}\circ \dirIm{\alpha})(\cel) & =
        \bsem{\pop}^{A} \left (
          \set{\frame{\alpha(\set{\sigma_i}),
            \alpha(\Delta_i)}\concat \dirIm{\alpha}(S_i) \mid
        i \in I} \right ) \\
        & =
        \set{\dirIm{\alpha}(S_i) \mid i \in I}%
        %
      \end{align*}
    \end{proof}

    When we move to coarser abstractions based on a compatible
    equivalence over the domain $A$, we can still retain a similar result.
    %
    %


    \begin{definition}[strong equivalence]
      \label{def:strong-eq}
      Let
      $\langle \alpha,\gamma \rangle: \pow{\Sigma} \rightleftarrows A$
      be an abstraction of state properties and let $\sim$ be a
      compatible equivalence on the abstract domain $A$. Say that a
      set of states $X \subseteq \Sigma$ is $\sim$-uniform if for all
      $\sigma, \sigma' \in X$
      $\alpha(\{\sigma\}) \sim \alpha(\{\sigma'\})$. We say that $\sim$
      is \emph{strong} when for all $X \subseteq \Sigma$ $\sim$-uniform it
      holds that $\gamma(\alpha(X))$ is $\sim$-uniform.
    \end{definition}
    %
    \begin{remark}[equivalence properties]
      \label{rem:eq}
      Let $\sigma$ be a strong equivalence and let
      $\sigma_1^\sharp, \sigma_2^\sharp$ such that
      $\sigma_1^\sharp \leq \sigma_2^\sharp$. If
      $\sigma_2^\sharp = \alpha(X)$ for some $\sim$-uniform set
      $X \subseteq \Sigma$ then
      $\sigma_1^\sharp = \alpha(\gamma(\sigma_1^\sharp))$ with
      $\gamma(\sigma_1^\sharp) \subseteq \gamma(\sigma_2^\sharp) =
      \gamma(\alpha(X))$. Hence also $\sigma_1^\sharp = \alpha(Y)$ for
      $Y = \gamma(\sigma_2^\sharp)$ a $\sim$-uniform set and thus
      $\sigma_1^\sharp \sim \sigma_2^{\sharp}$.
    \end{remark}
