    \begin{theorem}
      \label{th:BCAs-equiv}
      Let
      $\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}\in
      \str{\operatorname{F}_{A}}$ and consider an abstraction as in
      Definition~\ref{de:equivalence-abstraction}.
      %
      Then the BCAs of the basic expressions $\loops, \add, \reset,$
      in the domain $\As = \pow{\str{\operatorname{F}_A}}_\ssim$, denoted
      $\bsem{\cdot}^{\As}$, computed with respect to the
      pointwise lifting (Definition~\ref{de:pointwise-lifting}) are the same
      as Theorem~\ref{th:BCAs}, with the exception of operator $\loops$ for which we have
      \begin{center}
        \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l}
          $\bsem{\loops}^{\As} \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}} \concat S^{\sharp}}$ & $\leq_\ssim$ &
          $\set{\frame{\sigma^{\sharp},
            \delta^{\sharp}} \concat S^{\sharp} \mid \sigma^{\sharp}
          \wedge \delta^{\sharp} \neq \bot}$ \\
