    \begin{proof}
      \textbf{(BCA computation)} By exploiting Lemma~\ref{lem:top-frame}, we can compute the BCAs of $\add, \reset, \loops$
      considering only the top frame.
      \begin{align*}
        \bsem{\add}^{\As}(\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}})
        &= \alpha_{\ssimplus}(\bsem{\add}^{A}(\gamma_{\ssimplus}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})))\\
        %
        & \hspace{-5ex} = \alpha_{\ssimplus}(\bsem{\add}^{A}(
            \class{\frame{\sigma^{\sharp}, \delta^{\sharp}}}{\sim}
        \cap \cone{\frame{\sigma^{\sharp}, \delta^{\sharp}}}))\\
        %
        & \hspace{-5ex}=   \alpha_{\ssimplus} \left (\bsem{\add}^{A}\left(
            \set{\frame{\sigma^{\flat}, \delta^{\flat}} \mid
              \frame{\sigma^{\flat}, \delta^{\flat}} \sim
              \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
              \frame{\sigma^{\flat}, \delta^{\flat}} \leq
        \frame{\sigma^{\sharp}, \delta^{\sharp}}}\right)\right )\\
        %
        & \hspace{-5ex}=   \alpha_{\ssimplus} \left (
          \set{\frame{\sigma^{\flat}, \delta^{\flat} \vee
            \sigma^{\flat}} \mid
            \frame{\sigma^{\flat}, \delta^{\flat}} \sim
            \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
            \frame{\sigma^{\flat}, \delta^{\flat}} \leq
        \frame{\sigma^{\sharp}, \delta^{\sharp}}} \right )\\
        %
        &  \hspace{-5ex} \overset{\clubsuit}{=}  \set{\frame{\sigma^{\sharp},
        \delta^{\sharp} \vee \sigma^{\sharp}}}
      \end{align*}
      %
      \begin{align*}     
        \hspace{-2ex} \bsem{\reset}^{\As} \set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}} %
        & = \alpha_{\ssimplus}(\bsem{\reset}^{A}(\gamma_{\ssimplus}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})))\\
        %
        & = \alpha_{\ssimplus} \left (\bsem{\reset}^{A} \left (
            \class{\frame{\sigma^{\sharp}, \delta^{\sharp}}}{\sim}
        \cap \cone{\frame{\sigma^{\sharp}, \delta^{\sharp}}}\right) \right)\\
        %
        & = \alpha_{\ssimplus}\left (\bsem{\reset}^{A} \left (
            \set{\frame{\sigma^{\flat}, \delta^{\flat}} \mid
              \frame{\sigma^{\flat}, \delta^{\flat}}\sim
              \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
              \frame{\sigma^{\flat}, \delta^{\flat}}\leq
        \frame{\sigma^{\sharp}, \delta^{\sharp}}}\right ) \right )\\
        %
        & = \alpha_{\ssimplus} \left (
          \set{\frame{\sigma^{\flat}, \bot} \mid
            \frame{\sigma^{\flat}, \delta^{\flat}} \sim
            \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
            \frame{\sigma^{\flat}, \delta^{\flat}} \leq
        \frame{\sigma^{\sharp}, \delta^{\sharp}}}\right )\\
        %
        & \overset{\clubsuit}{=} \set{\frame{\sigma^{\sharp}, \bot}}
      \end{align*}

      Where  at 
      ($\clubsuit$) we use the fact that frame equivalence only depends on its first component.

      For $\loops$ we have
      \begin{align*} 
        \hspace{-2ex} \bsem{\loops}^{\As} \set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}}  %
        & = \alpha_{\ssimplus}(\bsem{\loops}^{A}(\gamma_{\ssimplus}(\set{\frame{\sigma^{\sharp},
        \delta^{\sharp}}})))\\
        %
        & = \alpha_{\ssimplus}(\bsem{\loops}^{A}(
            \class{\frame{\sigma^{\sharp}, \delta^{\sharp}}}{\sim}
        \cap \cone{\frame{\sigma^{\sharp}, \delta^{\sharp}}}))\\
        %
        & = \alpha_{\ssimplus}\left (\bsem{\loops}^{A}\left(
