              \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
              \frame{\sigma^{\flat}, \delta^{\flat}} \leq
        \frame{\sigma^{\sharp}, \delta^{\sharp}}}\right ) \right)\\
        %
        & = \alpha_{\ssimplus}\left (
          \set{\frame{\sigma^{\flat}, \delta^{\flat}} \mid
            \frame{\sigma^{\flat}, \delta^{\flat}} \sim
            \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
            \frame{\sigma^{\flat}, \delta^{\flat}} \leq
            \frame{\sigma^{\sharp}, \delta^{\sharp}}\land \sigma^{\flat}
        \leq \delta^{\flat}}\right)\\
        %
        & = \alpha_{\ssimplus}\left(
          \set{\frame{\sigma^{\flat}, \delta^{\flat}} \mid
            \frame{\sigma^{\flat}, \delta^{\flat}} \sim
            \frame{\sigma^{\sharp}, \delta^{\sharp}} \land
            \sigma^{\flat} \leq \sigma^{\sharp} \land
            \delta^{\flat} \leq  \delta^{\sharp}
        \land \sigma^{\flat} \leq \delta^{\flat}}\right )\\
      %
        & = \set{\frame{\bigvee \set{\sigma^{\flat} \mid \sigma^{\flat} \sim
          \sigma^{\sharp} \land
          \sigma^{\flat} \leq \sigma^{\sharp}          
          \land \sigma^{\flat} \leq \delta^{\sharp}}, \delta^{\sharp}} }\\
    %
        & = \set{\frame{\bigvee \set{\sigma^{\flat} \mid \sigma^{\flat} \sim
          \sigma^{\sharp} \land
          \sigma^{\flat} \leq \sigma^{\sharp} \wedge \delta^{\sharp}    
           }, \delta^{\sharp}}}\\
        %
        & \leq_\ssim
        \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}
          \mid \sigma^{\sharp}
        \wedge \delta^{\sharp} \neq \bot}
      \end{align*}

      When the equivalence is strong, in the last passage we obtain
      $\bsem{\loops}^{\As} \set{\frame{\sigma^{\sharp},
          \delta^{\sharp}}} = \set{\frame{\sigma^{\sharp}\wedge
          \delta^{\sharp}, \delta^{\sharp}} \mid
        \sigma^{\sharp} \wedge \delta^{\sharp} \neq \bot}$. In fact,
      as observed in Remark~\ref{rem:eq}, the assumption of dealing with a strong equivalence, 
      guarantees that for all $\sigma^{\flat}$ such that
      $\sigma^{\flat} \leq \sigma^{\sharp}$ it holds
      $\sigma^\flat \sim \sigma^{\sharp}$.
      %
      \begin{align*}
       & \bsem{\push}^{\As}(\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}})
        =\\
        & =
          \alpha_{\ssimplus}(\bsem{\push}^{A}(\gamma_{\ssimplus}(\set{\frame{\sigma^{\sharp},
