      %
      & \\
      %
      %
        & \bsem{\pop}^{\As}(\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}})
        =\\
        & =
          \alpha_{\ssimplus}(\bsem{\pop}^{A}(\gamma_{\ssimplus}(\set{\frame{\sigma^{\sharp},
          \delta^{\sharp}}\concat S^{\sharp}})))\\
          %
          & = \alpha_{\ssimplus}(\bsem{\pop}^{A}(
              \class{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}}{\sim}
          \cap \cone{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}}))\\
          %
          & = \alpha_{\ssimplus}\left (\bsem{\pop}^{A}\left(
              \set{\frame{\sigma^{\flat}, \delta^{\flat}} \concat S^{\flat} \mid
                \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \sim
                \frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp} \land
                \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \leq
          \frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}}\right) \right)\\
          %
          & = \alpha_{\ssimplus} \set{S^{\flat} \mid 
          \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \sim
          \frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp} \land
          \frame{\sigma^{\flat}, \delta^{\flat}}\concat S^{\flat} \leq
    \frame{\sigma^{\sharp}, \delta^{\sharp}} \concat S^{\sharp}}\\
        %
        & = \set{S^{\sharp}}
      \end{align*}
      \textbf{(Global Completeness)} Let $\ela = \set{\frame{\sigma^{\sharp}_i,
          \delta^{\sharp}_i}\concat S^{\sharp}_i \mid i \in I } \in \As = \pow{\str{\operatorname{F}_A}}$.

      \subparagraph*{Operator $\reset$}
        \begin{align*}
          (\alpha_{\ssimplus} \circ \bsem{\reset}^A)(\ela) & =
          \alpha_{\ssimplus} \left (
            \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I} \right ) \\
          & = \set{\bigvee \class{\frame{\sigma^{\sharp}_j, \bot} \concat S^{\sharp}_j}{\sim} 
          \cap  \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I} \mid j \in I} \\
          & = \set{\frame{\overline{\sigma^{\sharp}_j}, \bot} \concat \overline{S^{\sharp}_j} \mid j \in I}
        \end{align*}
        where we named $\frame{\overline{\sigma^{\sharp}_j}, \bot} \concat \overline{S^{\sharp}_j} = 
        \bigvee \class{\frame{\sigma^{\sharp}_j, \bot} \concat S^{\sharp}_j}{\sim} 
        \cap  \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I}$.
        \begin{align*}
          (\bsem{\reset}^{\As}\circ \alpha_{\ssimplus})(\ela) & =
          \bsem{\reset}^{\As} \left (
            \set{\bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
            \cap  \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I} \mid j \in I} \right ) \\
          & = \bsem{\reset}^{\As}\set{\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
          \concat \widehat{S^{\sharp}_j} \mid j \in I} \\
          & = \set{\frame{\widehat{\sigma^{\sharp}_j}, \bot} 
          \concat \widehat{S^{\sharp}_j} \mid j \in I} 
        \end{align*}
where $\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
        \concat \widehat{S^{\sharp}_j} =  \bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
        \cap  \set{\frame{\sigma^{\sharp}_i, \delta_i^{\sharp}}
      \concat S^{\sharp}_i \mid \ i \in I}$ and actually for all $j \in I$ we have 
      $\frame{\overline{\sigma^{\sharp}_j}, \bot} \concat \overline{S^{\sharp}_j} = \frame{\widehat{\sigma^{\sharp}_j}, \bot} 
          \concat \widehat{S^{\sharp}_j}$ by the strongness of the equivalence and the fact that 
        the order $\leq$ is pointwise on frame components and on stacks (sequences). 
        %

        \subparagraph*{Operator $\push$}
        \begin{align*}
          (\alpha_{\ssimplus} \circ \bsem{\push}^A)(\ela) & =
          \alpha_{\ssimplus} \left (
            \set{\frame{\sigma^{\sharp}_i, \delta^{\sharp}_i} \concat \frame{\sigma^{\sharp}_i, \delta^{\sharp}_i}
          \concat S^{\sharp}_i \mid \ i \in I} \right ) \\
          & = \set{\bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat \frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
          \cap  \set{\frame{\sigma^{\sharp}_i, \delta^{\sharp}_i} \concat \frame{\sigma^{\sharp}_i, \delta^{\sharp}_i}
          \concat S^{\sharp}_i \mid \ i \in I} \mid j \in I} \\
          & = \set{\frame{\overline{\sigma^{\sharp}_j}, \overline{\delta^{\sharp}_j}} \concat \frame{\overline{\sigma^{\sharp}_j}, \overline{\delta^{\sharp}_j}} \concat \overline{S^{\sharp}_j} \mid j \in I}
        \end{align*}
        %
        where $\frame{\overline{\sigma^{\sharp}_j}, \overline{\delta^{\sharp}_j}} \concat \frame{\overline{\sigma^{\sharp}_j}, 
        \overline{\delta^{\sharp}_j}} \concat \overline{S^{\sharp}_j} = 
        \bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat \frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
        \cap  \set{\frame{\sigma^{\sharp}_i, \delta^{\sharp}_i}
        \concat \frame{\sigma^{\sharp}_i, \delta^{\sharp}_i}
        \concat S^{\sharp}_i \mid \ i \in I}$.

        \begin{align*}
          (\bsem{\push}^{\As}\circ \alpha_{\ssimplus})(\ela) & =
          \bsem{\push}^{\As} \left (
            \set{\bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
            \cap  \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I} \mid j \in I} \right ) \\
          & = \bsem{\push}^{\As}\set{\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
          \concat \widehat{S^{\sharp}_j} \mid j \in I} \\
          & = \set{\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
          \concat \frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
          \concat \widehat{S^{\sharp}_j} \mid j \in I} \\
        \end{align*}
        where $\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
        \concat \widehat{S^{\sharp}_j} =  \bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
        \cap  \set{\frame{\sigma^{\sharp}_i, \delta_i^{\sharp}}
      \concat S^{\sharp}_i \mid \ i \in I}$ and actually for all $j \in I$ we have 
      $\frame{\overline{\sigma^{\sharp}_j}, \overline{\delta^{\sharp}_j}} \concat \frame{\overline{\sigma^{\sharp}_j}, 
      \overline{\delta^{\sharp}_j}} \concat \overline{S^{\sharp}_j} = \frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
      \concat \frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
      \concat \widehat{S^{\sharp}_j}$ since 
        the order $\leq$ is pointwise on frame components and on stacks (sequences). 


        \subparagraph*{Operator $\pop$}

        \begin{align*}
          (\alpha_{\ssimplus} \circ \bsem{\pop}^A)(\ela) & =
          \alpha_{\ssimplus} \left (
            \set{S^{\sharp}_i \mid \ i \in I} \right ) \\
          & = \set{\bigvee \class{S^{\sharp}_j}{\sim} 
          \cap  \set{S^{\sharp}_i \mid \ i \in I} \mid j \in I} \\
          & = \set{\overline{S^{\sharp}_j} \mid j \in I}
        \end{align*}
        %
        where $\overline{S^{\sharp}_j} = 
        \bigvee \class{S^{\sharp}_j}{\sim} 
        \cap  \set{S^{\sharp}_i \mid \ i \in I}$.

          \begin{align*}
          (\bsem{\pop}^{\As}\circ \alpha_{\ssimplus})(\ela) & =
          \bsem{\pop}^{\As} \left (
            \set{\bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
            \cap  \set{\frame{\sigma^{\sharp}_i, \bot}
          \concat S^{\sharp}_i \mid \ i \in I} \mid j \in I} \right ) \\
          & = \bsem{\pop}^{\As}\set{\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
          \concat \widehat{S^{\sharp}_j} \mid j \in I} \\
          & = \set{\widehat{S^{\sharp}_j} \mid j \in I}
        \end{align*}
        where $\frame{\widehat{\sigma^{\sharp}_j}, \widehat{\delta^{\sharp}_j}} 
        \concat \widehat{S^{\sharp}_j} =  \bigvee \class{\frame{\sigma^{\sharp}_j, \delta^{\sharp}_j} \concat S^{\sharp}_j}{\sim} 
        \cap  \set{\frame{\sigma^{\sharp}_i, \delta_i^{\sharp}}
      \concat S^{\sharp}_i \mid \ i \in I}$ and actually for all $j \in I$ we have $\overline{S^{\sharp}_j} = \widehat{S^{\sharp}_j}$ 
      since the order $\leq$ is pointwise on frame components and on stacks (sequences), and whenever it happens that 
      $\frame{\sigma^{\sharp}_1, \delta^{\sharp}_1}\concat S^{\sharp}_1 \not\sim \frame{\sigma^{\sharp}_2, \delta^{\sharp}_2}\concat S^{\sharp}_2$
      but $S^{\sharp}_1 \sim S^{\sharp}_2$, then the $\bsem{\pop}^{\As}$ also takes their least upper bound, 
      yielding the same least upper bound we find if we remove the top element first. 
    \end{proof}

