\begin{toappendix}
  %
  The next lemma shows that, besides providing a result which depends only on the top frame, programs associated with formulae operate as filters also at the abstract level.

    \begin{proposition}[Top-frame]
      \label{prop:top-frame}
      Let $\sim$ be a compatible equivalence on the abstract domain
  $A$. For all
  $\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}\in
  \str{\operatorname{F}_{A}}$ and $\varphi$ formula, it holds 
  \begin{equation}\label{eq:strong-top-frame}
  \sem{\PtoR{\varphi}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} 
  = \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp}
  \end{cases}
  \end{equation}
\end{proposition}
%
\begin{proof}
We prove the statement 
by induction on the structure of $\varphi$. 
\paragraph*{ACTL.} Let us first note that the environment is inessential for ACTL formulae, so we omit it.
\subparagraph*{($\varphi = p$)}  By exploiting Lemma~\ref{lem:top-frame}, we can compute counterexamples to $p$ by looking at the top frame. 
\begin{align*}
  & \hspace{-3ex} \sem[]{\PtoR{p}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}} %
  = \sem[]{\np}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}} \\ 
  &  \hspace{-3ex} = \alpha_{\ssimplus}\dirIm{\alpha}\sem[]{\np}\invIm{\alpha}\gamma_{\ssimplus}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}}  \\ 
  &  \hspace{-3ex} = \alpha_{\ssimplus}\dirIm{\alpha}\sem[]{\np}\invIm{\alpha}\left \{ \frame{\sigma^{\flat}, \delta^{\flat}} 
  \mid \frame{\sigma^{\flat}, \delta^{\flat}}\sim \frame{\sigma^{\sharp}, \delta^{\sharp}} \right . \\ & \qquad \left . 
  \land \ \frame{\sigma^{\flat}, \delta^{\flat}}\ \leq \frame{\sigma^{\sharp}, \delta^{\sharp}}\right \}  \\
  &  \hspace{-3ex}= \alpha_{\ssimplus}\dirIm{\alpha}\sem[]{\np} \left \{ \frame{\sigma, \Delta} 
  \mid \alpha(\frame{\sigma, \Delta}) = \frame{\sigma^{\flat}, \delta^{\flat}} \
  %
  \land  \ \frame{\sigma^{\flat}, \delta^{\flat}} \sim \frame{\sigma^{\sharp}, \delta^{\sharp}}
  \land \frame{\sigma^{\flat}, \delta^{\flat}} \leq \frame{\sigma^{\sharp}, \delta^{\sharp}} \right \}  \\
  &  \hspace{-3ex} = \alpha_{\ssimplus}\dirIm{\alpha} \left \{ \frame{\sigma, \Delta} 
  \mid \alpha(\frame{\sigma, \Delta}) = \frame{\sigma^{\flat}, \delta^{\flat}}, \ \sigma \models \neg p 
 %
  \land \ \frame{\sigma^{\flat}, \delta^{\flat}} \sim \frame{\sigma^{\sharp}, \delta^{\sharp}}
  \land \frame{\sigma^{\flat}, \delta^{\flat}} \leq \frame{\sigma^{\sharp}, \delta^{\sharp}} \right \}  \\
  &  \hspace{-3ex}= \alpha_{\ssimplus} \left \{ \frame{\sigma^{\flat}, \delta^{\flat}} \mid \exists \sigma \in \invIm{\alpha}(\set{\sigma^{\flat}}). \ \sigma \models \neg p 
  %
  \land \ \frame{\sigma^{\flat}, \delta^{\flat}} \sim \frame{\sigma^{\sharp}, \delta^{\sharp}}
  \land \frame{\sigma^{\flat}, \delta^{\flat}} \leq \frame{\sigma^{\sharp}, \delta^{\sharp}}\right \} \\
  &  \hspace{-3ex}= \set{\frame{\sigma_1^{\sharp}, \delta^{\sharp}} \mid \exists \sigma \in \invIm{\alpha}(\sigma_1^{\sharp}). \sigma \models \neg p}
\end{align*}
where $\sigma_1^{\sharp}$ is defined as
\begin{equation*}
  %
  \sigma_1^{\sharp} = \bigvee_{\sigma^{\flat} \leq_{\ssim} \sigma^{\sharp} } \set{\sigma^{\flat} 
  \mid \exists \sigma \in \invIm{\alpha}(\set{\sigma^{\flat}}). \sigma \models \neg p} 
\end{equation*} 
hence $\sigma_1^{\sharp} \sim \sigma^{\sharp}$ by transitivity and $\sigma_1^{\sharp}\leq \sigma^{\sharp}$. 
The case $\neg p$ is analogous.
%
\subparagraph*{($\varphi = \varphi_1 \land \varphi_2$)} 
\begin{align*}
  & \sem[]{\PtoR{\varphi_1 \land \varphi_2}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} %
  = 
  \sem[]{\PtoR{\varphi_1} \oplus \PtoR{\varphi_2}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  & = \sem[]{\PtoR{\varphi_1}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \vee
  \sem[]{\PtoR{\varphi_2}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  & \overset{\heartsuit}{=} \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp}
  \end{cases} \vee \ \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_2^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_2^{\sharp} \leq \sigma^{\sharp}, \ \sigma_2^{\sharp} \sim \sigma^{\sharp}
  \end{cases}  \\
  & = \begin{cases}
    \varnothing \\ 
    \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp} \\ 
    \set{\frame{\sigma_2^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_2^{\sharp} \leq \sigma^{\sharp}, \ \sigma_2^{\sharp} \sim \sigma^{\sharp} \\
    \set{\frame{\sigma_3^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_3^{\sharp} = \sigma_1^{\sharp} \vee \sigma_2^{\sharp} \leq \sigma^{\sharp}, 
    \ \sigma_3^{\sharp} \sim \sigma_1^{\sharp} \sim \sigma_2^{\sharp} \sim \sigma^{\sharp}
  \end{cases}
\end{align*}
where at $(\heartsuit)$ we used the inductive hypothesis for $\varphi_1$ and $\varphi_2$.
%
\subparagraph*{($\varphi = \varphi_1 \lor \varphi_2$)} 
\begin{align*}
  & \sem[]{\PtoR{\varphi_1 \lor \varphi_2}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} %
  =
  \sem[]{\PtoR{\varphi_1} ; \PtoR{\varphi_2}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  & = \sem[]{\PtoR{\varphi_2}}^{\As}\left (\sem[]{\PtoR{\varphi_1}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \right) \\
  & \overset{\heartsuit}{=} \sem[]{\PtoR{\varphi_2}}^{\As} \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp}
  \end{cases} \\
  & \overset{\clubsuit}{=} \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_2^{\sharp},\delta^{\sharp}}\concat S^{\sharp}} & \sigma_2^{\sharp} \leq \sigma_1^{\sharp} \leq \sigma^{\sharp}, 
    \ \sigma_2^{\sharp} \sim \sigma_1^{\sharp} \sim \sigma^{\sharp}
  \end{cases} \\
\end{align*}
where at $(\heartsuit)$ we used the inductive hypothesis for $\varphi_1$ and at $(\clubsuit)$ for $\varphi_2$.
%
\subparagraph*{($\varphi = \AX \varphi_1$)} 
\begin{align*}
  & \sem[]{\PtoR{\AX \varphi_1}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} 
  %
  = \sem[]{\push; \nexte; \PtoR{\varphi_1}; \pop}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  %
  & = \sem[]{\pop}^{\As}\left (\sem[]{\PtoR{\varphi_1}}^{\As}\left (\sem[]{\nexte}^{\As}
  \left (\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \right ) \right ) \right ) \\
  & \overset{\clubsuit}{=} \sem[]{\pop}^{\As}\left (\sem[]{\PtoR{\varphi_1}}^{\As}
  \left (\set{\frame{\sigma^{\flat}, \delta^{\sharp}}\concat \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp} 
  \mid \frame{\sigma^{\flat}, \delta^{\sharp}} \in \sem[]{\nexte}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}}} \right ) \right ) \\
  & \overset{\heartsuit}{=} \sem[]{\pop}^{\As}
  \begin{cases} 
    \varnothing \\
    T \subseteq \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}}\concat \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} 
    & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp}
  \end{cases} \\
  & = \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma^{\sharp},\delta^{\sharp}}\concat S^{\sharp}}
  \end{cases} \\
\end{align*}
as desired, since $\sigma^{\sharp} \sim \sigma^{\sharp}$ and $\sigma^{\sharp} \leq \sigma^{\sharp}$. 
Note that at $(\heartsuit)$ we used the inductive hypothesis and at $(\clubsuit)$ we use Lemma~\ref{lem:top-frame}, 
noticing additionally that the operator $\nexte$ 
only changes the current state and leaves the trace $\delta^{\sharp}$ unchanged.
%
\subparagraph*{($\varphi = \AF \varphi_1$)} 
\begin{align*}
  \sem[]{\PtoR{\AF \varphi_1}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}}
  & = \sem[]{\PtoR{\varphi_1}; \r}^{\As}
  \set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  & \overset{\heartsuit}{=} \sem[]{\r}^{\As}\begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_1^{\sharp},\delta^{\sharp}} \concat S^{\sharp}} 
    & \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp} \\ 
  \end{cases} 
\end{align*}
where$\r = \push; \reset; (\add; \nexte; \PtoR{\varphi_1})^*; \loops;  \pop$ and at $(\heartsuit)$ we use the inductive hypothesis. 
Now if the result is $\varnothing$, the computation will yield $\varnothing$. Hence we proceed as in the second case: 
\begin{align*}
  & \sem[]{\push; \reset; (\add; \nexte; \PtoR{\varphi_1})^*; \loops;  \pop}^{\As}\set{\frame{\sigma_1^{\sharp},\delta^{\sharp}} \concat S^{\sharp}} \\ 
  %
  & \quad = \sem[]{\pop}^{\As}\left ( \sem[]{\loops}^{\As}\left ( \sem[]{(\add; \nexte; \PtoR{\varphi})^*}^{\As}\left ( 
      \set{\frame{\sigma_1^{\sharp},\bot} \concat \frame{\sigma_1^{\sharp},\delta^{\sharp}} \concat S^{\sharp}} \right ) \right ) \right ) %
\end{align*}
We obtain a subset $T$ of $\set{\frame{\sigma^{\sharp}_{k_i}, \delta^{\sharp}_{k_i}} \concat \frame{\sigma_1^{\sharp}, \delta^{\sharp}} \concat S^{\sharp} \mid 
\frame{\sigma^{\sharp}_{k_i}, \delta^{\sharp}_{k_i}} \in \sem[]{(\add; \nexte; \PtoR{\varphi})^k}^{\As}(\frame{\sigma_1^{\sharp}, \bot})}$, 
exploiting the definition of $\sem[]{\add}^{\As}$, the lemma ensuring the property of the $\nexte$ operator and the inductive hypothesis on $\PtoR{\varphi}$. 
Then, we filter $T$ with $\sem[]{\loops}^{\As}$, which is the BCA of a filter, hence has the top-frame dependence property, 
and finally we apply $\sem[]{\pop}^{\As}$, which let us conclude as in the $\AX$ case.
%
The cases $\AG \varphi_1$ and $\varphi_1 \AU \varphi_2$ are analogous. 
%
\paragraph*{$\mu$-calculus}
We first prove that the following weaker property holds for all closed formulae, assuming that 
the environment $\eta$ associates to each variable $\X$ 
a function that also satisfies the following property:
\begin{equation}\label{eq:weak}
\sem{\PtoR{\varphi}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} 
  = \begin{cases} 
    \varnothing \\
    \set{\frame{\sigma_1^{\sharp},\delta_1^{\sharp}}\concat S^{\sharp}} &
    \sigma_1^{\sharp} \leq \sigma^{\sharp}, \ \sigma_1^{\sharp} \sim \sigma^{\sharp}, \ \delta_1^{\sharp} \geq \delta^{\sharp}
  \end{cases}
\end{equation}
  %
  \begin{itemize}
    \item The cases $\varphi = p$ and $\varphi = \neg p$ hold by the same argument as in the ACTL case, with $\delta_1^{\sharp} = \delta^{\sharp}$.
    \item The case $\varphi = \varphi_1 \land \varphi_2$ holds by the same argument as in the ACTL case, with $\delta_1^{\sharp}$ 
    as the least upper bound of the traces resulting from the two branches.
    \item The case $\varphi = \varphi_1 \lor \varphi_2$ holds by the same argument as in the ACTL case.
    \item The case $\varphi = x$ holds by the hypothesis on $\eta(\X)$. 
    \item The case $\varphi = \Box \varphi_1$ is analogous to the case $\AX \varphi_1$ in ACTL.
  \end{itemize}
  %
\subparagraph*{($\varphi = \mu x . \varphi_x$)}
\begin{align*}
  \hspace{-10pt}\sem{\PtoR{\mu x . \varphi_x}}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} & = 
  \sem{\push; \reset; \upmu \X . ( \loops \oplus \add; \PtoR{\varphi_x}); \pop}^{\As}\set{\frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}} \\
  & = \sem{\pop}^{\As}\left ( \sem{\upmu \X . ( \loops \oplus \add; \PtoR{\varphi_x})}^{\As}
  \set{\frame{\sigma^{\sharp}, \bot}\concat \frame{\sigma^{\sharp}, \delta^{\sharp}}\concat S^{\sharp}}  \right )  \\
\end{align*}
Let $F(f) = \sem[{\eta[\X \mapsto f]}]{\loops \oplus (\add; \PtoR{\varphi_1})}$, then if $f$ has property~\eqref{eq:weak} also $F(f)$ has it, 
since $\loops$ (BCA of a filter), $\add$ (computation) and $\PtoR{\varphi_1}$ (inductive hypothesis) have it, and the operators $\oplus$ and $;$ preserve it. 
Then the least fixpoint $\upmu \X. \r_x$ has the property~\eqref{eq:weak}.  The case $\varphi = \nu x . \varphi_x$ is straightforward  by inductive hypothesis.

By relying on the property~\eqref{eq:weak}, the fact that for any formula $\varphi$ in $\mu_{\Box}$-calculus 
also the strongest property~(\ref{eq:strong-top-frame}) holds, follows by a further  routine induction.
\end{proof}
%
\end{toappendix}

  The soundness-by-design of this abstract semantics entails a
  sound program verification.

  \begin{proposition}[Program verification for satisfaction]
    \label{pr:prg-ver-sat}
    Given a transition system
  $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$,
    for all ACTL or $\mu_{\Box}$-calculus formulae 
    $\varphi$, abstract domain $A$, and a compatible equivalence $\sim$ on A, 
%
    if
    $\sem{\PtoR{\varphi}}^{\sharp}(\alpha^s_\ssim(I)) = \bot$ then, for all
    $\sigma \in I$, we have $\sigma \models \varphi$.
  \end{proposition}

  As in the concrete case, the abstract semantics
  of programs encoding formulae is a lower closure.  This,
  together with the observation that the semantics only depends on the
  top frame of a stack (see Proposition~\ref{prop:top-frame} in the
  appendix) is relevant for the concrete implementation.


  %

  %


  \begin{remark}
  \label{re:bca}
  \rm
  We recalled in~\S~\ref{sec:s4} that for any Boolean test $b$ and abstract domain $A$, 
  the identity function %
  $\lambda a\in A.\, a$ is %
  a correct approximation of the filtering semantics $\sem[]{b}$ of $b$. 
  %
  This function can be enhanced to $\lambda a\in A.\, 
  \alpha(\sem[]{b}\Sigma) \wedge_A a$, which is also a correct approximation of $\sem[]{b}$~\cite[Section~4.1]{mine17}. 
  %
  If $A$ is a partitioning abstraction 
  then one can show that 
  $\lambda a\in A.\, \alpha(\sem[]{b}\Sigma) \wedge_A a$ 
  is indeed the \emph{best} correct approximation of $\sem[]{b}$.
  However, this property does not hold in general, even assuming that $A$ is a disjunctive abstraction, i.e.,
  the additivity of $\gamma$ (see Example~\ref{ex:filter} in the appendix).
  \qed
  \end{remark}

  \begin{toappendix}
  \begin{example}[on the BCA for Boolean tests]
    \label{ex:filter}
    We provide an example of a disjuctive abstraction where the
    $\lambda a\in A.\, \alpha(\sem[]{b}\Sigma) \wedge_A a$ is bot the
    BCA of $\sem[]{b}$.

  This can be shown by considering the following 
  simple sign abstraction for an integer variable $x$: $\mathrm{Sign}_{\alpha,\gamma}\triangleq \{x\in \mathbb{Z},\, x\in \mathbb{Z}_{\leq 0},\, x\in \mathbb{Z}_{\geq 0},\, x\in \mathbb{Z}_{= 0},\, x \in \varnothing\}$, which, being closed under unions, is disjunctive, whereas $\mathrm{Sign}$ is not partitioning (e.g., $\mathrm{Sign}$ does not include the complement of $\mathbb{Z}_{\leq 0}$).  
Then, by considering the Boolean test $x< 0 $, we have that 
$\alpha (\sem[]{x< 0 }\mathbb{Z}) \wedge_{\mathrm{Sign}} \mathbb{Z}_{\geq 0} = \mathbb{Z}_{\leq 0} \wedge_{\mathrm{Sign}} \mathbb{Z}_{\geq 0}=
\mathbb{Z}_{= 0}$, whereas the best approximation is
$\alpha(\sem[]{x< 0  }\mathbb{Z}_{\geq 0}) = \alpha(\varnothing) = \varnothing$. 
  \qed
\end{example}
\end{toappendix}
