  \begin{example}[Control flow graphs - Abstract frames, LCL
    derivation and repair]\label{ex:cfg-appendix}
    We exemplify the use of LCL for showing that
    the property $\varphi = \AG (n = e \to z = 0)$ from Example~\ref{ex:actl}, 
    encoded in $\MOKA$ by the program 
    $\mathsf{m}_{\varphi} = \push; \nexte^*; \mathsf{n = e ?}; \mathsf{z \neq 0 ?}; \pop$ 
    holds for our running
    example in Figure~\ref{fig:example}. We use the abstraction
    %
    $A_{\alpha,\gamma}$ depicted in Figure~\ref{fig:predicate}. 
    The set of initial states is $I_0 =
    \set{\frame{(s, 0100), \varnothing}, \frame{(s, 0011),
    \varnothing}}$ that satisfy the properties $x = 0$, $y \neq
    z = w \leq 1$. Note that the abstraction of
    $I_0$ covers the set of possible
    initial states
    $\set{\frame{(s, xyzw), \varnothing} \mid x, y, z, w \in \ev}$,
    since
    $\dirIm{\alpha}(I_0) = (s \mapsto \top)$.

    Let us consider the triple
      $\vdash_{\As}~[I_0] \ \mathsf{m}_{\varphi}
      \ [\varnothing]$, which reads \begin{equation*}
        \vdash_{\As}~ [I_0] \ \push; \nexte^*; \mathsf{n = e ?}; \mathsf{z \neq 0 ?}; \pop \ [\varnothing]
      \end{equation*}
    As pointed out in Example~\ref{ex:cfg-abstraction} the computation of the program $\mathsf{m}_{\varphi}$ 
    yields a false alarm when using the abstract domain $A$. 
    Hence this triple cannot be inferred in LCL with this 
    abstract domain $\As$ due to the failure of some local completeness 
    assumptions, and, on the other hand, this lack of local completeness
    drives the refinement of $\As$.  

    The root of the
    derivation tree is the judgement above.
    Since, by Theorem~\ref{th:gen-BCAs}, $\push$, and $\pop$ are
  complete we
  can apply the
  rule $(\operatorname{seq})$ twice to infer the
  triple below, where, to improve readability, we abuse the notation by
  noticing that stacks are inessential and that computation paths
  are never exploited (because the commands $\add$ and $\loops$
  do not occur in the program), to write $\sigma$ in place of
  $\frame{\sigma, \Delta}\concat S$, e.g., we write $I_0 =
  \set{(s, 0100), (s, 0011)}$:
    \begin{equation*}
      \vdash_{\As}~[I_0] \ \nexte^*;
      \mathsf{n =  e ?}; \mathsf{z \neq 0?} \ [\varnothing]
    \end{equation*}
    To ease the notation, any variable $x,
    y, z, w$ free is inteded to be in $\ev$. 
    Moreover, let $T_i = \bigcup_{j \leq i} I_j$.

    The derivation begins as

    \begin{equation*}
      \resizebox{\textwidth}{!}{
        \inference{
          \inference{
            \inference{\mathbb{C}^{\As}_{I_0}(\nexte)}{\vdash_{\As}~
              [I_0]\ \nexte
            \ [I_1]}[{\normalfont (transfer)}]
            &
            \inference{\heartsuit}{\vdash_{\As}~[T_1]
              \ \nexte^* \ [R]}[{\normalfont (rec)}]
          }{\vdash_{\As}~
          [I_0]\ \nexte^*\ [R]}[{\normalfont (rec)}]
          &
          \inference{\spadesuit}{\vdash_{\As}~ [R] \ \mathsf{n =
          e?}; \mathsf{z \neq 0 ?} \ [\varnothing]}[{\normalfont (seq)}]
        }{\vdash_{\As} [I_0]\ \nexte^*; \mathsf{n =  e ?};
        \mathsf{\neq 0?} \ [\varnothing]}[{\normalfont (seq)}]
    }
    \end{equation*}
    where $R$ needs to be found to infer the triples $\vdash_{\As} [I_0] \ \nexte^*\ [R]$ 
    and $\vdash_{\As} [R] \ \mathsf{n =  e ?}; \mathsf{z \neq 0?} \ [\varnothing]$,
    %
    %
    $I_1 = \sem[]{\nexte}(I_0) = \set{(1, 1100), (1, 0001)}$.
    The local completeness hypothesis
    at $I_0$ on the domain $\As$, that we denote $\mathbb{C}^{\As}_{I_0}$, is
    satisfied since $\alpha^s_\ssim \circ \sem[]{\nexte} \circ \gamma^s_\ssim \circ \alpha^s_\ssim (\set{(s, 0100),
    (s, 0011)}) =
    \alpha^s_\ssim \circ \sem[]{\nexte} (\set{(s, 0100), (s, 0011)})$, because
    \begin{align*}
      \alpha^s_\ssim \circ \sem[]{\nexte} \circ \gamma^s_\ssim \circ \alpha^s_\ssim(\set{(s, 0100), (s, 0011)}) & =
      \alpha^s_\ssim \circ \sem[]{\nexte} (\set{(s, xyzw)}) \\
      & =\alpha^s_\ssim (\set{(1, yy0w)}) \\
      & = (1 \mapsto p \land q)
      & \\
      \alpha^s_\ssim \circ \sem[]{\nexte} (\set{(s, 0100), (s, 0011)}) & = \alpha^s_\ssim (\set{(1,
      1100), (1, 0001)}) \\ 
      & = (1 \mapsto p \land q)
    \end{align*}
    The branch which is most interesting
    to explore is now $(\heartsuit)$, in which we apply again the $(\operatorname{rec})$
    rule:
    \begin{equation*}
      \inference{
        \inference
        {\mathbb{C}^{\As}_{T_1}(\nexte)}
        {\vdash_{\As} [T_1] \ \nexte \ [I_2]}
        [{\normalfont(transfer)}]
        &
        \inference
        {\diamondsuit}
        {\vdash_{\As} [T_2] \ \nexte^* \ [R]}
        [{\normalfont (rec)}]
      }
      {\vdash_{\As} [T_1] \ \nexte^* \ [R]}[{\normalfont (rec)}]
    \end{equation*}
    where $I_2 = \sem[]{\nexte}{T_1} = I_1 \cup \set{(2, 0001), (3,
    1100)}$. Also the completeness hypothesis $\mathbb{C}^{\As}_{T_1}(\nexte)$
    is satisfied:
    \begin{align*}
      \alpha^s_\ssim  \circ \sem[]{\nexte} \circ \gamma^s_\ssim \circ \alpha^s_\ssim& (\set{(s, 0100), (s, 0011),
          (1,
      1100), (1, 0001)}) \\
      & = \alpha^s_\ssim \circ \sem[]{\nexte}(\set{(s, xyzw),
      (1, yy0w)}) \\
      & = \alpha^s_\ssim (\set{(1, yy0w), (2, y y 0 1), (3, yy00)}) \\
      & = (1 \mapsto p \land q, 2 \mapsto p \land q, 3 \mapsto p \land q) \\
      & \\
      \alpha^s_\ssim  \circ \sem[]{\nexte} & (\set{(s, 0100), (s, 0011), (1,
      1100), (1, 0001)})    \\
      & = \alpha^s_\ssim (\set{(1, 1100), (1, 0001), (2, 0001), (3, 1100)}) \\
      & = (1 \mapsto p \land q, 2 \mapsto p \land q, 3 \mapsto p \land q) %
      %
    \end{align*}
    We proceed in the exploration of the $(\diamondsuit)$ branch:
    \begin{equation*}
      \inference{
        \inference
        {\mathbb{C}^{\As}_{T_2}(\nexte)}
        {\vdash_{\As} [T_2] \ \nexte \ [I_3]}
        [{\normalfont(transfer)}]
        &
        \inference
        {\clubsuit}
        {\vdash_{\As} [T_3] \ \nexte^* [R]}[{\normalfont(iterate)}]
      }{
        \vdash_{\As} [T_2] \ \nexte^* \ [R]
      }[{\normalfont (rec)}]
    \end{equation*}
    where $I_3 = \sem[]{\nexte}T_2 = I_2 \cup \set{(3, 0111), (e, 1100)}$. 
    Also the completeness hypothesis 
    $\mathbb{C}^{\As}_{T_2}(\nexte)$ holds, because
    \begin{align*}
      \alpha^s_\ssim \circ \sem[]{\nexte} \circ \gamma^s_\ssim \circ \alpha^s_\ssim & (\set{(s,
          0100), (s, 0011), (1, 1100), (1,0001), (2, 000 1), (3,
      1100)}) = \\
      & =  \alpha^s_\ssim \circ \sem[]{\nexte}(\set{(s, xyzw), (1, yy0w), (2, yy0w),
      (3, yy0w)}) \\
      & = \alpha^s_\ssim (\set{(1, yy0w), (2, yy0w), (3, yy0w), (3, y [y\! +\!1] 1 w),
      (e, yy0w)}) \\
      & = \set{(1 \mapsto p \land q, 2 \mapsto p \land q, 
      3 \mapsto \top, e \mapsto p \land q)}  \\
      %
      %
      \alpha^s_\ssim \circ \sem[]{\nexte} & (\set{(s,
          0100), (s, 0011), (1, 1100), (1,0001), (2, 000 1), (3,
      1100)})  = \\
      & = \alpha^s_\ssim (\set{(1, 1100), (1, 0001), (2, 0001), (3, 1100), (3,
      0111), (e, 1100)}) \\
      & = \set{(1 \mapsto p \land q, 2 \mapsto p \land q, 
      3 \mapsto \top, e \mapsto p \land q)}  \\
     %
    \end{align*}
    Now the source of incompleteness is found in exploring the
    $(\clubsuit)$ branch, since the proof obligation for
    $\mathbb{C}^{\As}_{T_3}(\nexte)$ fails:
    {%
      \begin{equation*}
        \inference{
          \inference{\mathbb{C}^{\As}_{T_3}(\nexte)}
          {\vdash_{\As}
            [T_3] \ \nexte \ [I_4]
            }
            [{\normalfont (transfer)}] 
            &
            I_4 \leq A(T_3)
            }
            {\vdash_{\As} [T_3] \ \nexte^*
        \ [R]}
        [{\normalfont(iterate)}]
    \end{equation*}}
    where $I_4 = \sem[]{\nexte}T_3 = I_3 \cup \set{(s, 0111), (e, 1100)}$, we set $R \triangleq T_4$ and the
    condition $I_4 \leq A(T_3)$ guarantees that, thanks to the
    abstraction, we can stop the
    unfolding of the fixpoint, while the concrete computation would
    instead require $4k$ (where $k$ is the modulo in $\ev$) steps to reach a fixpoint.
    We have that 
    \begin{align*}
      \hspace{-10ex}\alpha^s_\ssim \circ  & \sem[]{\nexte}  \circ  \gamma^s_\ssim \circ \alpha^s_\ssim  (\left \{(s,0100), (s, 0011), (1,
      1100), (1, 0001), \right . \\ 
      & \qquad \qquad \qquad \left . 
      (2, 0001), (3, 1100), (3, 0111), (e, 1100)\right \}) = \\
      & = \alpha^s_\ssim \circ \sem[]{\nexte} (\set{(s, xyzw), (1, yy0w),
          (2, yy0w), (3,
      xyzw), (e, yy0w)}) \\
      & = \alpha^s_\ssim (\set{(1, yy0w), (2, yy0w), (3, yy0w), (3, y [y\! +\!1] 1 w),
      (e, yy0w), (s, x^{\neq y} z w), (e, yyzw)}) \\
      & = (s \mapsto \overline{q}, 1 \mapsto p \land q, 2 \mapsto p \land q, 3 \mapsto \top,
      e \mapsto q) \\
      %
      %
      & \\
      \hspace{-10ex} \alpha^s_\ssim \circ & \sem[]{\nexte}  (\left \{(s,0100), (s, 0011), (1,
      1100), (1, 0001),
      \right . \\ 
      & \qquad \quad \left .  
      (2, 0001), (3, 1100), (3, 0111), (e, 1100)\right \}) = \\
      & = \alpha^s_\ssim (\set{(1, 1100), (1, 0001), (2, 0001), (3, 1100), (e,
      1100), (3, 0 1 1 1), (s, 01 1 1)}) \\
      & = \set{(s, x^{\neq y} y z^{\neq 0} w), (1, yy0w), (2, yy0w), (3,
      xyzw), (e, yy0w)} \\ 
      & = (s \mapsto \overline{q} \land \overline{p}, 
      1 \mapsto p \land q, 2 \mapsto p \land q, 3 \mapsto \top,
      e \mapsto p \land q) %
    \end{align*}
    The source of imprecision is due to the fact that the abstraction $(3, xyzw)$ 
  is too coarse for the set $\set{(3, 1100),(3, 0111)}$, because the relation between $p$ and $q$ 
  being either both valid or both invalid is lost. Several domain repairs are possible. 
  In~\cite{DBLP:conf/pldi/BruniGGR22} it is shown that adding the abstract element $q\to p$ to the domain 
  $A$ offers a more abstract repair than adding the element $q\leftrightarrow p$, as originally proposed 
  in~\cite{DBLP:conf/tacas/BallPR01}. 
  In fact, letting $A_1=A\cup\set{q\leftrightarrow p}$, 
  the abstract interpreter computes $\sem[]{\PtoR{\varphi}}^{\sharp}{\alpha_1}^s_\ssim(I_0) 
  = \sem[]{\PtoR{\varphi}}^{\sharp}{(s \mapsto \top)} = \bot$, implying
  that the formula holds from any initial states.
 Here we can also exploit a different route, by refining the equivalence so
  that $\sigma^{\sharp}_1 \sim \sigma^{\sharp}_2$
  when $\supp{\sigma^{\sharp}_1} = \supp{\sigma^{\sharp}_2} \neq 3$.
  Intuitively, this corresponds to abstract separately the states at program point $n=3$.
  If we denote by $\approx$ be refined equivalence, 
  the proof obligation
  $\mathbb{C}^{\Aa}_{T_3}(\nexte)$ is now satisfied:
    \begin{align*}
      \hspace{-15ex} & \alpha^s_{\aapprox} \circ  \sem[]{\nexte}  \circ \gamma^s_{\aapprox} \circ \alpha^s_{\aapprox} (
        \left \{(s, 0100), (s, 0011), (1,
      1100), (1, 0001), \right . \\ & \left . 
      \qquad \qquad \qquad \qquad \qquad 
      (2, 0001), (3, 1100), (3, 0111), (e, 1100)\right \}) = \\
      & = \alpha^s_{\aapprox} \circ \sem[]{\nexte} (\set{(s, xyzw), (1, yy0w),
      (2, yy0w), (3,yy0w), (3, x^{\neq y} y z^{\neq 0} w), (e, yy0w)}) \\
      & = \alpha^s_{\aapprox} (\set{(1, yy0w), (2, yy0w), (3, yy0w), (3, y [y\! +\!1] 1 w),
      (e, yy0w), (s, x^{\neq y} z^{\neq 0} w), (e, yy0w)}) \\
      %
      %
      %
      & = (s \mapsto
      \overline{p} \land \overline{q}, 1\mapsto p \land q, 2
      \mapsto p \land q,
      3 \mapsto p \land q, 3 \mapsto \overline{p} \land \overline{q},
    e \mapsto p \land q) \\
      & \\
      \hspace{-15ex} & \alpha^s_{\aapprox} \circ  \sem[]{\nexte}  (\left \{(s,0100), (s, 0011), (1,
      1100), (1, 0001), 
      \right . \\ & \left . 
      \qquad \qquad \qquad
      (2, 0001), (3, 1100), (3, 0111), (e, 1100)\right \}) = \\
      & = \alpha^s_{\aapprox} (\set{(1, 1100), (1, 0001), (2, 0001), (3, 1100), (e,
      1100), (3, 0 1 1 1), (s, 01 1 1)}) \\
     & = (s \mapsto
      \overline{p} \land \overline{q}, 1\mapsto p \land q, 2
      \mapsto p \land q,
      3 \mapsto p \land q, 3 \mapsto \overline{p} \land \overline{q},
    e \mapsto p \land q)
      %
      %
    \end{align*}
    and in fact one can compute $\sem[]{\PtoR{\varphi}}^{\sharp}\alpha^s_{\aapprox}(I_0) = \bot$.

    Then we can go back to the $(\spadesuit)$ branch to conclude:
    \begin{equation*}
      \resizebox{\textwidth}{!}{
      \inference{
        \inference
        {\mathbb{C}^{\Aa}_{R}(\mathsf{n =  e?})}
        {\vdash_{\Aa} [R] \ \mathsf{n =  e ?} \ [\set{(e, yy0w)}]}
        [{\tiny\normalfont(transfer)}]
        &
        \inference
        {\mathbb{C}^{\Aa}_{\set{(e, yy0w)}}(\mathsf{z \neq 0?})}
        {\vdash_{\Aa} [\set{(e, yy0w)}] \ \mathsf{z \neq 0?} \ [\varnothing]}
        [{\tiny\normalfont(transfer)}]
      }
      {
        \vdash_{\Aa} [R] \ \mathsf{n = e ?}; \mathsf{z \neq 0?} \ [\varnothing]
      }
      [{\tiny\normalfont (seq)}]
    }
    \end{equation*}
    where the proof obligations $\mathbb{C}^{\Aa}_{R}(\mathsf{n = e ?}),
    \ \mathbb{C}^{\Aa}_{\set{(e, yy0w)}}(\mathsf{z \neq 0?})$ are
    satisfied, since both properties $n = e$ and
    $z \neq 0$  are representable in the abstract domain.
    \qed
  \end{example}
