  \begin{toappendix}
    \section{Propositional Dynamic Logic}
    \label{sec:pdl}
Propositional Dynamic Logic (PDL) is a modal logic that allows 
one to reason about propositional properties of programs~\cite{Book:DynLog}. 
As we did for the other logics, we restrict here to universal fragment, and we thus define 
three syntactic categories: the formulae $\varphi$ that we verify (universal formulae), 
the programs $\r$ that act on a transition system 
$(\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, 
and the formulae $\psi$ that can be nested inside programs (existential formulae). 
Thus,
given a set of atomic propositions $p\in \mathbf{P}$:
\begin{center}
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l}
  $\varphi $ & $::=$ & $\true \mid  \false \mid p \mid \neg p\mid
  \varphi_1 \lor \varphi_2 \mid
  \varphi_1 \land \varphi_2 \mid
  [\r] \varphi_1$ \\
  $\r  $ & $::=$ & $  \nexte \mid \r_1; \r_2 \mid \r_1 \oplus \r_2 \ | 
  \ \r_1^* \mid \psi? $ \\
  $\psi$ & $ ::= $ & $  \true \mid \false \mid p \mid \neg p \mid 
  \psi_1 \lor \psi_2 \mid
  \psi_1 \land \psi_2 \mid 
  \langle \r \rangle \psi_1 $ 
    \end{tabular}
\end{center}
As usual, $p \to \varphi'$ is syntactic sugar for
$\neg p \lor \varphi'$.

\begin{definition}[PDL semantics]\label{PDL-semantics}
    Given a transition system
    $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, the
    semantics %
    $\sem[]{\zeta} \subseteq \Sigma$ of
    {\rm \text{PDL}} formulae, for $\zeta \in \set{\varphi, \psi}$ 
    and of $\sem[]{\r}: \Sigma \to \pow{\Sigma}$ 
    programs over $T$ is as follows:
    \begin{center}
      \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l@{\hspace{40pt}}r@{\hspace{2pt}}c@{\hspace{2pt}}l}
        $\sem[]{\true}$ & $\triangleq$ & $\Sigma$ &
        $\sem[]{\false}$ & $\triangleq$ & $\varnothing$ \\
        $\sem[]{p}$ & $\triangleq$ & $\set{\sigma \in \Sigma \mid
        \sigma \vdash p}$ & $\sem[]{\neg p}$ & $\triangleq$ & $\set{\sigma \in \Sigma \mid
        \sigma \vdash \neg p}$\\ 
        $\sem[]{\zeta_1 \lor \zeta_2}$ & $\triangleq$ &
      $\sem[]{\zeta_1} \cup \sem[]{\zeta_2}$ &
      $\sem[]{\zeta_1 \land \zeta_2}$  & $\triangleq$ &
      $\sem[]{\zeta_1} \cap \sem[]{\zeta_2}$ \\
      $\sem[]{[\r_1]\varphi_1}$ & $\triangleq$ & $\set{\sigma \mid \sem[]{\r}\sigma \subseteq \sem[]{\varphi_1}}$ &
      $\sem[]{\langle\r_1\rangle\varphi_1}$ & $\triangleq$ & $\set{\sigma \mid \sem[]{\r}\sigma \cap \sem[]{\varphi_1} \neq \varnothing}$ \\
      $\sem[]{\nexte}(\sigma)$ & $\triangleq$ & $\set{\sigma' \mid \sigma \trel \sigma'}$ \\
      $\sem[]{\r_1 ; \r_2}(\sigma)$ & $\triangleq$ & $\sem[]{\r_2}\left ( \sem[]{\r_1}(\sigma)\right )$ &
      $\sem[]{\r_1 \oplus \r_2}(\sigma)$ & $\triangleq$ & $\sem[]{\r_1}(\sigma) \cup \sem[]{\r_2}(\sigma)$ \\
      $\sem[]{\mathsf{r_1^*}}(\sigma)$ & $\triangleq$ & $ \bigvee \set{\sem[]{\mathsf{r_1}}^k(\sigma) \mid k \in \N}$ &
      $\sem[]{\psi?}(\sigma)$ & $\triangleq$ & $ \set{\sigma} \cap \sem[]{\psi}$
      \end{tabular}
    \end{center}
  \end{definition}

\subparagraph{PDL as $\MOKA$.}
  %
  To each ACTL formula $\varphi$ we assign a $\MOKA$ program
  as follows: to each formula $\varphi$ we associate a 
  program $\PtoR{\varphi}$ which computes \textit{counterexamples} to $\varphi$, while to 
  each formula $\psi$ we associate a program $\PtoE{\psi}$ that computes \textit{examples} to 
  $\psi$. Since the logic is based on $\kat$, the encoding of programs $\r$ is just the identity\footnote{In the sense that 
  it is the program on our domain of stacks with the same name, and we overload the symbols.}, 
  with $\PtoE{\psi?} = \PtoE{\psi}$. 
  \begin{center}
    %
    \begin{tabular}{r@{\hspace{2pt}}c@{\hspace{2pt}}l@{\hspace{50pt}}r@{\hspace{2pt}}c@{\hspace{2pt}}l}
       $\PtoR{\,\true}$ & $\triangleq$ & $\zero$ &  $\PtoE{\,\true}$ & $\triangleq$ & $\one$ \\ 
       $\PtoR{\,\false}$ & $\triangleq$ & $\one$ & $\PtoE{\,\false}$ & $\triangleq$ & $\zero$ \\ 
      $\PtoR{\,p}$ & $\triangleq$ & $\np$ & $\PtoE{\,p}$ & $\triangleq$ & $\p$ \\
      $\PtoR{\,\neg p}$ & $\triangleq$ & $\p$ & $\PtoE{\,\neg p}$ & $\triangleq$ & $\np$ \\
      $\PtoR{\varphi_1\land \varphi_2}$ & $\triangleq$ &
      $\PtoR{\varphi_1} \oplus \PtoR{\varphi_2}$
      &  $\PtoE{\psi_1\land \psi_2}$ & $\triangleq$ &
      $\PtoE{\psi_1}; \PtoE{\psi_2}$
      \\
      $\PtoR{\varphi_1\lor \varphi_2}$ & $\triangleq$ & 
      $\PtoR{\varphi_1} ; \PtoR{\varphi_2}$ 
      &  $\PtoE{\psi_1\lor \psi_2}$ & $\triangleq$ & 
      $\PtoE{\psi_1} \oplus \PtoE{\psi_2}$ \\
      $\PtoR{[\r]\varphi_1}$ & $\triangleq$ & $\push; \PtoE{\r}; 
      \PtoR{\varphi_1}; \pop$ 
      & $\PtoE{\langle\r\rangle\psi_1}$ & $\triangleq$ & $\push; \PtoE{\r}; 
       \PtoE{\psi_1}; \pop$ \\
    \end{tabular}
  \end{center}


  \begin{theorem}[Formula satisfaction as program verification - PDL version]
    \label{th:counterexamples-pdl}
    Given 
      $T = (\Sigma, \operatorname{I}, \mathbf{P}, \trel, \vdash)$, for all frames $\frame{\sigma, \Delta}\concat S \in
    \str{\operatorname{F}_{\Sigma}}$,
    for any \emph{PDL} formula $\varphi$
    \begin{equation*}
      \sem[]{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
      \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
        \sem[]{\varphi}}
    \end{equation*}
  \end{theorem}

  \begin{proof}
    In order to prove the previous theorem we first need to prove that: 
    for any existential formula $\psi$ and command $\r$, as defined above, and for $\set{\frame{\sigma, \Delta}\concat S}
    \in  \pow{\operatorname{F}_{\Sigma}}$, then
  \begin{align}
    \sem[]{\PtoE{\psi}}\set{\frame{\sigma, \Delta}\concat S} & = 
      \set{\frame{\sigma, \Delta}\concat S \mid \sigma \in \sem[]{\psi}} \label{eq:example1} \\
      \sem[]{\PtoE{\r}}\set{\frame{\sigma, \Delta}\concat S} & = 
      \set{\frame{\sigma', \Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma)} \label{eq:examples}
  \end{align}

  We proceed by induction on the structure of $\psi$ and $\r$. For $\psi$, 
all cases are straightforward with the exception of $\psi = \langle\r\rangle\psi_1$. 
%
We assume the inductive hypotheses:
\begin{align*}
  \forall \sigma,\Delta,S~\sem[]{\PtoE{\r_i}}
  \set{\frame{\sigma,
  \Delta}\concat S} & = \set{\frame{\sigma', \Delta}\concat S \mid
  \sigma'\in \sem[]{\r_i}(\sigma)} \\ 
  \sem[]{\PtoE{\psi_i}}
  \set{\frame{\sigma,
  \Delta}\concat S} & = \set{\frame{\sigma, \Delta}\concat S \mid
  \sigma\in \sem[]{\psi_i}} %
\end{align*} 
%
\begin{align*}
  \sem{\PtoE{\langle\r\rangle\psi_1}}\set{\frame{\sigma, \Delta}\concat S}
  & =
  \sem{\push;\PtoE{\r};\PtoE{\psi_1};\pop}\set{\frame{\sigma,
  \Delta}\concat S} \\
  & =
  \sem{\PtoE{\r};\PtoE{\psi_1};\pop}\set{
    \frame{\sigma,\Delta}\concat\,
    \frame{\sigma,\Delta}\concat S} \\
  & = \sem[]{\PtoE{\psi_1};\pop}\left ( \sem[]{\PtoE{\r}}\set{
    \frame{\sigma,\Delta}\concat\,
    \frame{\sigma,\Delta}\concat S} \right ) \\
  & \overset{\heartsuit}{=} \sem[]{\PtoE{\psi_1};\pop}\set{
    \frame{\sigma',\Delta}\concat\,
    \frame{\sigma,\Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma)}\\
  & \overset{\clubsuit}{=} \sem[]{\pop}\set{
    \frame{\sigma',\Delta}\concat\,
    \frame{\sigma,\Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma), \sigma' \in \sem[]{\psi_1}} \\ 
  & = \sem[]{\pop}\set{
    \frame{\sigma',\Delta}\concat\,
    \frame{\sigma,\Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma) \cap \sem[]{\psi_1}} \\ 
    & = \set{\frame{\sigma,\Delta}\concat S \mid \exists \sigma' \in \sem[]{\r}(\sigma) \cap \sem[]{\psi_1}} %
\end{align*}
where at $(\heartsuit)$ we used the inductive hypothesis for $\r$ and at $(\clubsuit)$ we used the inductive hypothesis for $\psi_1$. 

Consider now the $\r$ cases: 
\subparagraph*{($\r=\nexte$)} By definition: \begin{align*}
  \sem[]{\PtoE{\nexte}}\set{\frame{\sigma, \Delta}\concat S} 
  & = \sem[]{\nexte}\set{\frame{\sigma, \Delta}\concat S} \\ 
  & = \set{\frame{\sigma', \Delta}\concat S \mid \sigma \trel \sigma'} \\
  & = \set{\frame{\sigma', \Delta}\concat S \mid \sigma' \in \sem[]{\nexte}(\sigma)}
\end{align*}
%

%
\subparagraph*{($\r=\r_1; \r_2$)} 
%
\begin{align*}
  \sem[]{\PtoE{\r_1; \r_2}}\set{\frame{\sigma, \Delta}\concat S} 
  & = \sem[]{\r_1; \r_2}\set{\frame{\sigma, \Delta}\concat S} \\ 
  & = \sem[]{\r_2} \left ( \sem[]{\r_1}\set{\frame{\sigma, \Delta}\concat S} \right ) \\
  & \overset{\heartsuit}{=} \sem[]{\r_2}\set{\frame{\sigma', \Delta}\concat S \mid \sigma'\in \sem[]{\r_1}(\sigma)} \\
  & \overset{\clubsuit}{=} \set{\frame{\sigma'', \Delta}\concat S \mid \sigma''\in \sem[]{\r_2}(\sem[]{\r_1}(\sigma))} \\
  & = \set{\frame{\sigma'', \Delta}\concat S \mid \sigma''\in \sem[]{\r_1; \r_2}(\sigma)} %
\end{align*}
where at $(\heartsuit)$ we used the inductive hypothesis for $\r_1$ and
at $(\clubsuit)$ we used the inductive hypothesis for $\r_2$.
%
\subparagraph*{($\r=\r_1 \oplus \r_2$)} Analogous to the case $\r=\r_1; \r_2$. 
%
\subparagraph{($\r = \r_1^*$)} Follows from the fact that $\r_1^{k+1} = \r_1; \r_1^{k}$. 
%
\subparagraph{($\r = \psi?$)} 
%

%
\begin{align*}
  \sem[]{\PtoE{\psi?}}\set{\frame{\sigma, \Delta}\concat S} 
  &\overset{\clubsuit}{=} \sem[]{\PtoE{\psi}}\set{\frame{\sigma, \Delta}\concat S} \\ 
  & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma\in \sem[]{\psi}} \\
  & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma\in \set{\sigma} \cap \sem[]{\psi}} \\
  & = \set{\frame{\sigma, \Delta}\concat S \mid \sigma\in \sem[]{\psi?}(\sigma)} %
\end{align*}
where at $(\clubsuit)$ we used the inductive hypothesis.

\bigskip
  We can now get back to the proof of the theorem:
  \begin{equation*}
    \sem[]{\PtoR{\varphi}} \set{\frame{\sigma, \Delta}\concat S} =
    \set{\frame{\sigma, \Delta}\concat S \mid \sigma \notin
    \sem[]{\varphi}}
  \end{equation*}
%
  We proceed by structural induction on $\varphi$. All cases are straightforward with 
  the exception of $\varphi = [\r]\varphi_1$.  
  We assume the inductive hypothesis:
      \begin{equation*}
        \forall \sigma,\Delta,S.~\sem{\PtoR{\varphi_1}}
        \set{\frame{\sigma,
        \Delta}\concat S} = \set{\frame{\sigma, \Delta}\concat S \mid
        \sigma \notin \sem[]{\varphi_1}}
      \end{equation*}
  %
      \begin{align*}
        \sem{\PtoR{[\r]\varphi_1}}\set{\frame{\sigma, \Delta}\concat S}
        & =
        \sem{\push;\PtoE{\r};\PtoR{\varphi_1};\pop}\set{\frame{\sigma,
        \Delta}\concat S} \\
        & =
        \sem{\PtoE{\r};\PtoR{\varphi_1};\pop}\set{
          \frame{\sigma,\Delta}\concat\,
          \frame{\sigma,\Delta}\concat S} \\
        & = \sem[]{\PtoR{\varphi_1};\pop}\left ( \sem[]{\PtoE{\r}}\set{
          \frame{\sigma,\Delta}\concat\,
          \frame{\sigma,\Delta}\concat S} \right ) \\
        & \overset{\heartsuit}{=} \sem[]{\PtoR{\varphi_1};\pop}\set{
          \frame{\sigma',\Delta}\concat\,
          \frame{\sigma,\Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma)}\\
        & \overset{\clubsuit}{=} \sem[]{\pop}\set{
          \frame{\sigma',\Delta}\concat\,
          \frame{\sigma,\Delta}\concat S \mid \sigma' \in \sem[]{\r}(\sigma), \sigma' \notin \sem[]{\varphi_1}} \\ 
          & = \set{\frame{\sigma,\Delta}\concat S \mid \exists \sigma' \in \sem[]{\r}(\sigma), \sigma' \notin \sem[]{\varphi_1}} \\ 
          & = \set{\frame{\sigma,\Delta}\concat S \mid \sem[]{\r}(\sigma) \centernot\subseteq \sem[]{\varphi_1}} 
      \end{align*}    
      where $(\heartsuit)$ is justified by~\eqref{eq:examples} and at $(\clubsuit)$ we used the inductive hypothesis.
\end{proof}
