\section{Proofs for Section 3 (System Model)}

\setcounter{thm}{13}
\begin{lem} 
    Let $\alpha \in \mathcal{F}$ and $\beta \in \mathcal{F}$ be given. Then it holds that
    \begin{align}
        v(\alpha,\beta) = v(\alpha, \beta_\downarrow). 
    \end{align}

    \begin{proof} \normalfont{ 
        \begin{align*}
            v(\alpha, \beta_\downarrow) &= \sup_{t \geq 0} \{\alpha(t) - \beta_\downarrow(t) \} \\
            &= \sup_{t \geq 0} \{\alpha(t) - \inf_{s \geq 0}\{ \beta(t+s) \} \} \\
            &= \sup_{t \geq 0} \sup_{s \geq 0} \{ \alpha(t) - \beta(t+s) \} \\
            &= \sup_{s \geq 0} \sup_{t \geq 0} \{ \alpha(t) - \beta(t+s) \} \\
            &= \sup_{s \geq 0} \ v(\alpha, \beta \otimes \delta_{-s}) \\
            &= \sup_{s \geq 0} \ v(\alpha \otimes \delta_{s}, \beta) \\
            \overset{s=0}&{=} v(\alpha,\beta)
        \end{align*}
    } \qed \end{proof}
\end{lem}

\section{Proofs for Section 4 (Derivation of the $\theta$ Parameter for Minimal Per-Flow Backlog Bounds)}

\begin{lem} 
    Let $\alpha_1$ and $\alpha_2$ be PWL concave arrival curves and let $\beta$ be a PWL convex service curve under FIFO multiplexing. Let $h(\alpha_2,\beta)$ be the horizontal deviation of $\alpha_2$ and $\beta$. Then, it holds for $0 \leq \theta \leq h(\alpha_2,\beta)$ that
    \begin{align*}
        v(\alpha_1, \beta_{\theta}^1) \geq v(\alpha_1, \beta_{h(\alpha_2,\beta)}^1).
    \end{align*}
    \begin{proof} \normalfont{
        Let $0 \leq \theta \leq h(\alpha_2, \beta)$. Clearly, it holds that
        \begin{align}
            \alpha_2(t-\theta) \geq \alpha_2(t-h(\alpha_2, \beta)). \label{Eq:a2_of_theta_geq_a2_of_h}
        \end{align}
        Let $z(\theta)$ be a function of the last intersection of $\alpha_2(t-\theta)$ and $\beta(t)$, given by 
        \begin{align*}
            z(\theta) = \sup\{ t \geq 0 \ | \ \alpha_2(t-\theta) = \beta(t) \}.
        \end{align*}
        It holds that $z(\theta) \geq h(\alpha_2,\beta) \geq \theta$ and that $z(\theta)$ is decreasing for increasing $\theta$. So $z(\theta)$ is minimal for $\theta=h(\alpha_2,\beta)$. Note that we can write $\beta_{\theta \downarrow}^1=\lo\cdot \mathbbm{1}_{\{t \geq z(\theta) \}}$ as $\beta_{\theta}^1(t)$ is non-decreasing for $t\geq z(\theta)$.
        Then we obtain
        \begin{align*}
            v(\alpha_1, \lo) \overset{Eq.(\ref{Eq:vertical_dev_with_LNDC})}&{=} v(\alpha, \beta_{\theta \downarrow}^1 ) \\
            &= \sup_{t\geq0} \{ \alpha_1(t) - \beta_{\theta \downarrow}^1(t) \} \\
            &= \sup_{t\geq0} \{ \alpha_1(t) - ([\beta(t) - \alpha_2(t-\theta)]^+ \cdot \mathbbm{1}_{\{t \geq \theta \}} ) \cdot \mathbbm{1}_{\{t \geq z(\theta) \}} \} \\
            \overset{z(\theta) \geq \theta}&{=} \sup_{t\geq0} \{ \alpha_1(t) - [\beta(t) - \alpha_2(t-\theta)]^+ \cdot \mathbbm{1}_{\{t \geq z(\theta) \}}  \} \\
            \overset{Eq.(\ref{Eq:a2_of_theta_geq_a2_of_h}), \theta\leq h(\alpha_2,\beta)}&{\geq}  \sup_{t\geq0} \{ \alpha_1(t) - [\beta(t) - \alpha_2(t-h(\alpha_2,\beta))]^+ \cdot \mathbbm{1}_{\{t \geq z(h(\alpha_2,\beta)) \}}  \} \\
            \overset{z(\theta) \geq h(\alpha_2,\beta)}&{=}  \sup_{t\geq0} \{ \alpha_1(t) - [\beta(t) - \alpha_2(t-h(\alpha_2,\beta))]^+
            \cdot \mathbbm{1}_{\{t \geq h(\alpha_2,\beta) \}} 
            \cdot \mathbbm{1}_{\{t \geq z(h(\alpha_2,\beta)) \}} \}  \\
            &= v(\alpha, \beta_{h(\alpha_2,\beta) \downarrow}^1 ) \overset{Eq.(\ref{Eq:vertical_dev_with_LNDC})}{=} v(\alpha, \beta_{h(\alpha_2,\beta)}^1 )
        \end{align*}
    } \qed \end{proof}
\end{lem}


\begin{lem} 
    Let $\alpha$ be a PWL concave function and $\beta$ be a PWL convex function. Let $A$ and $B$ be the set of breakpoints of $\alpha$ and $\beta$, respectively. Then, the vertical deviation of $\alpha$ and $\beta$ can always be calculated at some time $t \in A \cup B$.

    \begin{proof} \normalfont{ 
        Suppose the vertical deviation $v(\alpha,\beta)$ of $\alpha$ and $\beta$ is assumed or calculated at $t' \in \mathbb{R} \setminus (A \cup B)$ and cannot be calculated at $t \in A \cup B$. So $v(\alpha,\beta) = \sup_{\tau \geq 0}\{\alpha(\tau) - \beta(\tau)\} \overset{\tau=t'}{=} \alpha(t) - \beta(t)$ holds. 
        Since the stability condition holds and $\alpha$ is concave and $\beta$ is convex, there always exists such a $t'$ for which we assume the supremum. 

        Consider the linear segments of $\alpha$ and $\beta$ at time $t'$, in particular the respective rates $r^{t'}$ and $R^{t'}$ (according to Def.~\ref{def:linear_segment_at_time_t}).
        There are three cases to consider: $r^{t'} = R^{t'}$, $r^{t'} > R^{t'}$ and $r^{t'} < R^{t'}$. \\
        \underline{Case I} ($r^{t'} = R^{t'}$): Since $r^{t'} = R^{t'}$ holds the vertical distance of $\alpha$ and $\beta$ does neither increase nor decrease for the linear segments $\alpha^{t'}$ and $\beta^{t'}$. So for breakpoints $t_l = \max \{t \in A \cup B : t < t'\}$ and $t_u = \min \{t \in A \cup B : t > t'\}$ it should also hold that $v(\alpha,\beta) = \alpha(t') - \beta(t') = \alpha(t_l) - \beta(t_l) = \alpha(t_u) - \beta(t_u)$. $\quad \lightning$ \\
        \underline{Case II} ($r^{t'} > R^{t'}$): Since $r^{t'} > R^{t'}$ holds, the vertical distance of $\alpha$ and $\beta$ is increasing with time until the first breakpoint for which the rate of $\alpha$ becomes lower than the rate of $\beta$. Let $x = a^*_{\alpha,\beta}$ (see Def.~\ref{def:a_star_and_s_star}). So, it should also hold that $v(\alpha,\beta) = \alpha(t') - \beta(t') < \alpha(x) - \beta(x). \quad \lightning$  \\
        \underline{Case III} ($r^{t'} < R^{t'}$): Analogous to Case II.
    } \qed \end{proof}
\end{lem}


