\section{Proofs for Section 5 (Efficient Calculation of Near-Optimal Backlog Bounds)}

\setcounter{thm}{21}
\begin{lem}
It holds that $\topt^1\geq \dots \geq \topt^n$.
\end{lem}
\begin{proof}
From Eq.~\eqref{eq:concp1}, we know that the rate of $\gamma_i$ decreases in $i$. Together with $\beta_\theta^1$ being convex, the largest time at which the backlog of a single segment of $\foi$ is assumed is for the first segment $\topt^1$, as $S_1$ has the highest rate of all segment curves. Consequently, all subsequent $\topt^i$ are ordered and decrease in $i$. 
\qed \end{proof}
\begin{lem}
There is at most one $\topt^i$ with $\topt^i=\toptp^i$.
\end{lem}
\begin{proof}
Let an arbitrary but fixed $\topt^i=\toptp^i$, i.e., $\topt^i\in I_i$ . Then, using Lem.~\ref{cor:tqiorder}, we know that $\topt^1,\dots,\topt^{i-1}\geq \topt^i$. Since $\topt^i\in I_i$, no earlier segment can assume its backlog on its respective interval according to Eq.~\eqref{eq:concp2}, as the respective interval limits are $< a_i$. Likewise, $\topt^{i+1},\dots,\topt^n\leq \topt^i$, i.e., no later segment can assume its backlog on its respective minimal interval as all interval limits $\geq a_{i+1}$. It follows that if $\exists \topt^i, \topt^i=\toptp^i$, there exists exactly one such entry. 
\qed \end{proof}

