\begin{algorithm}[h]
	\SetAlgoNoLine
	\KwIn{Numbers $n,m,k\in\N$ with $k\le m$, set $V$ of $n$ voters, set $C$ of $m$ candidates.}
	\KwOut{Committee $W\subseteq C$ of size $k$.}
    Let $W=[\ ]$ be an empty list\;
    \For{$i=1,\ldots,k$,}{
		\begin{enumerate}
			\item  For all $c'\notin W$, determine $\Delta(W,c')$.
			\item Append $W$ with  $\argmax_{c'\notin W}\,\Delta(W,c')$.
		\end{enumerate}
	}
    \caption{\textsc{Greedy}}
    \label{alg:greedy}
\end{algorithm}

\begin{lemma}\label{lem:greedy_cc_ratio}
Algorithm~\ref{alg:greedy} is $(1-\frac{1}{\e})$-approximate for the Max Cover, and runs in time $\mathcal{O}(kmn)$.
\end{lemma}
This is a well known result, see e.g. \cite{hochbaum_analysis_1998}. We provide our own proof of Lemma~\ref{lem:greedy_cc_ratio} in the appendix. Writing $\gr(k)$ for the Max Cover score of the greedy algorithm after termination, we will assume that $\sum_{i\in V}\mathds{1}(|A(i)|\ge 1)\ge k$; there exist at least $k$ voters that approve a candidate. We call such instances, for which $\sum_{i\in V}\mathds{1}(|A(i)|\ge 1)\ge k$ is true, \emph{non-trivial} instances. After running the algorithm, thereby gathering the query responses, we can verify efficiently whether an instance is non-trivial. %\todo{niet per se? t kan dat je t niet ziet maar t wel zo is, maar dat is niet erg?}

\begin{proposition}\label{prop:ratio_greedy_eps}
On any non-trivial instance, $\gr(k)\ge k$. 
\end{proposition}

