\section{Proofs of Section 4}

\begin{replemma}{lem:greedy_cc_ratio}
Algorithm~\ref{alg:greedy} is $(1-\frac{1}{\e})$-approximate for the maximum coverage problem, and runs in time $\mathcal{O}(kmn)$.
\end{replemma}
For the proof we use the following notation: for $i\le k$, let $\gr_i$ denote the increase in Max Cover score the greedy algorithm attains in iteration $i$. Also for $i\le k$, write $\gr(i)$ for the Max Cover score of the greedy solution after $i$ iterations, so $\gr(k)$ is the final score. We write $\opt(k)$ for the score an optimal solution, consisting of $k$ candidates, would have.
\begin{proof}
We start with the approximation ratio. Like \cite[Lemma 1]{hochbaum_analysis_1998}, we first prove that, for $\ell\le k$, $\gr_{\ell}\ge (\opt(k)-\gr(\ell-1))/k$. Fix an optimal solution. At the start of iteration $\ell$, the difference between the greedy score and the optimal score is $\opt(k)-\gr(\ell-1)$. Thus, there are \emph{at least} this many elements covered in the (fixed) optimal solution, that have not been covered yet by \textsc{greedy} up to that point (it could be more: the set selected by \textsc{greedy} at the start of iteration $\ell$, needn't be a subset of the optimal solution). These $\opt(k)-\gr(\ell-1)$ elements are covered by the $k$ sets in the optimal solution so, by the pigeon hole principle, there exists a set in the optimal solution, that is not currently selected by \textsc{greedy}, that will cover at least $(\opt(k)-\gr(\ell-1))/k$ of these elements. Then, in iteration $\ell$, the greedy algorithm picks the set that covers the most additional elements, so these must be at least $(\opt(k)-\gr(\ell-1))/k$ many. We use this relation to obtain an expression for $\gr(k)$ in terms of $\opt(k)$. For all $k$,

\begin{align*}
\gr(k)&=\gr(k-1)+\gr_k\\
&\ge \gr(k-1)+\frac{\opt(k)-\gr(k-1)}{k}\\
&=\frac{\opt(k)}{k}+\gr(k-1)\left(1-\frac{1}{k}\right)\\
&\ge \frac{\opt(k)}{k}+\left(\frac{\opt(k)}{k}+\gr(k-2)\left(1-\frac{1}{k}\right)\right)\left(1-\frac{1}{k}\right)\\
&\ge \frac{\opt(k)}{k}+\left(\frac{\opt(k)}{k}+\left(\frac{\opt(k)}{k}+\gr(k-3)\left(1-\frac{1}{k}\right)\right)\left(1-\frac{1}{k}\right)\right)\left(1-\frac{1}{k}\right) \\ 
&\ldots \\
&\ge \frac{\opt(k)}{k}+\frac{\opt(k)}{k}\left(1-\frac{1}{k}\right)+\frac{\opt(k)}{k}\left(1-\frac{1}{k}\right)^2+\ldots+\frac{\opt(k)}{k}\left(1-\frac{1}{k}\right)^{k-2}+\gr(1)\left(1-\frac{1}{k}\right)^{k-1}\\
&\ge \frac{\opt(k)}{k}\left(\sum_{i=0}^{k-2}\left(1-\frac{1}{k}\right)^i+\left(1-\frac{1}{k}\right)^{k-1}\right)\\
&=\frac{\opt(k)}{k}\sum_{i=0}^{k-1}\left(1-\frac{1}{k}\right)^i\\
&= \frac{\opt(k)}{k}\left(k\left(1-\left(1-\frac{1}{k}\right)^k\right)\right)\\
&= \opt(k)\left(1-\left(1-\frac{1}{k}\right)^k\right).
\end{align*}
Because $\left(1-\frac{1}{k}\right)^k$ is an increasing sequence with $\lim_{k\to\infty}\left(1-\frac{1}{k}\right)^k=\frac{1}{\e}$, we can bound the last expression from below by $\opt(k)\left(1-\frac{1}{\e}\right)$, which proves the approximation ratio. 

Regarding the time complexity, the algorithm chooses $k$ candidates sequentially. For each of these $k$ steps, we have to go over all $m$ candidates to check which adds most to the current score. Per candidate, we have to check for each of the $n$ voters whether it is already represented (we can keep track of the represented voters in one set). This gives a time complexity in $\mathcal{O}(k m n)$.
\end{proof}

\begin{remark}
The convergence goes rather quickly; for $k=10$, we already have $1-(1-\frac{1}{k})^k=1-\frac{9}{10}^{10}\approx 0.651$, whereas $1-1/\e\approx 0.632$. However, for small committee sizes the actual worst case approximation ratio can be substantially smaller than the general ratio of $1-1/\e$: when $k=3$, the ratio is actually $1-\frac{2}{3}^3\approx 0.704$.
\end{remark}

\begin{repproposition}{prop:ratio_greedy_eps}
On any non-trivial instance, $\gr(k)\ge k$. 
\end{repproposition}
\begin{proof}
We proceed by contraposition. Assume $\gr(k)<k$, which is equivalent to $\gr(k)\le k-1$, so (by the pigeonhole principle) there exists $i\le k$ such that $\gr_i=0$. Because $\gr_i \le \gr_{i-1}$ for all $i\le k$, we must have (at least) $\gr_k=0$; no candidate with a yet uncovered voter is left in iteration $k$, since otherwise the greedy algorithm would pick that over an empty candidate and then $\gr_k>0$. At this point, $\gr(k-1)\le k-1$ and no uncovered voters are left, so $\sum_{i\in V}\mathds{1}(|A(i)|\ge 1)\le k-1$.
\end{proof}

\begin{replemma}{lem:greedy_eps}
For any non-trivial instance, \textsc{greedy}-$\epsilon$ is $\left(\left(1-\frac{1}{\e}\right)\cdot\left(\frac{1}{1+\epsilon(1-\frac{1}{\e})}\right)\right)$-approximate.
\end{replemma}
For $i\le k$, define $\gr\hspace{-0.5mm}\text{-}\epsilon_i$ and $\gr\hspace{-0.5mm}\text{-}\epsilon(i)$ similarly to before.
\begin{proof}
We write out $\gr\hspace{-0.5mm}\text{-}\epsilon(k)$ recursively like before, but now subtracting $\epsilon$ in each iteration. For any $k$, we have
\begin{align*}
\gr\hspace{-0.5mm}\text{-}\epsilon(k)&=\gr\hspace{-0.5mm}\text{-}\epsilon(k-1)+\gr\hspace{-0.5mm}\text{-}\epsilon_k\\
&\ge \gr\hspace{-0.5mm}\text{-}\epsilon(k-1)+\frac{\opt(k)-\gr\hspace{-0.5mm}\text{-}\epsilon(k-1)}{k}-\epsilon\\
&=\frac{\opt(k)}{k}+\gr\hspace{-0.5mm}\text{-}\epsilon(k-1)\left(1-\frac{1}{k}\right)-\epsilon\\
&\ge \frac{\opt(k)}{k}+\left(\frac{\opt(k)}{k}+\gr\hspace{-0.5mm}\text{-}\epsilon(k-2)\left(1-\frac{1}{k}\right)-\epsilon\right)\left(1-\frac{1}{k}\right)-\epsilon\\
&= \frac{\opt(k)}{k}-\epsilon + \left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)+\gr\hspace{-0.5mm}\text{-}\epsilon(k-2)\left(1-\frac{1}{k}\right)^2\\
&\ge \frac{\opt(k)}{k}-\epsilon +\left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)+\left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)^2+\gr\hspace{-0.5mm}\text{-}\epsilon(k-3)\left(1-\frac{1}{k}\right)^3
&\ldots \\
&\ge \frac{\opt(k)}{k}-\epsilon +\left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)+\left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)^2\\
&\ \ \ +\ldots+ \left(\frac{\opt(k)}{k}-\epsilon\right)\left(1-\frac{1}{k}\right)^{k-2}+\gr\hspace{-0.5mm}\text{-}\epsilon(1)\left(1-\frac{1}{k}\right)^{k-1}\\
&\ge \left(\frac{\opt(k)}{k}-\epsilon\right)\sum_{i=0}^{k-1}\left(1-\frac{1}{k}\right)^i\\
&= \opt(k)\left(1-\left(1-\frac{1}{k}\right)^k\right) -\epsilon k\left(1-\left(1-\frac{1}{k}\right)^k\right),
\end{align*}
which we can bound from below by $(\opt(k)-\epsilon k)\left(1-\frac{1}{\e}\right)$ again by taking a limit $k\to\infty$. This shows $\frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k)}{\opt(k)}\ge \left(1-\frac{\epsilon k}{\opt(k)}\right)\left(1-\frac{1}{\e}\right) = \left(1-\frac{1}{\e}\right)+\frac{1}{\opt(k)}\left(\frac{\epsilon k}{\e}-\epsilon k\right)\iff \frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k) +\epsilon k\left(1-\frac{1}{\e}\right)}{\opt(k)}\ge 1-\frac{1}{\e}.$

Using $\gr(k)\ge k$, we can reformulate $1-\frac{1}{\e}\le \frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k) +\epsilon k\left(1-\frac{1}{\e}\right)}{\opt(k)}\le \frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k) +\gr\hspace{-0.5mm}\text{-}\epsilon(k)\cdot\epsilon\left(1-\frac{1}{\e}\right)}{\opt(k)}= \frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k)\cdot\left(1+\epsilon\left(1-\frac{1}{\e}\right)\right)}{\opt(k)}$.
\end{proof}

\begin{reptheorem}{thm:greedy_bound}
For any non-trivial instance, any $\delta>0,\, \gamma\in(0,1)$, and $k<t\le m$, with probability at least $1-\delta$, Algorithm~\ref{alg:greedy-incomplete-queries} is $(1-1/\e)\gamma$-approximate for Max Cover using 
\[
k\cdot t \left\lceil\frac{m-k}{t-k}\right\rceil\cdot\left \lceil 0.8\left(\frac{\gamma}{1-\gamma}\right)^2\log\left(\frac{2 m k}{\delta}\right)\right \rceil\in 
\mathcal{O}\left(\left(\frac{\gamma}{1-\gamma}\right)^2km\log\left(\frac{km}{\delta}\right)\right)
\]
queries.
\end{reptheorem}

\begin{proof}
We will compute the necessary values of $\epsilon$ and $\ell$ so that the statement is true, and we will see that they are indeed as stated in Algorithm~\ref{alg:greedy-incomplete-queries}. From Proposition~\ref{prop:ratio_greedy_eps} and Lemma~\ref{lem:greedy_eps}, we know that if all our estimates are within $\frac{1}{2}\epsilon$ of the value that they estimate, then $\frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k)}{\opt(k)}\ge \left(1-\frac{1}{\e}\right)\left(\frac{1}{1+\epsilon(1-\frac{1}{\e})}\right)$. For $\gamma\in(0,1)$, we take $\epsilon=\frac{(1-\gamma)e}{\gamma(e-1)}$ so that $\frac{\gr\hspace{-0.5mm}\text{-}\epsilon(k)}{\opt(k)}\ge\gamma\cdot\left(1-\frac{1}{\e}\right)$.

We want to find $\ell$ so that with probability $1-\delta$, all our estimations $\hat{\Delta}$ are within  $\frac{1}{2}\epsilon$ of the true values $\Delta$. For this, we use Hoeffding's inequality to bound the probability that a single estimate is more than $\frac{1}{2}\epsilon$ away from its corresponding true value. We assume our samples are independent, and we know that all samples are in $\{0,1\}$, that their sample mean is $\hat{\Delta}$ and their expected value is $\Delta$, so using Hoeffding's inequality we obtain for any estimate $\hat{\Delta}$ of $\Delta$:
\begin{align}
\P\left(|\hat{\Delta}-\Delta|\ge\frac{1}{2}\epsilon\right)\le 2\exp\left(-\frac{1}{2}\ell\epsilon^2\right).
\end{align}
There are $k$ iterations and at most $m$ estimates per iteration so no more than $k\cdot m$ estimations in total. Thus, by independence, we have
\begin{align}
\P\left(\forall i: |\hat{\Delta}_i-\Delta_i|<\frac{1}{2}\epsilon\right)\ge 1-2\exp\left(-\frac{1}{2}\ell\epsilon^2\right)\cdot  m \cdot k.
\end{align}
We want to find $\ell$ so that this value equals at least $1-\delta$, and so we proceed to write
\begin{align}
1-2\exp\left(-\frac{1}{2}\ell\epsilon^2\right)\cdot m \cdot k\ge1-\delta 
\iff \exp\left(-\frac{1}{2}\ell\epsilon^2\right)\le\frac{\delta}{2 m k}
% &\iff -\ell\le \frac{2\log\left(\frac{\delta}{2 m k}\right)}{\epsilon^2}\\ 
\iff \ell\ge \frac{2}{\epsilon^2}\log\left(\frac{2 m k}{\delta}\right).
\end{align}
This means, for any $0<\delta\le 1$, any $\ell$ that is at least this large, will, with probability $1-\delta$, produce (querying $\ell$ voters) estimates that are all at most $\frac{1}{2}\epsilon$ apart from the value that they estimate. Then we can invoke Lemma~\ref{lem:greedy_eps} to obtain the desired ratio. We take the smallest possible value: $\ell = \left\lceil \frac{2}{\epsilon^2}\log\left(\frac{2 m k}{\delta}\right)\right\rceil$ and filling in for $\epsilon$ this results in
\begin{align}
\ell=\left \lceil \frac{2}{\left(\frac{(1-\gamma)e}{\gamma(e-1)}\right)^2}\log\left(\frac{2 m k}{\delta}\right)\right \rceil = \left \lceil \frac{2\gamma^2(e-1)^2}{(1-\gamma)^2\e^2}\log\left(\frac{2 m k}{\delta}\right)\right \rceil \le \left \lceil 0.8\left(\frac{\gamma}{1-\gamma}\right)^2\log\left(\frac{2 m k}{\delta}\right)\right \rceil \ ,
\end{align}
giving 
\begin{align}
k\cdot t \left\lceil\frac{m-k}{t-k}\right\rceil\cdot \ell\le k\cdot t \left\lceil\frac{m-k}{t-k}\right\rceil\cdot\left \lceil 0.8\left(\frac{\gamma}{1-\gamma}\right)^2\log\left(\frac{2 m k}{\delta}\right)\right \rceil \in \mathcal{O}\left(\left(\frac{\gamma}{1-\gamma}\right)^2km\log\left (\frac{km}{\delta}\right)\right)
\end{align}
queries.
\end{proof}

\begin{repproposition}{prop:matroid}
For any instance $(V,C,A,k)$ and any matroid $\mathcal{M}$ of rank $k$, no cover of size $\ell<k$ will attain a unique maximal Max Cover score.
\end{repproposition}
\begin{proof}
Suppose there does exist a cover $L\in\mathcal{M}$ of size $\ell<k$ that has a higher Max Cover score than any size-$k$ cover $M\in\mathcal{M}$. This means there exists no superset of $L$ in $\mathcal{M}$, in particular not any of size $k$, because the Max Cover score is monotone in the amount of sets that the cover contains. But by requirement 3) in Definition~\ref{matroid}, using any basis element $K\in\mathcal{M}$, we can make a path of sets $L,\ L\cup k_1,\ L\cup k_1\cup k_2,\ \ldots, L\cup k_1\cup\ldots\cup k_{k-\ell}=: L'$ from $L$ to attain a basis element $L'\in\mathcal{M}$ that contains $L$. 
\end{proof}

\begin{reptheorem}{thm:ls_bound}
For any $\delta>0$, $\gamma\in(0,1)$, $m\ge t > k$, and some universal constant $C_2$, with probability at least $1-\delta$, Algorithm~\ref{alg:LS-incomplete-queries}, with $\beta = C_2\frac{1-\gamma}{\gamma k\log k}$, is $(1-1/\e)\gamma$-approximate for Max Cover when using 
\[
\xi\alpha_k\cdot\left(\frac{\gamma k\log k}{C_2(1-\gamma)}\right)^3\cdot t\left\lceil\frac{m-k}{t-k}\right\rceil\cdot\left\lceil\frac{(2-2/\e)^2}{2}\left(\frac{2\xi}{\xi-1}\right)^2\log\left(\frac{2\cdot(m-k)k\cdot\xi\alpha_k\cdot\gamma  k\log k}{C_2(1-\gamma)\delta}\right)\right\rceil
\]
queries. Asymptotically in $k,m,\gamma$ and $\delta$, this is in
\[
\mathcal{O}\left(\left(\frac{\gamma k\log k}{1-\gamma}\right)^3m\log\left(\frac{m\gamma k^2\log k}{\delta(1-\gamma)}\right)\right).
\]
\end{reptheorem}
\begin{proof}
We will compute the necessary values of $\epsilon$ and $\ell$ so that the statement is true, and we will see that they are indeed the same as stated in Algorithm~\ref{alg:LS-incomplete-queries}. In the original approximation ratio (of Algorithm~\ref{alg:LS}), we substitute $\gamma$ for $(1-1/\e)(1-\gamma)$, so that the ratio becomes $(1-1/\e)\cdot\gamma$ and we adapt the constant factor accordingly. %Then $C_1\le\frac{\log2}{1-1/\e}$ and $C_2=C_1\cdot (1-1/\e)\le\log 2$.

With this value of $\beta$, the minimum step size of \textsc{Local Search}-$\beta$ (Algorithm~\ref{alg:LS}) is $C_2\frac{1-\gamma}{\gamma k\log k}$, and every committee attains score at least $0$ and at most $\alpha_k$, so Algorithm~\ref{alg:LS} runs at most $\alpha_k \cdot \frac{\gamma k\log k}{C_2(1-\gamma)}$ iterations. We anticipate that querying will increase the amount of required iterations, because of the uncertainty inducing estimations. Depending on how many iterations we allow, values of $\epsilon$ (the estimation margin) and $\ell$ (the amount of voters queried per round) will also differ. Thus, to make this dependency explicit, we add in a factor $\xi\ge 1$ and say the algorithm with queries has a total of at most $\xi \alpha_k \cdot \frac{\gamma k\log k}{C_2(1-\gamma)}$ iterations. We then compute the maximal value of $\epsilon$ this corresponds to. 

Until the last run of the algorithm, we have $\hat{\Delta}(W,c',c)>\beta-\epsilon$, and when this is no longer true, the swap of $c$ for $c'$ is not made. We take $\epsilon$ so that all improvements ${\Delta}(W,c',c)$ are at least size $\hat{\Delta}(W,c',c)-\epsilon >\beta-2\epsilon$ and solve
\begin{align}
\beta-2\epsilon= C_2\frac{1-\gamma}{\gamma k\log k}-2\epsilon = C_2\frac{1-\gamma}{\xi\cdot \gamma k\log k},
\end{align}
for $\epsilon$ to obtain $\epsilon=\frac{\xi - 1}{2\xi}\cdot C_2\frac{1-\gamma}{\gamma k\log k}$, which is the maximum margin of estimation we can allow in order to have our original number of iterations multiplied by at most $\xi$.

We want to have $\ell$ such that with probability $1-\delta$, all our estimations $\hat{\Delta}$ are within $\epsilon$ of the true values $\Delta$. To this end, we use Hoeffding's inequality to bound the probability that a single estimation is more than $\epsilon$ away from its corresponding $\Delta$-value. For any committee, any voter will attain some score in $\{\alpha_0,\ldots,\alpha_k\}$ and whenever a candidate $c\in W$ is replaced for another candidate $c'\notin W$, the voter can approve one less candidate than before, the same amount of candidates as before, or one more candidate than before. A score $\alpha_i$ before a swap, can thus become any of scores $\{\alpha_{i-1},\alpha_i,\alpha_{i+1}\}$ after. In Lemma 3, \cite{filmus_power_2013} prove that for all $i<k$, $\alpha_{i+1}>\alpha_i$ and $\alpha_{i+2}-\alpha_{i+1}\le\alpha_{i+1}-\alpha_i$. Thus, $\{\alpha_i\}_i$ is an increasing sequence, but the increase declines monotonically. We may thus take $\alpha_1-\alpha_0=1-\frac{1}{\e}$ for an upper bound on the difference between consecutive values in $\{\alpha_i\}_i$. Then we see that all our samples of $\Delta(W,c)$ and $\Delta(W,c',c)$ take values in the interval $[-1+\frac{1}{\e},1-\frac{1}{\e}]$. The sample mean is $\hat{\Delta}$ and the expected value is $\Delta$, and we assume the samples are independent. Hoeffding's inequality then yields, for any of the estimates $\hat{\Delta}$ of $\Delta$,
\begin{align}
\P(|\hat{\Delta}-\Delta|\ge\epsilon)\le 2\exp \left(-\frac{2\epsilon^2\ell}{(2-2/\e)^2}\right).
\end{align}
In each iteration we estimate $\Delta(W,c',c)$ based on all combinations $(c',c)$, so these are $(m-k)\cdot k$ estimations. This gives $(m-k)\cdot k\cdot\xi\alpha_k\cdot \frac{\gamma k\log k}{C_2(1-\gamma)}$ estimations in total over all iterations. The probability that for all $i$, the estimation $\hat{\Delta}_i$ of $\Delta_i$ is within $\epsilon$ of the true value, then becomes
\begin{align}
\P(\forall i: |\hat{\Delta}_i-\Delta_i|<\epsilon) \ge 1-2\exp\left(-\frac{2\epsilon^2\ell}{(2-2/\e)^2}\right)\cdot (m-k)k\cdot\xi\alpha_k\cdot\frac{\gamma k\log k}{C_2(1-\gamma)}.
\end{align}
We can now choose $\ell$ such that this it at least $1-\delta$:
\begin{align}
\begin{split}
1-2&\exp\left(-\frac{2\epsilon^2\ell}{(2-2/\e)^2}\right)\cdot (m-k)k\cdot\xi\alpha_k\cdot\frac{\gamma k\log k}{C_2(1-\gamma)} \ge 1-\delta\\
\iff &2\exp\left(-\frac{2\epsilon^2\ell}{(2-2/\e)^2}\right)\cdot (m-k)k\cdot\xi\alpha_k\cdot\frac{\gamma k\log k}{C_2(1-\gamma)}\le\delta\\
\iff &\exp\left(-\frac{2\epsilon^2\ell}{(2-2/\e)^2}\right)\le \frac{1}{2}\delta\cdot\frac{1}{(m-k)k}\cdot\frac{1}{\xi\alpha_k}\cdot\frac{C_2(1-\gamma)}{\gamma k\log k}\\
\iff &-\ell\le\frac{(2-2/\e)^2}{2\epsilon^2} \log\left(\frac{1}{2}\delta\cdot\frac{1}{(m-k)k}\cdot\frac{1}{\xi\alpha_k}\cdot\frac{C_2(1-\gamma)}{\gamma k\log k}\right)\\
\iff & \ell\ge \frac{(2-2/\e)^2}{2\epsilon^2}\log\left(\frac{2\cdot(m-k)k\cdot\xi\alpha_k\cdot  \gamma k\log k}{C_2(1-\gamma)\delta}\right).
\end{split}
\end{align}
This means, for any $0<\delta\le 1$, any $\ell$ that is at least this size, will, with probability $1-\delta$, produce (querying $\ell$ voters) estimates that are all at most $\epsilon$ apart from the value that they estimate. We take the smallest possible value of $\ell$:
\[\ell=\left\lceil\frac{(2-2/\e)^2}{2\epsilon^2}\log\left(\frac{2\cdot(m-k)k\cdot\xi\alpha_k\cdot \gamma k\log k}{C_2(1-\gamma)\delta}\right)\right\rceil.\]

The algorithm terminates when $\hat{\Delta}(W,c',c)<\frac{C_2(1-\gamma)}{\gamma k\log k}-\epsilon$, which implies $\Delta(W,c',c)<\frac{C_2(1-\gamma)}{\gamma k\log k}$. This is the original stopping condition of the algorithm without queries, so the original performance guarantees also hold here; the approximation ratio is $(1-1/\e)\gamma$. Last we study the amount of queries. In total there are
\begin{align}
&\xi\alpha_k\cdot\frac{\gamma k\log k}{C_2(1-\gamma)}\cdot t\left\lceil\frac{m-k}{t-k}\right\rceil\cdot\left\lceil\frac{(2-2/\e)^2}{2\epsilon^2}\log\left(\frac{2\cdot(m-k)k\cdot\xi\alpha_k\cdot \gamma k\log k}{C_2(1-\gamma)\delta}\right)\right\rceil\\
&= \xi\alpha_k\cdot\left(\frac{\gamma k\log k}{C_2(1-\gamma)}\right)^3\cdot t\left\lceil\frac{m-k}{t-k}\right\rceil\cdot\left\lceil\frac{(2-2/\e)^2}{2}\left(\frac{2\xi}{\xi-1}\right)^2\log\left(\frac{2\cdot(m-k)k\cdot\xi\alpha_k\cdot\gamma  k\log k}{C_2(1-\gamma)\delta}\right)\right\rceil \nonumber
\end{align}
queries. Asymptotically in $k\ll m,\,\gamma$ and $\delta$, this is in $\mathcal{O}\left(\left(\frac{\gamma k\log k}{1-\gamma}\right)^3m\log\left(\frac{m\gamma k^2\log k}{\delta(1-\gamma)}\right)\right)$.
\end{proof}

\section{Lower bound for the query complexity of non-adaptive algorithms in the incomplete information setting}
For the incomplete information setting, we have seen two algorithms. Both algorithms make use of information acquired during the run of the algorithm. Indeed, when selecting the query sets, we need these to contain the currently elected committee. We next present a lower bound for the query complexity of non-adaptive algorithms, which can not adapt their querying strategy to readily obtained information. The proof concerns the original setting, without matroid constraints, but the result extends to the problem over a matroid constraint, as it is a more general problem. The proof strategy follows \cite[Theorem 3.1]{halpern_representation_2023}.

\begin{theorem}\label{thm:incomplete_lower_bound}For any $k\ge 2$, $\epsilon>0$, and $\gamma\in(\frac{1}{2},1)$, any non-adaptive committee selection algorithm that makes fewer than $\Omega(\frac{m^2 \epsilon}{1-\gamma})$ queries, attains a $(1-1/\e)\gamma$-approximate max cover score with probability at most $\epsilon$.	
\end{theorem}

\begin{proof}
We denote a given non-adaptive committee selection algorithm by $\alg$. We define the class of instances that will serve as an example for the lower bound: let $k=2p+r$, where $p\in\N$ and $r\in\{0,1\}$, which means we can form any $k\in\N_{\ge 2}$ for the committee size. Partition the candidates into $C_1\cup C_2\cup\ldots\cup C_p\cup D$, with $|C_i|=\lfloor (m-r)/p\rfloor$ for all $i\in\{1,\ldots,p\}$, $D$ containing the remaining candidates. Because $\sum_{i=1}^p|C_i|=p\cdot \lfloor (m-r)/p\rfloor \le m-r$, we know $|D|\ge r$. For each $i$, we form $S_i=\{c_{i,1},\ldots,c_{i,\ell}\}\subseteq C_i$ by picking $\ell$ distinct candidates from $C_i$. The candidates are all chosen to join $S_i$ uniformly and independently of one another, and the assignment of these candidates to the numbers $1,\ldots,\ell$ is also random. Moreover, this procedure happens independently for all $C_i$. We partition the voters into $p$ parties $P_1,\ldots,P_p$ and, if $r=1$, one party $R$ (if $r=0$ there is no set $R$). Each party $P_i$ contains $2/k$ of the voters and all voters in $P_i$ approve only of candidates within $S_i$ (so no one approves any candidate in $C_i\setminus S_i$). More specifically, for each $P_i$, we can again partition the candidates of $C_i$ into two groups with non-overlapping approval sets: candidates $c_{i,1},\ldots,c_{i,\ell-1}$, are collectively approved by $1/2$ of the voters in $P_i$ (so $1/(2k)$ voters in total) and $c_{i,\ell}$, that we call the designated candidate, is approved by the other half of $P_i$. The party $R$, if it exists, contains $1/k$ of the voters, all of whom approve precisely one candidate $d\in D$.

We say that $\alg$ \emph{covers} a set of candidates $S$ if $\alg$ ever submits a query set $Q$ for which $|Q\cap S|\ge 2$. This means that, if for any of the parties $P_i$, $\alg$ fails to cover $S_i$, all $\ell$ of these candidates are indistinguishable to $\alg$, given the definition of our query model. Indeed, all candidates within $S_i$ are approved by the same number of voters, and we can only start to distinguish the structure of $S_i$ if we combine $c_{i,\ell}$ and $c_{i,j}$ for some $j\in\{1,\ldots,\ell-1\}$ in one query. Then, if a set $S_i$ is not covered, the best $\alg$ can do is pick candidates from $S_i$ randomly, since  without covering $S_i$ it is still possible to distinguish which elements form the set $S_i$. 

