\begin{algorithm}[h]
	\SetAlgoNoLine
	\KwIn{Numbers $n,m,k\in\N$ with $k\le m$, set $V$ of $n$ voters, set $C$ of $m$ candidates, parameters $p\in(0,\frac{1}{2}),\,\delta>0$.}
	\KwOut{Committee $W\subseteq C$ of size $k$.}
    $U=\lceil -2\frac{\log((nm)/\delta)}{\log(4p(1-p))}\rceil$\;
    For all $i\in V,\, j\in C$, perform query $(i,j)$ $U$ times and take the majority winner as the `true' query response\;
    Let $W=[\ ]$ be an empty list\;
    \For{$i=1,\ldots,k$,}{
		\begin{enumerate}
			\item For all $c'\notin W$, determine $\Delta(W,c')$.
			\item Append $W$ with  $\argmax_{c'\notin W}\,\Delta(W,c')$.
		\end{enumerate}
	}
    \caption{\textsc{Greedy-inaccurate}}
    \label{alg:greedy-inaccurate}
\end{algorithm}

\begin{reptheorem}{thm:inaccurate_upper_bound}
In the query model with inaccurate query responses and parameter $p\in(0,\frac{1}{2})$, for any $\delta>0$, $n,m\in\mathbb{N}$, we attain a $(1-1/\e)$-approximate solution to Max Cover with probability at least $1-\delta$ using $nm\cdot U$ queries, where $U=\lceil -2\frac{\log((nm)/\delta)}{\log(4p(1-p))}\rceil$. This gives a query complexity in $\mathcal{O}(nm\log(nm/\delta))$.
\end{reptheorem}
\begin{proof}
We adapt Algorithm~\ref{alg:greedy}: for all pairs $(i,j)$ for $i\in V$ and $j\in C$, we perform query $(i,j)$ $U$ times and take the majority winner of the results to be the `true' value, breaking ties arbitrarily. There are $nm$ pairs $(i,j)$ for $i\in V$ and $j\in C$, so we only need to show that for any $\delta>0$, taking $U$ as stated, we obtain an $(1-1/\e)$-approximate solution with probability $1-\delta$. 

Take $\Omega = \{0,1\}^U$, $\mathcal{F}=\mathcal{P}(\Omega)$ and $\P:\mathcal{F}\to[0,1]$ that satisfies $\P(\{\mathbf{v}\})=(1-p)^y p^{U-y}$ when $\mathbf{v}$ contains $y$ 1s and $U-y$ 0s. Accordingly, write $\mathbf{v}_{i,j}$ for a vector that is the outcome of $U$ throws of $(i,j)$, where entry 0 means the outcome is correct (success) and 1 means the outcome is corrupted (failure). Then take $X:\Omega\to\N: \mathbf{v}_{i,j} \mapsto \sum_{l=1}^U v_{i,j,l}$ for the random variable that maps an outcome vector to the number of successes and write $\bar{X}:= U-X$ for the number of failures. 

%\begin{align*}
%\P\left(\bar{X}\ge \frac{1}{2}M\right)
%=\P\left(\frac{\bar{X}-\E[\bar{X}]}{M}\ge \frac{1}{2}-p\right)
%\le \exp\left(-2M\left(\frac{1}{2}-p\right)^2\right),
%\end{align*}
%by Hoeffding's inequality.
A Chernoff bound gives $\P(\bar{X}\ge \frac{1}{2}U)\le \exp(-UD(\frac{1}{2}||p))$ \cite{gordon_tutorial_1989} and we can reformulate to
\begin{align}
\begin{split}
\exp\left\{-UD\left(\frac{1}{2}||p\right)\right\} &= \exp\left\{-U\left(\frac{1}{2}\log\left(\frac{1/2}{1-p}\right) + \frac{1}{2}\log\left(\frac{1/2}{p}\right)\right)\right\}\\
&= \exp\left\{-U\frac{1}{2}\log\left(\frac{1/2}{1-p}\right)\right\}\exp\left\{-U\frac{1}{2}\log\left(\frac{1/2}{p}\right)\right\}\\
&=\left(\frac{1}{4(1-p)p}\right)^{-\frac{1}{2}U}.
\end{split}
\end{align}

This gives an upper bound on the probability that we have an incorrect majority for a single $(i,j)$, where each throw is correct with probability $1-p$. We choose $U$ so that this stays smaller than $\frac{\delta}{nm}$, and for that we need 
\begin{align}
-\frac{1}{2}U\ge \log_{\frac{1}{4p(1-p)}}\left(\frac{\delta}{nm}\right)=\frac{\log \frac{\delta}{nm}}{\log\frac{1}{4p(1-p)}}=-\frac{\log \frac{nm}{\delta}}{\log\frac{1}{4p(1-p)}},
\end{align} so we can take $U=\lceil -2\frac{\log((nm)/\delta)}{\log(4p(1-p))}\rceil$. Then the probability of any of the $nm$ estimates being incorrect, is bounded above by $\delta$. 
\end{proof}

\begin{reptheorem}{thm:inaccurate_lower_bound}
In the query model with inaccurate query responses, for any $\delta\in(0,1),\,n,m\in\mathbb{N}$, any algorithm that outputs an ($1-1/\e$)-approximate solution to Max Cover with probability at least $1-\delta$, makes $\Omega(nm\log(1/\delta))$ queries in expectation.
\end{reptheorem}
To establish the theorem, we adapt the proof of Theorem 9 in \cite{schafer_complexity_2024}, using a result from multi-armed bandit theory \cite{lattimore_bandit_2020} to lower bound the query complexity. The Kullback-Leibler divergence between two probability distributions is defined as $D(P||Q)=\sum_{x} P(x)\log\frac{P(x)}{Q(x)}$ for discrete probability functions $P$ and $Q$, as long as, for all $x,\, Q(x)=0\implies P(x)=0$ (otherwise we define it as $+\infty$). This reduces to $d(a,b)=a\log\frac{a}{b}+(1-a)\log\frac{1-a}{1-b}$ for two Bernoulli distributions with parameters $a,b\in(0,1)$.

\begin{proof}
We interpret each query $(i,j)$, with $v_i\in V$ and $c_j\in C$, as an arm $a\in\mathcal{A}$ in a multi-armed bandit problem. For $p\in(0,1/2)$, response $y_t$ to $a_t=(i,j)$, for query number $t$, is distributed as Bernoulli$(1-p)$ if $v_i$ approves of $c_j$, and as Bernoulli$(p)$ otherwise. Let $P_a$ denote the Bernoulli distribution associated with action $a$: for any query index $t$ and any $y\in\{0,1\}$ we have $P_a(y)=\P(y_t=y|a_t=a)$. Let us refer to an arbitrary (possibly randomized) algorithm for the problem by $\alg$. We write $\E^{\nu}$ and $\P^{\nu}$ for the expectation and probability when the underlying instance is $\nu$. Write $L_\nu$ for the set of optimal committees for instance $\nu$. By assumption we have $\P^\nu(\alg(\nu)\in L_\nu)\ge 1-\delta$ for any instance $\nu$. We denote the random variable that portrays the number of queries taken when $\alg$ terminates, by $\tau$. We use the following lemma from multi-armed bandit theory, that is mentioned e.g. in \cite{lattimore_bandit_2020}, Chapter 15 (Lemma 15.1 and more specifically Exercise 15.7).
\begin{lemma}\label{lemma_KL}
Let $\nu$ and $\nu'$ be any two bandit instances defined on the same set of arms $\mathcal{A}$, with corresponding observation distributions $\{P_a\}_{a\in\mathcal{A}}$ and $\{P'_a\}_{a\in\mathcal{A}}$. Let $\tau$ be the total number of queries made when the algorithm terminates, and let $\mathcal{E}$ be any probabilistic event that can be deduced from the resulting history $(a_1,y_1,\ldots,a_\tau,y_\tau)$, possibly with additional randomness independent of that history. Then, for $T_a$ the number of times action $a$ is queried up to termination index $\tau$, we have
\begin{align}
\sum_{a\in\mathcal{A}}\E^\nu[T_a]D(P_a||P'_a)\ge d(\P^\nu(\mathcal{E}),\P^{\nu'}(\mathcal{E})).
\end{align}
\end{lemma}

For any $k\ge 2$, consider an instance $\nu$ with $m$ candidates and $n$ voters. We partition the voters into $m-w$ disjoint ``parties" $P_1,\ldots,P_{m-w}$, where $ w\ge 0$ and $w$ is bounded from above by some fraction of $m$. Voters in party $P_i$ approve precisely $c_i$. Candidates $c_1,\ldots,c_{m-w-k}$ (together $C_1$) all have one approving voter. These $m-w-k$ voters (together $V_1$) are alone in their party. Candidates $c_{m-w-k+1},\ldots,c_{m-w}$ (together $C_2$) all have $u>\frac{1}{1-\frac{1}{\e}\cdot k}$ approving voters (together $V_2$), so that the only $(1-\frac{1}{\e})$-approximate solution consists of the $k$ candidates in $C_2$:
\begin{align}
(k-1)u+1 < \left( 1-\frac{1}{\e} \right)ku \iff \left(\frac{1}{\e} k-1 \right) u < -1\iff u>\frac{1}{1-\frac{k}{\e}}.
\end{align}

The remaining $w$ candidates (together $C_3$) have no approving voters. Finally we have $V_4$, a set of voters that approve of no candidate (homeless voters). For any $m,n$, we can find constants $D,E\in (0,1)$ such that $|C_1|\ge D\cdot m$ (which means we need $w\le m-Dm-k$) and $(1-E)n -ku \ge |C_1|$ so that $|V_4|\ge E\cdot n$, so let's pick any such constant $D$ and $E$. Now consider the instance $\nu '$ that is obtained by taking, $x:=\lceil k(\frac{u}{1-1/\e}-1)\rceil$ homeless voters and distributing them (as) evenly (as possible) over $k$ candidates $c_{1},\ldots,c_k\in C_1$. Other than that, all preferences remain unchanged. With this value of $x$, we have $x+k>\frac{ku}{1-1/\e}$, which means that $\nu '$ has a unique $(1-1/\e)$-approximate solution in $c_1,\ldots,c_k\subseteq C_1$, whereas the unique $(1-1/\e)$-approximate solution of $\nu$ was the set $C_2$. Since both instances have only one optimal solution, and these differ, we have $L_{\nu}\cap L_{\nu'}=\emptyset$.

