\textbf{Claim 1.} Let $h\left( x \right)=\varepsilon \text{log}\left( \underset{j=1}{\overset{m}{\mathop \sum }}\,{{e}^{\frac{1}{\varepsilon }\left( {{\beta }_{j}}-\alpha _{j}^{T}x \right)}} \right)$. Suppose the problem P1 has the following objective function
\begin{equation}
\text{minimize}\quad h\left( x \right)
\label{eq50}
\end{equation}
Suppose the optimal value of P1 is $p_{1}^{*}$, then we have $0\le p_{1}^{*}-p_{0}^{*}\le ~\varepsilon \log m$.

\textbf{Proof:} Let ${{y}_{j}}={{\beta }_{j}}-\alpha _{j}^{T}x$, then the problem P1 is equivalent to problem P4:
\begin{equation}
\text{minimize}\quad \varepsilon \text{log}\left( \sum\limits_{j\in M}{{{e}^{\frac{1}{\varepsilon }{{y}_{j}}}}} \right)
\label{eq51}
\end{equation}
\begin{equation}
s.t.\quad {{y}_{j}}={{\beta }_{j}}-\alpha _{j}^{T}x
\label{eq52}
\end{equation}
then the Lagrangian function of P4 is
\begin{equation}
L\left( x,y,z \right)=\varepsilon \text{log}\left( \sum\limits_{j\in M}{{{e}^{\frac{1}{\varepsilon }{{y}_{j}}}}} \right)+{{z}^{T}}\left( \beta -Ax-y \right)
\label{eq53}
\end{equation}
, where $A=\left[ \alpha  \right]$, $L\left( x,y,z \right)$ is bounded below as a function of $x$ only if ${{z}^{T}}A=0$, to find the optimum over $y$, we set the gradient equal to zero.
\begin{equation}
\frac{\partial L\left( x,y,z \right)}{\partial y}=0
\label{eq54}
\end{equation}
That is
\begin{equation}
\frac{{{e}^{\frac{1}{\varepsilon }{{y}_{j}}}}}{\sum\limits_{j\in M}{{{e}^{\frac{1}{\varepsilon }{{y}_{j}}}}}}={{z}_{j}}
\label{eq55}
\end{equation}
This is solvable for $y_i$ if $z\ge 0,{{1}^{T}}z=1$. By substituting the above equation into the original one, we rewrite the Lagrangian function of P4 as
\begin{equation}
g\left( z \right)={{\beta }^{T}}z-\varepsilon \sum\limits_{j\in M}{{{z}_{j}}\log {{z}_{j}}}
\label{eq56}
\end{equation}
Overall, the dual problem P5 of the problem P4 is
\begin{equation}
\text{maximize}\quad {{\beta }^{T}}z-\varepsilon \sum\limits_{j\in M}{{{z}_{j}}\log {{z}_{j}}}
\label{eq57}
\end{equation}
\begin{equation}
s.t.\quad {{A}^{T}}z=0,{{1}^{T}}z=1,z\ge 0
\label{eq58}
\end{equation}
Suppose $z^{*}$ is the optimal solution for the dual problem P5, then $z^{*}$ is also feasible for the dual problem P3. Suppose the optimal value of P3 is $p_{3}^{*}$ and the optimal value of the original problem P0 is $p_{0}^{*}$, according to the Claim A.1, we have 
\begin{equation}
p_{0}^{*}=p_{3}^{*}\ge {{b}^{T}}{{z}^{*}}
\label{eq59}
\end{equation}
Then, since the problem P5 is the dual problem of P4, we have 
\begin{equation}
p_{5}^{*}=p_{4}^{*}={{b}^{T}}{{z}^{*}}-\varepsilon \sum\limits_{j\in M}{z_{j}^{*}\log z_{j}^{*}}
\label{eq60}
\end{equation}
, where $p_{4}^{*}$ and $p_{5}^{*}$ are the optimal value of problem P4 and P5. Combining the above two equations gives
\begin{equation}
p_{0}^{*}\ge p_{5}^{*}+\varepsilon \sum\limits_{j\in M}{z_{j}^{*}\log z_{j}^{*}}\ge p_{4}^{*}-\varepsilon \log m
\label{eq61}
\end{equation}
The bound follows from
\begin{equation}
\underset{{{1}^{T}}{{z}^{*}}=1}{\mathop{\min }}\,\sum\limits_{j\in M}{z_{j}^{*}\log z_{j}^{*}}=-\log m
\label{eq62}
\end{equation}
On the other hand, we have
\begin{equation}
\underset{j}{\mathop{\max }}\,\left( {{\beta }_{j}}-\alpha _{j}^{T}x \right)\le \varepsilon \text{log}\left( \sum\limits_{j\in M}{{{e}^{\frac{1}{\varepsilon }{{y}_{j}}}}} \right)
