\title{A Fast Algorithm for Computing Zigzag Representatives}


\author{Tamal K. Dey\thanks{Department of Computer Science, Purdue University. \texttt{tamaldey@purdue.edu}}
\and Tao Hou\thanks{Department of Computer Science, University of Oregon. \texttt{taohou@uoregon.edu}}
