\section{Proof of Proposition~\ref{prop:cyclebasis}}
\label{sec:pf-prop-cyclebasis}
    First, 
    the fact that
    $\bigSet{[\cyc_1^H],\ldots,[\cyc_{k'}^H]}$
    is a basis of $\Hm(K_j)$ and
    $\bigSet{\cyc^B_1,\ldots,\cyc^B_{k}}$
    is a basis of $\Bnd(K_j)$
    follows from the definition of interval decomposition and representatives.
    Consider any
    cycle $\cyc$ in $\Zyc(K_j)$. Then, there exists a unique $\alpha_t\in \{0,1\}$
    for each
    $1\leq j\leq k'$ so that $[\cyc]=\sum_t\alpha_t[\cyc^H_t]$. Then,
    $[\cyc]+\sum_t\alpha_t[\cyc^H_t]=[\cyc+\sum_t\alpha_t\cyc^H_t]=0$.
    It follows that $(\cyc+\sum_t\alpha_t\cyc^H_t)\in \Bnd(K_j)$, which implies that there exists a unique $\beta_\ell$ 
    for each $1\leq \ell\leq k$ so that
    $\cyc+\sum_t\alpha_t\cyc^H_t=\sum_\ell \beta_\ell\cyc^B_\ell$.
    So,
    $\cyc= \sum_t\alpha_t\cyc^H_t + \sum_\ell \beta_\ell \cyc^B_\ell$ for
    unique $\alpha_j$'s, $1\leq t\leq k'$ and $\beta_\ell$'s, $1\leq \ell \leq k$.
    It follows that the union of the cycles $\{\cyc^B_\ell\}$ and $\{\cyc^H_t\}$
    generate $\Zyc(K_j)$. Since $k+k'=\mathrm{dim}(\Bnd(K_j)) + \mathrm{dim}(\Hm(K_j))=\mathrm{dim}(\Zyc(K_j))$, they form a basis.

\section{Proof of Proposition~\ref{prop:repsum}}
\label{sec:pf-prop-repsum}
\noindent
    {\bf Case 1}, $b<b'$: In this case, every cycle $\bar{\cyc}_\alpha$,
    $\alpha\in[b',i]$, in
    $\rep\bndlsum\rep'$ satisfies that $\bar{\cyc}_\alpha=\cyc_\alpha+\cyc'_\alpha$. 
    It can be verified that we only have three different cases: (i) $b\in \pinds^B(\Fcal_i)$, $b'\in \pinds^H(\Fcal_i)$, (ii) $b\in \pinds^B(\Fcal_i)$, $b'\in \pinds^B(\Fcal_i)$, and (iii) 
    $b\in \pinds^H(\Fcal_i)$, $b'\in \pinds^H(\Fcal_i)$.
    We take up the case (i) and the proof for the other cases is similar.
    Assuming $K_\alpha\inctosp{}K_{\alpha+1}$ is  forward
    for $b'\leq \aG<i$,
    we have $\linmapB_\alpha(\cyc_\alpha)=\cyc_\alpha=\cyc_{\alpha+1}$ and
    $\linmap_\alpha([\cyc'_\alpha])=[\cyc'_{\alpha+1}]$. Therefore,
    $\linmap_\alpha([\bar{\cyc}_\alpha])=
    \linmap_\alpha([\cyc_\alpha])+\linmap_\alpha([\cyc'_\alpha])=
    [\cyc_{\alpha+1}]+[\cyc'_{\alpha+1}]= [\bar{\cyc}_{\alpha+1}]$ as required. The same applies
     when $K_\alpha\bakinctosp{}K_{\alpha+1}$ is backward. Finally, we verify that the birth and death conditions
    hold for $\bar{\cyc}_{b'}$.
    First assume that $K_{b'-1}\inctosp{} K_{b'}$ is forward. 
    For the birth condition,
    we have that $\bar{\cyc}_{b'}=\cyc_{b'}+\cyc'_{b'}\in \Zyc(K_{b'})\setminus \Zyc(K_{b'-1})$ because $\cyc'_{b'}\in \Zyc(K_{b'})\setminus \Zyc(K_{b'-1})$ and $\cyc_{b'}=\cyc_{b'-1}\in \Zyc(K_{b'})\cap \Zyc(K_{b'-1})$.
     One can also verify the death condition for the cycle
    $\bar{\cyc}_i$. 
    For a backward $K_{b'-1}\bakincto K_{b'}$, 
    we omit the verification for the birth and death conditions.
    It follows that in case (i), $\rep\bndlsum \rep'$ is
    a homology representative for $[b',i]$, $b'\in \pinds^H(\Fcal_i)$, as required. 
    We also have that the justification for case (ii) and (iii) can be similarly done.

    \smallskip
    \noindent
    {\bf Case 2}, $b' < b$: In this case, we have $\bar{\cyc}_\alpha=\cyc'_\alpha$ for $\alpha\in [b',b-1]$ and
    $\bar{\cyc}_\alpha=\cyc_\alpha + \cyc'_\alpha$ for $\alpha \in [b,i]$. 
    We have only two possible cases: (i) $b\in \pinds^B(\Fcal_i)$ and
    $b'\in \pinds^H(\Fcal_i)$; (ii) $b,b'\in \pinds^H(\Fcal_i)$ and $K_{b-1}\bakinctosp{}K_b$ is backward. Again, using the case analysis, one can show that $\linmap_\alpha([\bar{\cyc}_\alpha])=[\bar{\cyc}_{\alpha+1}]$ if $\linmap_\alpha$ is forward and $\linmap_\alpha([\bar{\cyc}_{\alpha+1}])=[\bar{\cyc}_\alpha]$ otherwise.
    Moreover, the birth and death conditions can also be verified easily implying that $\rep\bndlsum \rep'$ in both cases is a homology representative for $[b',i]$, $b'\in \pinds^H(\Fcal_i)$.

\section{Missing cases in the proof of Theorem~\ref{thm:bundle}}
\label{sec:pf-miss-thm-bundle}

\noindent
{\bf Case 3}, $K_i\bakinctosp{\sigma_i} K_{i+1}$ and
$i+1\in \pinds^H(\Fcal_{i+1})$: In this case, an interval $[b,i]\in \Pers^B(\Fcal_i)$ 
does not extend to $i+1$
and a new interval $[i+1,i+1]\in \Pers^H(\Fcal_{i+1})$ begins. 
 Let $[b_1,i],\ldots,[b_k,i]$ be all the
intervals in $\Pers^B(\Fcal_i)$ 
with representatives $\rep_1,\ldots, \rep_k$ respectively,
and let $z^j_i$
be the cycle at index $i$ in $\rep_j$ for each $1\leq j\leq k$.
Since $z^j_i\in\Bnd(K_i)$, $z^j_i$ has a `bounding chain' $c^j\in\Chn(K_i)$
s.t.\ $z^j_i=\partial(c^j)$.
Assuming after reindexing $z^j_1,\ldots,z^j_\ell$
are all the cycles
whose bounding chains contain $\sigma_i$
where $b_1\lessB\cdots\lessB b_\ell$.
We add $\rep_1$ to $\rep_2,\ldots,\rep_\ell$ to remove $\sigma_i$ from their bounding chains. 
Then, the new representatives $\rep'_2:=\rep_1\bndlsum\rep_2,\ldots,
\rep'_\ell:=\rep_1\bndlsum\rep_\ell$ for the intervals $[b_2,i],\ldots,[b_\ell,i]$ 
can extend to $i+1$ because their bounding chains now do not contain $\sigma_i$.
By Proposition~\ref{prop:wiresum},
$W^{[b_j,i]}\bndlsum W^{[b_1,i]}$ represents
$[b_j,i+1]\in\PersB(\Filt{i+1})$ for $2\leq j\leq \ell$.
So, we update $W^{[b_j,i]}$ as $W^{[b_j,i]}\bndlsum W^{[b_1,i]}$ for $2\leq j\leq k$.
The interval $[b_1,i]$ does not extend to $i+1$
with the wire bundle
$W^{[b_1,i]}$ still representing $[b_1,i]\in\PersB(\Filt{i+1})$.
A new interval $[i+1,i+1]\in \Pers^H(\Fcal_{i+1})$ begins with a representative  $\Set{\partial \sigma_i\textit{}}$ which is generated by a new wire
$\wire{i+1}=\partial\sigma_i$. Subsets of the wire bundle $W_{i+1}=W_i\cup\{\wire{i+1}\}$ then generate representatives for all intervals in $\Pers^H(\Fcal_{i+1})\cup\Pers^B(\Fcal_{i+1})$.

\smallskip
\noindent
{\bf Case 4}, $K_i\bakinctosp{\sigma_i} K_{i+1}$ and
$i\in \ninds^H(\Fcal_{i})$: In this case, an interval $[b,i]\in \Pers^H(\Fcal_i)$
does not extend to $i+1$.
Let $\rep_1,\ldots,\rep_k$ be all the representatives for 
$[b_1,i],\ldots, [b_k,i]\in \Pers^H(\Fcal_i)$ respectively 
whose cycles
at index $i$ contain $\sigma_i$.
WLOG, assume that $b_1\lessB\cdots\lessB b_k$.
We cannot extend these representatives
to $i+1$ because $\sigma_i\nsubseteq K_{i+1}$.
We add $\rep_1$ to $\rep_2,\ldots,\rep_k$
to obtain new representatives $\rep_2',\ldots,\rep_k'$ for the intervals 
whose cycles at index $i$ now do not contain $\sigma_i$. 
Similar to  previous cases, the  bundle $W^{[b_j,i]}\bndlsum W^{[b_1,i]}$ 
represents $[b_j,i+1]\in\PersH(\Filt{i+1})$
for $2\leq j\leq k$. 
So, we update 
$W^{[b_j,i]}$ 
as $W^{[b_j,i]}\bndlsum W^{[b_1,i]}$ for $2\leq j\leq k$. 
The interval $[b_1,i]$ does not extend to $i+1$
and $\rep_1$ remains a representative for $[b_1,i]\in \PersH(\Filt{i+1})$. 

\section{Implementation details}
\label{sec:impl} 

We provide implementation details for the algorithm presented in Section~\ref{sec:alg-oview}.
For a column $c$ of the matrices maintained,
we denote the pivot of $c$ as $\pivot(c)$.
Also,
in our algorithm,
each simplex $\fsimp_i$ added in $\Fcal$ is assigned an 
{\tt id} $i$.
This means that
a simplex has 
a new {\tt id} when it is added again 
after being deleted.
We then present the details for the different cases.


\subsection{Forward  $K_i\inctosp{\fsimp_{i}}K_{i+1}$}
\label{sec:detail-fwd}
We need to determine whether $\partial\fsimp_{i}$
is already a boundary in $K_i$.
If this is true, 
a new cycle containing $\fsimp_i$ is created in $K_{i+1}$
and $\linmap_i$ is injective;
otherwise, the homology class $[\partial\fsimp_{i}]$
becomes trivial in $\Hm(K_{i+1})$
and $\linmap_i$ is surjective.
To determine this,
we  perform reductions on $\partial\fsimp_i$
and the columns in $\cycmat$ and $\bndmat$
to get a sum $\partial\fsimp_i=\sum_{j\in J} \cmatcol{j}+\sum_{k\in I}\bndmat[k]$.
We then have that $\partial\fsimp_{i}$
is a boundary in $K_i$ iff $J=\emptyset$.

\subsubsection{$\linmap_i$ is injective}
\label{sec:fwd-birth-detail}
Since $\partial\fsimp_i=\sum_{k\in I}\bndmat[k]$,
we let the new wire 
$\wire{i+1}$ 
containing $\fsimp_i$
 be $\wire{i+1}=\fsimp_i+\sum_{k\in I}\chnmat[k]$,
where $\partial(\fsimp_i+\sum_{k\in I}\chnmat[k])=\partial\fsimp_i+\sum_{k\in I}\bndmat[k]=0$.
Notice that as mentioned,
we need to add $\wire{i+1}$ 
as a new column to the matrix $\cycmat$.
Since $\pivot(\wire{i+1})=i$, columns in $\cycmat$
and $\bndmat$  still have distinct pivots.

\subsubsection{$\linmap_i$ is surjective}
\label{sec:fwd-death-detail}

The subset $J$ derived from the reductions
is the same as the subset $J$ 
in Equation~(\ref{eqn:sum-to-zero})
in the corresponding case 
of Section~\ref{sec:alg-oview}.
So the processing for the corresponding case
described 
in Section~\ref{sec:alg-oview}
can be directly performed.
Notice that we add a new column to $\bndmat$ in this case.
Since the pivot of the new column of $\bndmat$
may conflict with the pivot of another column in $\cycmat$ or $\bndmat$,
we use a loop to repeatedly sum two columns 
whose pivots are the same 
until the pivots become distinct again.
In each iteration of the loop, three cases can happen:
\begin{enumerate}
    \item Two columns $\bndmat[j]$ and $\bndmat[k]$ have the same pivot:
    WLOG,
    assume that $\bbirth_k\lessB\bbirth_j$.
    Let $\bndmat[j]=\bndmat[j]+\bndmat[k]$,
     $\chnmat[j]=\chnmat[j]+\chnmat[k]$,
     and $\bndbndl^j=\bndbndl^j\bndlsum\bndbndl^k$.

    \item Two columns $\cmatcol{j}$ and $\bndmat[k]$ have the same pivot:
    We have $\bbirth_{k}\lessB\hbirth_j$.
    Let $\cmatcol{j}=\cmatcol{j}+\bndmat[k]$
    and  $\bndl^j=\bndl^j\bndlsum\bndbndl^k$.

    \item Two columns $\cmatcol{j}$ and $\cmatcol{k}$ have the same pivot:
    WLOG,
    assume that $\hbirth_k\lessB\hbirth_j$.
    Let $\cmatcol{j}=\cmatcol{j}+\cmatcol{k}$
    and $\bndl^j=\bndl^j\bndlsum\bndl^k$.
\end{enumerate}

Since in each iteration of the above loop we change only one column
of $\cycmat$ and $\bndmat$,
there are at most two columns of $\cycmat$ and $\bndmat$ 
with the same pivot at any time.
Hence, the above loop ends in no more than $\simpcnt$ iterations
because the pivot of the two clashed columns is always decreasing.

\subsection{Backward  $K_i\bakinctosp{\fsimp_{i}}K_{i+1}$}
\label{sec:detail-bak}
We need to determine whether $\fsimp_{i}$
is in a cycle $\cyc$ in $K_i$.
If this is true, 
$z$ is a cycle in $K_{i}$ but not in $K_{i+1}$
indicating that $\linmap_i$ is injective;
otherwise,
$\linmap_i$ is surjective.
Since columns in $\cycmat$ and $\bndmat$ form a basis for 
$\Zyc(K_i)$,
we only need to check whether 
$\fsimp_{i}$
is in a column in $\cycmat$ or $\bndmat$.
 Moreover, since $\fsimp_i$ has no cofaces in $K_i$,
we have that $\fsimp_i$ cannot be in a boundary in $K_i$.
Therefore, we only need to check 
whether 
$\fsimp_{i}$
is in a column in $\cycmat$.

\subsubsection{$\linmap_i$ is surjective}
\label{sec:bak-birth-detail}



Since columns in $\cycmat$, $\bndmat$, and $\chnmat$ form a basis for $\Chn(K_i)$
and 
$\fsimp_{i}$
is not in a column in $\cycmat$ or $\bndmat$,
we have that $\fsimp_{i}$ must be in at least one column of $\chnmat$.
Since $\fsimp_i\not\in K_{i+1}$,
we need to remove $\fsimp_{i}$ from $\chnmat$
when proceeding from $K_i$ to $K_{i+1}$.
To do this, 
we use a loop to repeatedly sum two columns 
in $\chnmat$ containing $\fsimp_i$
until only one column in $\chnmat$
contains $\fsimp_i$.
Notice that
whenever we sum two columns 
in $\chnmat$, we also need to sum the corresponding columns
in $\bndmat$
and their wire bundles.
Hence, the summations have to respect the order `$\lessB$'.
We use the following loop to perform the summations:

\newlength\ParaAlgIndent
\setlength{\ParaAlgIndent}{1.2em}
        \begin{enumerate}[parsep=0pt]
            \item $\aG_1,\ldots,\aG_\ell\leftarrow$ indices of all columns of $\chnmat$ containing $\fsimp_i$
            \item sort and rename $\aG_1,\ldots,\aG_\ell$ s.t. 
            $\bbirth_{\aG_1}\lessB\cdots\lessB\bbirth_{\aG_\ell}$.
            \item $c_1\leftarrow\matcol{{\chnmat}}{\aG_1}$
            \item $c_2\leftarrow\matcol{{\bndmat}}{\aG_1}$
            \item $U\leftarrow\bndbndl^{\aG_1}$
