// 1,ready: 1  1,valid: 0  sender,state: 1    
receiver,state : 6
// 1,ready: 1  1,valid: 0  sender,state: 2    
// 1,ready: 1  1,valid: 1  sender,state: 2    
// 1,ready: 1  1,valid: 1  sender,state: 1  
\end{verbatim}
